    public MainWindow(string[] args)
    {
        factoryFloatingLayoutPending =
            initializeFactoryFloatingLayout || !SupportsDesktopWindowSizing;
        WindowsOnlineAccountHost? createdOnlineHost = null;
        string? createdOnlineHostError = null;
        try
        {
            createdOnlineHost = WindowsOnlineAccountHost.Create();
            createdOnlineHost.Session.Changed += OnlineAccountSession_Changed;
            createdOnlineHost.Session.NotificationsReceived +=
                OnlineAccountSession_NotificationsReceived;
        }
        catch (Exception exception)
        {
            createdOnlineHostError = exception.Message;
        }
        onlineAccountHost = createdOnlineHost;
        onlineHostError = createdOnlineHostError;

        keySoundRuntime = new WindowsKeySoundPlaybackRuntime(audioTransport);
        keySoundRuntime.Volume = (float)keySoundSettings.Volume;
        keySoundPlanDebounceTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(50)
        };
        keySoundPlanDebounceTimer.Tick += (_, _) =>
        {
            keySoundPlanDebounceTimer.Stop();
            _ = RequestKeySoundPlanNow();
        };
        keySoundSettingsSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        keySoundSettingsSaveTimer.Tick += (_, _) => PersistPendingKeySoundSettings();
        displayScaleSettingsSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        displayScaleSettingsSaveTimer.Tick += (_, _) => PersistPendingDisplayScaleSettings();
        editorViewSettingsSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        editorViewSettingsSaveTimer.Tick += (_, _) => PersistPendingEditorViewSettings();
        navigationMarkerSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        navigationMarkerSaveTimer.Tick += async (_, _) => await PersistPendingNavigationMarkersAsync();
        settingsSnapCommitTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(300)
        };
        // The text-change debounce commits without Enter on purpose (IME-safe;
        // the settings GUI evidence requires it), but it must not add a
        // drop-down entry for every intermediate value it passes ("1/19" on the
        // way to "1/192"). Only Enter or focus loss adds the final custom value.
        settingsSnapCommitTimer.Tick += (_, _) =>
            CommitSettingsSnapBoxText(
                restoreInvalidText: false,
                addCustomDivisionItem: false);
        settingsFixedSnapCommitTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(300)
        };
        settingsFixedSnapCommitTimer.Tick += (_, _) =>
            CommitSettingsFixedSnapBoxText(
                restoreInvalidText: false,
                addCustomDivisionItem: false);
        shortcutSettingsSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        shortcutSettingsSaveTimer.Tick += (_, _) => PersistPendingShortcutSettings();
        audioPanelSettingsSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        audioPanelSettingsSaveTimer.Tick += (_, _) => PersistPendingAudioPanelSettings();
        groupCatalogSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(600)
        };
        groupCatalogSaveTimer.Tick += (_, _) => PersistPendingGroupCatalogs(force: true);
        groupDisplaySettingsSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        groupDisplaySettingsSaveTimer.Tick += (_, _) => PersistPendingGroupDisplaySettings(force: true);
        editorToastTimer.Tick += (_, _) => HideEditorToast();
        autoBackupTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMinutes(editorViewSettings.AutoBackupMinutes)
        };
        autoBackupTimer.Tick += AutoBackupTimer_Tick;
        editorSeekCommitTimer = new DispatcherTimer(DispatcherPriority.Normal)
        {
            Interval = TimeSpan.FromMilliseconds(90)
        };
        editorSeekCommitTimer.Tick += (_, _) =>
        {
            editorSeekCommitTimer.Stop();
            if (editorSeekCommitRunning) return;
            editorSeekCommitTask = CommitPendingEditorSeekAsync();
        };
        roomInvitationTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromSeconds(2)
        };
        roomInvitationTimer.Tick += async (_, _) => await PollRoomInvitationsAsync();
        friendInviteCooldownTimer.Tick += (_, _) =>
            RefreshFriendInviteCooldownButtons();
        followNotificationTimer.Tick += async (_, _) =>
            await PollFollowNotificationsAsync();
        chartingHeartbeatTimer.Tick += ChartingHeartbeatTimer_Tick;
        followNotificationToastTimer.Tick += (_, _) =>
            AdvanceFollowNotificationToast();
        fullscreenTitleHideTimer.Tick += FullscreenTitleHideTimer_Tick;
        fullscreenTitleAnimationTimer.Tick += FullscreenTitleAnimationTimer_Tick;
        suppressKeySoundControls = true;
        var evidenceChartPath = ParseArgument(args, "--evidence-chart");
        evidenceChartMode = !string.IsNullOrWhiteSpace(evidenceChartPath);
        var evidenceSecondChartPath = ParseArgument(
            args,
            "--evidence-second-chart");
        if (!string.IsNullOrWhiteSpace(evidenceSecondChartPath) &&
            !evidenceChartMode)
            throw new InvalidOperationException(
                "A second evidence chart requires the primary direct evidence chart.");
        startupChartPaths = !string.IsNullOrWhiteSpace(evidenceChartPath)
            ? string.IsNullOrWhiteSpace(evidenceSecondChartPath)
                ? [Path.GetFullPath(evidenceChartPath)]
                :
                [
                    Path.GetFullPath(evidenceChartPath),
                    Path.GetFullPath(evidenceSecondChartPath)
                ]
            : WindowsSingleInstancePolicy.ExtractSupportedPaths(args);
        evidenceShowOsuImportDialog = args.Contains(
            "--evidence-osu-import-dialog",
            StringComparer.OrdinalIgnoreCase);
        if (evidenceShowOsuImportDialog &&
            (!evidenceChartMode ||
             startupChartPaths.Count != 1 ||
             !Path.GetExtension(startupChartPaths[0]).Equals(
                 ".osu",
                 StringComparison.OrdinalIgnoreCase)))
            throw new InvalidOperationException(
                "Evidence osu import-dialog mode requires one direct .osu evidence chart.");
        libraryVisible = startupChartPaths.Count == 0;
        evidenceOutputPath = ParseArgument(args, "--evidence-output");
        evidenceInteractionOutputPath = ParseArgument(args, "--evidence-interaction-output");
        evidenceSyntheticNoteCount = ParsePositiveIntArgument(args, "--evidence-synthetic-notes");
        var requestedInteractionDelay = ParsePositiveIntArgument(
            args,
            "--evidence-interaction-delay-ms");
        evidenceInteractionDelayMilliseconds = requestedInteractionDelay == 0
            ? 1800
            : Math.Clamp(requestedInteractionDelay, 1000, 60_000);
        evidenceFocusTiming = args.Contains("--evidence-focus-timing", StringComparer.OrdinalIgnoreCase);
        evidenceFocusHoldTail = args.Contains(
            "--evidence-focus-hold-tail",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusNoteProperty = args.Contains(
            "--evidence-focus-note-property",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusGroup = args.Contains(
            "--evidence-focus-group",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusProEditor = args.Contains(
            "--evidence-focus-proeditor",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusKeySound = args.Contains(
            "--evidence-focus-key-sound",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusAudioTransport = args.Contains(
            "--evidence-focus-audio-transport",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusDisplayScale = args.Contains(
            "--evidence-focus-display-scale",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusSettingsCache = args.Contains(
            "--evidence-focus-settings-cache",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusAudioPanels = args.Contains(
            "--evidence-focus-audio-panels",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusLibraryDeletion = args.Contains(
            "--evidence-focus-library-deletion",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusLibraryLauncher = args.Contains(
            "--evidence-focus-library-launcher",
            StringComparer.OrdinalIgnoreCase);
        var evidenceUsePersistedWorkspaceRoot = args.Contains(
            "--evidence-use-persisted-workspace-root",
            StringComparer.OrdinalIgnoreCase);
        if (evidenceUsePersistedWorkspaceRoot &&
            !evidenceFocusLibraryLauncher)
            throw new InvalidOperationException(
                "Persisted-workspace evidence requires library-launcher evidence mode.");
        evidenceFocusChartValidation = args.Contains(
            "--evidence-focus-chart-validation",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusTitleBarAnimation = args.Contains(
            "--evidence-focus-titlebar-animation",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusLibraryVirtualization = args.Contains(
            "--evidence-focus-library-virtualization",
            StringComparer.OrdinalIgnoreCase);
        if (evidenceFocusLibraryVirtualization)
        {
            if (evidenceChartMode)
                throw new InvalidOperationException(
                    "Library virtualization evidence cannot open an editor chart.");
            if (string.IsNullOrWhiteSpace(evidenceOutputPath))
                throw new InvalidOperationException(
                    "Library virtualization evidence requires --evidence-output.");
            if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(
                    "LUMACHART_AVALONIA_LOCAL_DATA_ROOT")) ||
                string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(
                    "LUMACHART_AVALONIA_WORKSPACE_ROOT")))
                throw new InvalidOperationException(
                    "Library virtualization evidence requires isolated local-data and workspace roots.");
        }
        evidenceSuppressExportReveal = args.Contains(
            "--evidence-suppress-export-reveal",
            StringComparer.OrdinalIgnoreCase);
        evidenceFollowActiveTab = args.Contains(
            "--evidence-follow-active-tab",
            StringComparer.OrdinalIgnoreCase);
        evidenceAutoBackupDelayMilliseconds = ParsePositiveIntArgument(
            args,
            "--evidence-auto-backup-delay-ms");
        if (evidenceAutoBackupDelayMilliseconds > 5000)
            throw new ArgumentOutOfRangeException(
                nameof(evidenceAutoBackupDelayMilliseconds),
                "Evidence automatic-backup delay must be at most 5000 ms.");
        evidenceAudioPermissionRevokeDelayMilliseconds = ParsePositiveIntArgument(
            args,
            "--evidence-audio-permission-revoke-delay-ms");
        if (evidenceAudioPermissionRevokeDelayMilliseconds > 5000)
            throw new ArgumentOutOfRangeException(
                nameof(evidenceAudioPermissionRevokeDelayMilliseconds),
                "Evidence audio-permission revoke delay must be at most 5000 ms.");
        if (evidenceAudioPermissionRevokeDelayMilliseconds > 0 && !evidenceChartMode)
            throw new InvalidOperationException(
                "Evidence audio-permission revocation requires a direct evidence chart.");
        evidenceAudioPreCommitDelayMilliseconds = ParsePositiveIntArgument(
            args,
            "--evidence-audio-pre-commit-delay-ms");
        if (evidenceAudioPreCommitDelayMilliseconds > 5000)
            throw new ArgumentOutOfRangeException(
                nameof(evidenceAudioPreCommitDelayMilliseconds),
                "Evidence audio pre-commit delay must be at most 5000 ms.");
        if (evidenceAudioPreCommitDelayMilliseconds > 0 && !evidenceChartMode)
            throw new InvalidOperationException(
                "Evidence audio pre-commit delay requires a direct evidence chart.");
        var requestedEvidenceFilePickerStartDirectory = ParseArgument(
            args,
            "--evidence-file-picker-start-directory");
        evidenceFilePickerStartDirectory =
            (evidenceChartMode || evidenceFocusLibraryLauncher) &&
                                            !string.IsNullOrWhiteSpace(requestedEvidenceFilePickerStartDirectory)
            ? Path.GetFullPath(requestedEvidenceFilePickerStartDirectory)
            : null;
        if (evidenceFilePickerStartDirectory != null &&
            !Directory.Exists(evidenceFilePickerStartDirectory))
            throw new DirectoryNotFoundException(
                $"Evidence file-picker start directory does not exist: {evidenceFilePickerStartDirectory}");
        if (evidenceFocusLibraryLauncher)
        {
            var localDataRoot = Environment.GetEnvironmentVariable(
                "LUMACHART_AVALONIA_LOCAL_DATA_ROOT");
            var editingRoot = Environment.GetEnvironmentVariable(
                "LUMACHART_AVALONIA_EDITING_ROOT");
            var workspaceRoot = Environment.GetEnvironmentVariable(
                "LUMACHART_AVALONIA_WORKSPACE_ROOT");
            if (string.IsNullOrWhiteSpace(localDataRoot) ||
                string.IsNullOrWhiteSpace(editingRoot) ||
                (!evidenceUsePersistedWorkspaceRoot &&
                 string.IsNullOrWhiteSpace(workspaceRoot)))
                throw new InvalidOperationException(
                    "Library launcher evidence requires isolated local-data, editing and workspace roots.");
            if (evidenceUsePersistedWorkspaceRoot &&
                !string.IsNullOrWhiteSpace(workspaceRoot))
                throw new InvalidOperationException(
                    "Persisted-workspace evidence must omit the workspace-root override.");
            if (evidenceUsePersistedWorkspaceRoot &&
                !File.Exists(AvaloniaAppPaths.WorkspaceSettingsPath))
                throw new InvalidOperationException(
                    "Persisted-workspace evidence requires an isolated workspace.json.");
        }
        evidenceUsePlacementProbeViewport = args.Contains(
            "--evidence-placement-probe-viewport",
            StringComparer.OrdinalIgnoreCase);
        evidenceFocusNotePropertyBeat = BeatPosition.TryParse(
            ParseArgument(args, "--evidence-focus-note-property-beat"),
            out var parsedEvidenceFocusNotePropertyBeat)
            ? parsedEvidenceFocusNotePropertyBeat
            : null;
        evidenceFocusGroupBeat = BeatPosition.TryParse(
            ParseArgument(args, "--evidence-focus-group-beat"),
            out var parsedEvidenceFocusGroupBeat)
            ? parsedEvidenceFocusGroupBeat
            : null;
        evidenceEnableBackgroundWaveform = args.Contains(
            "--evidence-background-waveform",
            StringComparer.OrdinalIgnoreCase);
        evidenceEnableBackgroundSpectrogram = args.Contains(
            "--evidence-background-spectrogram",
            StringComparer.OrdinalIgnoreCase);
        if (evidenceEnableBackgroundWaveform)
        {
            audioPanelSettings = audioPanelSettings.WithWaveform(
                audioPanelSettings.Waveform
                    .WithMode(WindowsAudioPanelDisplayMode.Background)
                    .WithCollapsed(false));
        }
        if (evidenceEnableBackgroundSpectrogram)
        {
            audioPanelSettings = audioPanelSettings.WithSpectrogram(
                audioPanelSettings.Spectrogram
                    .WithMode(WindowsAudioPanelDisplayMode.Background)
                    .WithCollapsed(false));
        }

        Title = "LumaChart Studio";
        TryApplyApplicationIcon();
        ConfigureInitialWindowBounds(1320, 800, 1080, 680);
        Background = new SolidColorBrush(WindowColor);
        FontFamily = new FontFamily("Segoe UI Variable Text, Microsoft YaHei UI");
        FontSize = 12;
        WindowDecorations = global::Avalonia.Controls.WindowDecorations.None;
        CanResize = true;
        AddHandler(
            InputElement.PointerPressedEvent,
            WindowResize_PointerPressed,
            RoutingStrategies.Tunnel);
        WindowStartupLocation = WindowStartupLocation.CenterScreen;
        localizationController = new AvaloniaLocalizationController(
            this,
            languageSettings.Preference);
        AvaloniaLocalizationRuntime.SetPreference(languageSettings.Preference);
        displayScaleRoot.Child = BuildShell();
        Content = displayScaleRoot;
        fontScaleController = new AvaloniaWindowFontScaleController(this);
        localizationController.Apply();
        displayScaleController = new WindowsDisplayScaleController(
            this,
            displayScaleRoot,
            fontScaleController,
            displayScaleSettings);
        popupScaleController = new AvaloniaPopupScaleController(
            () => displayScaleController.CurrentSettings);
        libraryList.ContextMenu = CreateLibraryFolderContextMenu();
        displayScaleSettings = displayScaleController.CurrentSettings;
        RefreshDisplayScaleSettingsUi();
        ApplyEditorViewSettings();
        _ = audioTransport.SetVolumeAsync((float)editorViewSettings.MusicVolume);
        _ = audioTransport.SetPlaybackRateAsync(editorViewSettings.PlaybackRate);
        _ = audioTransport.SetPreservePitchAsync(editorViewSettings.PreservePitch);
        timeline.SetProGridColumnCount(persistedProGridColumns);
        suppressKeySoundControls = false;
        RefreshKeySoundSettingsUi();
        UpdateAudioUi();

        viewModel.StateChanged += ViewModel_StateChanged;
        audioTransport.StateChanged += AudioTransport_StateChanged;
        audioVisualization.StateChanged += AudioVisualization_StateChanged;
        keySoundRuntime.StateChanged += KeySoundRuntime_StateChanged;
        timeline.CurrentBeatChanged += Timeline_CurrentBeatChanged;
        timeline.ManualNavigationRequested += Timeline_ManualNavigationRequested;
        timeline.PixelsPerBeatChanged += Timeline_PixelsPerBeatChanged;
        timeline.SelectionChanged += (_, _) => UpdateSelectionUi();
        timeline.TimingSelectionChanged += Timeline_TimingSelectionChanged;
        timeline.ChartIssuesChanged += (_, _) =>
            editorOverview.SetIssues(timeline.ChartIssues);
        timeline.TimingDeleteRequested += Timeline_TimingDeleteRequested;
        timeline.AnnotationEditRequested += (_, eventArgs) =>
            OpenAnnotationEditor(eventArgs.Annotation, eventArgs.CardBounds);
        timeline.StatusChanged += (_, status) => viewModel.SetStatus(status);
        // Hover text is transient presentation only. Routing it through the
        // view-model used to run the full UpdateUi path on every mouse move,
        // write a slightly stale beat back into the timeline during playback,
        // and incorrectly enqueue a pause/seek/resume cycle.
        timeline.HoverChanged += (_, status) => statusText.Text = status;
        timeline.EditPermissionDenied += (_, category) =>
            ShowRoomPermissionNotice(
                WindowsRoomPermissionNoticePolicy.Denied(category));
        timeline.TrackPanChanged += Timeline_TrackPanChanged;
        timeline.SizeChanged += (_, _) =>
        {
            RefreshProEditorControls();
            QueueAudioPanelLayout();
            QueueDifficultyCardLayout();
            QueueFactoryFloatingLayout();
        };
        timelineHost.SizeChanged += (_, _) =>
        {
            QueueAudioPanelLayout(clampFreePanels: true);
            QueueDifficultyCardLayout();
        };
        editorWorkbench.SizeChanged += (_, _) => QueueFloatingPaletteClamp();
        Opened += Window_Opened;
        Activated += (_, _) =>
        {
            RefreshFollowSystemLanguage();
            if (roomChatHasUnread && IsRoomChatActivelyVisible())
                SetRoomChatUnread(false);
        };
#if !LUMACHART_SHARED
        Deactivated += (_, _) =>
        {
            oneShotShortcutState.Clear();
            imeDuplicateCommitGuard.Reset();
            if (spacePanGestureState.Cancel())
                timeline.EndSpacePanModifier();
        };
#endif
        Closing += Window_Closing;
        AddHandler(
            InputElement.KeyDownEvent,
            Window_KeyDown,
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        AddHandler(
            InputElement.KeyUpEvent,
            Window_KeyUp,
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        AddHandler(
            InputElement.TextInputEvent,
            Window_TextInput,
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        DragDrop.SetAllowDrop(this, true);
        DragDrop.AddDragOverHandler(this, Window_DragOver);
        DragDrop.AddDropHandler(this, Window_Drop);

        audioUiTimer = new DispatcherTimer(DispatcherPriority.Render)
        {
            Interval = WindowsEditorFrameInterval(EffectiveFrameRateLimit())
        };
        audioUiTimer.Tick += AudioUiTimer_Tick;
        frameRateRuntimeReady = true;
        RefreshFrameRateStatus(isPlaying: false);
        proGridColumnSaveTimer = new DispatcherTimer(DispatcherPriority.Background)
        {
            Interval = TimeSpan.FromMilliseconds(350)
        };
        proGridColumnSaveTimer.Tick += (_, _) => PersistPendingProGridColumns();
    }

    private Control BuildShell()
    {
        var root = shellRoot;
        root.RowDefinitions = new RowDefinitions(
            $"{WindowsTitleBarParityPolicy.TitleBarHeight},*");
        root.Children.Add(BuildTitleBar());
        if (SupportsDesktopWindowSizing)
        {
            fullscreenTitleRevealHotZone.Height =
                WindowsTitleBarParityPolicy.FullscreenRevealHotZoneHeight;
            fullscreenTitleRevealHotZone.VerticalAlignment = VerticalAlignment.Top;
            fullscreenTitleRevealHotZone.Background = Brushes.Transparent;
            fullscreenTitleRevealHotZone.IsVisible = false;
            fullscreenTitleRevealHotZone.PointerEntered += (_, _) =>
                SetFullscreenTitleBarRevealed(true);
            AutomationProperties.SetAutomationId(
                fullscreenTitleRevealHotZone,
                "Title.FullscreenRevealHotZone");
            Grid.SetRowSpan(fullscreenTitleRevealHotZone, 3);
            fullscreenTitleRevealHotZone.SetValue(Panel.ZIndexProperty, 210);
            root.Children.Add(fullscreenTitleRevealHotZone);
        }

        var body = new Grid
        {
            Background = new SolidColorBrush(WindowColor)
        };
        Grid.SetRow(body, 1);

        var content = new Grid();
        BuildLibraryView();
        BuildEditorView();
        AutomationProperties.SetAutomationId(libraryView, "Library.Surface");
        AutomationProperties.SetAutomationId(editorView, "Editor.Surface");
        content.Children.Add(libraryView);
        content.Children.Add(editorView);
        body.Children.Add(content);
        root.Children.Add(body);

        statusText.Foreground = MutedBrush;
        statusText.FontSize = 12;
        statusText.VerticalAlignment = VerticalAlignment.Center;
        statusText.Margin = new Thickness(14, 0);
        AutomationProperties.SetAutomationId(statusText, "Editor.Status");
        frameRateStatusText.Foreground = MutedBrush;
        frameRateStatusText.FontSize = 11;
        frameRateStatusText.FontFamily = new FontFamily("Cascadia Mono,Consolas");
        frameRateStatusText.VerticalAlignment = VerticalAlignment.Center;
        frameRateStatusText.HorizontalAlignment = HorizontalAlignment.Right;
        frameRateStatusText.Margin = new Thickness(14, 0);
        frameRateStatusText.Text = "空闲 · 播放时测量帧率";
        AutomationProperties.SetAutomationId(frameRateStatusText, "Editor.FrameRateStatus");
        var statusGrid = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,Auto")
        };
        statusGrid.Children.Add(statusText);
        Grid.SetColumn(frameRateStatusText, 1);
        statusGrid.Children.Add(frameRateStatusText);
        statusBar.Height = 20;
        // The status strip floats over the body so a desktop window can keep the
        // workbench flush with its bottom edge. SingleView has no window chrome
        // below it, so on tablets the strip would sit on top of the DENSITY and
        // DIFF footers; reserve its height there instead.
        if (!SupportsDesktopWindowSizing)
            body.Margin = new Thickness(0, 0, 0, statusBar.Height);
        statusBar.Background = new SolidColorBrush(Color.Parse("#D9171A1D"));
        statusBar.BorderBrush = StrokeBrush;
        statusBar.BorderThickness = new Thickness(0, 1, 0, 0);
        statusBar.VerticalAlignment = VerticalAlignment.Bottom;
        statusBar.IsHitTestVisible = false;
        statusBar.Child = statusGrid;
        Grid.SetRow(statusBar, 1);
        statusBar.SetValue(Panel.ZIndexProperty, 18);
        root.Children.Add(statusBar);
        var onlineToastStack = BuildOnlineToastStack();
        Grid.SetRowSpan(onlineToastStack, 3);
        onlineToastStack.SetValue(Panel.ZIndexProperty, 1000);
        root.Children.Add(onlineToastStack);
        var transientEditorToast = BuildEditorToast();
        Grid.SetRowSpan(transientEditorToast, 3);
        transientEditorToast.SetValue(Panel.ZIndexProperty, 1001);
        root.Children.Add(transientEditorToast);
        var permissionNotice = BuildRoomPermissionNotice();
        Grid.SetRow(permissionNotice, 1);
        Grid.SetRowSpan(permissionNotice, 2);
        permissionNotice.SetValue(Panel.ZIndexProperty, 1100);
        root.Children.Add(permissionNotice);
        var compactFriends = BuildFriendsPanel();
        Grid.SetRowSpan(compactFriends, 3);
        compactFriends.SetValue(Panel.ZIndexProperty, 850);
        root.Children.Add(compactFriends);
        var onlinePlayerPopup = BuildOnlinePlayerPopupLayer();
        Grid.SetRow(onlinePlayerPopup, 1);
        Grid.SetRowSpan(onlinePlayerPopup, 2);
        onlinePlayerPopup.SetValue(Panel.ZIndexProperty, 1050);
        root.Children.Add(onlinePlayerPopup);
        var audioImportName = BuildAudioImportNameLayer();
        Grid.SetRow(audioImportName, 1);
        Grid.SetRowSpan(audioImportName, 2);
        audioImportName.SetValue(Panel.ZIndexProperty, 950);
        root.Children.Add(audioImportName);
        Grid.SetRow(onlineSurfaceLayer, 1);
        Grid.SetRowSpan(onlineSurfaceLayer, 2);
        onlineSurfaceLayer.SetValue(Panel.ZIndexProperty, 900);
        AutomationProperties.SetAutomationId(
            onlineSurfaceLayer,
            "Online.SurfaceLayer");
        onlineSurfaceLayer.Child = onlineSurfaceContent;
        root.Children.Add(onlineSurfaceLayer);
        var roomUploadProgress = BuildRoomUploadProgressPopup();
        Grid.SetRow(roomUploadProgress, 1);
        Grid.SetRowSpan(roomUploadProgress, 2);
        roomUploadProgress.SetValue(Panel.ZIndexProperty, 1300);
        root.Children.Add(roomUploadProgress);
        var roomDownloadProgress = BuildRoomDownloadProgressLayer();
        Grid.SetRow(roomDownloadProgress, 1);
        Grid.SetRowSpan(roomDownloadProgress, 2);
        roomDownloadProgress.SetValue(Panel.ZIndexProperty, 1301);
        root.Children.Add(roomDownloadProgress);
        var about = BuildAboutLayer();
        Grid.SetRow(about, 1);
        Grid.SetRowSpan(about, 2);
        about.SetValue(Panel.ZIndexProperty, 1150);
        root.Children.Add(about);
        var update = BuildUpdateLayer();
        Grid.SetRow(update, 1);
        Grid.SetRowSpan(update, 2);
        update.SetValue(Panel.ZIndexProperty, 1200);
        root.Children.Add(update);
        return root;
    }

    private Control BuildRoomUploadProgressPopup()
    {
        roomUploadProgressTitleText.Text = "正在创建联机房间";
        roomUploadProgressTitleText.FontSize = 18;
        roomUploadProgressTitleText.FontWeight = FontWeight.SemiBold;
        roomUploadProgressTitleText.Foreground =
            new SolidColorBrush(Color.Parse("#E4E9EA"));
        roomUploadProgressTitleText.TextTrimming = TextTrimming.CharacterEllipsis;
        AutomationProperties.SetAutomationId(
            roomUploadProgressTitleText,
            "RoomUpload.Progress.Title");

        roomUploadProgressDetailText.Foreground =
            new SolidColorBrush(Color.Parse("#93A0A4"));
        roomUploadProgressDetailText.FontSize = 11;
        roomUploadProgressDetailText.Margin = new Thickness(0, 7, 0, 12);
        roomUploadProgressDetailText.TextTrimming = TextTrimming.CharacterEllipsis;
        AutomationProperties.SetAutomationId(
            roomUploadProgressDetailText,
            "RoomUpload.Progress.Detail");

        roomUploadProgressBar.Minimum = 0;
        roomUploadProgressBar.Maximum = 100;
        roomUploadProgressBar.Height = 9;
        roomUploadProgressBar.HorizontalAlignment = HorizontalAlignment.Stretch;
        roomUploadProgressBar.Foreground =
            new SolidColorBrush(Color.Parse("#6FA1A5"));
        roomUploadProgressBar.Background =
            new SolidColorBrush(Color.Parse("#252B2E"));
        AutomationProperties.SetAutomationId(
            roomUploadProgressBar,
            "RoomUpload.Progress.Bar");

        roomUploadProgressValueText.Foreground =
            new SolidColorBrush(Color.Parse("#A8B5B7"));
        roomUploadProgressValueText.FontFamily =
            new FontFamily("Cascadia Mono,Consolas");
        roomUploadProgressValueText.FontSize = 10;
        roomUploadProgressValueText.Margin = new Thickness(0, 8, 0, 0);
        roomUploadProgressValueText.HorizontalAlignment = HorizontalAlignment.Right;
        AutomationProperties.SetAutomationId(
            roomUploadProgressValueText,
            "RoomUpload.Progress.Value");

        roomUploadProgressPopup.Width = 430;
        roomUploadProgressPopup.MaxWidth = 430;
        roomUploadProgressPopup.Padding = new Thickness(22, 19);
        roomUploadProgressPopup.HorizontalAlignment = HorizontalAlignment.Center;
        roomUploadProgressPopup.VerticalAlignment = VerticalAlignment.Center;
        roomUploadProgressPopup.Background =
            new SolidColorBrush(Color.Parse("#FC1A1E21"));
        roomUploadProgressPopup.BorderBrush =
            new SolidColorBrush(Color.Parse("#60777B"));
        roomUploadProgressPopup.BorderThickness = new Thickness(1);
        roomUploadProgressPopup.CornerRadius = new CornerRadius(6);
        roomUploadProgressPopup.BoxShadow =
            new BoxShadows(new BoxShadow
            {
                Blur = 24,
                OffsetY = 8,
                Color = Color.Parse("#A0000000")
            });
        roomUploadProgressPopup.IsVisible = false;
        roomUploadProgressPopup.IsHitTestVisible = false;
        roomUploadProgressPopup.Child = new StackPanel
        {
            Children =
            {
                roomUploadProgressTitleText,
                roomUploadProgressDetailText,
                roomUploadProgressBar,
                roomUploadProgressValueText
            }
        };
        AutomationProperties.SetAutomationId(
            roomUploadProgressPopup,
            "RoomUpload.Progress.Popup");
        AutomationProperties.SetName(
            roomUploadProgressPopup,
            "创建房间资源上传进度");
        return roomUploadProgressPopup;
    }

    private void ShowRoomUploadProgress(
        Guid roomId,
        string roomName,
        WindowsOnlineRoomUploadPackage package)
    {
        roomUploadProgressRoomId = roomId;
        roomUploadProgressShownUtc = DateTimeOffset.UtcNow;
        roomUploadProgressTitleText.Text = AvaloniaLocalizationCatalog.Format("正在创建“{0}”", roomName);
        roomUploadProgressDetailText.Text =
            AvaloniaLocalizationCatalog.Format("准备上传 {0:N0} 个文件", package.Files.Count);
        roomUploadProgressBar.Value = 0;
        roomUploadProgressValueText.Text =
            $"0%  ·  0 B / {FormatTransferBytes(package.TotalBytes)}";
        roomUploadProgressPopup.IsVisible = true;
        AutomationProperties.SetHelpText(
            roomUploadProgressPopup,
            $"RoomId={roomId}; Visible=True; Progress=0; " +
            $"Files={package.Files.Count}; TotalBytes={package.TotalBytes}");
    }

    private void UpdateRoomUploadProgress(
        Guid roomId,
        WindowsOnlineRoomTransferProgress progress)
    {
        if (roomUploadProgressRoomId != roomId) return;
        var percent = Math.Clamp(progress.Fraction * 100, 0, 100);
        roomUploadProgressBar.Value = percent;
        roomUploadProgressDetailText.Text = string.IsNullOrWhiteSpace(progress.CurrentPath)
            ? "正在上传房间资源"
            : progress.CurrentPath;
        roomUploadProgressValueText.Text =
            $"{percent:0}%  ·  {FormatTransferBytes(progress.TransferredBytes)} / " +
            FormatTransferBytes(progress.TotalBytes);
        AutomationProperties.SetHelpText(
            roomUploadProgressPopup,
            $"RoomId={roomId}; Visible=True; Progress={percent:R}; " +
            $"TransferredBytes={progress.TransferredBytes}; " +
            $"TotalBytes={progress.TotalBytes}; CurrentPath={progress.CurrentPath}");
    }

    private async Task HideRoomUploadProgressAsync(Guid roomId, bool succeeded)
    {
        if (roomUploadProgressRoomId != roomId) return;
        if (succeeded)
        {
            roomUploadProgressBar.Value = 100;
            roomUploadProgressDetailText.Text = "资源上传完成，正在进入房间";
            roomUploadProgressValueText.Text = "100%  ·  已完成";
        }
        var minimumVisible = succeeded
            ? TimeSpan.FromMilliseconds(650)
            : TimeSpan.FromMilliseconds(900);
        var remaining = minimumVisible -
                        (DateTimeOffset.UtcNow - roomUploadProgressShownUtc);
        if (remaining > TimeSpan.Zero)
            await Task.Delay(remaining);
        if (roomUploadProgressRoomId != roomId) return;
        roomUploadProgressPopup.IsVisible = false;
        roomUploadProgressRoomId = null;
        AutomationProperties.SetHelpText(
            roomUploadProgressPopup,
            $"RoomId={roomId}; Visible=False; Succeeded={succeeded}");
    }

