    private void ShowRoomDownloadProgress(
        Guid roomId,
        string roomName,
        WindowsOnlineRoomResourceCacheStatus cacheStatus)
    {
        roomDownloadProgressRoomId = roomId;
        roomDownloadProgressShownUtc = DateTimeOffset.UtcNow;
        roomDownloadProgressTitleText.Text = AvaloniaLocalizationCatalog.Format("正在进入“{0}”", roomName);
        roomDownloadProgressBar.IsIndeterminate = cacheStatus.MissingBytes == 0;
        roomDownloadProgressBar.Value = 0;
        roomDownloadProgressDetailText.Text = cacheStatus.MissingBytes == 0
            ? AvaloniaLocalizationCatalog.Format("已复用 {0:N0} 个资源，正在生成编辑工作区", cacheStatus.ReusedCount)
            : AvaloniaLocalizationCatalog.Format("正在下载缺少的房间资源，共 {0}", FormatTransferBytes(cacheStatus.MissingBytes));
        roomDownloadProgressValueText.Text = cacheStatus.MissingBytes == 0
            ? AvaloniaLocalizationCatalog.Format("本地缓存已校验  ·  {0}", FormatTransferBytes(cacheStatus.TotalBytes))
            : $"0%  ·  0 B / {FormatTransferBytes(cacheStatus.MissingBytes)}";
        roomDownloadProgressLayer.IsVisible = true;
        AutomationProperties.SetHelpText(
            roomDownloadProgressLayer,
            $"RoomId={roomId}; Visible=True; MissingBytes={cacheStatus.MissingBytes}; " +
            $"TotalBytes={cacheStatus.TotalBytes}; ReusedCount={cacheStatus.ReusedCount}");
    }

    private void UpdateRoomDownloadProgress(
        Guid roomId,
        WindowsOnlineRoomTransferProgress progress)
    {
        if (roomDownloadProgressRoomId != roomId) return;
        var percent = Math.Clamp(progress.Fraction * 100, 0, 100);
        roomDownloadProgressBar.IsIndeterminate = progress.TotalBytes <= 0;
        roomDownloadProgressBar.Value = percent;
        roomDownloadProgressDetailText.Text = string.IsNullOrWhiteSpace(progress.CurrentPath)
            ? "正在下载房间资源"
            : progress.CurrentPath;
        roomDownloadProgressValueText.Text = progress.TotalBytes <= 0
            ? "正在复用本地缓存"
            : $"{percent:0}%  ·  {FormatTransferBytes(progress.TransferredBytes)} / " +
              FormatTransferBytes(progress.TotalBytes);
        AutomationProperties.SetHelpText(
            roomDownloadProgressLayer,
            $"RoomId={roomId}; Visible=True; Progress={percent:R}; " +
            $"TransferredBytes={progress.TransferredBytes}; " +
            $"TotalBytes={progress.TotalBytes}; CurrentPath={progress.CurrentPath}");
    }

    private void SetRoomDownloadProgressStage(Guid roomId, string detail, string value)
    {
        if (roomDownloadProgressRoomId != roomId) return;
        roomDownloadProgressBar.IsIndeterminate = false;
        roomDownloadProgressBar.Value = 100;
        roomDownloadProgressDetailText.Text = detail;
        roomDownloadProgressValueText.Text = value;
    }

    private async Task HideRoomDownloadProgressAsync(Guid roomId, bool succeeded)
    {
        if (roomDownloadProgressRoomId != roomId) return;
        if (succeeded)
            SetRoomDownloadProgressStage(roomId, "谱面与资源已校验，正在完成进入", "100%  ·  已完成");
        var minimumVisible = succeeded
            ? TimeSpan.FromMilliseconds(650)
            : TimeSpan.FromMilliseconds(900);
        var remaining = minimumVisible -
                        (DateTimeOffset.UtcNow - roomDownloadProgressShownUtc);
        if (remaining > TimeSpan.Zero)
            await Task.Delay(remaining);
        if (roomDownloadProgressRoomId != roomId) return;
        roomDownloadProgressLayer.IsVisible = false;
        roomDownloadProgressRoomId = null;
        roomDownloadProgressBar.IsIndeterminate = false;
        AutomationProperties.SetHelpText(
            roomDownloadProgressLayer,
            $"RoomId={roomId}; Visible=False; Succeeded={succeeded}");
    }

