    {
        Content = text,
        Width = 44,
        Height = 32,
        Padding = new Thickness(0),
        HorizontalAlignment = HorizontalAlignment.Center,
        VerticalAlignment = VerticalAlignment.Center,
        HorizontalContentAlignment = HorizontalAlignment.Center,
        VerticalContentAlignment = VerticalAlignment.Center,
        Background = Brushes.Transparent,
        Foreground = new SolidColorBrush(Color.Parse("#D3DADB")),
        BorderBrush = new SolidColorBrush(Color.Parse("#344044")),
        BorderThickness = new Thickness(1),
        CornerRadius = new CornerRadius(3)
    };

    private async Task ToggleFriendsPanelAsync()
    {
        startupAccountChoiceHandled = true;
        if (friendsPanel.IsVisible)
        {
            HideFriendsPanel();
            return;
        }
        if (onlineSurfaceCompletion != null || onlineAccountEntryInProgress) return;
        if (onlineAccountHost == null)
        {
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("好友功能不可用：{0}", onlineHostError ?? AvaloniaLocalizationCatalog.Text("联机配置无效")));
            return;
        }
        try
        {
            if (!onlineAccountHost.Session.IsAuthenticated)
            {
                var accepted =
                    await ShowHostedOnlineAccountAsync(onlineAccountHost.Session);
                UpdateOnlineAccountUi();
                if (!accepted || !onlineAccountHost.Session.IsAuthenticated) return;
            }

            friendsPanel.IsVisible = true;
            friendsStatusText.Text = "正在载入好友…";
            await RefreshFriendsPanelAsync();
        }
        catch (Exception exception)
        {
            // Last-resort boundary for the title-bar async handler; network
            // failures are already reported inside RefreshFriendsPanelAsync.
            Debug.WriteLine($"Friends panel failed: {exception}");
            if (windowCloseTeardownStarted) return;
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("好友功能不可用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void HideFriendsPanel()
    {
        // Detach the in-flight load as well as canceling it. Otherwise a quick
        // reopen is deduplicated against the canceled load, which then reports
        // its own cancellation as "载入好友失败" and never reloads.
        friendsPanelLoadCancellation?.Cancel();
        friendsPanelLoadCancellation = null;
        friendsPanel.IsVisible = false;
        friendsStatusText.Text = string.Empty;
    }

    private async Task RefreshFriendsPanelAsync()
    {
        if (friendsPanelLoadCancellation != null ||
            onlineAccountHost?.Session.IsAuthenticated != true)
            return;
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
        friendsPanelLoadCancellation = timeout;
        try
        {
            var directory =
                await onlineAccountHost.Session.GetFriendsAsync(timeout.Token);
            if (!ReferenceEquals(friendsPanelLoadCancellation, timeout) ||
                !friendsPanel.IsVisible)
                return;
            friendsOnlineCountText.Text = AvaloniaLocalizationCatalog.Format("在线 {0:N0}", directory.OnlineCount);
            friendInviteButtons.Clear();
            friendsList.ItemsSource = directory.Players;
            friendsStatusText.Text = directory.Players.Count == 0
                ? "暂无互相关注的好友"
                : AvaloniaLocalizationCatalog.Format("共 {0:N0} 名好友", directory.Players.Count);
        }
        catch (OperationCanceledException) when (
            !ReferenceEquals(friendsPanelLoadCancellation, timeout) ||
            !friendsPanel.IsVisible)
        {
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            if (ReferenceEquals(friendsPanelLoadCancellation, timeout))
                friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("载入好友失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
        }
        finally
        {
            if (ReferenceEquals(friendsPanelLoadCancellation, timeout))
                friendsPanelLoadCancellation = null;
        }
    }

    private async Task InviteFriendToCurrentRoomAsync(
        OnlinePlayerProfileDto friend,
        Button inviteButton)
    {
        var session = onlineAccountHost?.Session;
        if (session?.CurrentRoom == null)
        {
            friendsStatusText.Text = "请先进入联机房间";
            return;
        }
        inviteButton.IsEnabled = false;
        friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("正在邀请 {0}…", friend.DisplayName);
        try
        {
            using var timeout =
                new CancellationTokenSource(TimeSpan.FromSeconds(15));
            _ = await session.InviteToCurrentRoomAsync(
                friend.Id,
                timeout.Token);
            friendInviteCooldowns[friend.Id] =
                DateTimeOffset.UtcNow.AddSeconds(15);
            ApplyFriendInviteCooldown(friend.Id, inviteButton);
            if (!friendInviteCooldownTimer.IsEnabled)
                friendInviteCooldownTimer.Start();
            friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("已邀请 {0}", friend.DisplayName);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("邀请失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            inviteButton.IsEnabled = session.CurrentRoom != null;
        }
    }

    private void RefreshFriendInviteCooldownButtons()
    {
        foreach (var pair in friendInviteButtons.ToArray())
            ApplyFriendInviteCooldown(pair.Key, pair.Value);
        if (friendInviteCooldowns.Count == 0)
            friendInviteCooldownTimer.Stop();
    }

    private void ApplyFriendInviteCooldown(long userId, Button button)
    {
        if (friendInviteCooldowns.TryGetValue(userId, out var until))
        {
            var remaining = until - DateTimeOffset.UtcNow;
            if (remaining > TimeSpan.Zero)
            {
                button.Content = $"{Math.Max(1, (int)Math.Ceiling(remaining.TotalSeconds))}s";
                button.IsEnabled = false;
                return;
            }
            friendInviteCooldowns.Remove(userId);
        }

        button.Content = "邀请";
        var session = onlineAccountHost?.Session;
        button.IsEnabled = session?.CurrentRoom != null &&
                           session.CurrentUser?.Id != userId &&
                           button.Tag is true;
    }

