    private async Task ShowOnlinePlayerPopupAsync(
        long userId,
        OnlineRoomMemberDto? roomMember)
    {
        var session = onlineAccountHost?.Session;
        if (userId <= 0 || session?.IsAuthenticated != true) return;

        onlinePlayerPopupLoadCancellation?.Cancel();
        onlinePlayerPopupLoadCancellation?.Dispose();
        var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        onlinePlayerPopupLoadCancellation = timeout;
        onlinePlayerPopupUserId = userId;
        onlinePlayerPopupLayer.IsVisible = true;
        SetOnlinePlayerPopupContent(BuildOnlinePlayerLoadingCard("正在载入玩家主页…"));
        try
        {
            var profile = await session.GetPlayerAsync(
                userId,
                roomMember == null ? null : session.CurrentRoom?.Id,
                timeout.Token);
            if (!ReferenceEquals(onlinePlayerPopupLoadCancellation, timeout) ||
                onlinePlayerPopupUserId != userId)
                return;
            SetOnlinePlayerPopupContent(BuildOnlinePlayerCard(profile, roomMember));
        }
        catch (OperationCanceledException) when (
            !ReferenceEquals(onlinePlayerPopupLoadCancellation, timeout) ||
            onlinePlayerPopupUserId != userId)
        {
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            if (ReferenceEquals(onlinePlayerPopupLoadCancellation, timeout))
                SetOnlinePlayerPopupContent(
                    BuildOnlinePlayerLoadingCard(AvaloniaLocalizationCatalog.Format("载入玩家主页失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message))));
        }
    }

    private void SetOnlinePlayerPopupContent(Control content)
    {
        onlinePlayerPopupContent.Children.Clear();
        onlinePlayerPopupContent.Children.Add(content);
    }

    private Control BuildOnlinePlayerLoadingCard(string message)
