    private Control BuildOnlinePlayerCard(
        OnlinePlayerProfileDto profile,
        OnlineRoomMemberDto? initialRoomMember)
    {
        var session = onlineAccountHost?.Session ??
                      throw new InvalidOperationException("联机账号会话不可用。");
        var roomMember = initialRoomMember;
        var status = new TextBlock
        {
            Text = profile.IsOnline ? "当前在线" : "当前离线",
            Foreground = new SolidColorBrush(Color.Parse(
                profile.IsOnline ? "#8FC4A5" : "#788589")),
            FontSize = 9,
            Margin = new Thickness(0, 8, 0, 0),
            TextWrapping = TextWrapping.Wrap
        };
        var close = CompactOnlineActionButton("×");
        close.Width = 26;
        close.Height = 24;
        close.HorizontalAlignment = HorizontalAlignment.Right;
        close.VerticalAlignment = VerticalAlignment.Top;
        close.Click += (_, _) => CloseOnlinePlayerPopup();

        var avatar = new WindowsDefaultUserAvatar(
            62,
            new SolidColorBrush(Color.Parse("#59666A")),
            1,
            $"Online.PlayerPopup.{profile.Id}.Avatar");
        BindRemoteAvatar(avatar, profile.AvatarKey, profile.DisplayName);
        var identity = new StackPanel
        {
            Margin = new Thickness(10, 0, 0, 0),
            VerticalAlignment = VerticalAlignment.Center,
            Spacing = 4,
            Children =
            {
                new TextBlock
                {
                    Text = profile.DisplayName,
                    Foreground = new SolidColorBrush(Color.Parse("#E1E6E7")),
                    FontSize = 19,
                    FontWeight = FontWeight.SemiBold,
                    TextTrimming = TextTrimming.CharacterEllipsis
                },
                new TextBlock
                {
                    Text = AvaloniaLocalizationCatalog.Format("关注 {0:N0} · 粉丝 {1:N0} · 制谱 {2}", profile.FollowingCount, profile.FollowerCount, FormatOnlineChartingDuration(profile.ChartingSeconds)),
                    Foreground = new SolidColorBrush(Color.Parse("#839397")),
                    FontSize = 11,
                    TextWrapping = TextWrapping.Wrap
                }
            }
        };
        var titleRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,Auto")
        };
        titleRow.Children.Add(new TextBlock
        {
            Text = "玩家主页",
            Foreground = new SolidColorBrush(Color.Parse("#829B9E")),
            FontSize = 10,
            FontWeight = FontWeight.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        });
        Grid.SetColumn(close, 1);
        titleRow.Children.Add(close);
        var header = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("72,*"),
            Margin = new Thickness(0, 12, 0, 0)
        };
        header.Children.Add(avatar);
        Grid.SetColumn(identity, 1);
        header.Children.Add(identity);

        var body = new StackPanel();
        body.Children.Add(titleRow);
        body.Children.Add(header);
        body.Children.Add(new TextBlock
        {
            Text = string.IsNullOrWhiteSpace(profile.Bio) ? "暂无简介" : profile.Bio,
            Foreground = new SolidColorBrush(Color.Parse("#ABB5B8")),
            Margin = new Thickness(0, 14, 0, 0),
            MinHeight = 42,
            TextWrapping = TextWrapping.Wrap
        });

        Button? follow = null;
        if (session.CurrentUser?.Id != profile.Id)
        {
            Button followButton = null!;
            followButton = PrimaryButton(
                profile.IsFollowing ? "取消关注" : "关注",
                async (_, _) =>
                {
                    if (!followButton.IsEnabled) return;
                    followButton.IsEnabled = false;
                    status.Text = profile.IsFollowing ? "正在取消关注…" : "正在关注…";
                    try
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                        await session.SetFollowAsync(profile.Id, !profile.IsFollowing, timeout.Token);
                        // The change is committed server-side now. Flip the local
                        // state before the refresh: if the refresh fails, the button
                        // must not keep offering the action that just succeeded,
                        // where a second click would silently undo it.
                        profile = profile with { IsFollowing = !profile.IsFollowing };
                        followButton.Content = profile.IsFollowing ? "取消关注" : "关注";
                        var refreshed = await session.GetPlayerAsync(
                            profile.Id,
                            roomMember == null ? null : session.CurrentRoom?.Id,
                            timeout.Token);
                        if (onlinePlayerPopupUserId == profile.Id)
                            SetOnlinePlayerPopupContent(
                                BuildOnlinePlayerCard(refreshed, roomMember));
                    }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or
                            OperationCanceledException or JsonException)
                    {
                        status.Text = exception.Message;
                        status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
                        followButton.IsEnabled = true;
                    }
                });
            follow = followButton;
            follow.HorizontalAlignment = HorizontalAlignment.Stretch;
            ApplyOnlinePlayerPrimaryButtonStyle(follow, 36);
        }

        var currentRoom = session.CurrentRoom;
        var canManage = roomMember != null &&
                        currentRoom?.OwnerUserId == session.CurrentUser?.Id &&
                        roomMember.UserId != session.CurrentUser?.Id &&
                        // Static Equals: a server DTO may omit the role.
                        !string.Equals(roomMember.MemberRole, "owner", StringComparison.OrdinalIgnoreCase);
        if (canManage && roomMember != null)
        {
            var memberRole = string.Equals(
                roomMember.MemberRole,
                "viewer",
                StringComparison.OrdinalIgnoreCase)
                ? "viewer"
                : "editor";
            var metadata = PlayerPermissionCheckBox(
                "允许编辑谱面信息",
                roomMember.CanEditMetadata,
                $"Online.PlayerPopup.{profile.Id}.Metadata");
            var timing = PlayerPermissionCheckBox(
                "允许编辑 Effect（Timing Edit 全部功能）",
                roomMember.CanEditTiming,
                $"Online.PlayerPopup.{profile.Id}.Timing");
            var notes = PlayerPermissionCheckBox(
                "允许编辑 Note",
                roomMember.CanEditNotes,
                $"Online.PlayerPopup.{profile.Id}.Notes");
            metadata.Margin = new Thickness(0, 9, 0, 0);
            timing.Margin = new Thickness(0, 7, 0, 0);
            notes.Margin = new Thickness(0, 7, 0, 0);
            Button roleButton = null!;
            roleButton = PrimaryButton(
                memberRole == "viewer" ? "设为编辑者" : "设为观察者",
                async (_, _) =>
                {
                    roleButton.IsEnabled = false;
                    var nextRole = memberRole == "viewer" ? "editor" : "viewer";
                    status.Text = nextRole == "viewer" ? "正在设为观察者…" : "正在设为编辑者…";
                    try
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                        var allowMetadata = nextRole == "editor" && metadata.IsChecked == true;
                        var allowTiming = nextRole == "editor" && timing.IsChecked == true;
                        var allowNotes = nextRole == "editor" && notes.IsChecked == true;
                        await session.UpdateRoomMemberAccessAsync(
                            profile.Id,
                            nextRole,
                            allowMetadata,
                            allowTiming,
                            allowNotes,
                            timeout.Token);
                        memberRole = nextRole;
                        roomMember = roomMember with
                        {
                            MemberRole = nextRole,
                            CanEditMetadata = allowMetadata,
                            CanEditTiming = allowTiming,
                            CanEditNotes = allowNotes
                        };
                        ReplaceOnlineCreatorMember(roomMember);
                        metadata.IsChecked = allowMetadata;
                        timing.IsChecked = allowTiming;
                        notes.IsChecked = allowNotes;
                        var editor = memberRole == "editor";
                        metadata.IsEnabled = editor;
                        timing.IsEnabled = editor;
                        notes.IsEnabled = editor;
                        roleButton.Content = editor ? "设为观察者" : "设为编辑者";
                        status.Text = editor ? "已设为编辑者" : "已设为观察者";
                    }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or
                            OperationCanceledException or JsonException)
                    {
                        status.Text = exception.Message;
                        status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
                    }
                    finally
                    {
                        roleButton.IsEnabled = true;
                    }
                });
            roleButton.HorizontalAlignment = HorizontalAlignment.Stretch;
            ApplyOnlinePlayerSecondaryButtonStyle(roleButton, 36);

            Button save = null!;
            save = PrimaryButton(
                "保存房间权限",
                async (_, _) =>
                {
                    save.IsEnabled = false;
                    status.Text = "正在保存房间权限…";
                    try
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                        await session.UpdateRoomMemberAccessAsync(
                            profile.Id,
                            memberRole,
                            metadata.IsChecked == true,
                            timing.IsChecked == true,
                            notes.IsChecked == true,
                            timeout.Token);
                        roomMember = roomMember with
                        {
                            CanEditMetadata = metadata.IsChecked == true,
                            CanEditTiming = timing.IsChecked == true,
                            CanEditNotes = notes.IsChecked == true
                        };
                        ReplaceOnlineCreatorMember(roomMember);
                        status.Text = "房间权限已保存";
                    }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or
                            OperationCanceledException or JsonException)
                    {
                        status.Text = exception.Message;
                        status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
                    }
                    finally
                    {
                        save.IsEnabled = true;
                    }
                });
            save.HorizontalAlignment = HorizontalAlignment.Stretch;
            save.Margin = new Thickness(0, 10, 0, 0);
            ApplyOnlinePlayerPrimaryButtonStyle(save, 34);

            var permissionPanel = new Border
            {
                Margin = new Thickness(0, 10, 0, 0),
                Padding = new Thickness(11),
                Background = new SolidColorBrush(Color.Parse("#20272A")),
                BorderBrush = new SolidColorBrush(Color.Parse("#425256")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Child = new StackPanel
                {
                    Children =
                    {
                        new TextBlock
                        {
                            Text = "房间编辑权限 · 由房主持久分配",
                            Foreground = new SolidColorBrush(Color.Parse("#9DB7B9")),
                            FontSize = 10,
                            FontWeight = FontWeight.SemiBold
                        },
                        metadata,
                        timing,
                        notes,
                        save
                    }
                }
            };
            var isEditor = memberRole == "editor";
            metadata.IsEnabled = isEditor;
            timing.IsEnabled = isEditor;
            notes.IsEnabled = isEditor;
            var actions = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,*"),
                Margin = new Thickness(0, 14, 0, 0)
            };
            if (follow != null)
            {
                follow.Margin = new Thickness(0, 0, 4, 0);
                actions.Children.Add(follow);
                roleButton.Margin = new Thickness(4, 0, 0, 0);
                Grid.SetColumn(roleButton, 1);
            }
            else
            {
                Grid.SetColumnSpan(roleButton, 2);
            }
            actions.Children.Add(roleButton);
            body.Children.Add(actions);
            body.Children.Add(permissionPanel);

            var kick = PrimaryButton(
                "踢出",
                async (_, _) => await RemoveOnlinePlayerFromRoomAsync(
                    profile,
                    banMinutes: 0,
                    status));
            var ban = PrimaryButton(
                "暂时封禁 30 分钟",
                async (_, _) => await RemoveOnlinePlayerFromRoomAsync(
                    profile,
                    banMinutes: 30,
                    status));
            foreach (var button in new[] { kick, ban })
            {
                ApplyOnlinePlayerDangerButtonStyle(button, 34);
                button.HorizontalAlignment = HorizontalAlignment.Stretch;
            }
            var danger = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,*"),
                Margin = new Thickness(0, 8, 0, 0)
            };
            kick.Margin = new Thickness(0, 0, 4, 0);
            ban.Margin = new Thickness(4, 0, 0, 0);
            danger.Children.Add(kick);
            Grid.SetColumn(ban, 1);
            danger.Children.Add(ban);
            body.Children.Add(danger);
        }

        if (!canManage && follow != null)
        {
            follow.Margin = new Thickness(0, 14, 0, 0);
            body.Children.Add(follow);
        }

        body.Children.Add(status);
        return OnlinePlayerPopupCard(new ScrollViewer
        {
            MaxHeight = 704,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            Content = body
        });
    }

    private static CheckBox PlayerPermissionCheckBox(
        string text,
        bool value,
        string automationId)
    {
        var checkBox = new CheckBox
        {
            Content = text,
            IsChecked = value,
            Foreground = new SolidColorBrush(Color.Parse("#E1E6E7")),
            FontSize = 11
        };
        AutomationProperties.SetAutomationId(checkBox, automationId);
        return checkBox;
    }

    private static Control OnlinePlayerPopupCard(Control content) => new Border
    {
        Width = 390,
        MaxWidth = 390,
        MaxHeight = 740,
        Padding = new Thickness(18),
        Background = new SolidColorBrush(Color.Parse("#1A1F22")),
        BorderBrush = new SolidColorBrush(Color.Parse("#465358")),
        BorderThickness = new Thickness(1),
        CornerRadius = new CornerRadius(7),
        Child = content
    };

    private static void ApplyOnlinePlayerPrimaryButtonStyle(Button button, double height)
    {
        button.Height = height;
        button.Padding = new Thickness(9, 6);
        button.Background = new SolidColorBrush(Color.Parse("#38676C"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#4A777B"));
        button.Foreground = Brushes.White;
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(3);
        button.FontWeight = FontWeight.SemiBold;
    }

    private static void ApplyOnlinePlayerSecondaryButtonStyle(Button button, double height)
    {
        button.Height = height;
        button.Padding = new Thickness(9, 6);
        button.Background = new SolidColorBrush(Color.Parse("#1A1D20"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#34393D"));
        button.Foreground = new SolidColorBrush(Color.Parse("#D0D4D6"));
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(3);
    }

    private static void ApplyOnlinePlayerDangerButtonStyle(Button button, double height)
    {
        button.Height = height;
        button.Padding = new Thickness(9, 6);
        button.Background = new SolidColorBrush(Color.Parse("#4A292B"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#754548"));
        button.Foreground = new SolidColorBrush(Color.Parse("#FFD8D8"));
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(3);
        button.FontWeight = FontWeight.SemiBold;
    }

    private async Task RemoveOnlinePlayerFromRoomAsync(
        OnlinePlayerProfileDto profile,
        int banMinutes,
        TextBlock status)
    {
        var session = onlineAccountHost?.Session;
        if (session?.CurrentRoom == null) return;
        status.Text = banMinutes > 0 ? "正在暂时封禁并移出…" : "正在移出房间…";
        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
            await session.RemoveRoomMemberAsync(profile.Id, banMinutes, timeout.Token);
            onlineCreatorMembers = onlineCreatorMembers
                .Where(member => member.UserId != profile.Id)
                .ToArray();
            roomMemberList.ItemsSource = onlineCreatorMembers;
            RefreshTimelineOnlineCreators();
            CloseOnlinePlayerPopup();
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            status.Text = exception.Message;
            status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
        }
    }

    private void ReplaceOnlineCreatorMember(OnlineRoomMemberDto updated)
    {
        onlineCreatorMembers = onlineCreatorMembers
            .Select(member => member.UserId == updated.UserId ? updated : member)
            .ToArray();
        // Re-selecting only keeps the list highlight on the open card. It must
        // not raise the card reload, which would rebuild the popup and discard
        // the permission feedback the caller shows next.
        suppressRoomMemberSelectionChanged = true;
        try
        {
            roomMemberList.ItemsSource = onlineCreatorMembers;
            roomMemberList.SelectedItem = updated;
        }
        finally
        {
            suppressRoomMemberSelectionChanged = false;
        }
        RefreshTimelineOnlineCreators();
    }

    private void CloseOnlinePlayerPopup()
    {
        onlinePlayerPopupLoadCancellation?.Cancel();
        onlinePlayerPopupLoadCancellation?.Dispose();
        onlinePlayerPopupLoadCancellation = null;
        onlinePlayerPopupUserId = 0;
        onlinePlayerPopupLayer.IsVisible = false;
        onlinePlayerPopupContent.Children.Clear();
        roomMemberList.SelectedItem = null;
        timeline.Focus();
    }

    private static string FormatOnlineChartingDuration(long seconds)
    {
        var duration = TimeSpan.FromSeconds(Math.Max(0, seconds));
        return duration.TotalHours >= 1
            ? AvaloniaLocalizationCatalog.Format("{0:N0} 小时 {1:N0} 分钟", (int)duration.TotalHours, duration.Minutes)
            : AvaloniaLocalizationCatalog.Format("{0:N0} 分钟", duration.Minutes);
    }

