        var hint = new TextBlock
        {
            Text = AvaloniaLocalizationCatalog.Format("默认使用音频文件名。重名会自动追加 _1、_2；清空后使用时间戳。谱面先在软件旁缓存编辑，点击保存才写回曲库目录。"),
            Foreground = new SolidColorBrush(Color.Parse("#7F8D91")),
