        ApplyWpfToolButtonStyle(close);
        AutomationProperties.SetAutomationId(close, "About.Close");

        var header = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") };
#if LUMACHART_SHARED
        header.ColumnDefinitions = new ColumnDefinitions("*");
        header.RowDefinitions = new RowDefinitions("Auto,Auto");
#endif
        header.Children.Add(new StackPanel
        {
            Children =
            {
                aboutTitleText,
                aboutVersionText
            }
        });
        aboutTitleText.Text = "关于原作者";
        aboutTitleText.FontSize = 22;
        aboutTitleText.FontWeight = FontWeight.SemiBold;
        aboutTitleText.Foreground = new SolidColorBrush(Color.Parse("#E3E8E9"));
        AutomationProperties.SetAutomationId(aboutTitleText, "About.Title");
        Grid.SetColumn(close, 1);
        header.Children.Add(close);

        var bilibili = PrimaryButton("B站个人主页", (_, _) =>
