    private void OnlineAccountSession_NotificationsReceived(
        object? sender,
        OnlineUserNotificationsReceivedEventArgs eventArgs)
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() =>
                OnlineAccountSession_NotificationsReceived(sender, eventArgs));
            return;
        }
        if (windowCloseTeardownStarted ||
            onlineAccountHost?.Session.CurrentUser?.Id != eventArgs.UserId)
            return;
        foreach (var notification in eventArgs.Notifications.OrderBy(item => item.Id))
        {
            // A notification without a type is ignored rather than dereferenced.
            var message = (notification.Type ?? string.Empty).ToLowerInvariant() switch
            {
                "follow" => WindowsTransientToastParityPolicy.FormatFollowNotification(
                    notification.ActorDisplayName),
                "room_invite_accepted" =>
                    AvaloniaLocalizationCatalog.Format("{0} 已同意加入“{1}”", notification.ActorDisplayName, notification.ContextText),
                "room_invite_rejected" =>
                    AvaloniaLocalizationCatalog.Format("{0} 已拒绝加入“{1}”", notification.ActorDisplayName, notification.ContextText),
                _ => string.Empty
            };
            if (!string.IsNullOrWhiteSpace(message))
                EnqueueOnlineNotificationToast(message);
        }
    }

    private void EnqueueFollowNotificationToast(string? actorDisplayName)
        => EnqueueOnlineNotificationToast(
            WindowsTransientToastParityPolicy.FormatFollowNotification(actorDisplayName));

    private void EnqueueOnlineNotificationToast(string message)
    {
        followNotificationToastQueue.Enqueue(message);
        UpdateFollowNotificationToastAutomation();
        if (!followNotificationToastVisible) ShowNextFollowNotificationToast();
    }

    private void ShowNextFollowNotificationToast()
    {
        if (windowCloseTeardownStarted ||
            followNotificationToastQueue.Count == 0)
            return;
        followNotificationToastText.Text =
            followNotificationToastQueue.Dequeue();
        followNotificationToast.IsVisible = true;
        followNotificationToastVisible = true;
        followNotificationToastTimer.Stop();
        followNotificationToastTimer.Start();
        UpdateFollowNotificationToastAutomation();
    }

    private void AdvanceFollowNotificationToast()
    {
        followNotificationToastTimer.Stop();
        followNotificationToast.IsVisible = false;
        followNotificationToastVisible = false;
        UpdateFollowNotificationToastAutomation();
        ShowNextFollowNotificationToast();
    }

    private void ResetFollowNotificationToastUi()
    {
        followNotificationToastTimer.Stop();
        followNotificationToastQueue.Clear();
        followNotificationToastText.Text = string.Empty;
        followNotificationToast.IsVisible = false;
        followNotificationToastVisible = false;
        UpdateFollowNotificationToastAutomation();
    }

    private void UpdateFollowNotificationToastAutomation() =>
        AutomationProperties.SetHelpText(
            followNotificationToast,
            $"Visible={followNotificationToast.IsVisible}; " +
            $"Message={followNotificationToastText.Text}; " +
            $"DurationMilliseconds={WindowsTransientToastParityPolicy.FollowDurationMilliseconds}; " +
            $"Width={WindowsTransientToastParityPolicy.OnlineToastWidth:R}; " +
            $"Top={WindowsTransientToastParityPolicy.OnlineToastTopMargin:R}; " +
            $"Right={WindowsTransientToastParityPolicy.OnlineToastRightMargin:R}; " +
            $"Pending={followNotificationToastQueue.Count}");

