        workspaceText.TextTrimming = TextTrimming.CharacterEllipsis;
        header.Children.Add(heading);

#if LUMACHART_SHARED
        // Equal-width columns stretched each action to a quarter of the whole
        // header and pushed the fifth onto a ragged second row. Flowing them at
        // their natural width keeps one tidy row on a tablet and still wraps
        // cleanly on a narrower surface.
        var headerActions = new WrapPanel
        {
            Orientation = Orientation.Horizontal,
            VerticalAlignment = VerticalAlignment.Center
        };
#else
        var headerActions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 0,
            VerticalAlignment = VerticalAlignment.Center
        };
#endif
        void AddHeaderAction(Button action)
        {
#if LUMACHART_SHARED
            action.HorizontalAlignment = HorizontalAlignment.Left;
            action.HorizontalContentAlignment = HorizontalAlignment.Center;
            // One shared minimum makes the equal-length labels line up as a row
            // of matching buttons, while a longer label may still grow.
            action.MinWidth = 128;
            action.MinHeight = 44;
            action.Margin = new Thickness(0, 0, 10, 10);
#endif
