        };
        librarySearchBox.PlaceholderText = string.Empty;
        librarySearchBox.Background = Brushes.Transparent;
        librarySearchBox.Foreground = new SolidColorBrush(
            Color.Parse(WindowsLibraryLayoutPolicy.SearchForeground));
        librarySearchBox.CaretBrush = new SolidColorBrush(
            Color.Parse(WindowsLibraryLayoutPolicy.SearchCaret));
        librarySearchBox.BorderThickness = new Thickness(0);
        librarySearchBox.Padding = new Thickness(0, 9);
        librarySearchBox.Margin = new Thickness(40, 0, 10, 0);
        librarySearchBox.FontSize = WindowsLibraryLayoutPolicy.SearchFontSize;
        librarySearchBox.VerticalContentAlignment = VerticalAlignment.Center;
