            librarySearchBox,
            "搜索标题、原文、作者、版本或路径；中文输入法组合文本按正常失焦提交，不依赖 Enter。");
        librarySearchBox.TextChanged += (_, _) => viewModel.SetLibrarySearch(librarySearchBox.Text);
        var searchHost = new Border
        {
            Margin = new Thickness(
                0,
                0,
                WindowsLibraryLayoutPolicy.SearchSortGap,
                12),
            Background = new SolidColorBrush(Color.Parse("#1A1E21")),
            BorderBrush = new SolidColorBrush(Color.Parse("#343B3F")),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(4),
            Child = new Grid
            {
                Children =
                {
                    new TextBlock
                    {
                        Text = "⌕",
                        FontSize = 19,
                        Foreground = new SolidColorBrush(Color.Parse("#849095")),
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(12, 0, 0, 1),
                        IsHitTestVisible = false
                    },
                    librarySearchBox
                }
            }
        };
        filters.Children.Add(searchHost);
        var sortChoices = new[]
        {
            new LibrarySortChoice("添加时间：新到旧", DesktopLibrarySort.AddedDescending),
            new LibrarySortChoice("添加时间：旧到新", DesktopLibrarySort.AddedAscending),
            new LibrarySortChoice("标题：A → Z", DesktopLibrarySort.TitleAscending),
            new LibrarySortChoice("标题：Z → A", DesktopLibrarySort.TitleDescending)
        };
        librarySortBox.ItemsSource = sortChoices;
        librarySortBox.SelectedItem = sortChoices.First(choice => choice.Sort == viewModel.LibrarySort);
        librarySortBox.Background = new SolidColorBrush(
            Color.Parse(WindowsLibraryLayoutPolicy.SortBackground));
        librarySortBox.Foreground = new SolidColorBrush(
            Color.Parse(WindowsLibraryLayoutPolicy.SortForeground));
        librarySortBox.BorderBrush = new SolidColorBrush(
            Color.Parse(WindowsLibraryLayoutPolicy.SortBorder));
        librarySortBox.BorderThickness = new Thickness(1);
        librarySortBox.Padding = new Thickness(10, 7);
