#else
        libraryView.Children.Add(filters);
        #endif

#if LUMACHART_SHARED
        tabletLibraryCards.HorizontalAlignment = HorizontalAlignment.Stretch;
        tabletLibraryCards.Margin = new Thickness(0, 0, 0, 16);
        tabletLibraryScroll.HorizontalContentAlignment = HorizontalAlignment.Stretch;
        tabletLibraryScroll.Content = tabletLibraryCards;
        tabletLibraryScroll.HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled;
        tabletLibraryScroll.VerticalScrollBarVisibility = ScrollBarVisibility.Auto;
        tabletLibraryScroll.Margin = new Thickness(24, 0, 24, 0);
        AutomationProperties.SetAutomationId(tabletLibraryScroll, "Library.TabletScroll");
        AutomationProperties.SetAutomationId(tabletLibraryCards, "Library.TabletCards");
        Grid.SetRow(tabletLibraryScroll, 2);
        libraryView.Children.Add(tabletLibraryScroll);
#else
        libraryList.Margin = WindowsLibraryLayoutPolicy.ContentMargin;
        libraryList.Background = Brushes.Transparent;
        libraryList.BorderThickness = new Thickness(0);
        libraryList.SelectionMode = SelectionMode.Multiple;
        ScrollViewer.SetBringIntoViewOnFocusChange(
            libraryList,
            WindowsLibraryLayoutPolicy.BringFocusedFolderIntoView);
        ConfigureLibraryListItemStyles();
        AutomationProperties.SetAutomationId(libraryList, "Library.List");
        // The ListBox virtualizes its ListBoxItem containers. The container
        // template below owns one stable LibraryFolderCard and binds it to the
        // container's current Content. This is intentionally not a
        // FuncDataTemplate: Avalonia 12 can recycle the container while
        // rebuilding a recyclable FuncDataTemplate child on every rebind.
        // Re-apply the independent font scale after every newly prepared
        // container so cards materialized by scrolling use the same stable
        // baseline multiplier as already visible content.
        libraryList.ContainerPrepared += (_, eventArgs) =>
        {
            ConfigureLibraryListItemAutomation(eventArgs.Container, eventArgs.Index);
            QueueDisplayScaleMaterializedContentScan();
        };
        // Register before the shared ContextMenu is attached in the constructor.
        // This handler therefore resolves the exact item and applies WPF's
        // right-click selection rule before Avalonia asks the menu to open.
        libraryList.ContextRequested += LibraryList_ContextRequested;
        libraryList.SelectionChanged += (_, _) => UpdateLibrarySelectionUi();
        libraryList.KeyDown += async (_, eventArgs) =>
        {
            if (eventArgs.Key != Key.Delete || eventArgs.KeyModifiers != KeyModifiers.None) return;
            eventArgs.Handled = true;
            await DeleteSelectedLibraryFoldersAsync();
        };
        Grid.SetRow(libraryList, 2);
