    private ContextMenu CreateLibraryFolderContextMenu()
    {
        var deleteMenuItem = new MenuItem
        {
            Header = "删除此歌曲文件夹",
            Foreground = new SolidColorBrush(Color.Parse("#FFD4D4")),
            Background = Brushes.Transparent,
            Padding = new Thickness(13, 8),
            MinWidth = 190
        };
        deleteMenuItem.Classes.Add("danger");
        AutomationProperties.SetAutomationId(
            deleteMenuItem,
            "Library.DeleteContextMenuItem");
        var contextMenu = new ContextMenu
        {
            ItemsSource = new[] { deleteMenuItem },
            Background = new SolidColorBrush(Color.Parse("#1A1E21")),
            Foreground = new SolidColorBrush(Color.Parse("#E7EAEB")),
            BorderBrush = new SolidColorBrush(Color.Parse("#3A4246")),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(4)
        };
        AutomationProperties.SetAutomationId(contextMenu, "Library.FolderContextMenu");
        popupScaleController.Attach(contextMenu);
        contextMenu.Opening += (_, eventArgs) =>
        {
            var item = pendingLibraryContextMenuItem;
            if (item == null || libraryList.IndexFromContainer(item) < 0)
            {
                pendingLibraryContextMenuItem = null;
                eventArgs.Cancel = true;
                return;
            }
            var index = libraryList.IndexFromContainer(item);
            var count = libraryList.Selection.IsSelected(index)
                ? libraryList.SelectedItems?.OfType<DesktopLibraryFolderView>().Count() ?? 0
                : 1;
            deleteMenuItem.Header = count > 1
                ? AvaloniaLocalizationCatalog.Format("删除所选 {0} 个歌曲文件夹", count)
                : "删除此歌曲文件夹";
        };
        contextMenu.Closed += (_, _) => pendingLibraryContextMenuItem = null;
        deleteMenuItem.Click += async (_, _) => await DeleteSelectedLibraryFoldersAsync();
        return contextMenu;
    }

    private ContextMenu CreateLibraryChartContextMenu(DesktopLibraryChartEntry chart)
    {
        var reveal = new MenuItem
        {
            Header = "在文件资源管理器中打开",
            Background = Brushes.Transparent,
            Foreground = new SolidColorBrush(Color.Parse("#E7EAEB")),
            Padding = new Thickness(13, 8),
            MinWidth = 190
        };
        AutomationProperties.SetAutomationId(reveal, "Library.ChartReveal");
        reveal.Click += (_, _) => RevealLibraryChart(chart);
        // Shown only where there is a shell file browser to hand the path to.
        // Off Windows this entry could never do anything but report its own
        // failure, which is worse than not offering it.
        reveal.IsVisible = OperatingSystem.IsWindows();

        var delete = new MenuItem
        {
            Header = "删除此谱面",
            Background = Brushes.Transparent,
            Foreground = new SolidColorBrush(Color.Parse("#FFD4D4")),
            Padding = new Thickness(13, 8),
            MinWidth = 190
        };
        delete.Classes.Add("danger");
        AutomationProperties.SetAutomationId(delete, "Library.ChartDelete");
        delete.Click += async (_, _) => await DeleteLibraryChartAsync(chart);

        var contextMenu = new ContextMenu
        {
            ItemsSource = new object[]
            {
                reveal,
                new Separator(),
                delete
            },
            Background = new SolidColorBrush(Color.Parse("#1A1E21")),
            Foreground = new SolidColorBrush(Color.Parse("#E7EAEB")),
            BorderBrush = new SolidColorBrush(Color.Parse("#3A4246")),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(4)
        };
        AutomationProperties.SetAutomationId(
            contextMenu,
            "Library.ChartContextMenu");
        popupScaleController.Attach(contextMenu);
        return contextMenu;
    }

    private void RevealLibraryChart(DesktopLibraryChartEntry chart)
    {
        try
        {
            var fullPath = Path.GetFullPath(chart.ChartPath);
            var start = new ProcessStartInfo("explorer.exe")
            {
                UseShellExecute = true
            };
            start.ArgumentList.Add("/select,");
            start.ArgumentList.Add(fullPath);
            Process.Start(start);
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("无法在文件资源管理器中打开谱面：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private async Task DeleteLibraryChartAsync(DesktopLibraryChartEntry chart)
    {
        if (libraryDeletionInProgress) return;
        var permanentDeletion = IsLibraryDeletionPermanent(chart.ChartPath);
        var plan = DesktopLibraryChartDeletionPlanner.Create(
            viewModel.ResolvedWorkspaceRoot,
            chart,
            CaptureLibraryOpenDocuments(),
            permanentDeletion);
        if (!plan.CanExecute)
        {
            var blocked = new LibraryDeleteConfirmationDialog(
                plan.BlockMessage ?? "当前谱面不能移入回收站。",
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale,
                plan.BlockReason == DesktopLibraryChartDeletionBlockReason.OpenDocument
                    ? "无法删除"
                    : "删除谱面",
                LibraryDeleteDialogTone.Warning,
                LibraryDeleteDialogButtons.Confirm,
                permanentDelete: permanentDeletion);
            lastLibraryDeleteDialogScale = blocked.ScaleDiagnostics;
            await blocked.ShowDialog<LibraryDeleteChoice>(this);
            return;
        }

        var confirmation = new LibraryDeleteConfirmationDialog(
            plan.ConfirmationMessage ?? string.Empty,
            displayScaleSettings.UiScale,
            displayScaleSettings.FontScale,
            "删除谱面",
            LibraryDeleteDialogTone.Question,
            LibraryDeleteDialogButtons.CancelRecycle,
                permanentDelete: plan.PermanentDeletion);
        lastLibraryDeleteDialogScale = confirmation.ScaleDiagnostics;
        var choice = await confirmation.ShowDialog<LibraryDeleteChoice>(this);
        if (choice != LibraryDeleteChoice.Recycle) return;

        // The plan was a snapshot taken before the modal confirmation. Re-plan
        // against the tabs open now; if the chart was opened meanwhile (single
        // instance request, room binding), the target moved, or it would now be
        // deleted permanently instead of recycled, start over so the user sees
        // the block or confirms what will actually happen.
        var confirmedPlan = DesktopLibraryChartDeletionPlanner.Create(
            viewModel.ResolvedWorkspaceRoot,
            chart,
            CaptureLibraryOpenDocuments(),
            IsLibraryDeletionPermanent(chart.ChartPath));
        if (!confirmedPlan.CanExecute ||
            confirmedPlan.PermanentDeletion != plan.PermanentDeletion ||
            !string.Equals(
                confirmedPlan.FullPath,
                plan.FullPath,
                StringComparison.OrdinalIgnoreCase))
        {
            await DeleteLibraryChartAsync(chart);
            return;
        }

        libraryDeletionInProgress = true;
        UpdateLibrarySelectionUi();
        viewModel.CancelLibraryScan();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("正在删除 {0}…", chart.PickerTitle));
        // Owner for the Shell's own "delete permanently?" prompt; read on the
        // UI thread before the worker runs.
        var ownerWindow = TryGetPlatformHandle()?.Handle ?? IntPtr.Zero;
        string? error = null;
        try
        {
            await Task.Run(() =>
            {
                try
                {
                    if (File.Exists(plan.FullPath))
                        WindowsRecycleBinService.MoveToRecycleBin(plan.FullPath!, ownerWindow);
                }
                catch (Exception exception)
                {
                    error = exception.Message;
                }
            });
            await RefreshLibraryWithErrorUiAsync();
            viewModel.SetStatus(error == null
                ? plan.PermanentDeletion
                    ? AvaloniaLocalizationCatalog.Format("已永久删除 {0}", chart.PickerTitle)
                    : AvaloniaLocalizationCatalog.Format("已将 {0} 移入回收站", chart.PickerTitle)
                : AvaloniaLocalizationCatalog.Format("{0} 未能删除", chart.PickerTitle));
            if (error != null)
            {
                var failed = new LibraryDeleteConfirmationDialog(
                    AvaloniaLocalizationCatalog.Format("谱面未能删除：\n\n{0}", error),
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale,
                    "删除失败",
                    LibraryDeleteDialogTone.Warning,
                    LibraryDeleteDialogButtons.Confirm,
                permanentDelete: plan.PermanentDeletion);
                lastLibraryDeleteDialogScale = failed.ScaleDiagnostics;
                await failed.ShowDialog<LibraryDeleteChoice>(this);
            }
        }
        finally
        {
            libraryDeletionInProgress = false;
            UpdateLibrarySelectionUi();
        }
    }

    /// <summary>
    /// Long press stands in for the right-click that deletes a song folder. A
    /// tablet has no right button, and the tablet library is a card list with no
    /// selection model, so without this the delete command cannot be reached at
    /// all. The press stays a candidate until it survives the hold interval
    /// without travelling, leaving ordinary taps and scrolling untouched.
    /// </summary>
    private void AttachLibraryCardLongPress(Control host, DesktopLibraryFolderView view)
    {
        libraryLongPressTimer ??= CreateLibraryLongPressTimer();

        host.AddHandler(
            PointerPressedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.Pointer.Type == PointerType.Mouse) return;
                libraryLongPressFolder = view;
                libraryLongPressOrigin = eventArgs.GetPosition(host);
                libraryLongPressHost = host;
                libraryLongPressTimer?.Start();
            },
            RoutingStrategies.Tunnel);

        host.AddHandler(
            PointerMovedEvent,
            (_, eventArgs) =>
            {
                if (libraryLongPressFolder == null || libraryLongPressHost == null) return;
                var position = eventArgs.GetPosition(libraryLongPressHost);
                // Anything that travels is a scroll, not a hold.
                if (Math.Abs(position.X - libraryLongPressOrigin.X) > 12 ||
                    Math.Abs(position.Y - libraryLongPressOrigin.Y) > 12)
                    CancelLibraryLongPress();
            },
            RoutingStrategies.Tunnel | RoutingStrategies.Bubble);

        host.AddHandler(
            PointerReleasedEvent,
            (_, _) => CancelLibraryLongPress(),
            RoutingStrategies.Tunnel | RoutingStrategies.Bubble);
        host.AddHandler(
            PointerCaptureLostEvent,
            (_, _) => CancelLibraryLongPress(),
            RoutingStrategies.Tunnel | RoutingStrategies.Bubble);
    }

    private DispatcherTimer CreateLibraryLongPressTimer()
    {
        var timer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(500) };
        timer.Tick += (_, _) =>
        {
            var folder = libraryLongPressFolder;
            var host = libraryLongPressHost;
            CancelLibraryLongPress();
            if (folder == null || host == null) return;
            // Two steps like the desktop right-click: the menu, then the
            // confirmation. A tablet has no recycle bin, so the action is a
            // plain, red-flagged delete.
            var deleteItem = new MenuItem
            {
                Header = "删除",
                Foreground = new SolidColorBrush(Color.Parse("#FF8A8A")),
                Background = Brushes.Transparent,
                Padding = new Thickness(13, 8),
                MinWidth = 140
            };
            deleteItem.Classes.Add("danger");
            AutomationProperties.SetAutomationId(deleteItem, "Library.TabletDelete");
            deleteItem.Click += async (_, _) =>
                await DeleteLibraryFoldersAsync([folder.Folder]);
            var menu = new ContextMenu
            {
                ItemsSource = new[] { deleteItem },
                Background = new SolidColorBrush(Color.Parse("#1A1E21")),
                Foreground = new SolidColorBrush(Color.Parse("#E7EAEB")),
                BorderBrush = new SolidColorBrush(Color.Parse("#3A4246")),
                BorderThickness = new Thickness(1),
                Padding = new Thickness(4)
            };
            popupScaleController.Attach(menu);
            menu.Open(host);
        };
        return timer;
    }

    private void CancelLibraryLongPress()
    {
        libraryLongPressTimer?.Stop();
        libraryLongPressFolder = null;
        libraryLongPressHost = null;
    }

    private void LibraryList_ContextRequested(
        object? sender,
        ContextRequestedEventArgs eventArgs)
    {
        var requestedByPointer = eventArgs.TryGetPosition(libraryList, out _);
        var item = (eventArgs.Source as Visual)?
            .FindAncestorOfType<ListBoxItem>(includeSelf: true);
        if (item == null &&
            !requestedByPointer &&
            ReferenceEquals(eventArgs.Source, libraryList) &&
            libraryList.SelectedItem != null)
            item = libraryList.ContainerFromItem(libraryList.SelectedItem) as ListBoxItem;

        var index = item == null ? -1 : libraryList.IndexFromContainer(item);
        pendingLibraryContextMenuItem = index >= 0 ? item : null;
        if (requestedByPointer && index < 0)
        {
            // WPF attaches this menu to each folder card, so a right-click on
            // list whitespace or its scroll chrome must not target a previous
            // selection. Mark only that invalid pointer request handled.
            eventArgs.Handled = true;
            return;
        }
        if (index >= 0 && !libraryList.Selection.IsSelected(index))
            libraryList.SelectedIndex = index;
    }

#if LUMACHART_SHARED
    private void RefreshTabletLibraryCards()
    {
        if (tabletRenderedLibraryFolders.Count == viewModel.LibraryFolders.Count &&
            tabletRenderedLibraryFolders
                .Zip(viewModel.LibraryFolders, ReferenceEquals)
                .All(same => same))
            return;

        tabletRenderedLibraryFolders.Clear();
        tabletLibraryCards.Children.Clear();
        foreach (var view in viewModel.LibraryFolders)
        {
            tabletRenderedLibraryFolders.Add(view);
            var card = new LibraryFolderCard(
                OpenChartAsync,
                CreateLibraryChartContextMenu,
                libraryFolderExpansionState)
            {
                DataContext = view,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Stretch
            };
            var cardHost = new Border
            {
                Background = Brushes.Transparent,
                BorderBrush = new SolidColorBrush(Color.Parse("#34393D")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Padding = new Thickness(0, 8),
                Child = card
            };
            AttachLibraryCardLongPress(cardHost, view);
            tabletLibraryCards.Children.Add(cardHost);
        }
        QueueDisplayScaleMaterializedContentScan();
    }
#endif

    private void ConfigureLibraryListItemStyles()
    {
#if LUMACHART_SHARED
        libraryList.ItemTemplate = new FuncDataTemplate<DesktopLibraryFolderView>(
            (view, _) => new LibraryFolderCard(
                OpenChartAsync,
                CreateLibraryChartContextMenu,
                libraryFolderExpansionState)
            {
                DataContext = view,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Stretch
            },
            supportsRecycling: false);
        libraryList.ItemsPanel = new FuncTemplate<Panel?>(() => new StackPanel());
#else
        var itemTheme = new ControlTheme(typeof(ListBoxItem));
        itemTheme.Setters.Add(new Setter(
            TemplatedControl.TemplateProperty,
            new FuncControlTemplate<ListBoxItem>((_, _) =>
            {
                var card = new LibraryFolderCard(
                    OpenChartAsync,
                    CreateLibraryChartContextMenu,
                    libraryFolderExpansionState)
                {
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    VerticalAlignment = VerticalAlignment.Stretch
                };
                card.Bind(
                    StyledElement.DataContextProperty,
                    new TemplateBinding(ContentControl.ContentProperty));

                var border = new Border { Child = card };
                border.Bind(
                    Border.BackgroundProperty,
                    new TemplateBinding(TemplatedControl.BackgroundProperty));
                border.Bind(
                    Border.BorderBrushProperty,
                    new TemplateBinding(TemplatedControl.BorderBrushProperty));
                border.Bind(
                    Border.BorderThicknessProperty,
                    new TemplateBinding(TemplatedControl.BorderThicknessProperty));
                border.Bind(
                    Border.CornerRadiusProperty,
                    new TemplateBinding(TemplatedControl.CornerRadiusProperty));
                border.Bind(
                    Border.PaddingProperty,
                    new TemplateBinding(ContentControl.PaddingProperty));
                return border;
            })));
        libraryList.ItemContainerTheme = itemTheme;
#endif

        var baseStyle = new Style(selector => selector.OfType<ListBoxItem>());
        baseStyle.Setters.Add(new Setter(TemplatedControl.BackgroundProperty, Brushes.Transparent));
        baseStyle.Setters.Add(new Setter(TemplatedControl.BorderBrushProperty,
            new SolidColorBrush(Color.Parse("#34393D"))));
        baseStyle.Setters.Add(new Setter(TemplatedControl.BorderThicknessProperty, new Thickness(1)));
        baseStyle.Setters.Add(new Setter(TemplatedControl.CornerRadiusProperty, new CornerRadius(3)));
        baseStyle.Setters.Add(new Setter(
            ContentControl.PaddingProperty,
            WindowsLibraryLayoutPolicy.FolderItemPadding));
        baseStyle.Setters.Add(new Setter(Layoutable.MarginProperty, new Thickness(0, 0, 0, 6)));
        baseStyle.Setters.Add(new Setter(ContentControl.HorizontalContentAlignmentProperty,
            HorizontalAlignment.Stretch));
        libraryList.Styles.Add(baseStyle);

        var hoverStyle = new Style(selector =>
            selector.OfType<ListBoxItem>().Class(":pointerover"));
        hoverStyle.Setters.Add(new Setter(TemplatedControl.BackgroundProperty,
            new SolidColorBrush(Color.Parse("#222629"))));
        libraryList.Styles.Add(hoverStyle);

        // Add selected last so a selected item keeps WPF's selected tone while
        // the pointer is over it instead of reverting to the hover tone.
        var selectedStyle = new Style(selector =>
            selector.OfType<ListBoxItem>().Class(":selected"));
        selectedStyle.Setters.Add(new Setter(TemplatedControl.BackgroundProperty,
            new SolidColorBrush(Color.Parse("#293235"))));
        selectedStyle.Setters.Add(new Setter(TemplatedControl.BorderBrushProperty,
            new SolidColorBrush(Color.Parse("#698B8E"))));
        libraryList.Styles.Add(selectedStyle);
    }

    private void ConfigureLibraryListItemAutomation(Control container, int index)
    {
        if (container is not ListBoxItem item) return;
        var view = item.DataContext as DesktopLibraryFolderView;
        if (view == null && index >= 0 && index < viewModel.LibraryFolders.Count)
            view = viewModel.LibraryFolders[index];
        if (view == null) return;
        AutomationProperties.SetAutomationId(item, "Library.FolderItem");
        AutomationProperties.SetName(
            item,
            $"{view.Folder.DisplayTitle} · {view.Folder.RelativeFolderPath}");
        // The stable ListBox owns one shared menu. ContextRequested resolves the
        // current visual container without making a recycled item the popup
        // owner, then applies WPF's right-click selection rule before opening.
    }

    private void UpdateLibrarySelectionUi()
    {
        var count = libraryList.SelectedItems?
            .OfType<DesktopLibraryFolderView>()
            .Count() ?? 0;
        libraryDeleteSelectedButton.Content = count > 0
            ? AvaloniaLocalizationCatalog.Format("删除所选  {0}", count)
            : "删除所选";
        libraryDeleteSelectedButton.IsEnabled = count > 0 && !libraryDeletionInProgress;
    }

    private DesktopLibraryOpenDocumentReference[] CaptureLibraryOpenDocuments() =>
        viewModel.Tabs.Select(tab =>
            new DesktopLibraryOpenDocumentReference(
                tab.DisplayTitle,
                new[] { tab.SourcePath, tab.WorkingPath, tab.Session.Document.FilePath }
                    .Where(path => !string.IsNullOrWhiteSpace(path))
                    .Select(path => path!)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToArray()))
            .ToArray();

    /// <summary>
    /// Whether deleting <paramref name="path"/> cannot be undone: SingleView
    /// (mobile) hosts have no recycle bin at all, and on Windows removable,
    /// network and UNC locations bypass it. The confirmation, the planner copy
    /// and the status line must all say "永久删除" in that case.
    /// </summary>
    private bool IsLibraryDeletionPermanent(string path) =>
        !SupportsDesktopWindowSizing ||
        WindowsRecycleBinService.IsLikelyPermanentDeletion(path);

    private bool IsLibraryFolderDeletionPermanent(
        IReadOnlyList<DesktopLibraryFolderEntry> folders) =>
        !SupportsDesktopWindowSizing ||
        folders.Any(folder => WindowsRecycleBinService.IsLikelyPermanentDeletion(folder.FolderPath));

    private Task DeleteSelectedLibraryFoldersAsync() =>
        DeleteLibraryFoldersAsync(
            libraryList.SelectedItems?
                .OfType<DesktopLibraryFolderView>()
                .Select(view => view.Folder)
                .ToArray() ?? []);

    /// <summary>
    /// Deletion for an explicit folder set. The desktop list supplies its
    /// multi-selection; the tablet has no selection model and supplies the one
    /// folder that was long-pressed. Everything past this point — planning,
    /// confirmation and removal — is the same for both.
    /// </summary>
    private async Task DeleteLibraryFoldersAsync(
        IReadOnlyList<DesktopLibraryFolderEntry> selectedFolders)
    {
        if (libraryDeletionInProgress) return;
        var permanentDeletion = IsLibraryFolderDeletionPermanent(selectedFolders);
        var plan = DesktopLibraryDeletionPlanner.Create(
            viewModel.ResolvedWorkspaceRoot,
            selectedFolders,
            CaptureLibraryOpenDocuments(),
            permanentDeletion);
        lastLibraryDeletionPlan = plan;
        lastLibraryRecycleResults = [];
        lastLibraryRecycleFailures = [];
        lastLibraryDeletionConfirmed = false;
        lastLibraryDeletionCanceled = false;
        if (plan.BlockReason == DesktopLibraryDeletionBlockReason.EmptySelection) return;

        if (!plan.CanExecute)
        {
            var blockedDialog = new LibraryDeleteConfirmationDialog(
                plan.BlockMessage ?? "当前选择不能移入回收站。",
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale,
                plan.BlockReason == DesktopLibraryDeletionBlockReason.OpenDocument
                    ? "无法删除"
                    : "删除歌曲",
                LibraryDeleteDialogTone.Warning,
                LibraryDeleteDialogButtons.Confirm,
                permanentDelete: permanentDeletion);
            lastLibraryDeleteDialogScale = blockedDialog.ScaleDiagnostics;
            await blockedDialog.ShowDialog<LibraryDeleteChoice>(this);
            return;
        }

        var confirmation = new LibraryDeleteConfirmationDialog(
            plan.ConfirmationMessage ?? string.Empty,
            displayScaleSettings.UiScale,
            displayScaleSettings.FontScale,
            "删除歌曲",
            LibraryDeleteDialogTone.Question,
            LibraryDeleteDialogButtons.CancelRecycle,
                permanentDelete: plan.PermanentDeletion);
        lastLibraryDeleteDialogScale = confirmation.ScaleDiagnostics;
        var choice = await confirmation.ShowDialog<LibraryDeleteChoice>(this);
        if (choice != LibraryDeleteChoice.Recycle)
        {
            lastLibraryDeletionCanceled = true;
            return;
        }

        // Re-plan after the modal confirmation: a tab opened meanwhile must
        // still block its folder, and the confirmed targets and recycle-versus-
        // permanent mode must be the ones carried out. Any difference restarts
        // planning and confirmation.
        var confirmedPlan = DesktopLibraryDeletionPlanner.Create(
            viewModel.ResolvedWorkspaceRoot,
            selectedFolders,
            CaptureLibraryOpenDocuments(),
            IsLibraryFolderDeletionPermanent(selectedFolders));
        if (!confirmedPlan.CanExecute ||
            confirmedPlan.PermanentDeletion != plan.PermanentDeletion ||
            !confirmedPlan.Targets
                .Select(target => target.FullPath)
                .SequenceEqual(
                    plan.Targets.Select(target => target.FullPath),
                    StringComparer.OrdinalIgnoreCase))
        {
            await DeleteLibraryFoldersAsync(selectedFolders);
            return;
        }

        lastLibraryDeletionConfirmed = true;
        libraryDeletionInProgress = true;
        UpdateLibrarySelectionUi();
        viewModel.CancelLibraryScan();
        viewModel.SetStatus(plan.PermanentDeletion
            ? AvaloniaLocalizationCatalog.Format("正在永久删除 {0} 个文件夹…", plan.FolderCount)
            : AvaloniaLocalizationCatalog.Format("正在将 {0} 个文件夹移入回收站…", plan.FolderCount));
        // Owner for the Shell's own "delete permanently?" prompt; read on the
        // UI thread before the worker runs.
        var ownerWindow = TryGetPlatformHandle()?.Handle ?? IntPtr.Zero;
        try
        {
            var operation = await Task.Run(() =>
            {
                var results = new List<WindowsRecycleBinOperationResult>();
                var failures = new List<string>();
                foreach (var target in plan.Targets)
                {
                    try
                    {
                        if (Directory.Exists(target.FullPath))
                            results.Add(WindowsRecycleBinService.MoveToRecycleBin(
                                target.FullPath,
                                ownerWindow));
                    }
                    catch (Exception exception)
                    {
                        failures.Add($"{target.Folder.DisplayTitle}：{exception.Message}");
                    }
                }
                return (Results: (IReadOnlyList<WindowsRecycleBinOperationResult>)results,
                    Failures: (IReadOnlyList<string>)failures);
            });
            lastLibraryRecycleResults = operation.Results;
            lastLibraryRecycleFailures = operation.Failures;
            await RefreshLibraryWithErrorUiAsync();
            viewModel.SetStatus(plan.PermanentDeletion
                ? operation.Failures.Count == 0
                    ? AvaloniaLocalizationCatalog.Format("已永久删除 {0} 个歌曲文件夹", operation.Results.Count)
                    : AvaloniaLocalizationCatalog.Format("已永久删除 {0} 个文件夹；{1} 个失败", operation.Results.Count, operation.Failures.Count)
                : operation.Failures.Count == 0
                    ? AvaloniaLocalizationCatalog.Format("已将 {0} 个歌曲文件夹移入回收站", operation.Results.Count)
                    : AvaloniaLocalizationCatalog.Format("已回收 {0} 个文件夹；{1} 个失败", operation.Results.Count, operation.Failures.Count));

            if (operation.Failures.Count > 0)
            {
                var failuresDialog = new LibraryDeleteConfirmationDialog(
                    AvaloniaLocalizationCatalog.Format("有 {0} 个文件夹未能删除：\n\n{1}", operation.Failures.Count, string.Join("\n", operation.Failures.Take(8))),
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale,
                    "部分删除失败",
                    LibraryDeleteDialogTone.Warning,
                    LibraryDeleteDialogButtons.Confirm,
                permanentDelete: plan.PermanentDeletion);
                lastLibraryDeleteDialogScale = failuresDialog.ScaleDiagnostics;
                await failuresDialog.ShowDialog<LibraryDeleteChoice>(this);
            }
        }
        finally
        {
            libraryDeletionInProgress = false;
            UpdateLibrarySelectionUi();
        }
    }

