        inspectorToggleButton.Background = PanelBrush;
        inspectorToggleButton.Foreground = Brushes.White;
        inspectorToggleButton.BorderBrush = StrokeBrush;
        inspectorToggleButton.BorderThickness = new Thickness(1);
        inspectorToggleButton.CornerRadius = new CornerRadius(3);
        ToolTip.SetTip(inspectorToggleButton, "收起右侧面板");
        AutomationProperties.SetAutomationId(inspectorToggleButton, "Inspector.Toggle");
        inspectorToggleButton.Click += (_, _) =>
        {
            var expanded = inspectorPanel.IsVisible;
            inspectorPanel.IsVisible = !expanded;
            workbench.ColumnDefinitions[4].Width = expanded
                ? new GridLength(0)
                : new GridLength(350);
            inspectorToggleButton.Content = expanded ? "+" : "−";
            ToolTip.SetTip(inspectorToggleButton, expanded ? "展开右侧面板" : "收起右侧面板");
        };
        Grid.SetColumn(inspectorToggleButton, 3);
        workbench.Children.Add(inspectorToggleButton);

        // The menu spans the whole workbench and draws above the inspector on
        // its own ZIndex. Confining it to the timeline columns on a tablet
        // would push its right-hand commands, Pro Editor included, off into the
        // horizontal scroller and make them reachable only by collapsing the
        // inspector; a transient menu covering the panel it overlaps is the
        // better trade.
        Grid.SetColumnSpan(commandMenu, 5);
        workbench.Children.Add(commandMenu);
        Grid.SetColumnSpan(commandMenuButton, 5);
        workbench.Children.Add(commandMenuButton);
        var quickPalette = BuildQuickEditPalette();
        var quickValues = BuildQuickValuesPalette();
        var roomCollaboration = BuildRoomCollaborationPanel();
        Grid.SetColumn(quickPalette, 2);
        Grid.SetColumnSpan(quickPalette, WindowsInspectorParityPolicy.FloatingPaletteColumnSpan);
        workbench.Children.Add(quickPalette);
        Grid.SetColumn(quickValues, 2);
        Grid.SetColumnSpan(quickValues, WindowsInspectorParityPolicy.FloatingPaletteColumnSpan);
        workbench.Children.Add(quickValues);
        Grid.SetColumn(roomCollaboration, 2);
        Grid.SetColumnSpan(
            roomCollaboration,
            WindowsInspectorParityPolicy.FloatingPaletteColumnSpan);
        workbench.Children.Add(roomCollaboration);
        var extension = BuildExtensionPalette();
        Grid.SetColumn(extension, 2);
        workbench.Children.Add(extension);
        editorView.Children.Add(workbench);
    }

    private Control BuildTabletInspectorSurface(IReadOnlyList<TabItem> tabs)
    {
        var tabBar = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions(
                string.Join(",", Enumerable.Repeat("*", Math.Max(1, tabs.Count)))),
            ColumnSpacing = 0,
            Margin = new Thickness(4, 4, 4, 0)
        };
        for (var index = 0; index < tabs.Count; index++)
        {
            var tab = tabs[index];
            var header = tab.Header?.ToString() ?? string.Empty;
            var button = new Button
            {
                Content = new TextBlock
                {
                    Text = header,
                    FontSize = 11,
                    TextAlignment = TextAlignment.Center,
                    TextWrapping = TextWrapping.NoWrap,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    VerticalAlignment = VerticalAlignment.Center
                },
                MinWidth = 0,
                Height = 36,
                Padding = new Thickness(3, 0),
                Margin = new Thickness(0),
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Stretch,
                HorizontalContentAlignment = HorizontalAlignment.Center,
                VerticalContentAlignment = VerticalAlignment.Center,
                ClipToBounds = true,
                Background = Brushes.Transparent,
                Foreground = MutedBrush,
                BorderBrush = StrokeBrush,
                BorderThickness = new Thickness(0, 0, 0, 1),
                CornerRadius = new CornerRadius(0)
            };
            button.Click += (_, _) => editorInspectorTabs.SelectedItem = tab;
            AutomationProperties.SetName(button, AvaloniaLocalizationCatalog.Format("{0}面板", tab.Header));
            AutomationProperties.SetAutomationId(
                button,
                $"Tablet.{AutomationProperties.GetAutomationId(tab)}");
            Grid.SetColumn(button, index);
            tabBar.Children.Add(button);
            tabletInspectorButtons[tab] = button;
        }

        tabletInspectorContent.HorizontalContentAlignment = HorizontalAlignment.Stretch;
        tabletInspectorContent.VerticalContentAlignment = VerticalAlignment.Stretch;
        var root = new Grid { RowDefinitions = new RowDefinitions("Auto,*") };
        var textInputStyle = new Style(selector => selector.OfType<TextBox>());
        textInputStyle.Setters.Add(new Setter(Layoutable.MinHeightProperty, 34d));
        root.Styles.Add(textInputStyle);
        var comboInputStyle = new Style(selector => selector.OfType<ComboBox>());
        comboInputStyle.Setters.Add(new Setter(Layoutable.MinHeightProperty, 34d));
        root.Styles.Add(comboInputStyle);
        // The desktop scrollbar is a 3-DIP rail with a 5-DIP thumb, sized for a
        // cursor. Dragging the inspector by that thumb is impractical with a
        // finger, so widen the rail, the grip and the bar's own hit column.
        var scrollBarStyle = new Style(selector => selector
            .OfType<ScrollBar>()
            .Class(":vertical"));
        scrollBarStyle.Setters.Add(new Setter(Layoutable.WidthProperty, 22d));
        root.Styles.Add(scrollBarStyle);
        var scrollRailStyle = new Style(selector => selector
            .OfType<ScrollBar>()
            .Class(":vertical")
            .Template()
            .OfType<global::Avalonia.Controls.Shapes.Rectangle>()
            .Name("TrackRect"));
        scrollRailStyle.Setters.Add(new Setter(Layoutable.WidthProperty, 10d));
        root.Styles.Add(scrollRailStyle);
        var scrollThumbStyle = new Style(selector => selector
            .OfType<ScrollBar>()
            .Class(":vertical")
            .Template()
            .OfType<Thumb>());
        scrollThumbStyle.Setters.Add(new Setter(Layoutable.WidthProperty, 14d));
        scrollThumbStyle.Setters.Add(new Setter(Layoutable.MinHeightProperty, 52d));
        scrollThumbStyle.Setters.Add(new Setter(
            TemplatedControl.CornerRadiusProperty,
            new CornerRadius(7)));
        root.Styles.Add(scrollThumbStyle);
        root.Children.Add(tabBar);
        Grid.SetRow(tabletInspectorContent, 1);
        root.Children.Add(tabletInspectorContent);
        UpdateTabletInspectorSelection();
        return root;
    }

    private void UpdateTabletInspectorSelection()
    {
        var selected = editorInspectorTabs.SelectedItem as TabItem ?? timingInspectorTab;
        if (tabletInspectorContents.TryGetValue(selected, out var content) &&
            !ReferenceEquals(tabletInspectorContent.Content, content))
            tabletInspectorContent.Content = content;

        foreach (var pair in tabletInspectorButtons)
        {
            var active = ReferenceEquals(pair.Key, selected);
            pair.Value.Background = active ? RaisedBrush : Brushes.Transparent;
            pair.Value.Foreground = active ? Brushes.White : MutedBrush;
            pair.Value.BorderBrush = active ? AccentBrush : StrokeBrush;
            pair.Value.BorderThickness = new Thickness(0, 0, 0, active ? 2 : 1);
        }
    }

    private Control BuildOverviewPanel()
    {
        editorOverview.Margin = new Thickness(3, 0);
        editorOverview.SeekRequested += beat =>
        {
            var tab = viewModel.ActiveTab;
            if (tab == null) return;
            var snapped = TimelineGridNavigation.Snap(
                beat.Value,
                tab.Session.SnapDivision);
            timeline.SetCurrentBeat(snapped.Value);
            viewModel.UpdateCurrentBeat(snapped.Value);
            timeline.Focus();
        };
        editorOverview.NavigationMarkerSeekRequested += beat =>
        {
            if (viewModel.ActiveTab == null) return;
            timeline.SetCurrentBeat(beat.Value);
            viewModel.UpdateCurrentBeat(beat.Value);
            timeline.Focus();
        };
        editorOverview.IssueSeekRequested += issue =>
        {
            var tab = viewModel.ActiveTab;
            if (tab == null) return;
            ApplyChartIssueNavigation(
                tab,
                DesktopChartIssueNavigationPlanner.Create(
                    tab.Session.Document,
                    issue,
                    tab.HiddenGroups));
        };
        AutomationProperties.SetAutomationId(editorOverview, "Editor.Overview");
        AutomationProperties.SetName(editorOverview, "Note 密度峰值");
        miniNoteCountText.Text = "0";
        miniNoteCountText.FontSize = 20;
        miniNoteCountText.FontWeight = FontWeight.SemiBold;
        miniNoteCountText.Foreground = new SolidColorBrush(Color.Parse("#E2E5E6"));
        miniNoteCountText.HorizontalAlignment = HorizontalAlignment.Center;
        var footer = new StackPanel
        {
            Margin = new Thickness(0, 10, 0, 0),
            Children =
            {
                miniNoteCountText,
                new TextBlock
                {
                    Text = "NOTES",
                    FontSize = 8,
                    Foreground = new SolidColorBrush(Color.Parse("#7F878C")),
                    HorizontalAlignment = HorizontalAlignment.Center
                }
            }
        };
        Grid.SetRow(footer, 2);
        var densityTitle = new TextBlock
        {
            Text = "DENSITY",
            FontSize = 9,
            Foreground = new SolidColorBrush(Color.Parse("#7F878C")),
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center
        };
        var densityActions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Center,
            Spacing = 3,
            Children =
            {
                navigationMarkerAddButton,
                navigationMarkerListButton
            }
        };
        var densityHeader = new StackPanel
        {
            Margin = new Thickness(0, 36, 0, 6),
            Spacing = 4,
            Children = { densityTitle, densityActions }
        };
        var content = new Grid { RowDefinitions = new RowDefinitions("Auto,*,Auto") };
