    private void BuildNavigationMarkerPopup()
    {
        navigationMarkerAddButton.Content = "+";
        navigationMarkerAddButton.Width = 24;
        navigationMarkerAddButton.Height = 24;
        navigationMarkerAddButton.Padding = new Thickness(0);
        navigationMarkerAddButton.Margin = new Thickness(0);
        navigationMarkerAddButton.FontFamily = new FontFamily("Segoe UI Symbol");
        navigationMarkerAddButton.HorizontalContentAlignment = HorizontalAlignment.Center;
        navigationMarkerAddButton.VerticalContentAlignment = VerticalAlignment.Center;
        ApplyWpfToolButtonStyle(navigationMarkerAddButton);
        navigationMarkerAddButton.Padding = new Thickness(0);
        navigationMarkerAddButton.FontSize = 15;
        ToolTip.SetTip(navigationMarkerAddButton, "在当前时间添加跳转标记");
        AutomationProperties.SetName(navigationMarkerAddButton, "添加跳转标记");
        AutomationProperties.SetAutomationId(
            navigationMarkerAddButton,
            "Editor.Overview.NavigationMarker.Add");
        navigationMarkerAddButton.Click += (_, _) => AddNavigationMarker();

        navigationMarkerListButton.Content = "≡";
        navigationMarkerListButton.Width = 24;
        navigationMarkerListButton.Height = 24;
        navigationMarkerListButton.Padding = new Thickness(0);
        navigationMarkerListButton.Margin = new Thickness(0);
        navigationMarkerListButton.FontFamily = new FontFamily("Segoe UI Symbol");
        navigationMarkerListButton.HorizontalContentAlignment = HorizontalAlignment.Center;
        navigationMarkerListButton.VerticalContentAlignment = VerticalAlignment.Center;
        ApplyWpfToolButtonStyle(navigationMarkerListButton);
        navigationMarkerListButton.Padding = new Thickness(0);
        navigationMarkerListButton.FontSize = 15;
        ToolTip.SetTip(navigationMarkerListButton, "打开跳转标记列表");
        AutomationProperties.SetName(navigationMarkerListButton, "跳转标记列表");
        AutomationProperties.SetAutomationId(
            navigationMarkerListButton,
            "Editor.Overview.NavigationMarker.List");
        navigationMarkerListButton.Click += (_, _) =>
        {
            if (viewModel.ActiveTab == null) return;
            if (navigationMarkerPopup.IsOpen)
            {
                navigationMarkerPopup.IsOpen = false;
                navigationMarkerListButton.Focus();
                return;
            }
            RefreshNavigationMarkerUi();
            navigationMarkerPopup.IsOpen = true;
        };

        navigationMarkerTitleText.Text = "跳转标记";
        navigationMarkerTitleText.Foreground = Brushes.White;
        navigationMarkerTitleText.FontWeight = FontWeight.SemiBold;
        navigationMarkerTitleText.VerticalAlignment = VerticalAlignment.Center;
        navigationMarkerCountText.Foreground = MutedBrush;
        navigationMarkerCountText.FontFamily = new FontFamily("Cascadia Mono, Consolas");
        navigationMarkerCountText.VerticalAlignment = VerticalAlignment.Center;
        navigationMarkerEmptyText.Foreground = MutedBrush;
        navigationMarkerEmptyText.Margin = new Thickness(6, 14);
        navigationMarkerEmptyText.TextWrapping = TextWrapping.Wrap;
        navigationMarkerEmptyText.IsVisible = false;
        navigationMarkerList.Spacing = 3;

        var header = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,Auto"),
            Margin = new Thickness(5, 3, 5, 7),
            Children =
            {
                navigationMarkerTitleText,
                navigationMarkerCountText
            }
        };
        Grid.SetColumn(navigationMarkerCountText, 1);

        var scrollViewer = new ScrollViewer
        {
            MaxHeight = 360,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            Content = navigationMarkerList
        };
        var itemHost = new Grid
        {
            Children =
            {
                navigationMarkerEmptyText,
                scrollViewer
            }
        };
        var content = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,*"),
            Children =
            {
                header,
                new Border
                {
                    Height = 1,
                    Background = StrokeBrush,
                    Margin = new Thickness(4, 0, 4, 6)
                },
                itemHost
            }
        };
        Grid.SetRow(content.Children[1], 1);
        Grid.SetRow(itemHost, 2);

        navigationMarkerPopupSurface.Width = SupportsDesktopWindowSizing ? 280 : 300;
        navigationMarkerPopupSurface.Padding = new Thickness(7);
        navigationMarkerPopupSurface.Background =
            new SolidColorBrush(Color.Parse("#F51A1D20"));
        navigationMarkerPopupSurface.BorderBrush =
            new SolidColorBrush(Color.Parse("#465257"));
        navigationMarkerPopupSurface.BorderThickness = new Thickness(1);
        navigationMarkerPopupSurface.CornerRadius = new CornerRadius(5);
        navigationMarkerPopupSurface.Child = content;
        AutomationProperties.SetName(navigationMarkerPopupSurface, "跳转标记列表");
        AutomationProperties.SetAutomationId(
            navigationMarkerPopupSurface,
            "Editor.Overview.NavigationMarker.Popup");
        navigationMarkerPopupSurface.AddHandler(
            InputElement.KeyDownEvent,
            NavigationMarkerPopup_KeyDown,
            RoutingStrategies.Tunnel);

        navigationMarkerPopup.PlacementTarget = navigationMarkerListButton;
        navigationMarkerPopup.Placement = PlacementMode.Bottom;
        navigationMarkerPopup.VerticalOffset = 4;
        navigationMarkerPopup.IsLightDismissEnabled = true;
        navigationMarkerPopup.TakesFocusFromNativeControl = true;
        navigationMarkerPopup.WindowManagerAddShadowHint = true;
        navigationMarkerPopup.Child = navigationMarkerPopupSurface;
        navigationMarkerPopup.Opened += (_, _) =>
        {
            RefreshNavigationMarkerUi();
            ApplyNavigationMarkerPopupScale();
            localizationController.ScheduleApply(navigationMarkerPopupSurface);
            Dispatcher.UIThread.Post(
                () =>
                {
                    if (navigationMarkerPopup.IsOpen &&
                        navigationMarkerButtons.Count > 0)
                        navigationMarkerButtons[0].Focus();
                    else if (navigationMarkerPopup.IsOpen)
                        navigationMarkerListButton.Focus();
                },
                DispatcherPriority.Input);
        };
        navigationMarkerPopup.Closed += (_, _) =>
        {
            navigationMarkerListButton.Focus();
            timeline.Focus();
        };
    }

    private void RefreshNavigationMarkerUi()
    {
        var tab = viewModel.ActiveTab;
        var markers = tab?.NavigationMarkers ?? [];
        navigationMarkerAddButton.IsEnabled = tab != null;
        navigationMarkerListButton.IsEnabled = tab != null;
        navigationMarkerCountText.Text = $"{markers.Count}/{DesktopNavigationMarker.MaximumCount}";
        navigationMarkerEmptyText.Text = tab == null
            ? "没有打开的谱面"
            : "当前谱面还没有跳转标记";
        navigationMarkerEmptyText.IsVisible = markers.Count == 0;
        navigationMarkerList.IsVisible = markers.Count > 0;
        navigationMarkerButtons.Clear();
        navigationMarkerDeleteButtons.Clear();
        navigationMarkerList.Children.Clear();

        if (tab == null) return;
        TimingMap? timingMap = null;
        try { timingMap = GetAudioTimingMap(tab); }
        catch (Exception) { }

        for (var index = 0; index < markers.Count; index++)
        {
            var marker = markers[index];
            var positionText = new TextBlock
            {
                Text = WindowsBeatDisplayFormat.Format(marker.Beat),
                Foreground = new SolidColorBrush(Color.Parse("#E4E9EA")),
                FontFamily = new FontFamily("Cascadia Mono, Consolas"),
                TextTrimming = TextTrimming.CharacterEllipsis
            };
            var timeText = new TextBlock
            {
                Text = timingMap == null
                    ? "音频时间不可用"
                    : FormatAudioTime(TimeSpan.FromMilliseconds(Math.Max(
                        0,
                        timingMap.BeatToMilliseconds(marker.Beat)))),
                Foreground = MutedBrush,
                FontFamily = new FontFamily("Cascadia Mono, Consolas"),
                TextTrimming = TextTrimming.CharacterEllipsis
            };
            var seekButton = new Button
            {
                Content = new StackPanel
                {
                    Spacing = 2,
                    Children = { positionText, timeText }
                },
                Padding = new Thickness(7, 5),
                Margin = new Thickness(0),
                HorizontalContentAlignment = HorizontalAlignment.Stretch,
                VerticalContentAlignment = VerticalAlignment.Center
            };
            ApplyWpfToolButtonStyle(seekButton);
            ToolTip.SetTip(seekButton, AvaloniaLocalizationCatalog.Format("精确跳转到 {0}", WindowsBeatDisplayFormat.Format(marker.Beat)));
            AutomationProperties.SetName(seekButton, AvaloniaLocalizationCatalog.Format("跳转到 {0}", WindowsBeatDisplayFormat.Format(marker.Beat)));
            AutomationProperties.SetAutomationId(
                seekButton,
                $"Editor.Overview.NavigationMarker.Item.{index}");
            seekButton.Click += (_, _) =>
            {
                NavigateNavigationMarker(marker.Beat);
                navigationMarkerPopup.IsOpen = false;
            };

            var deleteButton = new Button
            {
                Content = "×",
                Width = 30,
                Height = 34,
                Padding = new Thickness(0),
                Margin = new Thickness(0),
                HorizontalContentAlignment = HorizontalAlignment.Center,
                VerticalContentAlignment = VerticalAlignment.Center
            };
            ApplyDangerButtonStyle(deleteButton);
            ToolTip.SetTip(deleteButton, AvaloniaLocalizationCatalog.Format("删除跳转标记 {0}", WindowsBeatDisplayFormat.Format(marker.Beat)));
            AutomationProperties.SetName(deleteButton, AvaloniaLocalizationCatalog.Format("删除跳转标记 {0}", WindowsBeatDisplayFormat.Format(marker.Beat)));
            AutomationProperties.SetAutomationId(
                deleteButton,
                $"Editor.Overview.NavigationMarker.Delete.{index}");
            deleteButton.Click += (_, _) => RemoveNavigationMarker(marker.Id);

            var row = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,30"),
                ColumnSpacing = 4,
                Children = { seekButton, deleteButton }
            };
            Grid.SetColumn(deleteButton, 1);
            navigationMarkerList.Children.Add(row);
            navigationMarkerButtons.Add(seekButton);
            navigationMarkerDeleteButtons.Add(deleteButton);
        }

        if (navigationMarkerPopup.IsOpen)
            ApplyNavigationMarkerPopupScale();
    }

    private void ApplyNavigationMarkerPopupScale()
    {
        var settings = displayScaleController.CurrentSettings.Normalize();
        var plan = AvaloniaPopupScaleController.Resolve(10, settings);
        if (TopLevel.GetTopLevel(navigationMarkerPopupSurface) is PopupRoot popupRoot)
            popupRoot.Transform = new ScaleTransform(plan.UiScale, plan.UiScale);

        fontScaleController.Rebase(navigationMarkerTitleText, 11);
        fontScaleController.Rebase(navigationMarkerCountText, 9);
        fontScaleController.Rebase(navigationMarkerEmptyText, 10);
        foreach (var button in navigationMarkerButtons)
            fontScaleController.Rebase(button, 10);
        foreach (var button in navigationMarkerDeleteButtons)
            fontScaleController.Rebase(button, 12);
    }

    private void NavigationMarkerPopup_KeyDown(
        object? sender,
        KeyEventArgs eventArgs)
    {
        _ = sender;
        if (eventArgs.Key != Key.Escape) return;
        navigationMarkerPopup.IsOpen = false;
        eventArgs.Handled = true;
    }

    private void AddNavigationMarker()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var marker = WindowsNavigationMarkerPolicy.Create(timeline.CurrentBeat);
        var updated = WindowsNavigationMarkerPolicy.Add(
            tab.NavigationMarkers,
            marker,
            out var duplicate);
        if (duplicate)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("当前位置已有跳转标记 · {0}", WindowsBeatDisplayFormat.Format(marker.Beat)));
            timeline.Focus();
            return;
        }
        if (!updated.Any(candidate => candidate.Id == marker.Id))
        {
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("跳转标记最多保留 {0} 个", DesktopNavigationMarker.MaximumCount));
            timeline.Focus();
            return;
        }

        viewModel.ReplaceNavigationMarkers(tab.Id, updated);
        editorOverview.SetNavigationMarkers(tab.NavigationMarkers);
        RefreshNavigationMarkerUi();
        ScheduleNavigationMarkerSave();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已添加跳转标记 · {0}", WindowsBeatDisplayFormat.Format(marker.Beat)));
        timeline.Focus();
    }

    private void RemoveNavigationMarker(Guid markerId)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var updated = WindowsNavigationMarkerPolicy.Remove(
            tab.NavigationMarkers,
            markerId);
        if (updated.Count == tab.NavigationMarkers.Count) return;
        viewModel.ReplaceNavigationMarkers(tab.Id, updated);
        editorOverview.SetNavigationMarkers(tab.NavigationMarkers);
        RefreshNavigationMarkerUi();
        ScheduleNavigationMarkerSave();
        viewModel.SetStatus("已删除跳转标记");
    }

    private void NavigateNavigationMarker(BeatPosition beat)
    {
        if (viewModel.ActiveTab == null) return;
        timeline.SetCurrentBeat(beat.Value);
        viewModel.UpdateCurrentBeat(beat.Value);
        timeline.Focus();
    }

    private void ScheduleNavigationMarkerSave()
    {
        navigationMarkerSettingsDirty = true;
        navigationMarkerRevision++;
        // A fresh edit retries promptly even after earlier failures backed off.
        navigationMarkerSaveFailureCount = 0;
        navigationMarkerSaveTimer.Interval = NavigationMarkerSaveDelay;
        navigationMarkerSaveTimer.Stop();
        navigationMarkerSaveTimer.Start();
    }

    /// <summary>
    /// Retry after a failed marker save with exponential backoff and a cap.
    /// Retrying every 350 ms forever re-ran a full-window UpdateUi through the
    /// failure status each time. After the cap the markers stay dirty: the next
    /// marker edit or the close preflight tries again.
    /// </summary>
    private void ScheduleNavigationMarkerRetry()
    {
        navigationMarkerSaveFailureCount++;
        if (navigationMarkerSaveFailureCount > NavigationMarkerSaveMaximumRetries) return;
        var delay = Math.Min(
            NavigationMarkerSaveDelay.TotalMilliseconds *
            Math.Pow(2, navigationMarkerSaveFailureCount),
            30_000);
        navigationMarkerSaveTimer.Interval = TimeSpan.FromMilliseconds(delay);
        navigationMarkerSaveTimer.Stop();
        navigationMarkerSaveTimer.Start();
    }

    private async Task<bool> PersistPendingNavigationMarkersAsync(bool force = false)
    {
        navigationMarkerSaveTimer.Stop();
        if (!navigationMarkerSettingsDirty && !force) return true;

        await navigationMarkerPersistenceGate.WaitAsync();
        try
        {
            while (navigationMarkerSettingsDirty || force)
            {
                var revision = navigationMarkerRevision;
                if (!await viewModel.PersistNavigationStateAsync())
                {
                    if (!force) ScheduleNavigationMarkerRetry();
                    return false;
                }
                if (revision != navigationMarkerRevision)
                {
                    force = false;
                    continue;
                }
                navigationMarkerSettingsDirty = false;
                navigationMarkerSaveFailureCount = 0;
                navigationMarkerSaveTimer.Interval = NavigationMarkerSaveDelay;
                return true;
            }
            return true;
        }
        finally
        {
            navigationMarkerPersistenceGate.Release();
        }
    }

