    private void BuildDifficultyInfoCard()
    {
        difficultyInfoCard.Width = WindowsDifficultyUiPolicy.DefaultCardWidth;
        difficultyInfoCard.Height = WindowsDifficultyUiPolicy.ResolveCardHeight(
