    private static void AddDifficultyCardMetric(
        Grid parent,
        TextBlock value,
        string label,
        int column)
    {
        value.Text = column switch
        {
            0 => "—",
            1 => "0",
            _ => "OD8.0"
        };
        value.FontFamily = new FontFamily("Cascadia Mono, Consolas");
        value.FontSize = 12;
        value.FontWeight = FontWeight.SemiBold;
        value.Foreground = new SolidColorBrush(Color.Parse("#D5DDDE"));
        var stack = new StackPanel
        {
            Children =
            {
                value,
                new TextBlock
                {
                    Text = label,
                    FontSize = 8,
                    Foreground = new SolidColorBrush(Color.Parse("#758085"))
                }
            }
        };
        Grid.SetColumn(stack, column);
        parent.Children.Add(stack);
    }

    private DifficultyTabState GetDifficultyState(DesktopChartTab tab)
    {
        if (difficultyStates.TryGetValue(tab.Id, out var state)) return state;
        state = new DifficultyTabState
        {
            OverallDifficulty = Math.Clamp(
                tab.Session.Document.Metadata.OverallDifficulty,
                0,
                10)
        };
        difficultyStates.Add(tab.Id, state);
        return state;
    }

    private async Task ShowDifficultyAnalysisAsync()
    {
        var targetTab = viewModel.ActiveTab;
        if (targetTab == null)
        {
            await ShowSettingsMessageAsync("难度分析", "请先打开一张谱面。");
            return;
        }
        if (targetTab.Session.Document.KeyCount != 4)
        {
            await ShowSettingsMessageAsync(
                "难度分析",
                "Rework 难度分析目前只用于 4K 谱面。");
            return;
        }

        var targetSerial = targetTab.Session.ChangeSerial;
        var snapshot = targetTab.Session.CaptureCommittedDocument();
        var state = GetDifficultyState(targetTab);
        var analysisOd = Math.Clamp(
            state.OverallDifficulty ?? snapshot.Metadata.OverallDifficulty,
            0,
            10);
        difficultyAnalysisCancellation?.Cancel();
        difficultyAnalysisCancellation?.Dispose();
        var cancellation = difficultyAnalysisCancellation = new CancellationTokenSource();
        if (difficultyAnalysisButton != null) difficultyAnalysisButton.IsEnabled = false;
        Cursor = new Cursor(StandardCursorType.Wait);
        viewModel.SetStatus("正在计算 4K Rework 难度…");
        try
        {
            var analysisTask = Task.Run(
                () => ReworkDifficultyAnalyzer.Analyze(
                    snapshot,
                    overallDifficulty: analysisOd),
                cancellation.Token);
            activeDifficultyAnalysisTask = analysisTask;
            var result = await analysisTask;
            cancellation.Token.ThrowIfCancellationRequested();
            if (!WindowsDifficultyUiPolicy.IsAnalysisCurrent(
                    targetTab.Id,
                    targetSerial,
                    viewModel.ActiveTab?.Id,
                    viewModel.ActiveTab?.Session.ChangeSerial ?? -1))
            {
                viewModel.SetStatus("谱面已变化，请重新运行难度分析");
                return;
            }

            state.Result = result;
            state.ChangeSerial = targetSerial;
            state.OverallDifficulty = result.OverallDifficulty;
            RefreshDifficultyUi();
            viewModel.SetStatus(
                $"Rework {result.StarRating:0.00}★ · {result.ReferenceDifficulty}");
            var dialog = new DifficultyAnalysisWindow(
                result,
                NavigateDifficultyOverview,
                (od, token) => Task.Run(
                    () => ReworkDifficultyAnalyzer.Analyze(
                        snapshot,
                        overallDifficulty: od),
                    token),
                updatedResult =>
                {
                    if (!WindowsDifficultyUiPolicy.IsAnalysisCurrent(
                            targetTab.Id,
                            targetSerial,
                            viewModel.ActiveTab?.Id,
                            viewModel.ActiveTab?.Session.ChangeSerial ?? -1)) return;
                    state.Result = updatedResult;
                    state.ChangeSerial = targetSerial;
                    state.OverallDifficulty = updatedResult.OverallDifficulty;
                    RefreshDifficultyUi();
                    viewModel.SetStatus(
                        $"Rework {updatedResult.StarRating:0.00}★ · " +
                        $"OD{updatedResult.OverallDifficulty:0.0}");
                },
                displayScaleController.CurrentSettings.UiScale,
                displayScaleController.CurrentSettings.FontScale);
            await dialog.ShowDialog<bool>(this);
        }
        catch (OperationCanceledException)
        {
        }
        catch (Exception exception) when (
            exception is InvalidOperationException or NotSupportedException)
        {
            await ShowSettingsMessageAsync("难度分析", exception.Message);
        }
        catch (Exception exception)
        {
            await ShowSettingsMessageAsync(
                "难度分析失败",
                exception.Message);
        }
        finally
        {
            if (ReferenceEquals(difficultyAnalysisCancellation, cancellation))
            {
                difficultyAnalysisCancellation.Dispose();
                difficultyAnalysisCancellation = null;
            }
            Cursor = null;
            if (difficultyAnalysisButton != null)
                difficultyAnalysisButton.IsEnabled = viewModel.ActiveTab != null;
        }
    }

    private void NavigateDifficultyOverview(double beat)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var safe = double.IsFinite(beat) ? Math.Max(0, beat) : 0;
        var snapped = TimelineGridNavigation.Snap(
            safe,
            tab.Session.SnapDivision);
        timeline.SetCurrentBeat(snapped.Value);
        viewModel.UpdateCurrentBeat(snapped.Value);
        timeline.InvalidateVisual();
        difficultyOverview.SetCurrentBeat(snapped.Value);
        Dispatcher.UIThread.Post(() => timeline.Focus(), DispatcherPriority.Input);
    }

    private async Task StartPlaytestAsync(double startBeat, bool forceAutoPlay = false)
    {
        // Claimed before the first await: persisting the working copy yields,
        // and a double click used to open two modal playtest windows.
        if (playtestInProgress) return;
        playtestInProgress = true;
        try
        {
            await StartPlaytestCoreAsync(startBeat, forceAutoPlay);
        }
        finally
        {
            playtestInProgress = false;
            // Only now may the editor frame pump run again (the flag kept the
            // audio UI timer from restarting it while the playtest owned the
            // device clock).
            ConfigureEditorFrameRateRuntime(resetCounters: true);
        }
    }

    /// <summary>
    /// 快速测试：同一个键既打开也关闭。打开时从判定线起拍并强制 AutoPlay，
    /// 关掉时直接 Close 已开的窗口 —— 不会改用户存档里的 AutoPlay 偏好。
    /// </summary>
    private async Task ToggleQuickTestAsync()
    {
        if (activePlaytestWindow != null)
        {
            activePlaytestWindow.Close();
            return;
        }
        await StartPlaytestAsync(timeline.CurrentBeat, forceAutoPlay: true);
    }

    private string? ShortcutGesture(string action) =>
        shortcutSettings.Bindings.TryGetValue(action, out var gesture) &&
        !string.IsNullOrWhiteSpace(gesture)
            ? gesture
            : null;

    private async Task StartPlaytestCoreAsync(double startBeat, bool forceAutoPlay = false)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            await ShowSettingsMessageAsync("测试演奏", "请先打开一张谱面。");
            return;
        }
        var snapshot = tab.Session.CaptureCommittedDocument();
        if (snapshot.Notes.All(note => note.IsDraft))
        {
            await ShowSettingsMessageAsync("测试演奏", "当前谱面没有可测试的正式 Note。");
            return;
        }

        try
        {
            viewModel.SetStatus("正在保存测试工作副本…");
            if (!await viewModel.PersistAsync())
                throw new IOException(viewModel.Status);
            if (!File.Exists(tab.WorkingPath))
                throw new IOException("当前谱面没有可用的编辑缓存工作副本。");

            await PauseAllEditorPlaybackAsync();
            var settings = WindowsPlaytestSettingsStore.Load();
            if (forceAutoPlay) settings = settings.With(autoPlay: true);
            var audioPath = WindowsAudioTransportViewModel.ResolveDocumentAudioPath(tab);
            var safeStartBeat = double.IsFinite(startBeat) ? Math.Max(0, startBeat) : 0;
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("测试工作副本已保存：{0}", tab.WorkingPath));
            var dialog = new PlaytestWindow(
                snapshot,
                audioPath,
                tab.WorkingPath,
                safeStartBeat,
                settings,
                keySoundSettings,
                audioTransport.PlaybackRate,
                audioTransport.PreservePitch,
                audioTransport.Volume,
                editorViewSettings.FrameRateLimit,
                displayScaleController.CurrentSettings.UiScale,
                displayScaleController.CurrentSettings.FontScale,
                WindowState == WindowState.FullScreen,
                forceAutoPlay ? ShortcutGesture("QuickTest") : null);
            StopEditorHighRateFramePump();
            activePlaytestWindow = dialog;
            try
            {
                await dialog.ShowDialog(this);
            }
            finally
            {
                activePlaytestWindow = null;
            }
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("测试演奏已退出 · 源谱未写入 · 缓存 {0}", Path.GetFileName(tab.WorkingPath)));
        }
        catch (Exception exception)
        {
            await ShowSettingsMessageAsync(
                "无法开始测试演奏；原谱面未被修改",
                exception.Message);
        }
        finally
        {
            // Before UpdateUi, which is what asks for the background: see
            // InvalidateChartBackgroundCache.
            InvalidateChartBackgroundCache();
            UpdateUi();
            Dispatcher.UIThread.Post(() => timeline.Focus(), DispatcherPriority.Input);
        }
    }

    /// <summary>
    /// Stops every editor clock, e.g. before the playtest window takes over or
    /// the app goes to the background: the coalesced seek (whose commit could
    /// resume playback behind a modal), the music transport, and the silent
    /// key-sound clock that drives charts without usable audio. Pausing only
    /// the music left that clock and its key sounds running.
    /// </summary>
    private async Task PauseAllEditorPlaybackAsync()
    {
        if (keySoundRuntimeDisposed) return;
        await CancelPendingEditorSeek();
        if (audioTransport.IsPlaying)
        {
            keySoundRuntime.InvalidatePlayback();
            await audioTransport.TogglePlayPauseAsync();
        }
        if (!keySoundRuntimeDisposed && keySoundRuntime.Snapshot.IsSilentPlaying)
            keySoundRuntime.PauseSilent();
        if (!keySoundRuntimeDisposed) keySoundRuntime.InvalidatePlayback();
        UpdateQuickPlayPresentation();
    }

    private void RefreshDifficultyUi()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            difficultyOverview.SetResult(null);
            difficultyOverview.SetEndBeat(1);
            difficultyOverview.SetCurrentBeat(0);
            difficultyStarText.Text = "—";
            difficultyInfoCard.IsVisible = false;
            if (difficultyAnalysisButton != null) difficultyAnalysisButton.IsEnabled = false;
            return;
        }

        var state = GetDifficultyState(tab);
        if (state.Result != null && state.ChangeSerial != tab.Session.ChangeSerial)
            state.Result = null;
        var result = state.ChangeSerial == tab.Session.ChangeSerial
            ? state.Result
            : null;
        var document = tab.Session.Document;
        difficultyOverview.SetResult(result);
        difficultyOverview.SetEndBeat(Math.Max(1, document.EndBeat));
        difficultyOverview.SetCurrentBeat(timeline.CurrentBeat);
        difficultyStarText.Text = document.KeyCount != 4
            ? "N/A"
            : result == null
                ? "—"
                : result.StarRating.ToString("0.00", CultureInfo.InvariantCulture);
        if (difficultyAnalysisButton != null)
            difficultyAnalysisButton.IsEnabled = document.KeyCount == 4 &&
                                                 difficultyAnalysisCancellation == null;
        RefreshDifficultyCard(tab, state, result);
        QueueDifficultyCardLayout();
    }

    private void RefreshDifficultyCard(
        DesktopChartTab tab,
        DifficultyTabState state,
        ReworkDifficultyResult? result)
    {
        var document = tab.Session.Document;
        var title = string.IsNullOrWhiteSpace(document.Metadata.Title)
            ? "Untitled"
            : document.Metadata.Title.Trim();
        var version = string.IsNullOrWhiteSpace(document.Metadata.Version)
            ? "Normal"
            : document.Metadata.Version.Trim();
        difficultyCardTitleText.Text = $"{title}  /  {version}";
        ToolTip.SetTip(difficultyCardTitleText, difficultyCardTitleText.Text);

        var officialNotes = document.Notes.Where(note => !note.IsDraft).ToArray();
        var longNoteCount = officialNotes.Count(note => note.IsHold);
        var longNoteRatio = officialNotes.Length == 0
            ? 0
            : (double)longNoteCount / officialNotes.Length;
        var analysisOd = Math.Clamp(
            state.OverallDifficulty ?? document.Metadata.OverallDifficulty,
            0,
            10);
        difficultyCardNoteText.Text = (result?.NoteCount ?? officialNotes.Length)
            .ToString("N0", CultureInfo.InvariantCulture);
        difficultyCardLnText.Text = (result?.LongNoteRatio ?? longNoteRatio)
            .ToString("P1", CultureInfo.InvariantCulture);
        difficultyCardOdText.Text =
            $"OD{(result?.OverallDifficulty ?? analysisOd):0.0}";
        difficultyCardPatternList.Children.Clear();

        if (result == null)
        {
            difficultyCardStateText.Text = "待分析";
            difficultyCardStarText.Text = "—";
            difficultyCardReferenceText.Text = officialNotes.Length < 2
                ? "至少需要 2 个正式 Note"
                : "运行顶部“难度”分析";
            difficultyCardPatternFamilyText.Text = "等待分析";
            difficultyCardPatternList.IsVisible = false;
            difficultyCardPatternHintText.IsVisible = true;
            return;
        }

        difficultyCardStateText.Text = "已分析";
        difficultyCardStarText.Text = result.StarRating.ToString(
            "0.00",
            CultureInfo.InvariantCulture);
        difficultyCardReferenceText.Text = result.ReferenceDifficulty;
        difficultyCardPatternFamilyText.Text = result.PatternFamily;
        var visiblePatterns = result.Patterns.Take(5).ToArray();
        var maximumRatio = Math.Max(.0001, visiblePatterns.FirstOrDefault()?.Ratio ?? 1);
        foreach (var pattern in visiblePatterns)
            difficultyCardPatternList.Children.Add(
                BuildDifficultyPatternRow(pattern, maximumRatio));
        difficultyCardPatternList.IsVisible = visiblePatterns.Length > 0;
        difficultyCardPatternHintText.IsVisible = visiblePatterns.Length == 0;
    }

    private static Control BuildDifficultyPatternRow(
        ReworkPatternContribution pattern,
        double maximumRatio)
    {
        var grid = new Grid
        {
            Height = 21,
            ColumnDefinitions = new ColumnDefinitions("62,*,34")
        };
        grid.Children.Add(new TextBlock
        {
            Text = pattern.Name,
            Foreground = new SolidColorBrush(Color.Parse("#AEB8BB")),
            FontSize = 9,
            VerticalAlignment = VerticalAlignment.Center,
            TextTrimming = TextTrimming.CharacterEllipsis
        });
        var bar = new Border
        {
            Height = 4,
            VerticalAlignment = VerticalAlignment.Center,
            Background = new SolidColorBrush(Color.Parse("#293034")),
            CornerRadius = new CornerRadius(2),
            Child = new Border
            {
                Width = Math.Max(7, Math.Round(50 * pattern.Ratio / maximumRatio)),
                HorizontalAlignment = HorizontalAlignment.Left,
                Background = new SolidColorBrush(Color.Parse("#6FA7AA")),
                CornerRadius = new CornerRadius(2)
            }
        };
        Grid.SetColumn(bar, 1);
        grid.Children.Add(bar);
        var ratio = new TextBlock
        {
            Text = pattern.Ratio.ToString("P1", CultureInfo.InvariantCulture),
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment = VerticalAlignment.Center,
            FontFamily = new FontFamily("Cascadia Mono, Consolas"),
            Foreground = new SolidColorBrush(Color.Parse("#879498")),
            FontSize = 9
        };
        Grid.SetColumn(ratio, 2);
        grid.Children.Add(ratio);
        return grid;
    }

    private void QueueDifficultyCardLayout()
    {
        if (difficultyCardLayoutQueued) return;
        difficultyCardLayoutQueued = true;
        Dispatcher.UIThread.Post(() =>
        {
            difficultyCardLayoutQueued = false;
            ApplyDifficultyCardLayout();
        }, DispatcherPriority.Loaded);
    }

    private void ApplyDifficultyCardLayout()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.Session.Document.KeyCount != 4 ||
            timelineHost.Bounds.Width <= 0 || timelineHost.Bounds.Height <= 0)
        {
            difficultyInfoCard.IsVisible = false;
            return;
        }
        var track = timeline.GetActiveTrackBounds();
        var trackPoint = track.Width > 0
            ? timeline.TranslatePoint(new Point(track.Left, 0), timelineHost)
            : null;
        if (trackPoint is not { } translatedTrack)
        {
            difficultyInfoCard.IsVisible = false;
            return;
        }

        double? leftDockedPanelLeft = null;
        if (waveformPanel.IsVisible &&
            waveformPanel.TranslatePoint(new Point(0, 0), timelineHost) is { } waveformPoint &&
            waveformPoint.X + waveformPanel.Bounds.Width <= translatedTrack.X + 1)
            leftDockedPanelLeft = waveformPoint.X;
        var layout = WindowsDifficultyUiPolicy.ResolveCardLayout(
            hasFourKeyChart: true,
            timelineHost.Bounds.Width,
            timelineHost.Bounds.Height,
            translatedTrack.X,
            leftDockedPanelLeft,
            editorViewSettings.DifficultyCardCollapsed,
            difficultyInfoCardTransform.X,
            difficultyInfoCardTransform.Y,
            difficultyInfoCard.Bounds.Height);
        if (layout.Collapsed != editorViewSettings.DifficultyCardCollapsed)
        {
            editorViewSettings = editorViewSettings.WithDifficultyCard(
                layout.X,
                layout.Y,
                layout.Collapsed);
            ApplyDifficultyCardCollapsedState();
            MarkEditorViewSettingsDirty();
        }
        difficultyInfoCard.Width = layout.Width;
        difficultyInfoCard.Height = WindowsDifficultyUiPolicy.ResolveCardHeight(layout.Collapsed);
        difficultyInfoCardTransform.X = layout.X;
        difficultyInfoCardTransform.Y = layout.Y;
        difficultyInfoCard.IsVisible = layout.Visible;
        AutomationProperties.SetHelpText(
            difficultyInfoCard,
            $"FixedSize={difficultyInfoCard.Width:0}x{difficultyInfoCard.Height:0}; " +
            $"Collapsed={layout.Collapsed}; X={layout.X:0.###}; Y={layout.Y:0.###}; " +
            $"NeighborAvailableWidth={layout.AvailableWidth:0.###}");
    }

    private void DifficultyCardHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        _ = sender;
        if (!eventArgs.GetCurrentPoint(difficultyInfoCardHeader).Properties.IsLeftButtonPressed ||
            difficultyCardCollapseButton.IsPointerOver) return;
        difficultyCardDragging = true;
        difficultyCardDragStart = eventArgs.GetPosition(timelineHost);
        difficultyCardDragStartX = difficultyInfoCardTransform.X;
        difficultyCardDragStartY = difficultyInfoCardTransform.Y;
        eventArgs.Pointer.Capture(difficultyInfoCardHeader);
        eventArgs.Handled = true;
    }

    private void DifficultyCardHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        _ = sender;
        if (!difficultyCardDragging ||
            !eventArgs.GetCurrentPoint(difficultyInfoCardHeader).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(timelineHost);
        var position = WindowsDifficultyUiPolicy.ApplyDrag(
            difficultyCardDragStartX + point.X - difficultyCardDragStart.X,
            difficultyCardDragStartY + point.Y - difficultyCardDragStart.Y,
            timelineHost.Bounds.Width,
            timelineHost.Bounds.Height,
            difficultyInfoCard.Bounds.Width,
            difficultyInfoCard.Bounds.Height);
        difficultyInfoCardTransform.X = position.X;
        difficultyInfoCardTransform.Y = position.Y;
        eventArgs.Handled = true;
    }

    private void DifficultyCardHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!difficultyCardDragging) return;
        EndDifficultyCardDrag();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndDifficultyCardDrag()
    {
        // Shared by release and capture loss, so a drag interrupted by Alt+Tab
        // or a modal still stores the position it visibly left the card at.
        if (!difficultyCardDragging) return;
        difficultyCardDragging = false;
        editorViewSettings = editorViewSettings.WithDifficultyCard(
            difficultyInfoCardTransform.X,
            difficultyInfoCardTransform.Y,
            editorViewSettings.DifficultyCardCollapsed);
        MarkEditorViewSettingsDirty();
    }

    private void ToggleDifficultyCardCollapsed()
    {
        editorViewSettings = editorViewSettings.WithDifficultyCard(
            difficultyInfoCardTransform.X,
            difficultyInfoCardTransform.Y,
            !editorViewSettings.DifficultyCardCollapsed);
        ApplyDifficultyCardCollapsedState();
        MarkEditorViewSettingsDirty();
        QueueDifficultyCardLayout();
    }

    private void ApplyDifficultyCardCollapsedState()
    {
        var collapsed = editorViewSettings.DifficultyCardCollapsed;
        difficultyInfoCardBody.IsVisible = !collapsed;
        difficultyCardCollapseButton.Content = collapsed ? "+" : "—";
        ToolTip.SetTip(
            difficultyCardCollapseButton,
            collapsed ? "展开难度卡片" : "收起难度卡片");
        difficultyInfoCard.Padding = collapsed
            ? new Thickness(6, 5)
            : new Thickness(11, 10);
        difficultyInfoCard.Width = WindowsDifficultyUiPolicy.DefaultCardWidth;
        difficultyInfoCard.Height = WindowsDifficultyUiPolicy.ResolveCardHeight(collapsed);
    }

    private static Control WrapInspectorContent(Control content, Thickness? padding = null) => new ScrollViewer
    {
        VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
        HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
        // Padding set on the ScrollViewer is not deducted from the width its
        // content is measured with, only from the viewport it is shown in, so
        // wrapping hint text used to lay out at the full panel width and then
        // lose its tail behind the padded edge. A padded Border keeps measure
        // and arrange on the same width.
        Content = new Border
        {
            Padding = padding ?? new Thickness(22, 14, 22, 24),
            Child = content
        }
    };

