    private static Button QuickPaletteButton(
        string text,
        string geometry,
        EventHandler<RoutedEventArgs> handler,
        out TextBlock label,
        bool filledIcon = false) =>
        QuickPaletteButton(
            text,
            geometry,
            handler,
            out label,
            out _,
            filledIcon);

    private static Button QuickPaletteButton(
        string text,
        string geometry,
        EventHandler<RoutedEventArgs> handler,
        out TextBlock label,
        out AvaloniaPath icon,
        bool filledIcon = false)
    {
        var iconBrush = new SolidColorBrush(Color.Parse("#B7C0C4"));
        icon = new AvaloniaPath
        {
            Data = StreamGeometry.Parse(geometry),
            Stroke = filledIcon ? null : iconBrush,
            StrokeThickness = 1.5,
            StrokeLineCap = PenLineCap.Round,
            StrokeJoin = PenLineJoin.Round,
            Fill = filledIcon ? iconBrush : null
        };
        var iconCanvas = new Canvas
        {
            Width = 17,
            Height = 17,
            Children = { icon }
        };
        var iconViewport = new Viewbox
        {
            Width = 18,
            Height = 18,
            Stretch = Stretch.Uniform,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center,
            Child = iconCanvas
        };
        label = new TextBlock
        {
            Text = text,
            HorizontalAlignment = HorizontalAlignment.Stretch,
            VerticalAlignment = VerticalAlignment.Center,
            TextAlignment = TextAlignment.Center
        };
        var content = new Grid
        {
            Width = 84,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center,
            ColumnDefinitions = new ColumnDefinitions("24,*")
        };
        content.Children.Add(iconViewport);
        Grid.SetColumn(label, 1);
        content.Children.Add(label);
        var button = new Button
        {
            Height = 35,
            Padding = new Thickness(4, 7),
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center,
            Background = Brushes.Transparent,
            Foreground = Brushes.White,
            BorderBrush = Brushes.Transparent,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Content = content
        };
        button.Click += handler;
        return button;
    }

    private void RegisterQuickShortcutButton(
        string action,
        string description,
        Button button) => quickShortcutButtons[action] = (button, description);

    private void SetQuickShortcutEnabled(string action, bool enabled)
    {
        if (quickShortcutButtons.TryGetValue(action, out var entry))
            entry.Button.IsEnabled = enabled;
    }

    private void QuickEditPaletteHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header || quickEditPaletteCollapseButton.IsPointerOver ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = quickEditPalette.TranslatePoint(new Point(0, 0), editorWorkbench);
        if (!current.HasValue) return;
        quickEditPaletteDragging = true;
        quickEditPaletteDragStart = eventArgs.GetPosition(editorWorkbench);
        quickEditPaletteDragStartX = quickEditPaletteTransform.X;
        quickEditPaletteDragStartY = quickEditPaletteTransform.Y;
        quickEditPaletteBaseLeft = current.Value.X - quickEditPaletteTransform.X;
        quickEditPaletteBaseTop = current.Value.Y - quickEditPaletteTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!quickEditPaletteDragging || sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var x = quickEditPaletteDragStartX + point.X - quickEditPaletteDragStart.X;
        var y = quickEditPaletteDragStartY + point.Y - quickEditPaletteDragStart.Y;
        quickEditPaletteTransform.X = Math.Clamp(
            x,
            4 - quickEditPaletteBaseLeft,
            Math.Max(
                4 - quickEditPaletteBaseLeft,
                editorWorkbench.Bounds.Width - quickEditPalette.Bounds.Width -
                quickEditPaletteBaseLeft - 4));
        quickEditPaletteTransform.Y = Math.Clamp(
            y,
            4 - quickEditPaletteBaseTop,
            Math.Max(
                4 - quickEditPaletteBaseTop,
                editorWorkbench.Bounds.Height - quickEditPalette.Bounds.Height -
                quickEditPaletteBaseTop - 4));
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!quickEditPaletteDragging) return;
        // Ends the gesture before releasing capture, so the CaptureLost raised
        // by Capture(null) finds the flag cleared and does not commit twice.
        EndQuickEditPaletteDrag();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndQuickEditPaletteDrag()
    {
        if (!quickEditPaletteDragging) return;
        quickEditPaletteDragging = false;
        editorViewSettings = editorViewSettings.WithQuickPalette(
            quickEditPaletteTransform.X,
            quickEditPaletteTransform.Y,
            editorViewSettings.QuickPaletteCollapsed);
        editorViewSettingsDirty = true;
        ScheduleEditorViewSettingsSave();
    }

    private void QuickEditPaletteResizeGrip_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control grip ||
            !eventArgs.GetCurrentPoint(grip).Properties.IsLeftButtonPressed)
            return;
        quickEditPaletteResizing = true;
        quickEditPaletteResizeStart = eventArgs.GetPosition(editorWorkbench);
        quickEditPaletteResizeStartTransformX = quickEditPaletteTransform.X;
        quickEditPaletteResizeStartWidth = Math.Max(
            180,
            quickEditPaletteScaleHost.Bounds.Width > 0
                ? quickEditPaletteScaleHost.Bounds.Width
                : quickEditPaletteWidth);
        quickEditPaletteResizeStartHeight = Math.Max(
            60,
            quickEditPaletteScaleHost.Bounds.Height > 0
                ? quickEditPaletteScaleHost.Bounds.Height
                : quickEditPaletteHeight ?? 60);
        eventArgs.Pointer.Capture(grip);
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteResizeGrip_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!quickEditPaletteResizing || sender is not Control grip ||
            !eventArgs.GetCurrentPoint(grip).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var size = WindowsQuickEditPaletteResizePolicy.Resolve(
            quickEditPaletteResizeStartWidth,
            quickEditPaletteResizeStartHeight,
            point.X - quickEditPaletteResizeStart.X,
            point.Y - quickEditPaletteResizeStart.Y,
            editorWorkbench.Bounds.Width,
            editorWorkbench.Bounds.Height);
        quickEditPaletteWidth = size.Width;
        quickEditPaletteHeight = size.Height;
        quickEditPaletteTransform.X = quickEditPaletteResizeStartTransformX +
                                      size.Width - quickEditPaletteResizeStartWidth;
        quickEditPaletteScaleHost.Width = quickEditPaletteWidth;
        quickEditPaletteScaleHost.Height = quickEditPaletteHeight.Value;
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteResizeGrip_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!quickEditPaletteResizing) return;
        EndQuickEditPaletteResize();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndQuickEditPaletteResize()
    {
        if (!quickEditPaletteResizing) return;
        quickEditPaletteResizing = false;
        ClampFloatingControl(quickEditPalette, quickEditPaletteTransform);
        editorViewSettings = editorViewSettings.WithQuickPalette(
            quickEditPaletteTransform.X,
            quickEditPaletteTransform.Y,
            editorViewSettings.QuickPaletteCollapsed);
        MarkEditorViewSettingsDirty();
    }

    private void ApplyQuickEditPaletteLayout()
    {
        // The saved position is honoured everywhere. This used to read
        // `SupportsDesktopWindowSizing ? saved : 0`, which on a tablet undid
        // every drag the moment anything re-applied the layout — and collapsing
        // or expanding the palette does exactly that, immediately after storing
        // the position it was about to discard, so the palette sprang back to
        // the corner on every toggle.
        //
        // Nothing is lost by trusting the value: a tablet gets its opening
        // placement from the factory floating layout instead
        // (factoryFloatingLayoutPending starts true when
        // SupportsDesktopWindowSizing is false), and the queued clamp pass pulls
        // a palette back inside the workbench whenever the bounds change. On
        // Windows the branch was already taking the saved value, so this is the
        // desktop behaviour the tablets are meant to mirror.
        quickEditPaletteTransform.X = editorViewSettings.QuickPaletteX;
        quickEditPaletteTransform.Y = editorViewSettings.QuickPaletteY;
        quickEditPaletteBody.IsVisible = !editorViewSettings.QuickPaletteCollapsed;
        quickEditPaletteContent.Width = editorViewSettings.QuickPaletteCollapsed
            ? 124
            : WindowsInspectorParityPolicy.QuickEditPaletteExpandedContentWidth;
        quickEditPaletteContent.Height = double.NaN;
        quickEditPaletteScaleHost.Width = editorViewSettings.QuickPaletteCollapsed
            ? 124
            : quickEditPaletteWidth;
        quickEditPaletteScaleHost.Height = editorViewSettings.QuickPaletteCollapsed
            ? double.NaN
            : quickEditPaletteHeight ?? double.NaN;
        quickEditPaletteResizeGrip.IsVisible = !editorViewSettings.QuickPaletteCollapsed;
        quickEditPaletteCollapseButton.Content = editorViewSettings.QuickPaletteCollapsed ? "+" : "−";
        ToolTip.SetTip(
            quickEditPaletteCollapseButton,
            editorViewSettings.QuickPaletteCollapsed ? "展开快捷编辑" : "收起快捷编辑");
    }

    private Control BuildQuickValuesPalette()
    {
        ConfigureQuickValueText(quickSnapText);
        ConfigureQuickValueText(quickGridScaleText);
        ConfigureQuickValueText(quickPlaybackRateText);
        quickValuesPaletteBody.Children.Add(BuildQuickValueSection(
            "分度",
            quickSnapText,
            (_, _) => AdjustQuickSnap(1),
            (_, _) => AdjustQuickSnap(-1),
            anchor => ShowQuickPresetMenu(
                anchor,
                QuickSnapDivisions.Select(value =>
                    (TimelineSubdivisionCheckPalette.FormatDivisionLabel(value), (Action)(() => SetQuickSnapDivision(value))))),
            "Snap"));
        quickValuesPaletteBody.Children.Add(BuildQuickValueSection(
            "高度",
            quickGridScaleText,
            (_, _) => AdjustQuickGrid(1),
            (_, _) => AdjustQuickGrid(-1),
            anchor => ShowQuickPresetMenu(
                anchor,
                QuickGridScales.Select(value =>
                    ($"{value:0.0}x", (Action)(() => SetQuickGridScale(value))))),
            "Grid"));
        quickValuesPaletteBody.Children.Add(BuildQuickValueSection(
            "倍速",
            quickPlaybackRateText,
            async (_, _) => await AdjustQuickPlaybackRateAsync(.1),
            async (_, _) => await AdjustQuickPlaybackRateAsync(-.1),
            anchor => ShowQuickPresetMenu(
                anchor,
                QuickPlaybackRates.Select(value =>
                    ($"{value:0.0}x", (Action)(() => _ = SetQuickPlaybackRateAsync(value))))),
            "Rate"));
        quickValuesPaletteBody.Margin = new Thickness(0, 4, 0, 0);
        quickValuesPaletteBody.Width = 100;
        quickValuesPaletteBody.HorizontalAlignment = HorizontalAlignment.Stretch;

        quickValuesPaletteCollapseButton.Content = "−";
        quickValuesPaletteCollapseButton.Width = 23;
        quickValuesPaletteCollapseButton.Height = 20;
        quickValuesPaletteCollapseButton.Padding = new Thickness(0);
        quickValuesPaletteCollapseButton.Background = PanelBrush;
        quickValuesPaletteCollapseButton.Foreground = Brushes.White;
        quickValuesPaletteCollapseButton.BorderBrush = StrokeBrush;
        quickValuesPaletteCollapseButton.BorderThickness = new Thickness(1);
        quickValuesPaletteCollapseButton.CornerRadius = new CornerRadius(3);
        AutomationProperties.SetAutomationId(
            quickValuesPaletteCollapseButton,
            "Editor.QuickValues.Toggle");
        quickValuesPaletteCollapseButton.Click += (_, _) =>
        {
            editorViewSettings = editorViewSettings.WithQuickValuesPalette(
                quickValuesPaletteTransform.X,
                quickValuesPaletteTransform.Y,
                !editorViewSettings.QuickValuesPaletteCollapsed);
            ApplyQuickValuesPaletteLayout();
            MarkEditorViewSettingsDirty();
        };
        var headerRule = new Border
        {
            Width = 20,
            Height = 2,
            Margin = new Thickness(0, 0, 5, 0),
            Background = new SolidColorBrush(Color.Parse("#566166")),
            CornerRadius = new CornerRadius(1),
            VerticalAlignment = VerticalAlignment.Center
        };
        var header = new Border
        {
            Height = 28,
            Cursor = new Cursor(StandardCursorType.SizeAll),
            Background = new SolidColorBrush(Color.Parse("#ED1A1E20")),
            BorderBrush = new SolidColorBrush(Color.Parse("#31383B")),
            BorderThickness = new Thickness(0, 0, 0, 1),
            CornerRadius = new CornerRadius(3, 3, 0, 0),
            Child = new Grid
            {
                Margin = new Thickness(8, 0, 3, 0),
                ColumnDefinitions = new ColumnDefinitions("*,Auto,25"),
                Children =
                {
                    new TextBlock
                    {
                        Text = "调整",
                        Foreground = new SolidColorBrush(Color.Parse("#AAB4B7")),
                        FontSize = 10,
                        FontWeight = FontWeight.SemiBold,
                        VerticalAlignment = VerticalAlignment.Center
                    },
                    headerRule,
                    quickValuesPaletteCollapseButton
                }
            }
        };
        Grid.SetColumn(headerRule, 1);
        Grid.SetColumn(quickValuesPaletteCollapseButton, 2);
        ToolTip.SetTip(header, "按住拖动调整浮窗");
        header.PointerPressed += QuickValuesPaletteHeader_PointerPressed;
        header.PointerMoved += QuickValuesPaletteHeader_PointerMoved;
        header.PointerReleased += QuickValuesPaletteHeader_PointerReleased;
        header.PointerCaptureLost += (_, _) => EndQuickValuesPaletteDrag();

        var content = new StackPanel
        {
            Width = 100,
            HorizontalAlignment = HorizontalAlignment.Stretch
        };
        content.Children.Add(header);
        content.Children.Add(quickValuesPaletteBody);
        quickValuesPalette.Width = WindowsInspectorParityPolicy.QuickValuesPaletteWidth;
        quickValuesPalette.Background = new SolidColorBrush(Color.Parse("#F51A1D20"));
        quickValuesPalette.BorderBrush =
            new SolidColorBrush(Color.Parse("#293135"));
        quickValuesPalette.BorderThickness = new Thickness(.7);
        quickValuesPalette.CornerRadius = new CornerRadius(4);
        quickValuesPalette.Padding = new Thickness(5);
        quickValuesPalette.Margin = new Thickness(
            0,
            54,
            WindowsInspectorParityPolicy.QuickValuesPaletteDefaultRightMargin,
            0);
        quickValuesPalette.HorizontalAlignment = HorizontalAlignment.Right;
        quickValuesPalette.VerticalAlignment = VerticalAlignment.Top;
        quickValuesPalette.ZIndex = 31;
        quickValuesPalette.RenderTransform = quickValuesPaletteTransform;
        quickValuesPalette.Child = content;
        AutomationProperties.SetAutomationId(quickValuesPalette, "Editor.QuickValuesPalette");
        RefreshQuickValuesPaletteValues();
        return quickValuesPalette;
    }

    private Control BuildQuickValueSection(
        string heading,
        TextBlock valueText,
        EventHandler<RoutedEventArgs> increase,
        EventHandler<RoutedEventArgs> decrease,
        Action<Button> showPresets,
        string kind)
    {
        var valueButton = QuickValueButton(string.Empty, (_, _) => { });
        valueButton.Content = valueText;
        valueButton.Click += (_, _) => showPresets(valueButton);
        AutomationProperties.SetAutomationId(valueButton, $"Editor.QuickValues.{kind}.Preset");
        ToolTip.SetTip(valueButton, "左键选择预设 · 右键自定义");

        var editor = new TextBox
        {
            Tag = kind,
            IsVisible = false,
            Height = WindowsInspectorParityPolicy.QuickValuesControlHeight,
            MinHeight = WindowsInspectorParityPolicy.QuickValuesControlHeight,
            FontFamily = new FontFamily("Cascadia Mono, Consolas"),
            FontSize = 10,
            Padding = new Thickness(2, 0),
            Margin = new Thickness(0),
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center
        };
        AutomationProperties.SetAutomationId(editor, $"Editor.QuickValues.{kind}.Editor");
        editor.LostFocus += (_, _) =>
        {
            if (editor.IsVisible) CommitQuickValueEdit(valueButton, editor);
        };
        editor.KeyDown += (_, eventArgs) =>
        {
            if (eventArgs.Key == Key.Enter)
            {
                CommitQuickValueEdit(valueButton, editor);
                timeline.Focus();
                eventArgs.Handled = true;
            }
            else if (eventArgs.Key == Key.Escape)
            {
                EndQuickValueEdit(valueButton, editor);
                timeline.Focus();
                eventArgs.Handled = true;
            }
        };
        editor.ContextRequested += (_, eventArgs) =>
        {
            editor.Focus();
            editor.SelectAll();
            eventArgs.Handled = true;
        };
        editor.AddHandler(
            InputElement.PointerPressedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(editor).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonPressed) return;
                editor.Focus();
                editor.SelectAll();
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        editor.AddHandler(
            InputElement.PointerReleasedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(editor).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonReleased) return;
                editor.Focus();
                editor.SelectAll();
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        valueButton.AddHandler(
            InputElement.PointerPressedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(valueButton).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonPressed) return;
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        valueButton.AddHandler(
            InputElement.PointerReleasedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(valueButton).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonReleased) return;
                BeginQuickValueEdit(valueButton, editor, kind);
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);

        var valueHost = new Grid
        {
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Children = { valueButton, editor }
        };
        var increaseButton = QuickValueButton("▲", increase, new Thickness(0, 3, 0, 0));
        var decreaseButton = QuickValueButton("▼", decrease);
        increaseButton.Click += (_, _) => timeline.Focus();
        decreaseButton.Click += (_, _) => timeline.Focus();
        AutomationProperties.SetAutomationId(increaseButton, $"Editor.QuickValues.{kind}.Up");
        AutomationProperties.SetAutomationId(decreaseButton, $"Editor.QuickValues.{kind}.Down");
        return new StackPanel
        {
            Width = 100,
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Margin = kind == "Rate"
                ? new Thickness(0)
                : new Thickness(
                    0,
                    0,
                    0,
                    WindowsInspectorParityPolicy.QuickValuesSectionGap),
            Children =
            {
                new TextBlock
                {
                    Text = heading,
                    Foreground = new SolidColorBrush(Color.Parse("#7F898D")),
                    FontSize = 9,
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    TextAlignment = TextAlignment.Center
                },
                increaseButton,
                valueHost,
                decreaseButton
            }
        };
    }

    private static Button QuickValueButton(
        string content,
        EventHandler<RoutedEventArgs> handler,
        Thickness? margin = null)
    {
        var button = new Button
        {
            Content = content,
            Height = WindowsInspectorParityPolicy.QuickValuesControlHeight,
            MinHeight = WindowsInspectorParityPolicy.QuickValuesControlHeight,
            Padding = new Thickness(0),
            Margin = margin ?? new Thickness(0),
            HorizontalAlignment = HorizontalAlignment.Stretch,
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center,
            Background = Brushes.Transparent,
            Foreground = Brushes.White,
            BorderBrush = Brushes.Transparent,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3)
        };
        button.Click += handler;
        return button;
    }

    private static void ConfigureQuickValueText(TextBlock text)
    {
        text.FontFamily = new FontFamily("Cascadia Mono, Consolas");
        text.FontSize = 10;
        text.HorizontalAlignment = HorizontalAlignment.Stretch;
        text.VerticalAlignment = VerticalAlignment.Center;
        text.TextAlignment = TextAlignment.Center;
    }

    private void ShowQuickPresetMenu(
        Button anchor,
        IEnumerable<(string Label, Action Apply)> entries)
    {
        var items = entries.Select(entry =>
        {
            var item = new MenuItem
            {
                Header = entry.Label,
                Padding = new Thickness(14, 6),
                FontFamily = new FontFamily("Cascadia Mono, Consolas"),
                Background = RaisedBrush,
                Foreground = Brushes.White
            };
            item.Click += (_, _) => entry.Apply();
            return item;
        }).ToArray();
        var menu = new ContextMenu
        {
            ItemsSource = items,
            Background = RaisedBrush,
            Foreground = Brushes.White,
            BorderBrush = StrokeBrush,
            BorderThickness = new Thickness(1),
            Padding = new Thickness(3)
        };
        popupScaleController.Attach(menu);
        anchor.ContextMenu = menu;
        menu.Open(anchor);
    }

    private void BeginQuickValueEdit(Button button, TextBox editor, string kind)
    {
        editor.Text = kind switch
        {
            "Snap" => TimelineSubdivisionCheckPalette.FormatDivisionLabel(viewModel.ActiveTab?.Session.SnapDivision ?? editorViewSettings.SnapDivision),
            "Grid" => (timeline.PixelsPerBeat / 140d).ToString("0.00", CultureInfo.InvariantCulture),
            _ => audioTransport.PlaybackRate.ToString("0.00", CultureInfo.InvariantCulture)
        };
        button.IsVisible = false;
        editor.IsVisible = true;
        editor.Focus();
        editor.SelectAll();
    }

    private void CommitQuickValueEdit(Button button, TextBox editor)
    {
        var text = (editor.Text ?? string.Empty).Trim().TrimEnd('x', 'X');
        var valid = false;
        if (Equals(editor.Tag, "Snap"))
        {
            if (text.StartsWith("1/", StringComparison.Ordinal)) text = text[2..];
            if (int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var division) &&
                division is >= 1 and <= 1920)
            {
                SetQuickSnapDivision(division);
                valid = true;
            }
        }
        else if (TryTimingNumber(text, out var value))
        {
            if (Equals(editor.Tag, "Grid") && value is >= .2 and <= 3.4)
            {
                SetQuickGridScale(value);
                valid = true;
            }
            else if (Equals(editor.Tag, "Rate") && value is >= .2 and <= 1)
            {
                _ = SetQuickPlaybackRateAsync(value);
                valid = true;
            }
        }

        if (!valid)
            viewModel.SetStatus(Equals(editor.Tag, "Snap")
                ? "分度范围：1–1920"
                : Equals(editor.Tag, "Grid")
                    ? "缩放范围：0.2–3.4"
                    : "倍速范围：0.2–1.0");
        EndQuickValueEdit(button, editor);
    }

    private static void EndQuickValueEdit(Button button, TextBox editor)
    {
        editor.IsVisible = false;
        button.IsVisible = true;
    }

    private void AdjustQuickSnap(int direction)
    {
        var current = viewModel.ActiveTab?.Session.SnapDivision ?? editorViewSettings.SnapDivision;
        var index = Array.IndexOf(QuickSnapDivisions, current);
        var target = index >= 0
            ? QuickSnapDivisions[Math.Clamp(index + direction, 0, QuickSnapDivisions.Length - 1)]
            : direction > 0
                ? QuickSnapDivisions.FirstOrDefault(value => value > current, current)
                : QuickSnapDivisions.LastOrDefault(value => value < current, current);
        SetQuickSnapDivision(target);
    }

    private void SetQuickSnapDivision(int division, bool addCustomDivisionItem = true)
    {
        division = Math.Clamp(division, 1, 1920);
        if (viewModel.ActiveTab is { } tab) tab.Session.SnapDivision = division;
        divisionPicker.SelectedItem = division;
        editorViewSettings = editorViewSettings.WithSnapDivision(division);
        SyncSettingsSnapBox(division, addCustomDivisionItem);
        RefreshQuickValuesPaletteValues();
        timeline.InvalidateVisual();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("当前分度 {0}", TimelineSubdivisionCheckPalette.FormatDivisionLabel(division)));
        MarkEditorViewSettingsDirty();
    }

    private void AdjustQuickGrid(int direction)
    {
        var scale = Math.Round(timeline.PixelsPerBeat / 140d * 10) / 10d;
        SetQuickGridScale(Math.Clamp(scale + direction * .1, .2, 3.4));
    }

    private void SetQuickGridScale(double scale)
    {
        timeline.SetZoom(Math.Clamp(Math.Round(140 * scale), 24, 480));
        RefreshQuickValuesPaletteValues();
    }

    private Task AdjustQuickPlaybackRateAsync(double delta) =>
        SetQuickPlaybackRateAsync(audioTransport.PlaybackRate + delta);

    private async Task SetQuickPlaybackRateAsync(double rate)
    {
        rate = Math.Round(Math.Clamp(rate, .2, 1), 2);
        await SetEditorPlaybackRateAsync(rate);
        RefreshQuickValuesPaletteValues();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("音频与谱面倍速：{0:0.00}x", rate));
    }

    private void RefreshQuickValuesPaletteValues()
    {
        var division = viewModel.ActiveTab?.Session.SnapDivision ?? editorViewSettings.SnapDivision;
        quickSnapText.Text = TimelineSubdivisionCheckPalette.FormatDivisionLabel(division);
        quickGridScaleText.Text = $"{timeline.PixelsPerBeat / 140d:0.00}x";
        quickPlaybackRateText.Text = $"{audioTransport.PlaybackRate:0.00}x";
    }

    private void ApplyQuickValuesPaletteLayout()
    {
        // Same reasoning as ApplyQuickEditPaletteLayout.
        quickValuesPaletteTransform.X = editorViewSettings.QuickValuesPaletteX;
        quickValuesPaletteTransform.Y = editorViewSettings.QuickValuesPaletteY;
        quickValuesPaletteBody.IsVisible = !editorViewSettings.QuickValuesPaletteCollapsed;
        quickValuesPaletteCollapseButton.Content =
            editorViewSettings.QuickValuesPaletteCollapsed ? "+" : "−";
        ToolTip.SetTip(
            quickValuesPaletteCollapseButton,
            editorViewSettings.QuickValuesPaletteCollapsed ? "展开调整" : "收起调整");
    }

    private void QueueFactoryFloatingLayout()
    {
        if (!factoryFloatingLayoutPending || factoryFloatingLayoutQueued) return;
        factoryFloatingLayoutQueued = true;
        Dispatcher.UIThread.Post(() =>
        {
            factoryFloatingLayoutQueued = false;
            if (ApplyFactoryFloatingLayout())
                factoryFloatingLayoutPending = false;
        }, DispatcherPriority.Loaded);
    }

    private void QueueFloatingPaletteClamp()
    {
        if (floatingPaletteClampQueued) return;
        floatingPaletteClampQueued = true;
        Dispatcher.UIThread.Post(() =>
        {
            floatingPaletteClampQueued = false;
            if (!editorView.IsVisible ||
                editorWorkbench.Bounds.Width <= 0 ||
                editorWorkbench.Bounds.Height <= 0)
                return;
            if (factoryFloatingLayoutPending)
            {
                QueueFactoryFloatingLayout();
                return;
            }

            ClampFloatingControl(quickEditPalette, quickEditPaletteTransform);
            ClampFloatingControl(quickValuesPalette, quickValuesPaletteTransform);
            ClampRoomCollaborationPosition();
            SeparateFloatingPalettesIfNeeded();
            editorViewSettings = editorViewSettings
                .WithQuickPalette(
                    quickEditPaletteTransform.X,
                    quickEditPaletteTransform.Y,
                    editorViewSettings.QuickPaletteCollapsed)
                .WithQuickValuesPalette(
                    quickValuesPaletteTransform.X,
                    quickValuesPaletteTransform.Y,
                    editorViewSettings.QuickValuesPaletteCollapsed);
            MarkEditorViewSettingsDirty();
        }, DispatcherPriority.Loaded);
    }

    private void SeparateFloatingPalettesIfNeeded()
    {
        var quickBounds = GetFloatingControlRect(quickEditPalette);
        var valuesBounds = GetFloatingControlRect(quickValuesPalette);
        if (quickBounds.Width <= 0 ||
            quickBounds.Height <= 0 ||
            valuesBounds.Width <= 0 ||
            valuesBounds.Height <= 0 ||
            quickBounds.Right <= valuesBounds.Left ||
            valuesBounds.Right <= quickBounds.Left ||
            quickBounds.Bottom <= valuesBounds.Top ||
            valuesBounds.Bottom <= quickBounds.Top)
            return;

        var placement = WindowsFloatingPaletteLayoutPolicy.Resolve(
            editorWorkbench.Bounds.Width,
            editorWorkbench.Bounds.Height,
            Math.Min(
                editorWorkbench.Bounds.Width - 4,
                Math.Max(quickBounds.Right, valuesBounds.Right)),
            quickBounds.Width,
            quickBounds.Height,
            valuesBounds.Width,
            valuesBounds.Height,
            Math.Min(
                quickBounds.Top,
                WindowsFloatingPaletteLayoutPolicy.DefaultQuickTop),
            WindowsInspectorParityPolicy.FloatingPaletteGap);
        MoveFloatingControlTo(
            quickEditPalette,
            quickEditPaletteTransform,
            placement.QuickLeft,
            placement.QuickTop);
        MoveFloatingControlTo(
            quickValuesPalette,
            quickValuesPaletteTransform,
            placement.ValuesLeft,
            placement.ValuesTop);
        ClampFloatingControl(quickEditPalette, quickEditPaletteTransform);
        ClampFloatingControl(quickValuesPalette, quickValuesPaletteTransform);
    }

    private bool ApplyFactoryFloatingLayout()
    {
        if (applyingFactoryFloatingLayout ||
            viewModel.ActiveTab == null ||
            editorWorkbench.Bounds.Width <= 0 ||
            editorWorkbench.Bounds.Height <= 0 ||
            timeline.Bounds.Width <= 0 ||
            timeline.Bounds.Height <= 0)
            return false;

        var activeTrack = timeline.GetActiveTrackBounds();
        var trackTopLeft = timeline.TranslatePoint(
            new Point(activeTrack.Left, activeTrack.Top),
            editorWorkbench);
        var trackBottomRight = timeline.TranslatePoint(
            new Point(activeTrack.Right, activeTrack.Bottom),
            editorWorkbench);
        if (activeTrack.Width <= 0 ||
            trackTopLeft is not { } topLeft ||
            trackBottomRight is not { } bottomRight ||
            bottomRight.X <= topLeft.X)
            return false;

        applyingFactoryFloatingLayout = true;
        try
        {
            var track = new Rect(
                topLeft.X,
                topLeft.Y,
                bottomRight.X - topLeft.X,
                Math.Max(1, bottomRight.Y - topLeft.Y));
            const double gap = WindowsInspectorParityPolicy.FloatingPaletteGap;
            var rightBoundary = Math.Max(4, editorWorkbench.Bounds.Width - 4);
            var inspectorBounds = GetFloatingControlRect(inspectorPanel);
            if (inspectorPanel.IsVisible &&
                inspectorBounds.Width > 0 &&
                inspectorBounds.Left > track.Right + 40)
                rightBoundary = Math.Min(
                    rightBoundary,
                    inspectorBounds.Left - 6);

            var quickBoundsBeforeCollapse = GetFloatingControlRect(quickEditPalette);
            if (quickBoundsBeforeCollapse.Width <= 0 ||
                quickBoundsBeforeCollapse.Height <= 0)
                return false;
            var quickWidth = Math.Max(
                quickBoundsBeforeCollapse.Width,
                editorViewSettings.QuickPaletteCollapsed ? 134d : 234d);
            var valuesBounds = GetFloatingControlRect(quickValuesPalette);
            if (valuesBounds.Width <= 0 || valuesBounds.Height <= 0)
                return false;
            var placement = WindowsFloatingPaletteLayoutPolicy.Resolve(
                editorWorkbench.Bounds.Width,
                editorWorkbench.Bounds.Height,
                rightBoundary,
                quickWidth,
                quickBoundsBeforeCollapse.Height,
                valuesBounds.Width,
                valuesBounds.Height,
                quickBoundsBeforeCollapse.Top,
                gap);
            MoveFloatingControlTo(
                quickEditPalette,
                quickEditPaletteTransform,
                placement.QuickLeft,
                placement.QuickTop);
            ClampFloatingControl(
                quickEditPalette,
                quickEditPaletteTransform);

            var quickPlaced = GetFloatingControlRect(quickEditPalette);
            if (quickPlaced.Width <= 0 || valuesBounds.Width <= 0)
                return false;
            MoveFloatingControlTo(
                quickValuesPalette,
                quickValuesPaletteTransform,
                placement.ValuesLeft,
                placement.ValuesTop);
            ClampFloatingControl(
                quickValuesPalette,
                quickValuesPaletteTransform);

            editorViewSettings = editorViewSettings
                .WithQuickPalette(
                    quickEditPaletteTransform.X,
                    quickEditPaletteTransform.Y,
                    editorViewSettings.QuickPaletteCollapsed)
                .WithQuickValuesPalette(
                    quickValuesPaletteTransform.X,
                    quickValuesPaletteTransform.Y,
                    editorViewSettings.QuickValuesPaletteCollapsed);
            MarkEditorViewSettingsDirty();
            return true;
        }
        finally
        {
            applyingFactoryFloatingLayout = false;
        }
    }

    private Rect GetFloatingControlRect(Control control)
    {
        if (!control.IsVisible ||
            control.Bounds.Width <= 0 ||
            control.Bounds.Height <= 0 ||
            control.TranslatePoint(new Point(0, 0), editorWorkbench) is not { } position)
            return default;
        return new Rect(
            position.X,
            position.Y,
            control.Bounds.Width,
            control.Bounds.Height);
    }

    private void MoveFloatingControlTo(
        Control control,
        TranslateTransform transform,
        double desiredLeft,
        double desiredTop)
    {
        if (control.TranslatePoint(new Point(0, 0), editorWorkbench) is not { } current)
            return;
        var baseLeft = current.X - transform.X;
        var baseTop = current.Y - transform.Y;
        transform.X = desiredLeft - baseLeft;
        transform.Y = desiredTop - baseTop;
    }

    private void ClampFloatingControl(
        Control control,
        TranslateTransform transform)
    {
        if (control.TranslatePoint(new Point(0, 0), editorWorkbench) is not { } current)
            return;
        var baseLeft = current.X - transform.X;
        var baseTop = current.Y - transform.Y;
        transform.X = Math.Clamp(
            transform.X,
            4 - baseLeft,
            Math.Max(
                4 - baseLeft,
                editorWorkbench.Bounds.Width -
                control.Bounds.Width -
                baseLeft -
                4));
        transform.Y = Math.Clamp(
            transform.Y,
            4 - baseTop,
            Math.Max(
                4 - baseTop,
                editorWorkbench.Bounds.Height -
                control.Bounds.Height -
                baseTop -
                4));
    }

    private void QuickValuesPaletteHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header || quickValuesPaletteCollapseButton.IsPointerOver ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = quickValuesPalette.TranslatePoint(new Point(0, 0), editorWorkbench);
        if (!current.HasValue) return;
        quickValuesPaletteDragging = true;
        quickValuesPaletteDragStart = eventArgs.GetPosition(editorWorkbench);
        quickValuesPaletteDragStartX = quickValuesPaletteTransform.X;
        quickValuesPaletteDragStartY = quickValuesPaletteTransform.Y;
        quickValuesPaletteBaseLeft = current.Value.X - quickValuesPaletteTransform.X;
        quickValuesPaletteBaseTop = current.Value.Y - quickValuesPaletteTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void QuickValuesPaletteHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!quickValuesPaletteDragging || sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var x = quickValuesPaletteDragStartX + point.X - quickValuesPaletteDragStart.X;
        var y = quickValuesPaletteDragStartY + point.Y - quickValuesPaletteDragStart.Y;
        quickValuesPaletteTransform.X = Math.Clamp(
            x,
            4 - quickValuesPaletteBaseLeft,
            Math.Max(
                4 - quickValuesPaletteBaseLeft,
                editorWorkbench.Bounds.Width - quickValuesPalette.Bounds.Width -
                quickValuesPaletteBaseLeft - 4));
        quickValuesPaletteTransform.Y = Math.Clamp(
            y,
            4 - quickValuesPaletteBaseTop,
            Math.Max(
                4 - quickValuesPaletteBaseTop,
                editorWorkbench.Bounds.Height - quickValuesPalette.Bounds.Height -
                quickValuesPaletteBaseTop - 4));
        eventArgs.Handled = true;
    }

    private void QuickValuesPaletteHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!quickValuesPaletteDragging) return;
        EndQuickValuesPaletteDrag();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndQuickValuesPaletteDrag()
    {
        if (!quickValuesPaletteDragging) return;
        quickValuesPaletteDragging = false;
        editorViewSettings = editorViewSettings.WithQuickValuesPalette(
            quickValuesPaletteTransform.X,
            quickValuesPaletteTransform.Y,
            editorViewSettings.QuickValuesPaletteCollapsed);
        MarkEditorViewSettingsDirty();
    }

