    private void ApplyRoomCollaborationCollapsedState()
    {
        roomCollaborationBody.IsVisible = !roomCollaborationCollapsed;
        roomCollaborationPanel.Width = roomCollaborationCollapsed ? 188 : 292;
        roomCollaborationToggleButton.Content =
            roomCollaborationCollapsed ? "+" : "−";
        ToolTip.SetTip(
            roomCollaborationToggleButton,
            roomCollaborationCollapsed
                ? "展开成员与聊天"
                : "收起成员与聊天");
        QueueFloatingPaletteClamp();
    }

    private void RefreshRoomCollaborationPanelVisibility()
    {
        var visible =
            onlineAccountHost?.Session.CurrentRoom?.Id == roomChartSyncRoomId &&
            roomChartSyncTab != null &&
            ReferenceEquals(viewModel.ActiveTab, roomChartSyncTab) &&
            editorView.IsVisible;
        roomCollaborationPanel.IsVisible = visible;
        if (visible && IsRoomChatActivelyVisible())
            SetRoomChatUnread(false);
        if (visible) QueueFloatingPaletteClamp();
    }

    private bool IsRoomChatActivelyVisible() =>
        IsActive &&
        roomCollaborationPanel.IsVisible &&
        roomCollaborationBody.IsVisible;

    private void SetRoomChatUnread(bool unread)
    {
        roomChatHasUnread = unread;
        roomChatUnreadDot.IsVisible = unread;
        AutomationProperties.SetHelpText(
            roomCollaborationPanel,
            $"Unread={unread}; Messages={roomChatMessages.Count}; " +
            $"LatestMessageId={latestRoomMessageId}; " +
            $"Collapsed={roomCollaborationCollapsed}");
    }

    private void ResetRoomChatUi(bool reveal)
    {
        roomChatMessages.Clear();
        latestRoomMessageId = 0;
        roomChatInitialized = false;
        roomChatStatusText.Text = string.Empty;
        roomChatInputBox.Text = string.Empty;
        roomChatList.ItemsSource = Array.Empty<OnlineRoomChatMessageDto>();
        roomMemberList.ItemsSource = Array.Empty<OnlineRoomMemberDto>();
        roomMemberCountText.Text = "0 / 8";
        roomCollaborationTitle.Text = roomChartSyncRoomName.Length == 0
            ? "联机房间"
            : roomChartSyncRoomName;
        if (reveal)
        {
            roomCollaborationCollapsed = false;
            ApplyRoomCollaborationCollapsedState();
        }
        SetRoomChatUnread(false);
        RefreshRoomCollaborationPanelVisibility();
    }

    private void AppendRoomChatMessages(
        IReadOnlyList<OnlineRoomChatMessageDto> messages,
        long latestMessageId)
    {
        var currentUserId =
            onlineAccountHost?.Session.CurrentUser?.Id ?? 0;
        var incoming = messages
            .Where(message => roomChatMessages.All(existing =>
                existing.Id != message.Id))
            .OrderBy(message => message.Id)
            .ToArray();
        var initializedBeforeAppend = roomChatInitialized;
        foreach (var message in incoming)
        {
            roomChatMessages.Add(message);
            latestRoomMessageId = Math.Max(latestRoomMessageId, message.Id);
            if (initializedBeforeAppend &&
                message.UserId != currentUserId &&
                !IsRoomChatActivelyVisible())
                SetRoomChatUnread(true);
        }
        latestRoomMessageId = Math.Max(latestRoomMessageId, latestMessageId);
        roomChatInitialized = true;
        if (roomChatMessages.Count > 200)
            roomChatMessages.RemoveRange(0, roomChatMessages.Count - 200);
        if (incoming.Length == 0) return;
        roomChatList.ItemsSource = roomChatMessages.ToArray();
        roomChatList.ScrollIntoView(roomChatMessages[^1]);
    }

    private async Task SendRoomChatAsync()
    {
        var session = onlineAccountHost?.Session;
        var message = roomChatInputBox.Text?.Trim() ?? string.Empty;
        if (roomChatSendInProgress || session?.CurrentRoom == null ||
            message.Length == 0)
            return;
        roomChatSendInProgress = true;
        sendRoomChatButton.IsEnabled = false;
        roomChatStatusText.Text = "正在发送…";
        try
        {
            using var timeout =
                new CancellationTokenSource(TimeSpan.FromSeconds(15));
            var result = await session.SendRoomChatAsync(
                message,
                timeout.Token);
            if (result.Outcome != OnlineRoomLifecycleOutcome.Success ||
                result.Value == null)
            {
                roomChatStatusText.Text = "消息未发送：房间已结束或无发送权限";
                return;
            }
            AppendRoomChatMessages(
                [result.Value],
                Math.Max(latestRoomMessageId, result.Value.Id));
            // The box stays editable while sending; only clear it when it still
            // holds the sent message, so text typed meanwhile is not swallowed.
            if (string.Equals(
                    roomChatInputBox.Text?.Trim() ?? string.Empty,
                    message,
                    StringComparison.Ordinal))
                roomChatInputBox.Text = string.Empty;
            roomChatStatusText.Text = string.Empty;
            SetRoomChatUnread(false);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            roomChatStatusText.Text = AvaloniaLocalizationCatalog.Format("发送失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
        }
        finally
        {
            roomChatSendInProgress = false;
            sendRoomChatButton.IsEnabled =
                onlineAccountHost?.Session.CurrentRoom != null;
        }
    }

    private void RoomCollaborationHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header ||
            roomCollaborationToggleButton.IsPointerOver ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = roomCollaborationPanel.TranslatePoint(
            new Point(0, 0),
            editorWorkbench);
        if (!current.HasValue) return;
        roomCollaborationDragging = true;
        roomCollaborationDragStart =
            eventArgs.GetPosition(editorWorkbench);
        roomCollaborationDragStartX = roomCollaborationTransform.X;
        roomCollaborationDragStartY = roomCollaborationTransform.Y;
        roomCollaborationBaseLeft =
            current.Value.X - roomCollaborationTransform.X;
        roomCollaborationBaseTop =
            current.Value.Y - roomCollaborationTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void RoomCollaborationHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!roomCollaborationDragging ||
            sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var x = roomCollaborationDragStartX +
                point.X - roomCollaborationDragStart.X;
        var y = roomCollaborationDragStartY +
                point.Y - roomCollaborationDragStart.Y;
        roomCollaborationTransform.X = Math.Clamp(
            x,
            4 - roomCollaborationBaseLeft,
            Math.Max(
                4 - roomCollaborationBaseLeft,
                editorWorkbench.Bounds.Width -
                roomCollaborationPanel.Bounds.Width -
                roomCollaborationBaseLeft - 4));
        roomCollaborationTransform.Y = Math.Clamp(
            y,
            4 - roomCollaborationBaseTop,
            Math.Max(
                4 - roomCollaborationBaseTop,
                editorWorkbench.Bounds.Height -
                roomCollaborationPanel.Bounds.Height -
                roomCollaborationBaseTop - 4));
        eventArgs.Handled = true;
    }

    private void RoomCollaborationHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!roomCollaborationDragging) return;
        roomCollaborationDragging = false;
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void ClampRoomCollaborationPosition()
    {
        if (roomCollaborationDragging ||
            editorWorkbench.Bounds.Width <= 0 ||
            editorWorkbench.Bounds.Height <= 0 ||
            roomCollaborationPanel.Bounds.Width <= 0)
            return;
        var current = roomCollaborationPanel.TranslatePoint(
            new Point(0, 0),
            editorWorkbench);
        if (!current.HasValue) return;
        var baseLeft = current.Value.X - roomCollaborationTransform.X;
        var baseTop = current.Value.Y - roomCollaborationTransform.Y;
        roomCollaborationTransform.X = Math.Clamp(
            roomCollaborationTransform.X,
            4 - baseLeft,
            Math.Max(
                4 - baseLeft,
                editorWorkbench.Bounds.Width -
                roomCollaborationPanel.Bounds.Width - baseLeft - 4));
        roomCollaborationTransform.Y = Math.Clamp(
            roomCollaborationTransform.Y,
            4 - baseTop,
            Math.Max(
                4 - baseTop,
                editorWorkbench.Bounds.Height -
                roomCollaborationPanel.Bounds.Height - baseTop - 4));
    }

    /// <summary>
    /// The toolbox: a list of functions on the left, the parameters of the
    /// selected function and the button that runs it on the right. Every
    /// action used to be its own button in a two-column grid, which is what
    /// made the palette read as a pile rather than a tool set.
    /// </summary>
    private Control BuildExtensionPalette()
    {
        var itemList = new StackPanel { Spacing = 1 };
        AddToolboxGroup(itemList, "选区");
        AddToolboxItem(itemList, ToolboxSelectLongNotes, "只选中面");
        AddToolboxItem(itemList, ToolboxSelectTaps, "只选中米");
        AddToolboxGroup(itemList, "转换");
        AddToolboxItem(itemList, ToolboxLongToTap, "面 → 米");
        AddToolboxItem(itemList, ToolboxTapToLong, "米 → 反键");
        AddToolboxItem(itemList, ToolboxTapPairToLong, "米 → 面");
        AddToolboxItem(itemList, ToolboxCurveDensity, "曲线密度");
        AddToolboxItem(itemList, ToolboxFillGaps, "填充音符间隔");
        AddToolboxGroup(itemList, "排列");
        AddToolboxItem(itemList, ToolboxRandomFixed, "随机排列");
        AddToolboxItem(itemList, ToolboxRandomPerBeat, "完全随机");
        AddToolboxItem(itemList, ToolboxSwapOuterInner, "内外对调");
        AddToolboxGroup(itemList, "视图");
        AddToolboxItem(itemList, ToolboxHideBodies, "隐藏面身");

        var listHost = new Border
        {
            Background = new SolidColorBrush(Color.Parse("#14181A")),
            BorderBrush = new SolidColorBrush(Color.Parse("#2C3237")),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Padding = new Thickness(3),
            VerticalAlignment = VerticalAlignment.Top,
            Child = itemList
        };

        toolboxPanelTitle = new TextBlock
        {
            FontSize = 12,
            FontWeight = FontWeight.SemiBold,
            Foreground = new SolidColorBrush(Color.Parse("#EDEFF0"))
        };
        toolboxPanelDescription = new TextBlock
        {
            FontSize = 10.5,
            Foreground = MutedBrush,
            TextWrapping = TextWrapping.Wrap,
            LineHeight = 15,
            Margin = new Thickness(0, 3, 0, 0)
        };
        toolboxCurveParameters = BuildToolboxCurveParameters();
        toolboxFillParameters = BuildToolboxFillParameters();
        // Filled once and only toggled visible: a ContentControl whose content
        // is set back to null and then re-attached tears the parameter controls
        // down and rebuilds them, which is where the division pickers used to
        // lose their rendered face. Both parameter panels stay attached and
        // only their own IsVisible changes when another tool is picked.
        // A tool with a few settings runs out of column height, so the parameter
        // area scrolls on its own. The title, the description and the run button
        // stay put; only what sits between them moves.
        toolboxParameterHost = new ScrollViewer
        {
            Margin = new Thickness(0, 7, 0, 0),
            MaxHeight = 320,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalContentAlignment = HorizontalAlignment.Stretch,
            Content = new StackPanel
            {
                Children =
                {
                    toolboxCurveParameters,
                    toolboxFillParameters
                }
            },
            IsVisible = false
        };
        toolboxActionButton = new Button
        {
            Content = "执行",
            Margin = new Thickness(0, 8, 0, 0),
            Padding = new Thickness(10, 6),
            HorizontalAlignment = HorizontalAlignment.Stretch,
            HorizontalContentAlignment = HorizontalAlignment.Center,
            Background = new SolidColorBrush(Color.Parse("#26302F")),
            BorderBrush = new SolidColorBrush(Color.Parse("#5F7E82")),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Foreground = new SolidColorBrush(Color.Parse("#EDEFF0"))
        };
        toolboxActionButton.Click += async (_, _) => await RunToolboxActionAsync();
        AutomationProperties.SetAutomationId(toolboxActionButton, "Editor.Toolbox.Run");
        ToolTip.SetTip(toolboxActionButton, "对当前选区执行左侧选中的功能");

        var panel = new Grid
        {
            Margin = new Thickness(7, 0, 0, 0),
            RowDefinitions = new RowDefinitions("Auto,Auto,*,Auto")
        };
        panel.Children.Add(toolboxPanelTitle);
        Grid.SetRow(toolboxPanelDescription, 1);
        panel.Children.Add(toolboxPanelDescription);
        Grid.SetRow(toolboxParameterHost, 2);
        panel.Children.Add(toolboxParameterHost);
        Grid.SetRow(toolboxActionButton, 3);
        panel.Children.Add(toolboxActionButton);

        var body = new Grid
        {
            Margin = new Thickness(0, 4, 0, 0),
            ColumnDefinitions = new ColumnDefinitions("112,*")
        };
        body.Children.Add(listHost);
        Grid.SetColumn(panel, 1);
        body.Children.Add(panel);

        var headerGrid = new Grid
        {
            Margin = new Thickness(8, 0),
            ColumnDefinitions = new ColumnDefinitions("*,Auto")
        };
        headerGrid.Children.Add(new TextBlock
        {
            Text = "工具箱",
            Foreground = new SolidColorBrush(Color.Parse("#D6DADB")),
            FontSize = 11,
            VerticalAlignment = VerticalAlignment.Center
        });
        var grip = new TextBlock
        {
            Text = "⠿",
            Foreground = new SolidColorBrush(Color.Parse("#7D878C")),
            FontSize = 15,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(grip, 1);
        headerGrid.Children.Add(grip);
        var header = new Border
        {
            Height = 28,
            Background = new SolidColorBrush(Color.Parse("#202428")),
            CornerRadius = new CornerRadius(3),
            Cursor = new Cursor(StandardCursorType.SizeAll),
            Child = headerGrid
        };
        ToolTip.SetTip(header, "按住拖动工具箱浮窗");
        AutomationProperties.SetAutomationId(header, "Editor.Extension.Header");
        header.PointerPressed += ExtensionPaletteHeader_PointerPressed;
        header.PointerMoved += ExtensionPaletteHeader_PointerMoved;
        header.PointerReleased += ExtensionPaletteHeader_PointerReleased;
        header.PointerCaptureLost += (_, _) => extensionPaletteDragging = false;

        var content = new StackPanel
        {
            Width = 352,
            Children = { header, body }
        };
        extensionPalette.Background = new SolidColorBrush(Color.Parse("#F51A1D20"));
        extensionPalette.BorderBrush = new SolidColorBrush(Color.Parse("#3B4246"));
        extensionPalette.BorderThickness = new Thickness(1);
        extensionPalette.CornerRadius = new CornerRadius(4);
        extensionPalette.Padding = new Thickness(5);
        extensionPalette.Margin = new Thickness(176, 54, 0, 0);
        extensionPalette.HorizontalAlignment = HorizontalAlignment.Left;
        extensionPalette.VerticalAlignment = VerticalAlignment.Top;
        extensionPalette.ZIndex = 26;
        extensionPalette.IsVisible = false;
        extensionPalette.RenderTransform = extensionPaletteTransform;
        extensionPalette.Child = content;
        AutomationProperties.SetAutomationId(extensionPalette, "Editor.Extension.Palette");

        RefreshToolboxPanel();
        return extensionPalette;
    }

    private static void AddToolboxGroup(Panel host, string text) =>
        host.Children.Add(new TextBlock
        {
            Text = text,
            FontSize = 9,
            Foreground = new SolidColorBrush(Color.Parse("#6D7A7F")),
            Margin = new Thickness(5, 6, 0, 2)
        });

    private void AddToolboxItem(Panel host, string key, string text)
    {
        var button = new Button
        {
            Content = new TextBlock
            {
                Text = text,
                FontSize = 11,
                HorizontalAlignment = HorizontalAlignment.Left
            },
            Padding = new Thickness(6, 3),
            HorizontalAlignment = HorizontalAlignment.Stretch,
            HorizontalContentAlignment = HorizontalAlignment.Left,
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(1),
            BorderBrush = Brushes.Transparent,
            CornerRadius = new CornerRadius(3)
        };
        button.Click += (_, _) => SelectToolboxItem(key);
        AutomationProperties.SetAutomationId(button, $"Editor.Toolbox.Item.{key}");
        toolboxItemButtons[key] = button;
        host.Children.Add(button);
    }

    private static void ApplyToolboxItemState(Button button, bool active)
    {
        button.Background = active
            ? new SolidColorBrush(Color.Parse("#2A3336"))
            : Brushes.Transparent;
        button.BorderBrush = active
            ? new SolidColorBrush(Color.Parse("#4C6266"))
            : Brushes.Transparent;
        button.Foreground = active
            ? new SolidColorBrush(Color.Parse("#F0F2F2"))
            : new SolidColorBrush(Color.Parse("#C3C9CB"));
    }

    private static void ApplyToolboxChoiceState(Button button, bool active)
    {
        button.Background = active
            ? new SolidColorBrush(Color.Parse("#2A3336"))
            : new SolidColorBrush(Color.Parse("#1B1F22"));
        button.BorderBrush = active
            ? new SolidColorBrush(Color.Parse("#5F7E82"))
            : new SolidColorBrush(Color.Parse("#2C3237"));
    }

    /// <summary>
    /// Parameter area of the curve function. Everything it edits lives in the
    /// editor view settings, so the next run reuses whatever was chosen here.
    /// </summary>
    private Control BuildToolboxCurveParameters()
    {
        var stack = new StackPanel { Spacing = 2 };
        stack.Children.Add(ToolboxFieldLabel("形状"));
        foreach (var (shape, text) in new[]
                 {
                     (CurveDensityShape.DenseSparseDense, "密 → 疏 → 密"),
                     (CurveDensityShape.SparseToDense, "疏 → 密"),
                     (CurveDensityShape.DenseToSparse, "密 → 疏")
                 })
        {
            var captured = shape;
            var button = new Button
            {
                Content = new TextBlock
                {
                    Text = text,
                    FontSize = 11,
                    HorizontalAlignment = HorizontalAlignment.Left
                },
                Padding = new Thickness(6, 3),
                HorizontalAlignment = HorizontalAlignment.Stretch,
                HorizontalContentAlignment = HorizontalAlignment.Left,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(3),
                Foreground = new SolidColorBrush(Color.Parse("#DCE1E2"))
            };
            button.Click += (_, _) => SetToolboxCurveShape(captured);
            AutomationProperties.SetAutomationId(
                button,
                $"Editor.Toolbox.CurveShape.{shape}");
            toolboxShapeButtons[shape] = button;
            stack.Children.Add(button);
        }

        stack.Children.Add(ToolboxFieldLabel("最密间隔", top: 6));
        stack.Children.Add(toolboxCurveDenseBox);
        stack.Children.Add(ToolboxFieldLabel("最疏间隔", top: 4));
        stack.Children.Add(toolboxCurveSparseBox);

        stack.Children.Add(ToolboxFieldLabel("排列方式", top: 6));
        foreach (var (arrangement, text) in new[]
                 {
                     (CurveLaneArrangement.Single, "单轨"),
                     (CurveLaneArrangement.Stairs, "楼梯"),
                     (CurveLaneArrangement.Alternate, "交互")
                 })
            toolboxCurveLaneBox.Items.Add(new LabeledChoice((int)arrangement, text));
        toolboxCurveLaneBox.IsTextSearchEnabled = false;
        toolboxCurveLaneBox.HorizontalAlignment = HorizontalAlignment.Stretch;
        toolboxCurveLaneBox.FontSize = 11;
        // A plain-data item again: a ComboBox fed ready-made ComboBoxItems keeps
        // rendering the item selected at build time (see the division pickers).
        toolboxCurveLaneBox.SelectionChanged += ToolboxCurveLaneBox_SelectionChanged;
        SyncToolboxCurveLaneBox();
        AutomationProperties.SetAutomationId(
            toolboxCurveLaneBox,
            "Editor.Toolbox.CurveLaneOrder");
        AutomationProperties.SetName(toolboxCurveLaneBox, "曲线排列方式");
        ToolTip.SetTip(
            toolboxCurveLaneBox,
            "单轨：全部落在原长条那一列；楼梯：1→2→3→4 循环；交互：1→2→1→2 交替。三种都从原长条所在列起算");
        stack.Children.Add(toolboxCurveLaneBox);

        toolboxCurvePreview = new TextBlock
        {
            FontSize = 10,
            Foreground = MutedBrush,
            TextWrapping = TextWrapping.Wrap,
            LineHeight = 14,
            Margin = new Thickness(0, 7, 0, 0)
        };
        stack.Children.Add(toolboxCurvePreview);
        return stack;
    }

    private static TextBlock ToolboxFieldLabel(string text, double top = 0) => new()
    {
        Text = text,
        FontSize = 9,
        Foreground = new SolidColorBrush(Color.Parse("#7B878C")),
        Margin = new Thickness(0, top, 0, 1)
    };

    /// <summary>
    /// Parameter area of the gap fill: one number, plus a preview of how many
    /// notes the current selection would get.
    /// </summary>
    private Control BuildToolboxFillParameters()
    {
        var stack = new StackPanel { Spacing = 2 };
        stack.Children.Add(ToolboxFieldLabel("每段中间插几个"));
        var row = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 4
        };
        row.Children.Add(ToolboxStepButton("−", () => AdjustGapFillCount(-1)));
        toolboxFillCountBox = new TextBox
        {
            Text = toolboxGapFillCount.ToString(
                System.Globalization.CultureInfo.InvariantCulture),
            Width = 48,
            FontSize = 11,
            Padding = new Thickness(4, 2),
            Background = new SolidColorBrush(Color.Parse("#1B1F22")),
            BorderBrush = new SolidColorBrush(Color.Parse("#2C3237")),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Foreground = new SolidColorBrush(Color.Parse("#EDEFF0")),
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center
        };
        toolboxFillCountBox.TextChanged += ToolboxFillCountBox_TextChanged;
        toolboxFillCountBox.LostFocus += (_, _) => SyncGapFillCountBox();
        AutomationProperties.SetAutomationId(
            toolboxFillCountBox,
            "Editor.Toolbox.FillCount");
        AutomationProperties.SetName(toolboxFillCountBox, "每段插入个数");
        row.Children.Add(toolboxFillCountBox);
        row.Children.Add(ToolboxStepButton("+", () => AdjustGapFillCount(1)));
        stack.Children.Add(row);

        toolboxFillPreview = new TextBlock
        {
            FontSize = 10,
            Foreground = MutedBrush,
            TextWrapping = TextWrapping.Wrap,
            LineHeight = 14,
            Margin = new Thickness(0, 7, 0, 0)
        };
        stack.Children.Add(toolboxFillPreview);
        return stack;
    }

    private static Button ToolboxStepButton(string text, Action onClick)
    {
        var button = new Button
        {
            Content = new TextBlock { Text = text, FontSize = 12 },
            Width = 26,
            Height = 24,
            Padding = new Thickness(0),
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center,
            Background = new SolidColorBrush(Color.Parse("#1B1F22")),
            BorderBrush = new SolidColorBrush(Color.Parse("#2C3237")),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Foreground = new SolidColorBrush(Color.Parse("#DCE1E2"))
        };
        button.Click += (_, _) => onClick();
        return button;
    }

    private void AdjustGapFillCount(int delta)
    {
        SetGapFillCount(toolboxGapFillCount + delta);
    }

    private void SetGapFillCount(int count)
    {
        toolboxGapFillCount = Math.Clamp(
            count,
            NoteGapFillService.MinimumCount,
            NoteGapFillService.MaximumCount);
        SyncGapFillCountBox();
        RefreshToolboxFillPreview();
    }

    private void SyncGapFillCountBox()
    {
        if (toolboxFillCountBox == null) return;
        var text = toolboxGapFillCount.ToString(
            System.Globalization.CultureInfo.InvariantCulture);
        if (toolboxFillCountBox.Text != text) toolboxFillCountBox.Text = text;
    }

    private void ToolboxFillCountBox_TextChanged(
        object? sender,
        TextChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (toolboxFillCountBox == null) return;
        var raw = (toolboxFillCountBox.Text ?? string.Empty).Trim();
        if (!int.TryParse(
                raw,
                System.Globalization.NumberStyles.Integer,
                System.Globalization.CultureInfo.InvariantCulture,
                out var parsed))
            return;
        parsed = Math.Clamp(
            parsed,
            NoteGapFillService.MinimumCount,
            NoteGapFillService.MaximumCount);
        if (parsed == toolboxGapFillCount) return;
        // Deliberately no text rewrite while typing: clamping a half-typed value
        // would move the caret out from under the user. The box is normalised on
        // lost focus and whenever the ± buttons run.
        toolboxGapFillCount = parsed;
        RefreshToolboxFillPreview();
    }

    /// <summary>
    /// How many notes the current selection would get, so the panel answers
    /// "how many is this going to make" before the run instead of after.
    /// </summary>
    private void RefreshToolboxFillPreview()
    {
        if (toolboxFillPreview == null) return;
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.Session.IsReadOnly)
        {
            toolboxFillPreview.Text = "打开一张可编辑的谱面后可用";
            return;
        }
        var taps = WindowsNoteGapFillCommand.CountSelectedTaps(
            tab.Session,
            tab.HiddenGroups);
        if (taps < 2)
        {
            toolboxFillPreview.Text = "先选中同一轨道上前后两颗米";
            return;
        }
        var plan = WindowsNoteGapFillCommand.Plan(
            tab.Session,
            toolboxGapFillCount,
            tab.HiddenGroups);
        var text = AvaloniaLocalizationCatalog.Format(
            "选中 {0} 颗米 · {1} 段 · 生成 {2} 个",
            taps,
            plan.Pairs,
            plan.Notes);
        if (plan.Blocked > 0)
            text += AvaloniaLocalizationCatalog.Format("（{0} 个位置已有音符，跳过）", plan.Blocked);
        if (plan.TooShort > 0)
            text += AvaloniaLocalizationCatalog.Format("（{0} 段放不下，跳过）", plan.TooShort);
        toolboxFillPreview.Text = text;
    }

    private void SetToolboxCurveShape(CurveDensityShape shape)
    {
        if (editorViewSettings.CurveShape != shape)
        {
            editorViewSettings = editorViewSettings.WithCurveShape(shape);
            ApplyEditorViewSettings();
            MarkEditorViewSettingsDirty();
        }
        RefreshToolboxPanel();
        timeline.Focus();
    }

    private void SyncToolboxCurveLaneBox()
    {
        var wasSuppressed = suppressEditorViewControls;
        suppressEditorViewControls = true;
        try
        {
            var wanted = (int)editorViewSettings.CurveLaneOrder;
            toolboxCurveLaneBox.SelectedItem = toolboxCurveLaneBox.Items
                .OfType<LabeledChoice>()
                .FirstOrDefault(choice => choice.Value == wanted);
        }
        finally
        {
            suppressEditorViewControls = wasSuppressed;
        }
    }

    private void ToolboxCurveLaneBox_SelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        _ = eventArgs;
        if (suppressEditorViewControls) return;
        if (sender is not ComboBox { SelectedItem: LabeledChoice choice }) return;
        if (!Enum.IsDefined(typeof(CurveLaneArrangement), choice.Value)) return;
        var arrangement = (CurveLaneArrangement)choice.Value;
        if (editorViewSettings.CurveLaneOrder == arrangement) return;
        editorViewSettings = editorViewSettings.WithCurveLaneOrder(arrangement);
        ApplyEditorViewSettings();
        MarkEditorViewSettingsDirty();
        RefreshToolboxCurvePreview();
        viewModel.SetStatus(arrangement switch
        {
            CurveLaneArrangement.Stairs => "曲线排列方式：楼梯（1→2→3→4 循环）",
            CurveLaneArrangement.Alternate => "曲线排列方式：交互（1→2→1→2 交替）",
            _ => "曲线排列方式：单轨"
        });
    }

    private void SelectToolboxItem(string key)
    {
        if (!toolboxItemButtons.ContainsKey(key)) return;
        toolboxSelection = key;
        RefreshToolboxPanel();
        timeline.Focus();
    }

    private static (string Title, string Description, string ActionText)
        DescribeToolboxSelection(string key) => key switch
        {
            ToolboxSelectLongNotes => (
                "只选中面",
                "从当前选区里只留下面（LN），米会被取消选中。",
                "只留面"),
            ToolboxSelectTaps => (
                "只选中米",
                "从当前选区里只留下米（Tap），面会被取消选中。",
                "只留米"),
            ToolboxLongToTap => (
                "面 → 米",
                "把选中的面转换成米，只在面头留下一颗。",
                "转换"),
            ToolboxTapToLong => (
                "米 → 反键",
                "把选中的米延伸成面，尾巴落在同列下一颗 Note 的前一格。",
                "转换"),
            ToolboxTapPairToLong => (
                "米 → 面",
                "选中同一轨道上前后两颗米，前一颗当面头、后一颗当面尾，合成一根面。同轨多颗米按相邻成对，落单的那颗不动。",
                "转换"),
            ToolboxCurveDensity => (
                "曲线密度",
                "把选中的面换成间隔按曲线变化的米，用面头到面尾做区间。",
                "生成"),
            ToolboxFillGaps => (
                "填充音符间隔",
                "选中同一轨道上前后两颗米，在它们中间平均插入指定个数的米。同轨多颗米按相邻成对处理。",
                "填充"),
            ToolboxRandomFixed => (
                "随机排列",
                "整组选区共用一套随机轨道映射，行的相对位置不变。",
                "重排"),
            ToolboxRandomPerBeat => (
                "完全随机",
                "每一排各自随机，行的相对位置也会变。",
                "重排"),
            ToolboxSwapOuterInner => (
                "内外对调",
                "把 1↔2、3↔4 轨道互换，只有 4K 谱面有效。",
                "对调"),
            ToolboxHideBodies => (
                "隐藏面身",
                "只画长条头部的方块，面身和尾巴不画。",
                "切换"),
            _ => ("工具箱", string.Empty, "执行")
        };

    private void RefreshToolboxPanel()
    {
        var (title, description, actionText) = DescribeToolboxSelection(toolboxSelection);
        if (toolboxPanelTitle != null) toolboxPanelTitle.Text = title;
        if (toolboxPanelDescription != null) toolboxPanelDescription.Text = description;
        var showCurveParameters = toolboxSelection == ToolboxCurveDensity;
        var showFillParameters = toolboxSelection == ToolboxFillGaps;
        if (toolboxCurveParameters != null)
            toolboxCurveParameters.IsVisible = showCurveParameters;
        if (toolboxFillParameters != null)
            toolboxFillParameters.IsVisible = showFillParameters;
        if (toolboxParameterHost != null)
            toolboxParameterHost.IsVisible = showCurveParameters || showFillParameters;
        if (toolboxActionButton != null)
            toolboxActionButton.Content = toolboxSelection == ToolboxHideBodies
                ? (timeline.HideLongNoteBodies ? "恢复面身显示" : "隐藏面身")
                : actionText;
        foreach (var pair in toolboxShapeButtons)
            ApplyToolboxChoiceState(pair.Value, pair.Key == editorViewSettings.CurveShape);
        foreach (var pair in toolboxItemButtons)
            ApplyToolboxItemState(pair.Value, pair.Key == toolboxSelection);
        RefreshToolboxCurvePreview();
        RefreshToolboxFillPreview();
        UpdateToolboxAvailability();
    }

    /// <summary>
    /// Note count of the selected range under the current settings, so the
    /// parameter panel answers "how many is this going to make" before the
    /// run instead of after.
    /// </summary>
    private void RefreshToolboxCurvePreview()
    {
        if (toolboxCurvePreview == null) return;
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.Session.IsReadOnly)
        {
            toolboxCurvePreview.Text = "打开一张可编辑的谱面后可用";
            return;
        }
        var count = WindowsCurveDensityCommand.CountSelectedLongNotes(
            tab.Session,
            tab.HiddenGroups);
        if (count == 0)
        {
            toolboxCurvePreview.Text = "先选中一根面：面头到面尾就是区间";
            return;
        }
        var first = WindowsCurveDensityCommand.FirstSelectedLongNote(
            tab.Session,
            tab.HiddenGroups);
        var length = first?.EndBeat is { } tail ? tail.Value - first.Beat.Value : 0;
        if (length <= 0)
        {
            toolboxCurvePreview.Text = "选中的面没有长度（面头等于面尾）";
            return;
        }
        try
        {
            var notes = CurveDensityService.EstimateNoteCount(
                length,
                CurrentCurveDensityOptions());
            toolboxCurvePreview.Text = AvaloniaLocalizationCatalog.Format(
                "区间 {0} 拍 → 约 {1} 个米",
                length.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture),
                notes);
        }
        catch (InvalidOperationException)
        {
            toolboxCurvePreview.Text = "这个区间会超过 4096 个米：加大最密间隔或缩短区间";
        }
    }

    private CurveDensityOptions CurrentCurveDensityOptions() => new(
        editorViewSettings.CurveShape,
        editorViewSettings.CurveDenseDivision,
        editorViewSettings.CurveSparseDivision,
        LaneArrangement: editorViewSettings.CurveLaneOrder);

    private void UpdateToolboxAvailability()
    {
        if (toolboxActionButton == null) return;
        var session = viewModel.ActiveTab?.Session;
        var selected = session?.Selection.Count ?? 0;
        var canEdit = session != null && !session.IsReadOnly && session.CanEditNotes;
        toolboxActionButton.IsEnabled = toolboxSelection switch
        {
            ToolboxSelectLongNotes or ToolboxSelectTaps => session != null && selected > 0,
            ToolboxFillGaps => canEdit && selected > 1,
            ToolboxTapPairToLong => canEdit && selected > 1,
            ToolboxRandomFixed or ToolboxRandomPerBeat or ToolboxSwapOuterInner =>
                canEdit && selected > 0,
            ToolboxHideBodies => true,
            _ => canEdit
        };
    }

    private async Task RunToolboxActionAsync()
    {
        switch (toolboxSelection)
        {
            case ToolboxSelectLongNotes:
                FilterSelectionByNoteType(longNotes: true);
                break;
            case ToolboxSelectTaps:
                FilterSelectionByNoteType(longNotes: false);
                break;
            case ToolboxLongToTap:
                await ConvertLongNotesToTapsAsync();
                break;
            case ToolboxTapToLong:
                ConvertTapsToLongNotes();
                break;
            case ToolboxTapPairToLong:
                ConvertTapPairsToLongNotes();
                break;
            case ToolboxCurveDensity:
                GenerateCurveDensity();
                break;
            case ToolboxFillGaps:
                FillNoteGaps();
                break;
            case ToolboxRandomFixed:
                RandomizeVisibleSelection(perBeat: false);
                break;
            case ToolboxRandomPerBeat:
                RandomizeVisibleSelection(perBeat: true);
                break;
            case ToolboxSwapOuterInner:
                SwapOuterInnerSelection();
                break;
            case ToolboxHideBodies:
                ToggleLongNoteBodyVisibility();
                break;
        }
        RefreshToolboxPanel();
    }

    private void ToggleExtensionPalette()
    {
        extensionPalette.IsVisible = !extensionPalette.IsVisible;
        if (extensionMenuButton != null)
        {
            extensionMenuButton.Tag = extensionPalette.IsVisible ? "Active" : null;
            extensionMenuButton.Background = extensionPalette.IsVisible
                ? new SolidColorBrush(Color.Parse("#22282A"))
                : Brushes.Transparent;
            extensionMenuButton.BorderBrush = extensionPalette.IsVisible
                ? new SolidColorBrush(Color.Parse("#5F7E82"))
                : Brushes.Transparent;
            extensionMenuButton.Foreground = extensionPalette.IsVisible
                ? new SolidColorBrush(Color.Parse("#F0F2F2"))
                : new SolidColorBrush(Color.Parse("#D0D4D6"));
            AutomationProperties.SetHelpText(
                extensionMenuButton,
                extensionPalette.IsVisible ? "工具箱已展开" : "工具箱已收起");
        }
        if (extensionPalette.IsVisible)
            Dispatcher.UIThread.Post(ClampExtensionPalettePosition, DispatcherPriority.Loaded);
        timeline.Focus();
    }

    private void FilterSelectionByNoteType(bool longNotes)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var count = WindowsNoteTypeTransformCommand.FilterSelectionByNoteType(
            tab.Session,
            longNotes,
            tab.HiddenGroups);
        timeline.SetSelectedTiming(null);
        SyncTimingListSelection([]);
        UpdateSelectionUi();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已保留 {0} 个{1}", count, (longNotes ? AvaloniaLocalizationCatalog.Text("面") : AvaloniaLocalizationCatalog.Text("米"))));
    }

    private void ToggleLongNoteBodyVisibility()
    {
        var enabled = !timeline.HideLongNoteBodies;
        timeline.SetHideLongNoteBodies(enabled);
        RefreshToolboxPanel();
        viewModel.SetStatus(enabled
            ? "已隐藏 LN 身体和尾部：头部 Note 以边框色区分"
            : "已恢复 LN 身体显示");
        timeline.Focus();
    }

    private void ExtensionPaletteHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = extensionPalette.TranslatePoint(new Point(0, 0), timeline);
        if (!current.HasValue) return;
        extensionPaletteDragging = true;
        extensionPaletteDragStart = eventArgs.GetPosition(timeline);
        extensionPaletteDragStartX = extensionPaletteTransform.X;
        extensionPaletteDragStartY = extensionPaletteTransform.Y;
        extensionPaletteBaseLeft = current.Value.X - extensionPaletteTransform.X;
        extensionPaletteBaseTop = current.Value.Y - extensionPaletteTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void ExtensionPaletteHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!extensionPaletteDragging || sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(timeline);
        extensionPaletteTransform.X = extensionPaletteDragStartX + point.X - extensionPaletteDragStart.X;
        extensionPaletteTransform.Y = extensionPaletteDragStartY + point.Y - extensionPaletteDragStart.Y;
        ClampExtensionPalettePosition();
        eventArgs.Handled = true;
    }

    private void ExtensionPaletteHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!extensionPaletteDragging) return;
        extensionPaletteDragging = false;
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void ClampExtensionPalettePosition()
    {
        if (timeline.Bounds.Width <= 0 || timeline.Bounds.Height <= 0 ||
            extensionPalette.Bounds.Width <= 0 || extensionPalette.Bounds.Height <= 0)
            return;
        var current = extensionPalette.TranslatePoint(new Point(0, 0), timeline);
        if (!current.HasValue) return;
        var baseLeft = current.Value.X - extensionPaletteTransform.X;
        var baseTop = current.Value.Y - extensionPaletteTransform.Y;
        extensionPaletteTransform.X = Math.Clamp(
            extensionPaletteTransform.X,
            4 - baseLeft,
            Math.Max(
                4 - baseLeft,
                timeline.Bounds.Width - extensionPalette.Bounds.Width - baseLeft - 4));
        extensionPaletteTransform.Y = Math.Clamp(
            extensionPaletteTransform.Y,
            4 - baseTop,
            Math.Max(
                4 - baseTop,
                timeline.Bounds.Height - extensionPalette.Bounds.Height - baseTop - 4));
    }

    private void MarkEditorViewSettingsDirty()
    {
        editorViewSettingsDirty = true;
        ScheduleEditorViewSettingsSave();
    }

    private void AddQuickTimelineToolButton(
        StackPanel panel,
        TimelineTool tool,
        string text,
        string geometry,
        bool filledIcon = false)
    {
        var button = QuickPaletteButton(
            text,
            geometry,
            (_, _) => SetTimelineTool(tool),
            out _,
            filledIcon);
        AutomationProperties.SetAutomationId(button, $"Editor.QuickTool.{tool}");
        quickTimelineToolButtons.Add(tool, button);
        RegisterQuickShortcutButton(
            tool switch
            {
                TimelineTool.Select => "ToolSelect",
                TimelineTool.Tap => "ToolTap",
                TimelineTool.Hold => "ToolHold",
                TimelineTool.Erase => "ToolErase",
                _ => throw new ArgumentOutOfRangeException(nameof(tool), tool, null)
            },
            AvaloniaLocalizationCatalog.Format("{0}工具", text),
            button);
        panel.Children.Add(button);
    }

