    private void ConfigureAudioPanel(
        Border panel,
        Border header,
        TextBlock title,
        Button modeButton,
        Button collapseButton,
        AudioVisualizationSideSurface surface,
        TranslateTransform transform,
        WindowsAudioPanelKind kind)
    {
        panel.HorizontalAlignment = HorizontalAlignment.Left;
        panel.VerticalAlignment = VerticalAlignment.Stretch;
        panel.Margin = new Thickness(0, 48, 0, 32);
        panel.Background = new SolidColorBrush(Color.Parse(
            kind == WindowsAudioPanelKind.Waveform ? "#F2171A1C" : "#F216191C"));
        panel.BorderBrush = new SolidColorBrush(Color.Parse(
            kind == WindowsAudioPanelKind.Waveform ? "#FF3B4246" : "#FF3B464A"));
        panel.BorderThickness = new Thickness(1);
        panel.CornerRadius = new CornerRadius(4);
        panel.RenderTransform = transform;
        AutomationProperties.SetName(panel,
            kind == WindowsAudioPanelKind.Waveform ? "音频波形面板" : "音频频谱面板");
        AutomationProperties.SetAutomationId(panel,
            kind == WindowsAudioPanelKind.Waveform ? "Audio.WaveformPanel" : "Audio.SpectrogramPanel");

        var content = new Grid { RowDefinitions = new RowDefinitions("25,*") };
        header.Background = new SolidColorBrush(Color.Parse("#ED1A1E20"));
        header.BorderBrush = new SolidColorBrush(Color.Parse("#FF31383B"));
        header.BorderThickness = new Thickness(0, 0, 0, 1);
        header.CornerRadius = new CornerRadius(3, 3, 0, 0);
        header.Cursor = new Cursor(StandardCursorType.SizeWestEast);
        ToolTip.SetTip(header, kind == WindowsAudioPanelKind.Waveform
            ? "横向拖动波形栏（收起后仍可拖动）"
            : "横向拖动频谱栏（收起后仍可拖动）；右键调整频谱强度与细节");
        // The toolbar is too narrow for another button, and right-click is where
        // desktop users look for a view's options. Adjusting from here shows the
        // result on the chart while the slider moves.
        if (kind == WindowsAudioPanelKind.Spectrogram)
            header.ContextFlyout = BuildSpectrogramAppearanceFlyout();
        AutomationProperties.SetAutomationId(header,
            kind == WindowsAudioPanelKind.Waveform ? "Audio.WaveformHeader" : "Audio.SpectrogramHeader");
        header.PointerPressed += AudioPanelHeader_PointerPressed;
        header.PointerMoved += AudioPanelHeader_PointerMoved;
        header.PointerReleased += AudioPanelHeader_PointerReleased;
        header.PointerCaptureLost += (_, _) => EndAudioPanelDrag();

        var headerContent = new Grid
        {
            Margin = new Thickness(7, 0, 3, 0),
            ColumnDefinitions = new ColumnDefinitions("*,Auto,Auto")
        };
        title.Foreground = new SolidColorBrush(Color.Parse(
            kind == WindowsAudioPanelKind.Waveform ? "#FF879397" : "#FF87979A"));
        title.FontSize = 8;
        title.FontWeight = FontWeight.SemiBold;
        title.VerticalAlignment = VerticalAlignment.Center;
        headerContent.Children.Add(title);

        ConfigureAudioPanelButton(modeButton);
        ConfigureAudioPanelButton(collapseButton);
        ToolTip.SetTip(modeButton, "切换侧栏 / 谱面背景");
        ToolTip.SetTip(collapseButton, kind == WindowsAudioPanelKind.Waveform
            ? "收起 / 展开音频波形"
            : "收起 / 展开音频频谱");
        AutomationProperties.SetAutomationId(modeButton,
            kind == WindowsAudioPanelKind.Waveform ? "Audio.WaveformMode" : "Audio.SpectrogramMode");
        AutomationProperties.SetAutomationId(collapseButton,
            kind == WindowsAudioPanelKind.Waveform ? "Audio.WaveformCollapse" : "Audio.SpectrogramCollapse");
        modeButton.Click += (_, _) => ToggleAudioPanelMode(kind);
        collapseButton.Click += (_, _) => ToggleAudioPanelCollapsed(kind);
        Grid.SetColumn(modeButton, 1);
        Grid.SetColumn(collapseButton, 2);
        headerContent.Children.Add(modeButton);
        headerContent.Children.Add(collapseButton);
        header.Child = headerContent;
        content.Children.Add(header);

        surface.Margin = new Thickness(3);
        surface.IsHitTestVisible = false;
        // The panel is aligned row-for-row with the chart, so the wheel over it
        // scrolls and zooms the chart exactly as it does over the timeline.
        panel.PointerWheelChanged += (_, eventArgs) =>
        {
            timeline.HandleCompanionWheel(eventArgs);
            eventArgs.Handled = true;
        };
        AutomationProperties.SetAutomationId(surface,
            kind == WindowsAudioPanelKind.Waveform ? "Audio.WaveformSurface" : "Audio.SpectrogramSurface");
        Grid.SetRow(surface, 1);
        content.Children.Add(surface);
        panel.Child = content;
        if (kind == WindowsAudioPanelKind.Spectrogram)
        {
            ToolTip.SetTip(panel,
                "频谱横轴：左侧低频 Bass / 底鼓，中间鼓与主体，右侧高频镲片 / 人声辅音起音");
        }
    }

    private static void ConfigureAudioPanelButton(Button button)
    {
        button.Width = 21;
        button.Height = 19;
        button.Padding = new Thickness(0);
        button.Margin = new Thickness(1, 0, 0, 0);
        button.FontSize = 10;
        button.Foreground = Brushes.White;
        button.Background = Brushes.Transparent;
        button.BorderBrush = new SolidColorBrush(Color.Parse("#553B464A"));
        button.BorderThickness = new Thickness(1);
        button.VerticalAlignment = VerticalAlignment.Center;
    }

    private WindowsAudioPanelState GetAudioPanelState(WindowsAudioPanelKind kind) =>
        kind == WindowsAudioPanelKind.Waveform
            ? audioPanelSettings.Waveform
            : audioPanelSettings.Spectrogram;

    private TranslateTransform GetAudioPanelTransform(WindowsAudioPanelKind kind) =>
        kind == WindowsAudioPanelKind.Waveform
            ? waveformPanelTransform
            : spectrogramPanelTransform;

    private void SetAudioPanelState(WindowsAudioPanelKind kind, WindowsAudioPanelState state)
    {
        audioPanelSettings = kind == WindowsAudioPanelKind.Waveform
            ? audioPanelSettings.WithWaveform(state)
            : audioPanelSettings.WithSpectrogram(state);
        audioPanelSettingsDirty = true;
        ApplyAudioPanelLayout();
        UpdateAudioVisualizationUi();
        ScheduleAudioPanelSettingsSave();
    }

    private void ToggleAudioPanelMode(WindowsAudioPanelKind kind)
    {
        var state = GetAudioPanelState(kind);
        var transform = GetAudioPanelTransform(kind);
        var nextMode = state.Mode == WindowsAudioPanelDisplayMode.Background
            ? WindowsAudioPanelDisplayMode.Side
            : WindowsAudioPanelDisplayMode.Background;
        SetAudioPanelState(
            kind,
            state.WithPosition(transform.X, transform.Y)
                .WithDocked(false)
                .WithMode(nextMode)
                .WithCollapsed(false));
    }

    private void ToggleAudioPanelCollapsed(WindowsAudioPanelKind kind)
    {
        var state = GetAudioPanelState(kind);
        if (!state.Collapsed)
        {
            var transform = GetAudioPanelTransform(kind);
            state = state.WithPosition(transform.X, transform.Y).WithDocked(false);
        }
        SetAudioPanelState(kind, state.WithCollapsed(!state.Collapsed));
    }

    private void SetAudioPanelBackgroundMode(WindowsAudioPanelKind kind, bool background)
    {
        var state = GetAudioPanelState(kind);
        var mode = background
            ? WindowsAudioPanelDisplayMode.Background
            : WindowsAudioPanelDisplayMode.Side;
        if (state.Mode == mode && !state.Collapsed) return;
        var transform = GetAudioPanelTransform(kind);
        SetAudioPanelState(
            kind,
            state.WithPosition(transform.X, transform.Y)
                .WithDocked(false)
                .WithMode(mode)
                .WithCollapsed(false));
    }

    private void AudioPanelHeader_PointerPressed(object? sender, PointerPressedEventArgs eventArgs)
    {
        if (sender is not Border header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed) return;
        var kind = ReferenceEquals(header, waveformHeader)
            ? WindowsAudioPanelKind.Waveform
            : WindowsAudioPanelKind.Spectrogram;
        var modeButton = kind == WindowsAudioPanelKind.Waveform
            ? waveformModeButton
            : spectrogramModeButton;
        var collapseButton = kind == WindowsAudioPanelKind.Waveform
            ? waveformCollapseButton
            : spectrogramCollapseButton;
        if (modeButton.IsPointerOver || collapseButton.IsPointerOver) return;
        draggingAudioPanelKind = kind;
        audioPanelDragStart = eventArgs.GetPosition(timelineHost);
        var transform = GetAudioPanelTransform(kind);
        audioPanelDragStartX = transform.X;
        audioPanelDragStartY = transform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void AudioPanelHeader_PointerMoved(object? sender, PointerEventArgs eventArgs)
    {
        if (sender is not Border header || draggingAudioPanelKind is not { } kind ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed) return;
        var point = eventArgs.GetPosition(timelineHost);
        var preview = WindowsAudioPanelLayoutPolicy.ApplyDrag(
            GetAudioPanelState(kind),
            kind,
            audioPanelDragStartX + point.X - audioPanelDragStart.X,
            audioPanelDragStartY + point.Y - audioPanelDragStart.Y,
            timelineHost.Bounds.Width,
            timelineHost.Bounds.Height);
        var transform = GetAudioPanelTransform(kind);
        transform.X = preview.X;
        transform.Y = preview.Y;
        eventArgs.Handled = true;
    }

    private void AudioPanelHeader_PointerReleased(object? sender, PointerReleasedEventArgs eventArgs)
    {
        if (sender is not Border || draggingAudioPanelKind == null) return;
        EndAudioPanelDrag();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndAudioPanelDrag()
    {
        if (draggingAudioPanelKind is not { } kind) return;
        draggingAudioPanelKind = null;
        var transform = GetAudioPanelTransform(kind);
        var state = WindowsAudioPanelLayoutPolicy.ApplyDrag(
            GetAudioPanelState(kind),
            kind,
            transform.X,
            transform.Y,
            timelineHost.Bounds.Width,
            timelineHost.Bounds.Height);
        SetAudioPanelState(kind, state);
    }

    private void QueueAudioPanelLayout(bool clampFreePanels = false)
    {
        if (clampFreePanels && timelineHost.Bounds.Width > 0 && timelineHost.Bounds.Height > 0)
        {
            audioPanelSettings = audioPanelSettings.WithPanels(
                WindowsAudioPanelLayoutPolicy.ClampAfterResize(
                    audioPanelSettings.Waveform,
                    WindowsAudioPanelKind.Waveform,
                    timelineHost.Bounds.Width,
                    timelineHost.Bounds.Height),
                WindowsAudioPanelLayoutPolicy.ClampAfterResize(
                    audioPanelSettings.Spectrogram,
                    WindowsAudioPanelKind.Spectrogram,
                    timelineHost.Bounds.Width,
                    timelineHost.Bounds.Height));
        }
        if (audioPanelLayoutQueued) return;
        audioPanelLayoutQueued = true;
        Dispatcher.UIThread.Post(() =>
        {
            audioPanelLayoutQueued = false;
            ApplyAudioPanelLayout();
        }, DispatcherPriority.Loaded);
    }

    private void ApplyAudioPanelLayout()
    {
        if (timelineHost.Bounds.Width <= 0 || timelineHost.Bounds.Height <= 0) return;
        var track = timeline.GetActiveTrackBounds();
        var left = timeline.TranslatePoint(new Point(track.Left, 0), timelineHost);
        var right = timeline.TranslatePoint(new Point(track.Right, 0), timelineHost);
        var trackBounds = track.Width > 0 && left is { } leftPoint && right is { } rightPoint
            ? new WindowsAudioTrackBounds(leftPoint.X, rightPoint.X)
            : default;
        var layout = WindowsAudioPanelLayoutPolicy.Resolve(
            audioPanelSettings,
            timelineHost.Bounds.Width,
            timelineHost.Bounds.Height,
            trackBounds);
        ApplyAudioPanelVisual(
            waveformPanel,
            waveformTitleText,
            waveformModeButton,
            waveformCollapseButton,
            waveformSideSurface,
            waveformPanelTransform,
            WindowsAudioPanelKind.Waveform,
            audioPanelSettings.Waveform,
            layout.Waveform);
        ApplyAudioPanelVisual(
            spectrogramPanel,
            spectrogramTitleText,
            spectrogramModeButton,
            spectrogramCollapseButton,
            spectrogramSideSurface,
            spectrogramPanelTransform,
            WindowsAudioPanelKind.Spectrogram,
            audioPanelSettings.Spectrogram,
            layout.Spectrogram);
        UpdateAudioPanelViewports();
        QueueDifficultyCardLayout();
    }

    private static void ApplyAudioPanelVisual(
        Border panel,
        TextBlock title,
        Button modeButton,
        Button collapseButton,
        AudioVisualizationSideSurface surface,
        TranslateTransform transform,
        WindowsAudioPanelKind kind,
        WindowsAudioPanelState state,
        WindowsAudioPanelLayout layout)
    {
        panel.Width = layout.Width;
        panel.Height = layout.ToolbarOnly ? WindowsAudioPanelLayoutPolicy.ToolbarHeight : double.NaN;
        panel.VerticalAlignment = layout.ToolbarOnly
            ? VerticalAlignment.Top
            : VerticalAlignment.Stretch;
        transform.X = layout.X;
        transform.Y = layout.Y;
        modeButton.Content = state.Mode == WindowsAudioPanelDisplayMode.Background ? "侧" : "背";
        collapseButton.Content = state.Collapsed ? "+" : "—";
        title.Text = kind == WindowsAudioPanelKind.Waveform
            ? "WAVE"
            : layout.ToolbarOnly ? "SPEC" : "SPEC  L · M · H";
        surface.IsVisible = !layout.ToolbarOnly;
        ToolTip.SetTip(modeButton, state.Mode == WindowsAudioPanelDisplayMode.Background
            ? kind == WindowsAudioPanelKind.Waveform ? "改为右侧波形栏" : "改为侧边频谱栏"
            : "铺满谱面背景");
    }

    private void UpdateAudioPanelViewports()
    {
        UpdateAudioPanelViewport(waveformSideSurface);
        UpdateAudioPanelViewport(spectrogramSideSurface);
    }

    private void UpdateAudioPanelPlaybackBeat(double beat)
    {
        if (waveformSideSurface.IsVisible)
            waveformSideSurface.SetPlaybackBeat(beat);
        if (spectrogramSideSurface.IsVisible)
            spectrogramSideSurface.SetPlaybackBeat(beat);
    }

    private void UpdateAudioPanelViewport(AudioVisualizationSideSurface surface)
    {
        var linePosition = timeline.JudgementLinePosition;
        if (surface.IsVisible && surface.Bounds.Height > 1 && timeline.Bounds.Height > 1)
        {
            var point = timeline.TranslatePoint(
                new Point(0, timeline.Bounds.Height * timeline.JudgementLinePosition),
                surface);
            // The panel is inset from the timeline, so the timeline's line can
            // sit outside the panel's own 15–95% band. Clamping it there moved
            // the panel's rows off the Notes; keep the true position.
            if (point is { } translated)
                linePosition = Math.Clamp(translated.Y / surface.Bounds.Height, -1, 2);
        }
        surface.SetViewport(timeline.CurrentBeat, timeline.PixelsPerBeat, linePosition);
    }

    private Control BuildSettingsPanel()
    {
        var tabletLayout = !SupportsDesktopWindowSizing;
        var content = new StackPanel
        {
            Spacing = 0,
            MinWidth = 0,
            MaxWidth = tabletLayout
                ? 300
                : WindowsInspectorParityPolicy.InspectorContentMaximumWidth,
            HorizontalAlignment = HorizontalAlignment.Stretch
        };
        var sections = new[]
        {
            BuildLanguageSettings(),
            BuildEditorViewSettings(),
            BuildDisplayScaleSettings(),
            BuildBackupCacheSettings(),
            BuildShortcutSettings(),
            BuildAudioTransport(),
            BuildApplicationInformationSettings()
        };
        for (var index = 0; index < sections.Length; index++)
        {
            if (index > 0) content.Children.Add(BuildWpfSettingsSeparator());
            content.Children.Add(sections[index]);
        }
        content.Children.Add(new Border
        {
            Height = WindowsInspectorParityPolicy.SettingsBottomScrollClearance,
            Focusable = false,
            IsHitTestVisible = false
        });
        var root = new ScrollViewer
        {
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            HorizontalContentAlignment = HorizontalAlignment.Stretch,
            ClipToBounds = true,
            Padding = tabletLayout
                ? new Thickness(16, 14, 16, 24)
                : WindowsInspectorParityPolicy.SettingsContentPadding,
            Content = content
        };
        var focusControls = root
            .GetLogicalDescendants()
            .OfType<Control>()
            .Where(control => WindowsInspectorParityPolicy.ResolveSettingsTabIndex(
                AutomationProperties.GetAutomationId(control)) >= 0)
            .ToArray();
        ApplyWpf110InspectorTabOrder(
            "Settings",
            focusControls,
            WindowsInspectorParityPolicy.ResolveSettingsTabIndex);
        DisableAvaloniaOnlySettingsTabStops();
        return root;
    }

    private static Border BuildWpfSettingsSeparator() => new()
    {
        Height = 1,
        Background = new SolidColorBrush(Color.Parse("#34393D")),
        Margin = WindowsInspectorParityPolicy.SettingsSeparatorMargin
    };

    private void DisableAvaloniaOnlySettingsTabStops()
    {
        foreach (var control in new Control[]
                 {
                     waveformBackgroundBox,
                     spectrogramBackgroundBox,
                     audioPlayPauseButton,
                     audioStopButton,
                     audioRefreshDeviceButton,
                     audioPositionSlider,
                     audioRateSlider
                 })
            control.IsTabStop = false;
    }

    private Control BuildLanguageSettings()
    {
        var previous = suppressLanguageControls;
        suppressLanguageControls = true;
        try
        {
            languagePreferenceBox.Items.Clear();
            foreach (var preference in new[]
                     {
                         AvaloniaLanguagePreference.FollowSystem,
                         AvaloniaLanguagePreference.SimplifiedChinese,
                         AvaloniaLanguagePreference.TraditionalChinese,
                         AvaloniaLanguagePreference.English,
                         AvaloniaLanguagePreference.Japanese,
                         AvaloniaLanguagePreference.Korean,
                         AvaloniaLanguagePreference.Spanish,
                         AvaloniaLanguagePreference.French,
                         AvaloniaLanguagePreference.German,
                         AvaloniaLanguagePreference.PortugueseBrazil,
                         AvaloniaLanguagePreference.Russian,
                         AvaloniaLanguagePreference.Italian,
                         AvaloniaLanguagePreference.Dutch,
                         AvaloniaLanguagePreference.Polish,
                         AvaloniaLanguagePreference.Turkish,
                         AvaloniaLanguagePreference.Vietnamese,
                         AvaloniaLanguagePreference.Arabic,
                         AvaloniaLanguagePreference.Hindi,
                         AvaloniaLanguagePreference.Thai,
                         AvaloniaLanguagePreference.Indonesian
                     })
            {
                languagePreferenceBox.Items.Add(new ComboBoxItem
                {
                    Content = LanguagePreferenceDisplayName(preference),
                    Tag = preference
                });
            }
            languagePreferenceBox.HorizontalAlignment = HorizontalAlignment.Stretch;
            languagePreferenceBox.MinWidth = 0;
            languagePreferenceBox.MaxWidth =
                WindowsInspectorParityPolicy.InspectorContentMaximumWidth;
            AutomationProperties.SetAutomationId(languagePreferenceBox, "Settings.Language");
            AutomationProperties.SetName(languagePreferenceBox, "显示语言");
            ToolTip.SetTip(languagePreferenceBox, "选择界面显示语言");
            RefreshLanguageSettingsUi();
        }
        finally
        {
            suppressLanguageControls = previous;
        }

        languagePreferenceBox.SelectionChanged += LanguagePreferenceBox_SelectionChanged;
        languageStatusText.Foreground = MutedBrush;
        languageStatusText.TextWrapping = TextWrapping.Wrap;
        languageStatusText.Margin = new Thickness(2, 4, 0, 1);
        AutomationProperties.SetAutomationId(languageStatusText, "Settings.LanguageStatus");

        return SettingsSection(
            "语言与地区",
            string.Empty,
            "Settings.LanguageSection",
            TimingField("显示语言", languagePreferenceBox),
            languageStatusText,
            new TextBlock
            {
                Text = "切换后立即生效；未翻译的内容会优先显示英文，并始终保留原文。",
                Foreground = MutedBrush,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(2, 2, 0, 2)
            });
    }

    private static string LanguagePreferenceDisplayName(
        AvaloniaLanguagePreference preference) => preference switch
    {
        AvaloniaLanguagePreference.FollowSystem => "跟随系统",
