    private void LanguagePreferenceBox_SelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressLanguageControls ||
            languagePreferenceBox.SelectedItem is not ComboBoxItem
            {
                Tag: AvaloniaLanguagePreference preference
            })
            return;

        languageSettings = languageSettings.WithPreference(preference);
        try
        {
            var saved = AvaloniaLanguageSettingsStore.Save(languageSettings);
            localizationController.SetPreference(languageSettings.Preference);
            AvaloniaLocalizationRuntime.SetPreference(languageSettings.Preference);
            RefreshLanguageSettingsUi();
            if (saved)
            {
                viewModel.SetStatus(AvaloniaLocalizationCatalog.LanguageUpdatedText(
                    localizationController.EffectiveLanguage));
            }
            else
            {
                // The store refuses to write while an existing settings file
                // could not be read this session, so the user's saved choice is
                // not overwritten. The switch still applies until restart.
                languageStatusText.Text = AvaloniaLocalizationCatalog.LanguageSaveFailedText(
                    localizationController.EffectiveLanguage,
                    AvaloniaLanguageSettingsStore.SettingsPath);
                languageStatusText.Foreground = Brushes.IndianRed;
            }
        }
        catch (Exception exception)
        {
            localizationController.SetPreference(languageSettings.Preference);
            AvaloniaLocalizationRuntime.SetPreference(languageSettings.Preference);
            languageStatusText.Text = AvaloniaLocalizationCatalog.LanguageSaveFailedText(
                localizationController.EffectiveLanguage,
                exception.Message);
            languageStatusText.Foreground = Brushes.IndianRed;
        }
    }

    private void RefreshLanguageSettingsUi()
    {
        var previous = suppressLanguageControls;
        suppressLanguageControls = true;
        try
        {
            languagePreferenceBox.SelectedItem = languagePreferenceBox.Items
                .OfType<ComboBoxItem>()
                .FirstOrDefault(item => item.Tag is AvaloniaLanguagePreference preference &&
                                        preference == languageSettings.Preference);
            var effective = AvaloniaLanguageSettings.ResolveEffectiveLanguage(
                languageSettings.Preference);
            languageStatusText.Text = AvaloniaLocalizationCatalog.CurrentLanguageStatus(
                languageSettings.Preference,
                effective);
            languageStatusText.Foreground = MutedBrush;
        }
        finally
        {
            suppressLanguageControls = previous;
        }
    }

    private void RefreshFollowSystemLanguage()
    {
        if (languageSettings.Preference != AvaloniaLanguagePreference.FollowSystem ||
            !localizationController.RefreshForSystemLanguage())
            return;

        localizationController.Apply();
        RefreshLanguageSettingsUi();
    }

    private Control BuildApplicationInformationSettings()
    {
        settingsVersionText.Text = WindowsAppUpdatePolicy.SettingsVersionText(
            WindowsOnlineAccountHost.ClientVersion,
            appUpdateSnapshot);
        settingsVersionText.Foreground = new SolidColorBrush(Color.Parse("#7E8D91"));
        settingsVersionText.FontSize = 10;
        settingsVersionText.Margin = new Thickness(0, 3, 0, 9);
        AutomationProperties.SetAutomationId(settingsVersionText, "Settings.Version");

        var about = PrimaryButton("关于原作者", async (_, _) => await ShowAboutAsync(showFork: false));
        about.Height = 37;
        about.HorizontalAlignment = HorizontalAlignment.Stretch;
        about.Margin = new Thickness(0, 2, 0, 0);
        ApplyWpfToolButtonStyle(about);
        AutomationProperties.SetAutomationId(about, "Settings.About");
        // The three upstream links used to sit here as well as inside the About
        // card. They now live only in the card, next to the text they belong to.
        var aboutModifier = PrimaryButton("关于修改者", async (_, _) => await ShowAboutAsync(showFork: true));
        aboutModifier.Height = 37;
        aboutModifier.HorizontalAlignment = HorizontalAlignment.Stretch;
        aboutModifier.Margin = new Thickness(0, 6, 0, 0);
        ApplyWpfToolButtonStyle(aboutModifier);
        AutomationProperties.SetAutomationId(aboutModifier, "Settings.AboutModifier");
        var check = PrimaryButton(
            "检查更新",
            async (_, _) => await RefreshUpdatePolicyAndShowAsync(
                blocksLogin: false,
                showWhenCurrent: true));
        check.Height = 37;
        check.HorizontalAlignment = HorizontalAlignment.Stretch;
        check.Margin = new Thickness(0, 6, 0, 2);
        ApplyWpfPrimaryButtonStyle(check);
        AutomationProperties.SetAutomationId(check, "Settings.CheckForUpdates");

        return SettingsSection(
            "LumaChart Studio",
            string.Empty,
            "Settings.ApplicationInformationSection",
            settingsVersionText,
            about,
            aboutModifier,
            check);
    }

