    private void ConfigureNoteAnchorButton(
        Button button,
        string content,
        string toolTip,
        WindowsNoteAnchorMode anchor,
        string automationId)
    {
        button.Content = content;
        button.Tag = anchor;
        button.HorizontalAlignment = HorizontalAlignment.Stretch;
        button.MinHeight = 34;
        ToolTip.SetTip(button, toolTip);
        AutomationProperties.SetAutomationId(button, automationId);
        AutomationProperties.SetName(button, content);
        ApplyWpfToolButtonStyle(button);
        button.Click += NoteAnchorButton_Click;
    }

    private void NoteAnchorButton_Click(object? sender, RoutedEventArgs eventArgs)
    {
        _ = eventArgs;
        if (sender is not Button { Tag: WindowsNoteAnchorMode anchor }) return;
        editorViewSettings = editorViewSettings.WithNoteAnchor(anchor);
        ApplyEditorViewSettings();
        RefreshEditorViewSettingsUi();
        MarkEditorViewSettingsDirty();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("Note 对齐：{0}", NoteAnchorDisplayName(anchor)));
    }

    private void RefreshNoteAnchorButtons()
    {
        foreach (var button in new[]
                 {
                     anchorLineButton,
                     anchorLineAboveButton,
                     anchorCellButton,
                     anchorCellBottomButton
                 })
        {
            ApplyWpfToolButtonStyle(button);
            var active = button.Tag is WindowsNoteAnchorMode anchor &&
                         anchor == editorViewSettings.NoteAnchor;
            if (active)
            {
                button.Background = new SolidColorBrush(Color.Parse("#38676C"));
                button.BorderBrush = new SolidColorBrush(Color.Parse("#4A777B"));
                button.Foreground = Brushes.White;
                button.FontWeight = FontWeight.SemiBold;
            }
            else
            {
                button.FontWeight = FontWeight.Normal;
            }
            AutomationProperties.SetHelpText(
                button,
                $"NoteAnchor={button.Tag}; Active={active}");
        }
    }

    private static string NoteAnchorDisplayName(WindowsNoteAnchorMode anchor) =>
        TimelinePlacementGeometry.DisplayName(anchor);

    private void SettingsSnapBox_SelectionChanged(object? sender, SelectionChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressEditorViewControls ||
            settingsSnapBox.SelectedItem is not ComboBoxItem { Tag: int division })
            return;
        SetQuickSnapDivision(division);
    }

    private void CommitSettingsSnapBoxText(
        bool restoreInvalidText = true,
        bool addCustomDivisionItem = true)
    {
        settingsSnapCommitTimer.Stop();
        if (suppressEditorViewControls ||
            !WindowsInspectorParityPolicy.AllowWindowUiMutation(
                windowCloseTeardownStarted,
                windowClosePreflightComplete))
            return;
        if (TryParseSnapDivisionText(settingsSnapBox.Text, out var division))
        {
            SetQuickSnapDivision(division, addCustomDivisionItem);
            return;
        }

        if (!restoreInvalidText) return;
        SyncSettingsSnapBox(
            viewModel.ActiveTab?.Session.SnapDivision ?? editorViewSettings.SnapDivision);
        viewModel.SetStatus("分度范围：1–1920");
    }

    private static bool TryParseSnapDivisionText(string? text, out int division)
    {
        division = 0;
        if (string.IsNullOrWhiteSpace(text)) return false;
        var trimmed = text.Trim();
        // "Un-snap" is a name rather than a fraction, so the editable box has to
        // accept it however it gets typed back: the UI writes "Un-snap", but
        // "unsnap" and "Un Snap" are the same request.
        if (IsUnsnapText(trimmed))
        {
            division = TimelineSubdivisionCheckPalette.UnsnapDivision;
            return true;
        }
        var slash = trimmed.LastIndexOf('/');
        if (slash >= 0) trimmed = trimmed[(slash + 1)..].Trim();
        return int.TryParse(
                   trimmed,
                   NumberStyles.Integer,
                   CultureInfo.InvariantCulture,
                   out division) &&
               division is >= 1 and <= 1920;
    }

    private static bool IsUnsnapText(string text)
    {
        Span<char> buffer = stackalloc char[text.Length];
        var length = 0;
        foreach (var character in text)
        {
            if (character is ' ' or '-' or '_') continue;
            buffer[length++] = character;
        }
        return length == "unsnap".Length &&
               MemoryExtensions.Equals(
                   buffer[..length],
                   "unsnap",
                   StringComparison.OrdinalIgnoreCase);
    }

    private void SyncSettingsSnapBox(int division, bool addCustomDivisionItem = true)
    {
        division = Math.Clamp(division, 1, 1920);
        var wasSuppressed = suppressEditorViewControls;
        suppressEditorViewControls = true;
        try
        {
            var item = settingsSnapBox.Items
                .OfType<ComboBoxItem>()
                .FirstOrDefault(candidate => candidate.Tag is int value && value == division);
            // A value the typing debounce applies mid-entry is not an entry
            // the user chose; leave it unselected (the editable box already
            // deselects on unmatched text) instead of growing the list.
            if (item == null && addCustomDivisionItem)
            {
                item = new ComboBoxItem
                {
                    Content = TimelineSubdivisionCheckPalette.FormatDivisionLabel(division),
                    Tag = division
                };
                settingsSnapBox.Items.Add(item);
            }
            settingsSnapBox.SelectedItem = item;
            settingsSnapBox.Text = TimelineSubdivisionCheckPalette.FormatDivisionLabel(division);
            AutomationProperties.SetHelpText(
                settingsSnapBox,
                $"SnapDivision={division}; Range=1-1920; Editable=True");
        }
        finally
        {
            suppressEditorViewControls = wasSuppressed;
        }
    }

    private void SettingsFixedSnapBox_SelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressEditorViewControls ||
            settingsFixedSnapBox.SelectedItem is not ComboBoxItem { Tag: int division })
            return;
        SetFixedSnapDivision(division);
    }

    private void CommitSettingsFixedSnapBoxText(
        bool restoreInvalidText = true,
        bool addCustomDivisionItem = true)
    {
        settingsFixedSnapCommitTimer.Stop();
        if (suppressEditorViewControls ||
            !WindowsInspectorParityPolicy.AllowWindowUiMutation(
                windowCloseTeardownStarted,
                windowClosePreflightComplete))
            return;
        if (TryParseSnapDivisionText(settingsFixedSnapBox.Text, out var division))
        {
            SetFixedSnapDivision(division, addCustomDivisionItem);
            return;
        }

        if (!restoreInvalidText) return;
        SyncSettingsFixedSnapBox(editorViewSettings.FixedSnapDivision);
        viewModel.SetStatus("分度范围：1–1920");
    }

    private void SetFixedSnapDivision(int division, bool addCustomDivisionItem = true)
    {
        division = Math.Clamp(division, 1, 1920);
        editorViewSettings = editorViewSettings.WithFixedSnapDivision(division);
        MarkEditorViewSettingsDirty();
        SyncSettingsFixedSnapBox(division, addCustomDivisionItem);
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("固定分度设为 {0}（{1} 一键切换）", TimelineSubdivisionCheckPalette.FormatDivisionLabel(division), CompactShortcut("SnapSetFixed")));
    }

    private void SyncSettingsFixedSnapBox(int division, bool addCustomDivisionItem = true)
    {
        division = Math.Clamp(division, 1, 1920);
        var wasSuppressed = suppressEditorViewControls;
        suppressEditorViewControls = true;
        try
        {
            var item = settingsFixedSnapBox.Items
                .OfType<ComboBoxItem>()
                .FirstOrDefault(candidate => candidate.Tag is int value && value == division);
            // See SyncSettingsSnapBox: debounce-applied values stay unlisted.
            if (item == null && addCustomDivisionItem)
            {
                item = new ComboBoxItem
                {
                    Content = TimelineSubdivisionCheckPalette.FormatDivisionLabel(division),
                    Tag = division
                };
                settingsFixedSnapBox.Items.Add(item);
            }
            settingsFixedSnapBox.SelectedItem = item;
            settingsFixedSnapBox.Text = TimelineSubdivisionCheckPalette.FormatDivisionLabel(division);
            AutomationProperties.SetHelpText(
                settingsFixedSnapBox,
                $"FixedSnapDivision={division}; Range=1-1920; Editable=True");
        }
        finally
        {
            suppressEditorViewControls = wasSuppressed;
        }
    }

    /// <summary>
    /// The two curve-density endpoints share one list of snap-like divisions.
    /// Keeping it to the values that divide a beat evenly means every generated
    /// gap is still a legal subdivision rather than an arbitrary decimal.
    /// </summary>
    /// <summary>
    /// Item of a non-editable settings ComboBox. Deliberately a plain object
    /// whose ToString is the label, not a ready-made ComboBoxItem: a ComboBox
    /// that creates its own containers re-renders the selection box on every
    /// change, while one fed ready-made ComboBoxItem instances keeps the
    /// container that was selected when the panel was built. Once the popup has
    /// realized the other containers, that stale face never repaints and the
    /// box shows the value it started with even though SelectedItem moved on.
    /// </summary>
    private sealed record LabeledChoice(int Value, string Label)
    {
        public override string ToString() => Label;
    }

    private static LabeledChoice DivisionChoice(int division) =>
        new(division, TimelineSubdivisionCheckPalette.FormatDivisionLabel(division));

    private void ConfigureCurveDivisionBox(
        ComboBox box,
        int current,
        string automationId,
        string name,
        string help)
    {
        box.Items.Clear();
        foreach (var division in UnsnapScrollDivisionValues)
            box.Items.Add(DivisionChoice(division));
        box.IsTextSearchEnabled = false;
        box.HorizontalAlignment = HorizontalAlignment.Stretch;
        SyncCurveDivisionBox(box, current);
        box.SelectionChanged += CurveDivisionBox_SelectionChanged;
        AutomationProperties.SetAutomationId(box, automationId);
        AutomationProperties.SetName(box, name);
        AutomationProperties.SetHelpText(box, help);
    }

    private void SyncCurveDivisionBox(ComboBox box, int division)
    {
        division = Math.Clamp(division, 1, 1920);
        var wasSuppressed = suppressEditorViewControls;
        suppressEditorViewControls = true;
        try
        {
            var item = box.Items
                .OfType<LabeledChoice>()
                .FirstOrDefault(candidate => candidate.Value == division);
            // A hand-edited settings file may hold a value outside the list; keep
            // it selectable instead of silently rewriting it to the default.
            if (item == null)
            {
                item = DivisionChoice(division);
                box.Items.Add(item);
            }
            box.SelectedItem = item;
        }
        finally
        {
            suppressEditorViewControls = wasSuppressed;
        }
    }

    private void CurveDivisionBox_SelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        _ = eventArgs;
        if (suppressEditorViewControls) return;
        if (sender is not ComboBox { SelectedItem: LabeledChoice choice } box) return;
        var division = choice.Value;
        if (ReferenceEquals(box, toolboxCurveDenseBox))
        {
            if (editorViewSettings.CurveDenseDivision == division) return;
            editorViewSettings = editorViewSettings.WithCurveDenseDivision(division);
        }
        else if (ReferenceEquals(box, toolboxCurveSparseBox))
        {
            if (editorViewSettings.CurveSparseDivision == division) return;
            editorViewSettings = editorViewSettings.WithCurveSparseDivision(division);
        }
        else
        {
            return;
        }

        ApplyEditorViewSettings();
        MarkEditorViewSettingsDirty();
        RefreshToolboxCurvePreview();
        viewModel.SetStatus(
            editorViewSettings.CurveDenseDivision < editorViewSettings.CurveSparseDivision
                ? "曲线密度：最密比最疏还稀，生成时会自动对调"
                : AvaloniaLocalizationCatalog.Format(
                    "曲线密度：最密 1/{0} · 最疏 1/{1}",
                    editorViewSettings.CurveDenseDivision,
                    editorViewSettings.CurveSparseDivision));
    }

    private void SetUnsnapScrollDivision(int division)
    {
        division = Math.Clamp(division, 1, 1920);
        if (editorViewSettings.UnsnapScrollDivision != division)
        {
            editorViewSettings = editorViewSettings.WithUnsnapScrollDivision(division);
            ApplyEditorViewSettings();
            MarkEditorViewSettingsDirty();
        }
        SyncSettingsUnsnapScrollBox(division);
        viewModel.SetStatus(
            AvaloniaLocalizationCatalog.Format(
                "Un-snap 滚动分度设为 {0}（按住 {1} 滚轮按 1/1 滚动）",
                TimelineSubdivisionCheckPalette.FormatDivisionLabel(division),
                ShortcutGesture("WheelQuickScroll") ?? "—"));
    }

    private void SyncSettingsUnsnapScrollBox(int division)
    {
        division = Math.Clamp(division, 1, 1920);
        var wasSuppressed = suppressEditorViewControls;
        suppressEditorViewControls = true;
        try
        {
            var item = settingsUnsnapScrollBox.Items
                .OfType<LabeledChoice>()
                .FirstOrDefault(candidate => candidate.Value == division);
            // A value carried over from a settings file edited by hand is kept
            // selectable instead of silently snapping back to the default.
            if (item == null)
            {
                item = DivisionChoice(division);
                settingsUnsnapScrollBox.Items.Add(item);
            }
            settingsUnsnapScrollBox.SelectedItem = item;
        }
        finally
        {
            suppressEditorViewControls = wasSuppressed;
        }
    }

    private void SettingsUnsnapScrollBox_SelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressEditorViewControls ||
            settingsUnsnapScrollBox.SelectedItem is not LabeledChoice { } unsnapChoice)
            return;
        SetUnsnapScrollDivision(unsnapChoice.Value);
    }

    private void QuickRangeCopyBox_Changed(object? sender, RoutedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressEditorViewControls) return;
        SetQuickRangeCopy(settingsQuickRangeCopyBox.IsChecked == true);
    }

    private void SetQuickRangeCopy(bool enabled)
    {
        if (editorViewSettings.QuickRangeCopy == enabled) return;
        editorViewSettings = editorViewSettings.WithQuickRangeCopy(enabled);
        // Turning the mode off must not leave a half-finished mark behind for
        // the next time it is turned on.
        CancelRangeCopySelection();
        MarkEditorViewSettingsDirty();
        RefreshShortcutLabels();
        viewModel.SetStatus(enabled
            ? "快捷区间复制已开启：复制快捷键改为两次标记判定线位置"
            : "快捷区间复制已关闭：复制快捷键恢复为复制选中内容");
    }

    private void SyncQuickRangeCopyBox()
    {
        var wasSuppressed = suppressEditorViewControls;
        suppressEditorViewControls = true;
        try
        {
            settingsQuickRangeCopyBox.IsChecked = editorViewSettings.QuickRangeCopy;
        }
        finally
        {
            suppressEditorViewControls = wasSuppressed;
        }
    }

    private Control BuildBackupCacheSettings()
    {
        autoBackupEnabledBox.Content = "启用自动备份";
        autoBackupEnabledBox.IsChecked = editorViewSettings.AutoBackupEnabled;
        autoBackupEnabledBox.Margin = new Thickness(2, 5, 0, 3);
        AutomationProperties.SetAutomationId(autoBackupEnabledBox, "Settings.AutoBackupEnabled");
        autoBackupEnabledBox.IsCheckedChanged += AutoBackupSettings_Changed;
        ConfigureSettingsSlider(
            autoBackupIntervalSlider,
            1,
            120,
            1,
            editorViewSettings.AutoBackupMinutes,
            "Settings.AutoBackupMinutes",
            "自动备份频率");
        autoBackupIntervalSlider.ValueChanged += AutoBackupIntervalSlider_ValueChanged;
        autoBackupIntervalText.Foreground = MutedBrush;
        autoBackupIntervalText.FontSize = 10;
        autoBackupIntervalText.TextWrapping = TextWrapping.Wrap;
        backupFolderText.Foreground = MutedBrush;
        backupFolderText.FontSize = 9;
        backupFolderText.TextWrapping = TextWrapping.Wrap;
        backupFolderText.Text = AvaloniaAppPaths.EditorBackupRoot;
        ToolTip.SetTip(backupFolderText, AvaloniaAppPaths.EditorBackupRoot);
        AutomationProperties.SetAutomationId(backupFolderText, "Settings.BackupFolder");

        var backupNowButton = new Button { Content = "立即备份" };
        ApplyPrimaryButtonStyle(backupNowButton);
        backupNowButton.Click += async (_, _) => await BackupCurrentTabAsync();
        AutomationProperties.SetAutomationId(backupNowButton, "Settings.BackupNow");
        var restoreButton = new Button { Content = "恢复备份" };
        restoreButton.Click += async (_, _) => await RestoreBackupAsync();
        AutomationProperties.SetAutomationId(restoreButton, "Settings.RestoreBackup");
        var openFolderButton = new Button { Content = "打开目录" };
        openFolderButton.Click += (_, _) => OpenBackupFolder();
        AutomationProperties.SetAutomationId(openFolderButton, "Settings.OpenBackupFolder");
        // "打开目录" hands the path to explorer.exe, so it is only offered where
        // that exists. It is hidden rather than dropped from the tree, and that
        // is not fussiness: Settings.OpenBackupFolder is a member of
        // WindowsInspectorParityPolicy's settings focus order, and that order is
        // verified to be contiguous over the controls actually present. Taking
        // the button out left a hole in the sequence and BuildSettingsPanel threw
        //
        //   InvalidOperationException: WPF 1.1.0 Settings focus order is not
        //   contiguous.
        //
        // during construction, which on iOS is a crash on launch. Hidden, it
        // stays in the logical tree for the check and out of tab navigation; its
        // columns collapse so no gap is left behind.
        var canOpenInShell = OperatingSystem.IsWindows();
        openFolderButton.IsVisible = canOpenInShell;
        var backupActions = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions(canOpenInShell ? "*,6,*,6,*" : "*,6,*,0,0")
        };
        backupActions.Children.Add(backupNowButton);
        Grid.SetColumn(restoreButton, 2);
        backupActions.Children.Add(restoreButton);
        Grid.SetColumn(openFolderButton, 4);
        backupActions.Children.Add(openFolderButton);

        cacheBackupFilesBox.Content = "自动备份文件";
        cacheEditingFilesBox.Content = "未打开的编辑缓存";
        cacheResourceFilesBox.Content = "联机资源缓存";
        foreach (var box in new[]
                 {
                     cacheBackupFilesBox,
                     cacheEditingFilesBox,
                     cacheResourceFilesBox
                 })
            box.Margin = new Thickness(2, 3, 0, 2);
        ToolTip.SetTip(cacheEditingFilesBox, "当前已打开的谱面工作目录始终会被保护并跳过");
        ToolTip.SetTip(cacheResourceFilesBox, "活动联机房间存在时会拒绝清理该缓存");
        AutomationProperties.SetAutomationId(cacheBackupFilesBox, "Settings.Cache.Backups");
        AutomationProperties.SetAutomationId(cacheEditingFilesBox, "Settings.Cache.UnopenedEditing");
        AutomationProperties.SetAutomationId(cacheResourceFilesBox, "Settings.Cache.OnlineResources");
        cleanSelectedCacheButton.Content = "清理勾选项目";
        cleanSelectedCacheButton.HorizontalAlignment = HorizontalAlignment.Stretch;
        cleanSelectedCacheButton.Click += async (_, _) => await CleanSelectedCacheAsync();
        AutomationProperties.SetAutomationId(cleanSelectedCacheButton, "Settings.Cache.CleanSelected");
        backupCacheStatusText.Text = "请选择需要清理的类别";
        backupCacheStatusText.Foreground = MutedBrush;
        backupCacheStatusText.FontSize = 10;
        backupCacheStatusText.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(backupCacheStatusText, "Settings.BackupCacheStatus");
        RefreshAutoBackupSettingsUi();

        var section = SettingsSection(
            "备份与恢复",
            string.Empty,
            "Settings.BackupCacheSection",
            autoBackupEnabledBox,
            TimingField("自动备份频率", autoBackupIntervalSlider),
            autoBackupIntervalText,
            backupActions,
            backupFolderText,
            new Border { Height = 1, Background = StrokeBrush, Margin = new Thickness(0, 9) },
            new TextBlock
            {
                Text = "缓存管理",
                Foreground = Brushes.White,
                FontSize = 17,
                FontWeight = FontWeight.SemiBold,
                Margin = new Thickness(0, 8, 0, 4)
            },
            cacheBackupFilesBox,
            cacheEditingFilesBox,
            cacheResourceFilesBox,
            cleanSelectedCacheButton,
            backupCacheStatusText);
        return section;
    }

    private Control BuildShortcutSettings()
    {
        shortcutButtons.Clear();
        shortcutListPanel.Children.Clear();
        var headerTitle = new TextBlock
        {
            Text = "快捷键",
            Foreground = Brushes.White,
            FontSize = 17,
            FontWeight = FontWeight.SemiBold
        };
        AutomationProperties.SetAutomationId(headerTitle, "Settings.ShortcutsSection");
        var resetButton = new Button
        {
            Content = "恢复默认",
            MinWidth = 102,
            Padding = new Thickness(12, 7),
            Background = PanelBrush,
            Foreground = Brushes.White,
            BorderBrush = StrokeBrush,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(4)
        };
        AutomationProperties.SetAutomationId(resetButton, "Settings.Shortcuts.Reset");
        resetButton.Click += (_, _) => ResetShortcutSettings();
        var header = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") };
        header.Children.Add(new StackPanel
        {
            Children =
            {
                headerTitle,
                new TextBlock
                {
                    Text = "点击按键框后录入组合键",
                    Foreground = MutedBrush,
                    FontSize = 10
                }
            }
        });
        Grid.SetColumn(resetButton, 1);
        header.Children.Add(resetButton);

        foreach (var descriptor in WindowsEditorShortcutSettings.Catalog)
        {
            var action = descriptor.Id;
            var row = new Grid { ColumnDefinitions = new ColumnDefinitions("*,122") };
            row.Children.Add(new TextBlock
            {
                Text = descriptor.Label,
                Foreground = MutedBrush,
                VerticalAlignment = VerticalAlignment.Center,
                TextWrapping = TextWrapping.Wrap
            });
            var button = new Button
            {
                MinWidth = 116,
                Padding = new Thickness(8, 6),
                Background = PanelBrush,
                Foreground = Brushes.White,
                BorderBrush = StrokeBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                HorizontalContentAlignment = HorizontalAlignment.Center
            };
            ToolTip.SetTip(button, "点击后按下新快捷键；Backspace 清除；Escape 取消");
            AutomationProperties.SetAutomationId(button, $"Shortcut_{action}");
            AutomationProperties.SetName(button, AvaloniaLocalizationCatalog.Format("{0}快捷键", descriptor.Label));
            button.Click += (_, _) => BeginShortcutCapture(action);
            Grid.SetColumn(button, 1);
            row.Children.Add(button);
            shortcutListPanel.Children.Add(row);
            shortcutButtons[action] = button;
        }

        shortcutStatusText.Text = "Backspace 清除绑定 · Escape 取消录入";
        shortcutStatusText.Foreground = MutedBrush;
        shortcutStatusText.FontSize = 10;
        shortcutStatusText.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(shortcutStatusText, "Settings.Shortcuts.Status");
        RefreshShortcutButtons();
        RefreshShortcutLabels();
        return new Border
        {
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(0),
            Padding = new Thickness(0),
            Child = new StackPanel
            {
                Spacing = 10,
                Children = { header, shortcutListPanel, shortcutStatusText }
            }
        };
    }

    private void BeginShortcutCapture(string action)
    {
        CancelShortcutCapture(updateStatus: false);
        capturingShortcutAction = action;
        shortcutStatusText.Text = IsWheelModifierAction(action)
            ? AvaloniaLocalizationCatalog.Format(
                "正在录入“{0}” · 按住修饰键（例如 Ctrl，可与其它修饰键组合），Backspace 清除，Escape 取消",
                ShortcutLabel(action))
            : AvaloniaLocalizationCatalog.Format("正在录入“{0}” · 直接按组合键，Backspace 清除，Escape 取消", ShortcutLabel(action));
        RefreshShortcutButtons();
        if (shortcutButtons.TryGetValue(action, out var button)) button.Focus();
    }

    private void CancelShortcutCapture(bool updateStatus = true)
    {
        capturingShortcutAction = null;
        if (updateStatus) shortcutStatusText.Text = "已取消快捷键录入";
        RefreshShortcutButtons();
    }

    private void ResetShortcutSettings()
    {
        CancelShortcutCapture(updateStatus: false);
        shortcutSettings.Reset();
        shortcutStatusText.Text = "快捷键已恢复 WPF 1.1.0 默认值";
        MarkShortcutSettingsDirty();
        RefreshShortcutButtons();
        RefreshShortcutLabels();
    }

    private void RefreshShortcutButtons()
    {
        foreach (var descriptor in WindowsEditorShortcutSettings.Catalog)
        {
            if (!shortcutButtons.TryGetValue(descriptor.Id, out var button)) continue;
            var capturing = descriptor.Id.Equals(
                capturingShortcutAction,
                StringComparison.OrdinalIgnoreCase);
            var gesture = shortcutSettings.Bindings.GetValueOrDefault(descriptor.Id) ?? string.Empty;
            button.Content = capturing
                ? "请按键…"
                : string.IsNullOrWhiteSpace(gesture) ? "未设置" : gesture;
            button.BorderBrush = capturing ? AccentBrush : StrokeBrush;
            AutomationProperties.SetHelpText(
                button,
                capturing
                    ? "正在录入快捷键"
                    : string.IsNullOrWhiteSpace(gesture) ? "未设置" : gesture);
        }
    }

    private void RefreshShortcutLabels()
    {
        timeline.SetWheelModifiers(
            WindowsEditorShortcutGesture.ResolveWheelModifiers(shortcutSettings, "WheelQuickScroll"),
            WindowsEditorShortcutGesture.ResolveWheelModifiers(shortcutSettings, "WheelZoom"),
            WindowsEditorShortcutGesture.ResolveWheelModifiers(shortcutSettings, "WheelPan"));
        RefreshUnsnapScrollHelpText();
        RefreshGridBeatHeightLabel();
        foreach (var pair in quickShortcutButtons)
            ToolTip.SetTip(
                pair.Value.Button,
                $"{pair.Value.Description}  {CompactShortcut(pair.Key)}");
        ToolTip.SetTip(audioPlayPauseButton, AvaloniaLocalizationCatalog.Format("播放 / 暂停  {0}", CompactShortcut("PlayPause")));
        if (commandPlayButton != null)
            ToolTip.SetTip(commandPlayButton, AvaloniaLocalizationCatalog.Format("播放 / 暂停  {0}", CompactShortcut("PlayPause")));
        if (commandFullscreenButton != null)
            ToolTip.SetTip(
                commandFullscreenButton,
                SupportsDesktopWindowSizing
                    ? AvaloniaLocalizationCatalog.Format("全屏窗口化（覆盖任务栏）/ 退出  {0}", CompactShortcut("ToggleFullscreen"))
                    : AvaloniaLocalizationCatalog.Format("隐藏 / 显示顶部标签  {0}", CompactShortcut("ToggleFullscreen")));
        if (mixedCopyButton != null)
            ToolTip.SetTip(mixedCopyButton, editorViewSettings.QuickRangeCopy
                ? AvaloniaLocalizationCatalog.Format(
                    "复制选中的 Note / Effect（快捷键 {0} 已改为区间复制）",
                    CompactShortcut("Copy"))
                : AvaloniaLocalizationCatalog.Format("复制选中的 Note / Effect  {0}", CompactShortcut("Copy")));
        if (mixedPasteButton != null)
            ToolTip.SetTip(mixedPasteButton, AvaloniaLocalizationCatalog.Format("按当前分度粘贴到红线  {0}", CompactShortcut("Paste")));
        if (mixedDeleteButton != null)
            ToolTip.SetTip(mixedDeleteButton, AvaloniaLocalizationCatalog.Format("删除选中的 Note / Effect  {0}", CompactShortcut("Delete")));
        if (timelineToolButtons.TryGetValue(TimelineTool.Select, out var select))
            ToolTip.SetTip(select, AvaloniaLocalizationCatalog.Format("选择工具  {0}", CompactShortcut("ToolSelect")));
        if (timelineToolButtons.TryGetValue(TimelineTool.Tap, out var tap))
            ToolTip.SetTip(tap, AvaloniaLocalizationCatalog.Format("单键工具  {0}", CompactShortcut("ToolTap")));
        if (timelineToolButtons.TryGetValue(TimelineTool.Hold, out var hold))
            ToolTip.SetTip(hold, AvaloniaLocalizationCatalog.Format("长键工具  {0}", CompactShortcut("ToolHold")));
        if (timelineToolButtons.TryGetValue(TimelineTool.Erase, out var erase))
            ToolTip.SetTip(erase, AvaloniaLocalizationCatalog.Format("擦除工具  {0}", CompactShortcut("ToolErase")));
        ToolTip.SetTip(proEditorButton, AvaloniaLocalizationCatalog.Format("切换 ProEditor  {0}", CompactShortcut("TogglePro")));
    }

    private string CompactShortcut(string action)
    {
        var gesture = shortcutSettings.Bindings.GetValueOrDefault(action) ?? string.Empty;
        return string.IsNullOrWhiteSpace(gesture)
            ? "—"
            : gesture.Replace("Ctrl+", "C+", StringComparison.Ordinal)
                .Replace("Shift+", "S+", StringComparison.Ordinal)
                .Replace("Alt+", "A+", StringComparison.Ordinal);
    }

    private static string ShortcutLabel(string action) =>
        WindowsEditorShortcutSettings.Catalog.FirstOrDefault(item =>
            item.Id.Equals(action, StringComparison.OrdinalIgnoreCase))?.Label ?? action;

    private void MarkShortcutSettingsDirty()
    {
        shortcutSettingsDirty = true;
        shortcutSettingsSaveTimer.Stop();
        shortcutSettingsSaveTimer.Start();
    }

    private void PersistPendingShortcutSettings(bool force = false)
    {
        shortcutSettingsSaveTimer.Stop();
        if (!shortcutSettingsDirty && !force) return;
        try
        {
            WindowsEditorShortcutSettingsStore.Save(shortcutSettings);
            shortcutSettingsDirty = false;
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("快捷键保存失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void ConfigureSpectrogramAppearanceSliders(
        Slider strength,
        Slider detail,
        string automationPrefix)
    {
        ConfigureSettingsSlider(
            strength,
            WindowsAudioPanelSettings.MinimumBackgroundSpectrogramStrength * 100,
            100,
            5,
            audioPanelSettings.BackgroundSpectrogramStrength * 100,
            $"{automationPrefix}.SpectrogramStrength",
            "背景频谱强度");
        ConfigureSettingsSlider(
            detail,
            0,
            100,
            5,
            audioPanelSettings.SpectrogramDetail * 100,
            $"{automationPrefix}.SpectrogramDetail",
            "频谱细节");
        ToolTip.SetTip(strength, "背景频谱有多醒目；越高越亮，并更多压暗轨道里的背景图");
        ToolTip.SetTip(detail, "越高保留越多弱信号与泛音；越低只留鼓点和起音");
        strength.ValueChanged += (_, eventArgs) =>
        {
            if (!suppressSpectrogramAppearanceControls)
                ApplySpectrogramAppearance(eventArgs.NewValue / 100, audioPanelSettings.SpectrogramDetail);
        };
        detail.ValueChanged += (_, eventArgs) =>
        {
            if (!suppressSpectrogramAppearanceControls)
                ApplySpectrogramAppearance(audioPanelSettings.BackgroundSpectrogramStrength, eventArgs.NewValue / 100);
        };
    }

    private static Grid BuildSpectrogramAppearanceGrid(
        Slider strength,
        TextBlock strengthValue,
        Slider detail,
        TextBlock detailValue)
    {
        var grid = new Grid { ColumnDefinitions = new ColumnDefinitions("*,12,*") };
        grid.Children.Add(new StackPanel
        {
            Children = { TimingField("背景频谱强度", strength), strengthValue }
        });
        var detailColumn = new StackPanel
