    private Flyout BuildSpectrogramAppearanceFlyout()
    {
        ConfigureSpectrogramAppearanceSliders(
            spectrogramFlyoutStrengthSlider,
            spectrogramFlyoutDetailSlider,
            "Audio.SpectrogramFlyout");
        foreach (var valueText in new[] { spectrogramFlyoutStrengthValueText, spectrogramFlyoutDetailValueText })
        {
