    /// <summary>
    /// Stores and applies the spectrogram's strength and detail. Strength only
    /// changes how the background layer is drawn; detail re-maps the spectrum
    /// for the background and the side panel alike.
    /// </summary>
    private void ApplySpectrogramAppearance(double strength, double detail)
    {
        audioPanelSettings = audioPanelSettings.WithSpectrogramAppearance(strength, detail);
        audioPanelSettingsDirty = true;
        ScheduleAudioPanelSettingsSave();
        timeline.SetSpectrogramAppearance(
            audioPanelSettings.BackgroundSpectrogramStrength,
            audioPanelSettings.SpectrogramDetail);
        spectrogramSideSurface.SetSpectrogramDetail(audioPanelSettings.SpectrogramDetail);
        RefreshSpectrogramAppearanceUi();
    }

    private void RefreshSpectrogramAppearanceUi()
    {
        var strength = audioPanelSettings.BackgroundSpectrogramStrength;
        var detail = audioPanelSettings.SpectrogramDetail;
        var previous = suppressSpectrogramAppearanceControls;
        suppressSpectrogramAppearanceControls = true;
        try
        {
            foreach (var slider in new[] { spectrogramStrengthSlider, spectrogramFlyoutStrengthSlider })
                if (Math.Abs(slider.Value - strength * 100) > .01) slider.Value = strength * 100;
            foreach (var slider in new[] { spectrogramDetailSlider, spectrogramFlyoutDetailSlider })
                if (Math.Abs(slider.Value - detail * 100) > .01) slider.Value = detail * 100;
        }
        finally
        {
            suppressSpectrogramAppearanceControls = previous;
        }
        var strengthText = strength.ToString("P0", CultureInfo.CurrentCulture);
        var detailText = string.Format(
            CultureInfo.CurrentCulture,
            "{0:P0} · {1}",
            detail,
            detail < .34
                ? AvaloniaLocalizationCatalog.Text("突出起音")
                : detail < .67
                    ? AvaloniaLocalizationCatalog.Text("均衡")
                    : AvaloniaLocalizationCatalog.Text("完整细节"));
        spectrogramStrengthValueText.Text = strengthText;
        spectrogramFlyoutStrengthValueText.Text = strengthText;
        spectrogramDetailValueText.Text = detailText;
        spectrogramFlyoutDetailValueText.Text = detailText;
    }

    private static void ConfigureSettingsSlider(
        Slider slider,
        double minimum,
        double maximum,
        double tick,
        double value,
        string automationId,
        string name)
    {
        slider.Minimum = minimum;
        slider.Maximum = maximum;
        slider.TickFrequency = tick;
        slider.IsSnapToTickEnabled = true;
        slider.SmallChange = tick;
        slider.LargeChange = Math.Max(tick, (maximum - minimum) / 10);
        slider.Value = Math.Clamp(value, minimum, maximum);
        ConstrainInspectorSlider(slider);
        AutomationProperties.SetAutomationId(slider, automationId);
        AutomationProperties.SetName(slider, name);
    }

    private static void ConstrainInspectorSlider(Slider slider)
    {
        slider.MinWidth = 0;
        slider.MaxWidth = WindowsInspectorParityPolicy.InspectorContentMaximumWidth;
        slider.HorizontalAlignment = HorizontalAlignment.Stretch;
    }

    private static Border SettingsSection(
        string title,
        string subtitle,
        string automationId,
        params Control[] controls)
    {
        var panel = new StackPanel { Spacing = 5 };
        var titleText = new TextBlock
        {
            Text = title,
            Foreground = Brushes.White,
            FontSize = string.Equals(
                automationId,
                "Settings.EditorViewSection",
                StringComparison.Ordinal)
                ? WindowsInspectorParityPolicy.SettingsTitleFontSize
                : WindowsInspectorParityPolicy.SettingsSectionTitleFontSize,
            FontWeight = FontWeight.SemiBold
        };
        AutomationProperties.SetAutomationId(titleText, automationId);
        panel.Children.Add(titleText);
        if (!string.IsNullOrWhiteSpace(subtitle))
        {
            panel.Children.Add(new TextBlock
            {
                Text = subtitle,
                Foreground = MutedBrush,
                FontSize = 10,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 4)
            });
        }
        foreach (var control in controls) panel.Children.Add(control);
        return new Border
        {
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(0),
            Padding = new Thickness(0),
            Child = panel
        };
    }

