    private Grid BuildDisplayScaleStepper(
        Slider slider,
        Button decreaseButton,
        Button increaseButton,
        string label,
        string automationIdPrefix)
    {
        ConfigureDisplayScaleStepButton(
            decreaseButton,
            "−",
            AvaloniaLocalizationCatalog.Format("{0}减少 5%", label),
            $"{automationIdPrefix}.Decrease");
        ConfigureDisplayScaleStepButton(
            increaseButton,
            "+",
            AvaloniaLocalizationCatalog.Format("{0}增加 5%", label),
            $"{automationIdPrefix}.Increase");
        decreaseButton.Click += (_, _) =>
            StepDisplayScaleSlider(slider, direction: -1);
        increaseButton.Click += (_, _) =>
            StepDisplayScaleSlider(slider, direction: 1);

        var row = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("32,6,*,6,32"),
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Children = { decreaseButton, slider, increaseButton }
        };
        Grid.SetColumn(slider, 2);
        Grid.SetColumn(increaseButton, 4);
        return row;
    }

    private static void ConfigureDisplayScaleStepButton(
        Button button,
        string content,
        string name,
        string automationId)
    {
        button.Content = content;
        button.Width = 32;
        button.Height = 30;
        button.Padding = new Thickness(0);
        button.FontSize = 16;
        ApplyWpfToolButtonStyle(button);
        button.Margin = new Thickness(0);
        AutomationProperties.SetName(button, name);
        AutomationProperties.SetAutomationId(button, automationId);
        ToolTip.SetTip(button, name);
    }

    private static void StepDisplayScaleSlider(Slider slider, int direction)
    {
        slider.Value = WindowsDisplayScaleStepPolicy.ResolvePercent(
            slider.Value,
            slider.Minimum,
            slider.Maximum,
            direction);
    }

    private void EditorViewSettingsSlider_ValueChanged(
        object? sender,
        RangeBaseValueChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressEditorViewControls) return;

        suppressEditorViewControls = true;
        try
        {
            noteWidthSlider.Maximum = Math.Max(12, gridLaneWidthSlider.Value - 6);
            if (noteWidthSlider.Value > noteWidthSlider.Maximum)
                noteWidthSlider.Value = noteWidthSlider.Maximum;
            editorViewSettings = editorViewSettings.WithView(
                Math.Round(gridLaneWidthSlider.Value),
                Math.Round(gridBeatHeightSlider.Value),
                Math.Round(mainEditorHorizontalOffsetSlider.Value),
                Math.Round(noteWidthSlider.Value),
                Math.Round(noteHeightSlider.Value),
                noteOpacitySlider.Value / 100,
                judgementLinePositionSlider.Value / 100,
                judgementLineThicknessSlider.Value,
                judgementLineOpacitySlider.Value / 100)
                .WithTrackOpacity(WindowsTrackTransparencyPolicy.ToFillOpacity(
                    trackOpacitySlider.Value / 100))
                .WithBarLineThickness(barLineThicknessSlider.Value)
                .WithSubdivisionLineThickness(subdivisionLineThicknessSlider.Value);
            editorBackgroundSettings = editorBackgroundSettings.WithDarkness(
                backgroundDarknessSlider.Value / 100);
        }
        finally
        {
            suppressEditorViewControls = false;
        }

        ApplyEditorViewSettings();
        RefreshEditorViewSettingsUi();
        editorViewSettingsDirty = true;
        editorBackgroundSettingsDirty = true;
        ScheduleEditorViewSettingsSave();
    }

    private void FrameRateLimitBox_SelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (suppressEditorViewControls ||
            frameRateLimitBox.SelectedItem is not LabeledChoice { } frameRateChoice)
            return;

        var selected = frameRateChoice.Value;
        var normalized = WindowsFrameRateOptions.ClampToPresentable(
            selected,
            PlatformDisplayRefreshRates.Current);
        editorViewSettings = editorViewSettings.WithFrameRateLimit(normalized);
        AutomationProperties.SetHelpText(
            frameRateLimitBox,
            $"FrameRateLimit={normalized}; " +
            $"Presets={string.Join(',', WindowsFrameRateOptions.PresentablePresets(
                PlatformDisplayRefreshRates.Current))}");
        ConfigureEditorFrameRateRuntime(resetCounters: true);
        MarkEditorViewSettingsDirty();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("帧率上限：{0} FPS", normalized));
    }

    private void Timeline_PixelsPerBeatChanged(object? sender, double pixelsPerBeat)
    {
        _ = sender;
        UpdateAudioPanelViewports();
        if (suppressEditorViewControls ||
            Math.Abs(editorViewSettings.GridBeatHeight - pixelsPerBeat) < .001)
            return;

        editorViewSettings = editorViewSettings.WithView(
            editorViewSettings.GridLaneWidth,
            pixelsPerBeat,
            editorViewSettings.MainEditorHorizontalOffset,
            editorViewSettings.NoteWidth,
            editorViewSettings.NoteHeight,
            editorViewSettings.NoteOpacity,
            editorViewSettings.JudgementLinePosition,
            editorViewSettings.JudgementLineThickness,
            editorViewSettings.JudgementLineOpacity);
        suppressEditorViewControls = true;
        try
        {
            gridBeatHeightSlider.Value = pixelsPerBeat;
        }
        finally
        {
            suppressEditorViewControls = false;
        }
        RefreshEditorViewSettingsUi();
        editorViewSettingsDirty = true;
        ScheduleEditorViewSettingsSave();
    }

    private void ApplyEditorViewSettings()
    {
        editorViewSettings = editorViewSettings.Normalize();
        ApplyQuickEditPaletteLayout();
        ApplyQuickValuesPaletteLayout();
        difficultyInfoCardTransform.X = editorViewSettings.DifficultyCardX;
        difficultyInfoCardTransform.Y = editorViewSettings.DifficultyCardY;
        ApplyDifficultyCardCollapsedState();
        timeline.ConfigureView(
            editorViewSettings.GridLaneWidth,
            editorViewSettings.GridBeatHeight,
            editorViewSettings.NoteWidth,
            editorViewSettings.NoteHeight,
            editorViewSettings.NoteOpacity,
            editorViewSettings.JudgementLinePosition,
            editorViewSettings.JudgementLineThickness,
            editorViewSettings.JudgementLineOpacity,
            editorViewSettings.NoteAnchor,
            editorViewSettings.BarLineThickness,
            editorViewSettings.SubdivisionLineThickness,
            editorViewSettings.TrackOpacity);
        timeline.SetMainTrackOffset(editorViewSettings.MainEditorHorizontalOffset);
        timeline.SetUnsnapScrollDivision(editorViewSettings.UnsnapScrollDivision);
        timeline.SetBackgroundOpacity(1 - editorBackgroundSettings.Darkness);
        RefreshQuickValuesPaletteValues();
        UpdateAudioPanelViewports();
        QueueAudioPanelLayout(clampFreePanels: true);
        QueueDifficultyCardLayout();
    }

    private void RefreshEditorViewSettingsUi()
    {
        SyncSettingsSnapBox(
            viewModel.ActiveTab?.Session.SnapDivision ?? editorViewSettings.SnapDivision);
        SyncSettingsFixedSnapBox(editorViewSettings.FixedSnapDivision);
        SyncSettingsUnsnapScrollBox(editorViewSettings.UnsnapScrollDivision);
        SyncCurveDivisionBox(toolboxCurveDenseBox, editorViewSettings.CurveDenseDivision);
        SyncCurveDivisionBox(toolboxCurveSparseBox, editorViewSettings.CurveSparseDivision);
        SyncToolboxCurveLaneBox();
        SyncQuickRangeCopyBox();
        RefreshNoteAnchorButtons();
        gridLaneWidthValueText.Text = $"{editorViewSettings.GridLaneWidth:0} DIP";
        gridBeatHeightValueText.Text = $"{editorViewSettings.GridBeatHeight:0} DIP / beat";
        mainEditorHorizontalOffsetValueText.Text =
            Math.Abs(editorViewSettings.MainEditorHorizontalOffset) < .5
                ? "居中（0 DIP）"
                : $"{editorViewSettings.MainEditorHorizontalOffset:+0;-0;0} DIP";
        noteWidthValueText.Text = $"{editorViewSettings.NoteWidth:0} DIP";
        noteHeightValueText.Text = $"{editorViewSettings.NoteHeight:0} DIP";
        noteOpacityValueText.Text = $"{editorViewSettings.NoteOpacity:P0}";
        trackOpacityValueText.Text =
            $"{WindowsTrackTransparencyPolicy.ToTransparency(editorViewSettings.TrackOpacity):P0}";
        backgroundDarknessValueText.Text = $"{editorBackgroundSettings.Darkness:P0}";
        barLineThicknessValueText.Text = $"{editorViewSettings.BarLineThickness:0.00} DIP";
        subdivisionLineThicknessValueText.Text =
            AvaloniaLocalizationCatalog.Format("{0:0.00} DIP 基准", editorViewSettings.SubdivisionLineThickness);
        judgementLinePositionValueText.Text = $"{editorViewSettings.JudgementLinePosition:P0}";
        judgementLineThicknessValueText.Text =
            $"{editorViewSettings.JudgementLineThickness:0.0} DIP";
        judgementLineOpacityValueText.Text = $"{editorViewSettings.JudgementLineOpacity:P0}";
    }

    private void ResetEditorViewSettings()
    {
        var defaults = WindowsEditorViewSettings.Default;
        editorBackgroundSettings = WindowsEditorBackgroundSettings.Default;
        editorViewSettings = editorViewSettings.WithView(
            defaults.GridLaneWidth,
            defaults.GridBeatHeight,
            defaults.MainEditorHorizontalOffset,
            defaults.NoteWidth,
            defaults.NoteHeight,
            defaults.NoteOpacity,
            defaults.JudgementLinePosition,
            defaults.JudgementLineThickness,
            defaults.JudgementLineOpacity)
            .WithTrackOpacity(defaults.TrackOpacity)
            .WithNoteAnchor(defaults.NoteAnchor)
            .WithBarLineThickness(defaults.BarLineThickness)
            .WithSubdivisionLineThickness(defaults.SubdivisionLineThickness);
        suppressEditorViewControls = true;
        try
        {
            gridLaneWidthSlider.Value = editorViewSettings.GridLaneWidth;
            gridBeatHeightSlider.Value = editorViewSettings.GridBeatHeight;
            mainEditorHorizontalOffsetSlider.Value = editorViewSettings.MainEditorHorizontalOffset;
            noteWidthSlider.Maximum = Math.Max(12, editorViewSettings.GridLaneWidth - 6);
            noteWidthSlider.Value = editorViewSettings.NoteWidth;
            noteHeightSlider.Value = editorViewSettings.NoteHeight;
            noteOpacitySlider.Value = editorViewSettings.NoteOpacity * 100;
            trackOpacitySlider.Value = WindowsTrackTransparencyPolicy.ToTransparency(
                editorViewSettings.TrackOpacity) * 100;
            backgroundDarknessSlider.Value = editorBackgroundSettings.Darkness * 100;
            barLineThicknessSlider.Value = editorViewSettings.BarLineThickness;
            subdivisionLineThicknessSlider.Value =
                editorViewSettings.SubdivisionLineThickness;
            judgementLinePositionSlider.Value = editorViewSettings.JudgementLinePosition * 100;
            judgementLineThicknessSlider.Value = editorViewSettings.JudgementLineThickness;
            judgementLineOpacitySlider.Value = editorViewSettings.JudgementLineOpacity * 100;
        }
        finally
        {
            suppressEditorViewControls = false;
        }
        ApplyEditorViewSettings();
        RefreshEditorViewSettingsUi();
        editorViewSettingsDirty = true;
        editorBackgroundSettingsDirty = true;
        PersistPendingEditorViewSettings();
        viewModel.SetStatus("已恢复 WPF 1.1.0 推荐视图比例");
    }

    private void ScheduleEditorViewSettingsSave()
    {
        editorViewSettingsSaveTimer.Stop();
        editorViewSettingsSaveTimer.Start();
    }

    private void PersistPendingEditorViewSettings(bool force = false)
    {
        editorViewSettingsSaveTimer.Stop();
        if (!editorViewSettingsDirty && !editorBackgroundSettingsDirty && !force) return;
        try
        {
            if (editorViewSettingsDirty || force)
            {
                WindowsEditorViewSettingsStore.Save(editorViewSettings);
                editorViewSettingsDirty = false;
            }
            if (editorBackgroundSettingsDirty || force)
            {
                WindowsEditorBackgroundSettingsStore.Save(editorBackgroundSettings);
                editorBackgroundSettingsDirty = false;
            }
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("编辑器设置保存失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

