        {
            field.MinWidth = 0;
            field.HorizontalAlignment = HorizontalAlignment.Stretch;
            field.ClipToBounds = true;
            action.MinWidth = 0;
            action.MaxWidth = actionWidth - 4;
            action.HorizontalAlignment = HorizontalAlignment.Stretch;
