                label,
                $"Metadata.Stats.{WindowsInspectorParityPolicy.Wpf110MetadataStatLabels[index]}.Label");
            var stat = new StackPanel
            {
                Children =
                {
                    value,
                    label
                }
            };
            Grid.SetColumn(stat, index);
            metadataStatsGrid.Children.Add(stat);
        }
        var metadataStatsPanel = new Border
        {
            Background = new SolidColorBrush(Color.Parse("#202326")),
            BorderBrush = new SolidColorBrush(Color.Parse("#30353A")),
            BorderThickness = new Thickness(1),
