                0,
                0),
            Child = metadataStatsGrid
        };
        AutomationProperties.SetAutomationId(metadataStatsPanel, "Metadata.Stats");

        return new StackPanel
        {
            Spacing = 8,
            Margin = new Thickness(
                0,
                0,
                0,
                WindowsInspectorParityPolicy.MetadataBottomScrollClearance),
            Children =
            {
                new TextBlock
                {
                    Text = WindowsInspectorParityPolicy.Wpf110MetadataTitle,
                    Foreground = Brushes.White,
                    FontSize = WindowsInspectorParityPolicy.MetadataTitleFontSize,
                    FontWeight = FontWeight.SemiBold
                },
                new TextBlock
                {
                    Text = WindowsInspectorParityPolicy.Wpf110MetadataSubtitle,
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap
                },
                TimingField(
                    WindowsInspectorParityPolicy.Wpf110MetadataTitleAsciiLabel,
                    titleRow),
                TimingField("歌曲名原文", metadataTitleOriginalBox),
                TimingField(
                    WindowsInspectorParityPolicy.Wpf110MetadataArtistAsciiLabel,
                    artistRow),
                TimingField("艺术家原文", metadataArtistOriginalBox),
                creatorVersion,
                bpmKeys,
                TimingField("音频", audioRow),
                analysisButtons,
