                    FontWeight = FontWeight.SemiBold
                },
                new TextBlock
                {
                    Text = "按音色 / 音轨组织 Note · 可嵌套 · 隐藏只影响编辑显示",
                    Foreground = MutedBrush,
                    FontSize = 10
                }
            }
        });
        Grid.SetColumn(groupCreateAndUseButton, 1);
        heading.Children.Add(groupCreateAndUseButton);

        var current = new Border
        {
            Background = PanelBrush,
            BorderBrush = StrokeBrush,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(4),
            Padding = new Thickness(9, 7),
            Margin = new Thickness(0, 12, 0, 2),
            Child = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,Auto"),
                Children =
                {
                    new TextBlock
                    {
                        Text = "当前放置分组",
                        Foreground = MutedBrush,
                        VerticalAlignment = VerticalAlignment.Center
                    },
                    currentPlacementGroupText
                }
            }
        };
        Grid.SetColumn(currentPlacementGroupText, 1);

        var idAndUse = new Grid { ColumnDefinitions = new ColumnDefinitions("82,8,*") };
        idAndUse.Children.Add(groupIdBox);
        Grid.SetColumn(groupSetCurrentButton, 2);
        idAndUse.Children.Add(groupSetCurrentButton);

        var visibilityActions = new UniformGrid { Columns = 3 };
        visibilityActions.Children.Add(groupShowAllButton);
        visibilityActions.Children.Add(groupHideNonzeroButton);
        visibilityActions.Children.Add(groupClearSelectedButton);

        BuildGroupColorPopup();

        // 存档 is the only way the editor's own metadata leaves this machine. It
        // lives on the group page because that is where the group names, colours
        // and drawers the archive is mostly about are made.
        ConfigureGroupButton(
            archiveExportButton,
            "导出存档",
            "导出编辑器存档",
            ExportEditorArchive);
        ConfigureGroupButton(
            archiveImportButton,
            "导入存档",
            "导入编辑器存档",
            ImportEditorArchive);
        ApplyWpfToolButtonStyle(archiveExportButton);
        ApplyWpfToolButtonStyle(archiveImportButton);
        AutomationProperties.SetAutomationId(
            archiveExportButton,
            "Inspector.Group.ExportArchive");
        AutomationProperties.SetAutomationId(
            archiveImportButton,
            "Inspector.Group.ImportArchive");
        AutomationProperties.SetName(archiveExportButton, "导出编辑器存档");
        AutomationProperties.SetName(archiveImportButton, "导入编辑器存档");
        ToolTip.SetTip(
            archiveExportButton,
            "把分组名 / 颜色 / 各套分组预设、Note 的分组、批注和批注预设、ProEditor 轨道写成一个文件");
        ToolTip.SetTip(
            archiveImportButton,
            "从一个存档文件接回这些内容；已有的分组和批注不会被删掉");
        KeyboardNavigation.SetTabIndex(archiveExportButton, displayTabIndex++);
        KeyboardNavigation.SetTabIndex(archiveImportButton, displayTabIndex++);
        archiveHintText.Foreground = MutedBrush;
        archiveHintText.FontSize = 10;
        archiveHintText.TextWrapping = TextWrapping.Wrap;
        archiveHintText.Text =
            "存档＝这张谱在编辑器里的全部记号：分组名 / 颜色 / 各套分组预设、每个 Note 属于哪个分组、" +
            "批注与批注预设、ProEditor 额外轨道。导入是合并，只覆盖存档里点到名字的部分。";
        var archiveActions = new UniformGrid { Columns = 2 };
        archiveActions.Children.Add(archiveExportButton);
        archiveActions.Children.Add(archiveImportButton);
        var archivePanel = new StackPanel
        {
            Spacing = 6,
            Children =
            {
                new Border { Height = 1, Background = StrokeBrush, Margin = new Thickness(0, 6, 0, 2) },
                archiveActions,
                archiveHintText
            }
        };

        return new StackPanel
        {
            Spacing = 8,
            Children =
            {
                heading,
                current,
                groupManagerHint,
                idAndUse,
                groupAssignButton,
                visibilityActions,
                displayPanel,
                archivePanel,
                // The drawer tabs are page chrome, not list content: they live in
                // the row above this scroller. What is left here is the caption
                // that explains them.
                groupPresetHintText,
                groupListPanel,
                groupColorPopup
            }
        };
    }

    /// <summary>
    /// The 分组 page: the preset tab row pinned under the inspector's own tab
    /// row, with the group manager scrolling underneath it. The strip is outside
    /// the scroller on purpose — a second level of tabs that scrolls away is
    /// neither a tab bar nor a list.
    /// </summary>
    private Control BuildGroupInspectorPage(Control groupManager)
    {
        var page = new Grid { RowDefinitions = new RowDefinitions("Auto,*") };
        Grid.SetRow(BuildPresetTabBar(), 0);
        page.Children.Add(groupPresetTabBar);
        var scroller = WrapInspectorContent(groupManager, new Thickness(18, 14, 18, 24));
        Grid.SetRow(scroller, 1);
        page.Children.Add(scroller);
        return page;
    }

    /// <summary>
    /// The preset tab row, built to match the inspector's own tabs: same
    /// palette and metrics as the TabItem theme the WPF 1.1.0 skin installs
    /// (muted #929A9F label, #22272A selected plate, 2-DIP #7FA4A7 underline,
    /// #202427 hover), so the two levels read as one control with a drawer
    /// under a page. The hairline under it is the line the tabs sit on.
    /// </summary>
    private Control BuildPresetTabBar()
    {
        groupPresetTabStrip.MinHeight = 32;
        groupPresetTabScroller.Content = groupPresetTabStrip;
        groupPresetTabScroller.HorizontalScrollBarVisibility = ScrollBarVisibility.Auto;
        groupPresetTabScroller.VerticalScrollBarVisibility = ScrollBarVisibility.Disabled;
        groupPresetTabScroller.HorizontalAlignment = HorizontalAlignment.Stretch;
        groupPresetTabScroller.VerticalAlignment = VerticalAlignment.Bottom;
        AutomationProperties.SetAutomationId(
            groupPresetTabScroller,
            "Inspector.Group.PresetTabs");
        AutomationProperties.SetName(groupPresetTabScroller, "分组预设标签");

        var actions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 3,
            Margin = new Thickness(6, 0, 6, 0),
            VerticalAlignment = VerticalAlignment.Bottom
        };
        actions.Children.Add(groupNewPresetButton);
        actions.Children.Add(groupRenamePresetButton);
        actions.Children.Add(groupDeletePresetButton);

        var row = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") };
        row.Children.Add(groupPresetTabScroller);
        Grid.SetColumn(actions, 1);
        row.Children.Add(actions);

        groupPresetTabBar.Background = Brushes.Transparent;
        groupPresetTabBar.BorderBrush = StrokeBrush;
        groupPresetTabBar.BorderThickness = new Thickness(0, 0, 0, 1);
        groupPresetTabBar.Padding = new Thickness(4, 0, 0, 0);
        groupPresetTabBar.Child = row;
        return groupPresetTabBar;
    }

    /// <summary>
    /// The 批注 page: a drawer strip pinned directly under the inspector's own
    /// tabs, with the block list below it — the same shape as 分组, so the two
    /// pages read as one control with a drawer under a page. The strip sits
    /// outside the scroller so it does not scroll away with the list.
    /// </summary>
    private Control BuildAnnotationInspectorPage()
    {
        var page = new Grid { RowDefinitions = new RowDefinitions("Auto,*") };
        Grid.SetRow(BuildAnnotationPresetTabBar(), 0);
        page.Children.Add(annotationPresetTabBar);
        var scroller = WrapInspectorContent(
            BuildAnnotationManager(),
            new Thickness(18, 14, 18, 24));
        Grid.SetRow(scroller, 1);
        page.Children.Add(scroller);
        return page;
    }

    /// <summary>
    /// The annotation drawer strip. Same palette and metrics as the group one —
    /// both ride on the inspector's tab row — but it is its own strip, over its
    /// own drawer set: the two never share a tab, a name or an id.
    /// </summary>
    private Control BuildAnnotationPresetTabBar()
    {
        annotationPresetTabStrip.MinHeight = 32;
        annotationPresetTabScroller.Content = annotationPresetTabStrip;
        annotationPresetTabScroller.HorizontalScrollBarVisibility = ScrollBarVisibility.Auto;
        annotationPresetTabScroller.VerticalScrollBarVisibility = ScrollBarVisibility.Disabled;
        annotationPresetTabScroller.HorizontalAlignment = HorizontalAlignment.Stretch;
        annotationPresetTabScroller.VerticalAlignment = VerticalAlignment.Bottom;
        AutomationProperties.SetAutomationId(
            annotationPresetTabScroller,
            "Inspector.Annotation.PresetTabs");
        AutomationProperties.SetName(annotationPresetTabScroller, "批注预设标签");

        ConfigureGroupButton(
            annotationNewPresetButton,
            "＋",
            "Annotation 新建预设",
            CreateAnnotationPreset);
        ConfigureGroupButton(
            annotationRenamePresetButton,
            "重命名",
            "Annotation 重命名预设",
            ToggleAnnotationPresetRenameMode);
        ConfigureGroupButton(
            annotationDeletePresetButton,
            "删除",
            "Annotation 删除预设",
            DeleteActiveAnnotationPreset);
        ApplyWpfToolButtonStyle(annotationNewPresetButton);
        ApplyWpfToolButtonStyle(annotationRenamePresetButton);
        ApplyWpfToolButtonStyle(annotationDeletePresetButton);
        CompactPresetStripButton(annotationNewPresetButton, 30, 13);
        CompactPresetStripButton(annotationRenamePresetButton, 58, 11);
        CompactPresetStripButton(annotationDeletePresetButton, 46, 11);
        AutomationProperties.SetAutomationId(
            annotationNewPresetButton,
            "Inspector.Annotation.NewPreset");
        AutomationProperties.SetAutomationId(
            annotationRenamePresetButton,
            "Inspector.Annotation.RenamePreset");
        AutomationProperties.SetAutomationId(
            annotationDeletePresetButton,
            "Inspector.Annotation.DeletePreset");
        AutomationProperties.SetName(annotationNewPresetButton, "新建批注预设");
        AutomationProperties.SetName(annotationRenamePresetButton, "重命名当前批注预设");
        AutomationProperties.SetName(annotationDeletePresetButton, "删除当前批注预设");
        ToolTip.SetTip(annotationNewPresetButton, "新建一个批注预设：只显示这个预设里的批注");
        ToolTip.SetTip(annotationRenamePresetButton, "重命名当前批注预设；也可以右键它的标签");
        ToolTip.SetTip(annotationDeletePresetButton, "删除当前批注预设；批注本身不会丢，回到「全部」里");

        var actions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
