    /// <summary>
    /// One tab on the annotation strip. Structurally the group strip's twin,
    /// including the right-click rename: a Button swallows the press, so it has
    /// to be caught on the tunnel route or it never arrives.
    /// </summary>
    private Control BuildAnnotationPresetTab(
        DesktopChartTab tab,
        int? preset,
        int blockCount,
        ref int dynamicTabIndex)
    {
        var key = preset ?? 0;
        var isActive = tab.ActiveAnnotationPreset == preset;
        var button = new Button
        {
            Content = AnnotationPresetTabLabel(tab, preset, blockCount, isActive),
            Padding = new Thickness(11, 6),
            MinHeight = 32,
            HorizontalAlignment = HorizontalAlignment.Left,
            VerticalAlignment = VerticalAlignment.Bottom,
            CornerRadius = new CornerRadius(0),
            BorderThickness = new Thickness(0, 0, 0, 2)
        };
        ApplyPresetTabAppearance(button, isActive);
        button.Click += (_, _) => UseAnnotationPreset(preset);
        button.PointerEntered += (_, _) =>
        {
            if (tab.ActiveAnnotationPreset != preset) ApplyPresetTabAppearance(button, false, hovered: true);
        };
        button.PointerExited += (_, _) =>
        {
            if (tab.ActiveAnnotationPreset != preset) ApplyPresetTabAppearance(button, false);
        };
        AutomationProperties.SetName(
            button,
            preset is { } described
                ? AvaloniaLocalizationCatalog.Format(
                    "批注预设「{0}」标签{1}",
                    tab.AnnotationCatalog.PresetNameOf(described),
                    isActive ? "（当前）" : string.Empty)
                : AvaloniaLocalizationCatalog.Format(
                    "全部批注标签{0}",
                    isActive ? "（当前）" : string.Empty));
        AutomationProperties.SetAutomationId(
            button,
            preset is { } tabbed
                ? $"Inspector.Annotation.Preset.{tabbed}.Tab"
                : "Inspector.Annotation.Preset.All.Tab");
        ToolTip.SetTip(
            button,
            preset is { } hinted
                ? AvaloniaLocalizationCatalog.Format(
                    "只显示「{0}」里的批注；右键这个标签可以改名",
                    tab.AnnotationCatalog.PresetNameOf(hinted))
                : "显示全部批注：不属于任何预设的批注也在这里");
        KeyboardNavigation.SetTabIndex(button, dynamicTabIndex++);
        annotationPresetTabButtons[key] = button;
        annotationPresetTabCounts[key] = blockCount;

        if (preset is { } rightClickable)
        {
            button.AddHandler(
                InputElement.PointerPressedEvent,
                (_, eventArgs) =>
                {
                    if (!eventArgs.GetCurrentPoint(button).Properties.IsRightButtonPressed) return;
                    eventArgs.Handled = true;
                    BeginAnnotationPresetRename(rightClickable);
                },
                RoutingStrategies.Tunnel);
        }

        if (preset is { } created && created == annotationPresetScrollTarget)
        {
            annotationPresetScrollTarget = 0;
            Dispatcher.UIThread.Post(
                () => button.BringIntoView(),
                DispatcherPriority.Loaded);
        }

        return button;
    }

    /// <summary>The caption on an annotation drawer tab, with its block count.</summary>
    private static TextBlock AnnotationPresetTabLabel(
        DesktopChartTab tab,
        int? preset,
        int blockCount,
        bool isActive)
    {
        var label = preset is { } named
            ? tab.AnnotationCatalog.PresetNameOf(named)
            : "全部";
        return new TextBlock
        {
            Text = blockCount == 0
                ? label
                : AvaloniaLocalizationCatalog.Format("{0} ({1})", label, blockCount),
            Foreground = isActive ? Brushes.White : MutedBrush,
            FontSize = 12,
            VerticalAlignment = VerticalAlignment.Center
        };
    }

    /// <summary>
    /// Sizes one of the strip's own controls. They ride on the tab row, so they
    /// are as tall as a tab and only as wide as their label.
    /// </summary>
    private static void CompactPresetStripButton(Button button, double width, double fontSize)
    {
        button.HorizontalAlignment = HorizontalAlignment.Left;
        button.VerticalAlignment = VerticalAlignment.Bottom;
        button.Width = width;
        button.Height = 27;
        button.MinHeight = 0;
        button.Padding = new Thickness(0);
        button.FontSize = fontSize;
        button.Margin = new Thickness(0, 0, 0, 3);
    }

    /// <summary>
    /// The 批注 tab: one block per annotation, listed in chart order. A block is
    /// a comment pinned to a set of notes — deliberately not a group — so it can
    /// cut across groups and sit on notes that were never grouped at all. Its
    /// sticky note on the timeline takes the colour of the notes' group, and the
    /// stock white when they have none.
    /// </summary>
    private Control BuildAnnotationManager()
    {
        ConfigureGroupButton(
            groupNewAnnotationButton,
            "把选中 Note 做成批注",
            "Annotation 新建批注",
            CreateAnnotationFromSelection);
        ApplyWpfPrimaryButtonStyle(groupNewAnnotationButton);
        AutomationProperties.SetAutomationId(
            groupNewAnnotationButton,
            "Inspector.Annotation.New");
        // The 批注 tab has no WPF 1.1.0 counterpart, so its focus range is its
        // own and no existing target moves.
        KeyboardNavigation.SetTabIndex(
            groupNewAnnotationButton,
            WindowsInspectorParityPolicy.AnnotationDynamicFocusStartIndex);

        annotationHintText.Foreground = MutedBrush;
        annotationHintText.FontSize = 11;
        annotationHintText.TextWrapping = TextWrapping.Wrap;
        annotationHintText.Text = "选中 Note 后新增一块批注。便利贴颜色跟着这些 Note 的分组走，未分组就是白色。";

        var heading = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") };
        heading.Children.Add(new StackPanel
        {
            Children =
            {
                new TextBlock
                {
                    Text = "批注",
                    Foreground = Brushes.White,
                    FontSize = WindowsInspectorParityPolicy.GroupTitleFontSize,
                    FontWeight = FontWeight.SemiBold
                },
                new TextBlock
                {
                    Text = "给一段 Note 写分析 · 点条目就跳到它",
                    Foreground = MutedBrush,
                    FontSize = 10
                }
            }
        });
        Grid.SetColumn(groupNewAnnotationButton, 1);
        heading.Children.Add(groupNewAnnotationButton);

        return new StackPanel
        {
            Spacing = 8,
            Children =
            {
                heading,
                annotationHintText,
                new Border { Height = 1, Background = StrokeBrush, Margin = new Thickness(0, 4) },
                annotationListPanel
            }
        };
    }

    private void RefreshAnnotationPanel()
    {
        var tab = viewModel.ActiveTab;
        // A chart switch retires the editor without committing: the text in the
        // box belongs to the block on the chart it was opened from.
        if (annotationEditorOverlay.IsVisible &&
            (tab == null || tab.Id != annotationEditorTabId))
            annotationEditorOverlay.IsVisible = false;
        if (tab == null)
        {
            if (annotationRows.Count > 0 ||
                annotationListPanel.Children.Count > 0 ||
                annotationPresetTabStrip.Children.Count > 0)
            {
                annotationListPanel.Children.Clear();
                annotationPresetTabStrip.Children.Clear();
                annotationRows.Clear();
            }
            annotationPanelSignature = string.Empty;
            DiscardAnnotationPresetRename();
            annotationHintText.Text = "选中 Note 后新增一块批注。";
            return;
        }

        // Same reasoning as the group strip: the name in the box belongs to a
        // drawer on the chart it was opened from, and the new chart's preset 1
        // is a different drawer that merely shares the number.
        if (annotationPresetRenameHost != 0 && tab.Id != annotationPresetRenameTabId)
            DiscardAnnotationPresetRename();

        var catalog = tab.AnnotationCatalog;
        var openDrawer = tab.ActiveAnnotationPreset;
        var openDrawerName = openDrawer is { } open
            ? catalog.PresetNameOf(open)
            : null;
        annotationHintText.Text = openDrawer is null
            ? (catalog.IsEmpty
                ? "还没有批注。在时间轴上选中 Note，再按「把选中 Note 做成批注」。"
                : AvaloniaLocalizationCatalog.Format(
                    "共 {0} 块批注。点条目跳到它的位置并选中它覆盖的 Note；在时间轴上双击便利贴可以直接写。",
                    catalog.Annotations.Count))
            : AvaloniaLocalizationCatalog.Format(
                "预设「{0}」：只显示这 {1} 块批注；新建的批注会直接落进来，用每行的「预设」下拉可以挪别的进来。",
                openDrawerName,
                AnnotationPanelAnnotations(tab, openDrawer).Count);
        if (catalog.Presets.Count == 0)
            annotationHintText.Text += " 上方标签行可以新建批注预设；它只决定显示哪些批注，和分组预设互不影响。";

        var signature = BuildAnnotationPanelSignature(tab);
        if (!string.Equals(signature, annotationPanelSignature, StringComparison.Ordinal))
        {
            // Recorded only when the rebuild actually ran: a rebuild refused by
            // the re-entrancy guard has to leave the old signature in place, or
            // the panel would believe it is showing a shape it never rendered.
            if (RebuildAnnotationPanel(tab)) annotationPanelSignature = signature;
        }
        else
        {
            UpdateAnnotationRows(tab);
        }
    }

    /// <summary>
    /// The preset a block is filed in, or null for 全部. Preset ids start at 1,
    /// so null is unambiguous — the same contract the group side uses.
    /// </summary>
    private static int? AnnotationPresetOf(DesktopChartTab tab, ChartAnnotation annotation) =>
        tab.AnnotationCatalog.PresetIdOf(annotation.Id);

    /// <summary>
    /// The blocks one preset puts on screen, in beat order. A null preset is
    /// 全部: every block, which is what keeps one that belongs to no preset
    /// reachable instead of invisible-but-present.
    /// </summary>
    private static List<ChartAnnotation> AnnotationPanelAnnotations(
        DesktopChartTab tab,
        int? preset) =>
        preset is { } selected && tab.AnnotationCatalog.FindPreset(selected) is { } found
            ? tab.AnnotationCatalog.InBeatOrder()
                .Where(annotation => found.AnnotationIds.Contains(annotation.Id))
                .ToList()
            : tab.AnnotationCatalog.InBeatOrder().ToList();

    /// <summary>
    /// Structure only, so a note edit does not rebuild the list and steal the
    /// caret out of a text box that is being typed in. The open drawer belongs
    /// in here even though it does not touch the catalog: it decides which rows
    /// are on screen, and a rebuild is the cheap way to follow it.
    /// </summary>
    private static string BuildAnnotationPanelSignature(DesktopChartTab tab)
    {
        var parts = new List<string>(
            tab.AnnotationCatalog.Annotations.Count +
            tab.AnnotationCatalog.Presets.Count +
            2)
        {
            tab.Id.ToString("N"),
            string.Concat(
                "A",
                (tab.ActiveAnnotationPreset ?? 0).ToString(CultureInfo.InvariantCulture))
        };
        foreach (var preset in tab.AnnotationCatalog.Presets)
        {
            parts.Add(string.Concat(
                "P",
                preset.Id.ToString(CultureInfo.InvariantCulture),
                ":",
                preset.Name));
        }
        foreach (var annotation in tab.AnnotationCatalog.InBeatOrder())
        {
            parts.Add(string.Concat(
                annotation.Id.ToString(CultureInfo.InvariantCulture),
                ":",
                annotation.Notes.Count.ToString(CultureInfo.InvariantCulture),
                ":",
                (AnnotationPresetOf(tab, annotation) ?? -1)
                    .ToString(CultureInfo.InvariantCulture)));
        }
        return string.Join("|", parts);
    }

    /// <summary>
    /// Re-entrancy is refused on purpose, exactly like the group panel: the strip
    /// holds controls that can take focus, and taking one off screen raises focus
    /// events that would clear the strip from inside the loop filling it.
    /// </summary>
    private bool RebuildAnnotationPanel(DesktopChartTab tab)
    {
        if (rebuildingAnnotationPanel) return false;
        rebuildingAnnotationPanel = true;
        try
        {
            FlushAnnotationPresetRename();
            RebuildAnnotationPresetTabStrip(tab);
            RebuildAnnotationRows(tab);
        }
        finally
        {
            rebuildingAnnotationPanel = false;
        }
        return true;
    }

    private void RebuildAnnotationPresetTabStrip(DesktopChartTab tab)
    {
        annotationPresetTabStrip.Children.Clear();
        annotationPresetTabButtons.Clear();
        annotationPresetTabCounts.Clear();

        var dynamicTabIndex =
            WindowsInspectorParityPolicy.AnnotationPresetDynamicFocusStartIndex;
        var openPreset = tab.ActiveAnnotationPreset;
        // 全部 is not a preset, so 删除 has no target while it is on screen — and
        // it is dimmed as well as disabled, because a skin that paints its own
        // colours leaves a disabled button looking exactly like a live one.
        annotationDeletePresetButton.IsEnabled = openPreset is not null;
        annotationDeletePresetButton.Opacity = openPreset is not null ? 1 : 0.45;

        // 全部 leads because it is the state a chart starts in, and it is where
        // a block no preset names stays visible.
        annotationPresetTabStrip.Children.Add(BuildAnnotationPresetTab(
            tab,
            null,
            AnnotationPanelAnnotations(tab, null).Count,
            ref dynamicTabIndex));
        foreach (var preset in tab.AnnotationCatalog.Presets)
        {
            annotationPresetTabStrip.Children.Add(BuildAnnotationPresetTab(
                tab,
                preset.Id,
                AnnotationPanelAnnotations(tab, preset.Id).Count,
                ref dynamicTabIndex));
        }
    }

    private void RebuildAnnotationRows(DesktopChartTab tab)
    {
        annotationListPanel.Children.Clear();
        annotationRows.Clear();

        var panelAnnotations = AnnotationPanelAnnotations(tab, tab.ActiveAnnotationPreset);
        if (panelAnnotations.Count == 0)
        {
            annotationListPanel.Children.Add(new TextBlock
            {
                Text = tab.ActiveAnnotationPreset is null
                    ? "还没有批注：在时间轴上选中 Note，再按「把选中 Note 做成批注」。"
                    : "这个批注预设还是空的：在时间轴上选中 Note 新建的批注会直接落进来，" +
                      "也可以用任意一行的「预设」下拉把别的批注挪进来。",
                Foreground = MutedBrush,
                FontSize = 10,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(2, 4, 0, 2)
            });
        }

        var tabIndex = WindowsInspectorParityPolicy.AnnotationDynamicFocusRowStartIndex;
        foreach (var annotation in panelAnnotations)
        {
            var id = annotation.Id;
            var color = ResolveAnnotationColor(tab, annotation);

            var swatch = new Border
            {
                Width = 14,
                Height = 14,
                CornerRadius = new CornerRadius(3),
                Background = new SolidColorBrush(color),
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 6, 0)
            };

            var position = new TextBlock
            {
                Text = BuildAnnotationPositionText(tab, annotation),
                Foreground = Brushes.White,
                FontSize = 11,
                VerticalAlignment = VerticalAlignment.Center
            };

            var coverage = new TextBlock
            {
                Text = BuildAnnotationCoverageText(tab, annotation),
                Foreground = MutedBrush,
                FontSize = 10,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(6, 0, 0, 0)
            };

            var jumpBody = new Grid { ColumnDefinitions = new ColumnDefinitions("Auto,*,Auto") };
            jumpBody.Children.Add(swatch);
            Grid.SetColumn(position, 1);
            jumpBody.Children.Add(position);
            Grid.SetColumn(coverage, 2);
            jumpBody.Children.Add(coverage);

            var jump = new Button
            {
                Content = jumpBody,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                HorizontalContentAlignment = HorizontalAlignment.Stretch,
                Padding = new Thickness(6, 4)
            };
            ApplyWpfToolButtonStyle(jump);
            AutomationProperties.SetName(
                jump,
                AvaloniaLocalizationCatalog.Format("批注 {0} 跳转", id));
            AutomationProperties.SetAutomationId(jump, $"Inspector.Annotation.{id}.Jump");
            ToolTip.SetTip(jump, "跳到这块批注的位置，并选中它覆盖的 Note");
            KeyboardNavigation.SetTabIndex(jump, tabIndex++);
            jump.Click += (_, _) => JumpToAnnotation(id);

            var text = new TextBox
            {
                Text = annotation.Text,
                PlaceholderText = "写点什么…（这块批注的便利贴上会显示这段文字）",
                FontSize = 12,
                AcceptsReturn = true,
                TextWrapping = TextWrapping.Wrap,
                MinHeight = 54,
                Padding = new Thickness(6, 4)
            };
            AutomationProperties.SetName(
                text,
                AvaloniaLocalizationCatalog.Format("批注 {0} 内容", id));
            AutomationProperties.SetAutomationId(text, $"Inspector.Annotation.{id}.Text");
            KeyboardNavigation.SetTabIndex(text, tabIndex++);
            // AcceptsReturn keeps Enter as a newline, so the commit point is
            // losing focus rather than Enter.
            text.LostFocus += (_, _) => CommitAnnotationText(id, text.Text);

            var retarget = PrimaryButton("重新指向选中", (_, _) => RetargetAnnotation(id));
            ApplyWpfToolButtonStyle(retarget);
            retarget.Padding = new Thickness(7, 5);
            AutomationProperties.SetName(
                retarget,
                AvaloniaLocalizationCatalog.Format("批注 {0} 重新指向", id));
            AutomationProperties.SetAutomationId(retarget, $"Inspector.Annotation.{id}.Retarget");
            ToolTip.SetTip(retarget, "把这块批注改成指向当前选中的 Note");
            KeyboardNavigation.SetTabIndex(retarget, tabIndex++);

            var delete = PrimaryButton("删除", (_, _) => DeleteAnnotation(id));
            ApplyWpfToolButtonStyle(delete);
            delete.Padding = new Thickness(7, 5);
            delete.Margin = new Thickness(3, 0, 0, 0);
            AutomationProperties.SetName(
                delete,
                AvaloniaLocalizationCatalog.Format("批注 {0} 删除", id));
            AutomationProperties.SetAutomationId(delete, $"Inspector.Annotation.{id}.Delete");
            KeyboardNavigation.SetTabIndex(delete, tabIndex++);

            var actions = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto,Auto") };
            actions.Children.Add(retarget);
            Grid.SetColumn(delete, 2);
            actions.Children.Add(delete);

            // Which preset this block belongs to. Filing is a display filter
            // only: it never touches the block's text, its notes or a group.
            var drawerIds = new List<int?> { null };
            var drawer = new ComboBox
            {
                FontSize = 11,
                Padding = new Thickness(6, 2),
                HorizontalAlignment = HorizontalAlignment.Stretch
            };
            drawer.Items.Add("不归入预设");
            foreach (var preset in tab.AnnotationCatalog.Presets)
            {
                drawer.Items.Add(tab.AnnotationCatalog.PresetNameOf(preset.Id));
                drawerIds.Add(preset.Id);
            }
            drawer.SelectedIndex = Math.Max(
                0,
                drawerIds.IndexOf(AnnotationPresetOf(tab, annotation)));
            AutomationProperties.SetName(
                drawer,
                AvaloniaLocalizationCatalog.Format("批注 {0} 预设", id));
            AutomationProperties.SetAutomationId(drawer, $"Inspector.Annotation.{id}.Preset");
            ToolTip.SetTip(drawer, "把这块批注归入哪个预设；它只决定显示，不动 Note");
            KeyboardNavigation.SetTabIndex(drawer, tabIndex++);
            drawer.SelectionChanged += (_, _) =>
            {
                var index = drawer.SelectedIndex;
                if (index < 0 || index >= drawerIds.Count) return;
                // The row is not in annotationRows until it is fully built, so
                // the programmatic SelectedIndex above finds nothing and does not
                // commit — only a user pick does.
                var row = FindAnnotationRow(id);
                if (row is { SuppressEvents: false })
                    CommitAnnotationPreset(id, drawerIds[index]);
            };

            var drawerRow = new Grid { ColumnDefinitions = new ColumnDefinitions("Auto,*") };
            drawerRow.Children.Add(new TextBlock
            {
                Text = "预设",
                Foreground = MutedBrush,
                FontSize = 10,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 6, 0)
            });
            Grid.SetColumn(drawer, 1);
            drawerRow.Children.Add(drawer);

            var stack = new StackPanel { Spacing = 4 };
            stack.Children.Add(jump);
            stack.Children.Add(text);
            stack.Children.Add(drawerRow);
            stack.Children.Add(actions);

            var container = new Border
            {
                Background = Brushes.Transparent,
                BorderBrush = StrokeBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Padding = new Thickness(7, 6),
                Child = stack
            };
            AutomationProperties.SetAutomationId(container, $"Inspector.Annotation.{id}");

            annotationListPanel.Children.Add(container);
            annotationRows.Add(new AnnotationRowControls(
                id,
                swatch,
                text,
                position,
                coverage,
                jump,
                retarget,
                delete,
                drawer,
                drawerIds,
                container));
        }
    }

    private void UpdateAnnotationRows(DesktopChartTab tab)
    {
        foreach (var controls in annotationRows)
        {
            if (tab.AnnotationCatalog.Find(controls.Annotation) is not { } annotation) continue;
            controls.SuppressEvents = true;
            try
            {
                var color = ResolveAnnotationColor(tab, annotation);
                if (controls.Swatch.Background is not SolidColorBrush current ||
                    current.Color != color)
                    controls.Swatch.Background = new SolidColorBrush(color);
                controls.Position.Text = BuildAnnotationPositionText(tab, annotation);
                controls.Coverage.Text = BuildAnnotationCoverageText(tab, annotation);
                var drawerIndex = Math.Max(
                    0,
                    IndexOf(controls.DrawerIds, AnnotationPresetOf(tab, annotation)));
                if (controls.Drawer.SelectedIndex != drawerIndex)
                    controls.Drawer.SelectedIndex = drawerIndex;
                if (!controls.Text.IsFocused && controls.Text.Text != annotation.Text)
                    controls.Text.Text = annotation.Text;
            }
            finally
            {
                controls.SuppressEvents = false;
            }
        }
    }

    /// <summary>
    /// The colour a block's sticky note wears: the group its notes were given,
    /// or the stock white. Computed live from the notes rather than stored, so
    /// re-tagging a note re-colours the card without touching the block.
    ///
    /// 额外轨道上的草稿 note 也算 —— 时间轴上的卡片一直把它们算进去
    /// （<c>AnnotationNoteLookup</c>），这里漏掉的话，同一个块在列表里是白卡、
    /// 在谱面上却是彩色卡。
    /// </summary>
    private static Color ResolveAnnotationColor(DesktopChartTab tab, ChartAnnotation annotation)
    {
        var keys = annotation.Notes.ToHashSet();
        var groups = tab.Session.Document.Notes
            .Where(note => keys.Contains(WindowsAnnotationCommand.NoteKeyFor(note)))
            .Select(note => note.Group);
        var dominant = WindowsGroupVisuals.DominantGroup(groups);
        if (dominant == 0) return WindowsGroupVisuals.Ungrouped.Color;
        var custom = tab.GroupCatalog.ColorOf(dominant);
        return ChartGroupCatalog.IsValidColorText(custom) && Color.TryParse(custom.Trim(), out var parsed)
            ? parsed
            : WindowsGroupVisuals.PaletteColor(dominant);
    }

    private static string BuildAnnotationPositionText(
        DesktopChartTab tab,
        ChartAnnotation annotation) =>
        AvaloniaLocalizationCatalog.Format(
            "批注 {0} · {1}",
            annotation.Id,
            WindowsBeatDisplayFormat.Format(
                BeatPosition.FromDouble(WindowsAnnotationCommand.AnchorBeatFor(tab.Session, annotation))));

    private static string BuildAnnotationCoverageText(
        DesktopChartTab tab,
        ChartAnnotation annotation)
    {
        var (resolved, total) = WindowsAnnotationCommand.Measure(tab.Session, annotation);
        return resolved == total
            ? AvaloniaLocalizationCatalog.Format("{0} 个 Note", total)
            : AvaloniaLocalizationCatalog.Format("{0}/{1} 有效", resolved, total);
    }

    private void JumpToAnnotation(int annotation)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.AnnotationCatalog.Find(annotation) is not { } block) return;
        var beat = WindowsAnnotationCommand.AnchorBeatFor(tab.Session, block);
        var count = WindowsAnnotationCommand.SelectNotes(tab, annotation, additive: false);
        timeline.SetCurrentBeat(beat);
        UpdateSelectionUi();
        RefreshAnnotationPanel();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "已跳到批注 {0}（{1}）并选中 {2} 个 Note",
            annotation,
            BeatPosition.FromDouble(beat),
            count));
    }

    private void RetargetAnnotation(int annotation)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var count = WindowsAnnotationCommand.RetargetFromSelection(tab, annotation);
        MarkGroupCatalogDirty(tab);
        annotationPanelSignature = string.Empty;
        RefreshAnnotationPanel();
        PushGroupVisuals();
        viewModel.SetStatus(count == 0
            ? "先在时间轴上选中 Note，再点「重新指向选中」"
            : AvaloniaLocalizationCatalog.Format(
                "批注 {0} 现在指向 {1} 个 Note",
                annotation,
                count));
    }

    private void DeleteAnnotation(int annotation)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        // A deleted block cannot be edited, so the box goes with it (no commit:
        // the text would be written back into an entry that is about to vanish).
        if (annotationEditorId == annotation) annotationEditorOverlay.IsVisible = false;
        if (!WindowsAnnotationCommand.Remove(tab, annotation)) return;
        MarkGroupCatalogDirty(tab);
        annotationPanelSignature = string.Empty;
        RefreshAnnotationPanel();
        PushGroupVisuals();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已删除批注 {0}", annotation));
    }

    /// <summary>
    /// Writes one block's text. Deliberately does not refresh the list: the
    /// caret is still in that text box and a rebuild would take it away. Only
    /// the timeline is repainted, so the sticky note follows while typing.
    /// </summary>
    private void CommitAnnotationText(int annotation, string? text)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (!WindowsAnnotationCommand.SetText(tab, annotation, text)) return;
        MarkGroupCatalogDirty(tab);
        PushGroupVisuals();
    }

    /// <summary>
    /// The editor that floats over a sticky note. The 批注 tab writes the same
    /// field, but it sits a tab away from the notes a comment is about, and the
    /// card is right next to them — so the card itself is a way in. Typing goes
    /// straight into the catalog: no document mutation, no undo entry, exactly
    /// like the tab, so a mapper's Ctrl+Z is never spent on a comment.
    /// </summary>
    private void BuildAnnotationEditorOverlay()
    {
        annotationEditorTitle.Foreground = Brushes.White;
        annotationEditorTitle.FontSize = 11;
        annotationEditorTitle.FontWeight = FontWeight.SemiBold;
        annotationEditorTitle.VerticalAlignment = VerticalAlignment.Center;
        annotationEditorTitle.TextTrimming = TextTrimming.CharacterEllipsis;

        var hint = new TextBlock
        {
            Text = "Esc 或点别处结束",
            Foreground = MutedBrush,
            FontSize = 10,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(8, 0, 0, 0)
        };
        var header = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") };
        header.Children.Add(annotationEditorTitle);
        Grid.SetColumn(hint, 1);
        header.Children.Add(hint);

        annotationEditorBox.FontSize = 12;
        annotationEditorBox.AcceptsReturn = true;
        annotationEditorBox.TextWrapping = TextWrapping.Wrap;
        annotationEditorBox.MinHeight = 62;
        annotationEditorBox.MaxHeight = 150;
        annotationEditorBox.MaxLength = ChartAnnotationCatalog.MaximumTextLength;
        annotationEditorBox.Padding = new Thickness(6, 4);
        annotationEditorBox.PlaceholderText = "写点什么…（这段字就长在便利贴上）";
        AutomationProperties.SetName(annotationEditorBox, "便利贴内容");
        AutomationProperties.SetAutomationId(annotationEditorBox, "Timeline.Annotation.Editor");
        annotationEditorBox.TextChanged += (_, _) => PushAnnotationEditorText();
        annotationEditorBox.LostFocus += (_, _) => CloseAnnotationEditor();
        annotationEditorBox.KeyDown += (_, eventArgs) =>
        {
            if (eventArgs.Key != Key.Escape) return;
            CloseAnnotationEditor();
            eventArgs.Handled = true;
        };

        annotationEditorOverlay.Width = 300;
        annotationEditorOverlay.Padding = new Thickness(8);
        annotationEditorOverlay.CornerRadius = new CornerRadius(6);
        annotationEditorOverlay.Background = new SolidColorBrush(Color.Parse("#F21B2023"));
        annotationEditorOverlay.BorderThickness = new Thickness(1);
        annotationEditorOverlay.BorderBrush = AccentBrush;
        annotationEditorOverlay.HorizontalAlignment = HorizontalAlignment.Left;
        annotationEditorOverlay.VerticalAlignment = VerticalAlignment.Top;
        annotationEditorOverlay.IsVisible = false;
        annotationEditorOverlay.SetValue(Panel.ZIndexProperty, 60);
        annotationEditorOverlay.Child = new StackPanel
        {
            Spacing = 5,
            Children = { header, annotationEditorBox }
        };
        timelineHost.Children.Add(annotationEditorOverlay);
    }

    private void OpenAnnotationEditor(int annotation, Rect cardBounds)
    {
        var tab = viewModel.ActiveTab;
        if (tab?.AnnotationCatalog.Find(annotation) is not { } block)
        {
            CloseAnnotationEditor();
            return;
        }
        annotationEditorId = annotation;
        annotationEditorTabId = tab.Id;
        annotationEditorSuppress = true;
        try
        {
            annotationEditorBox.Text = block.Text;
            annotationEditorTitle.Text = BuildAnnotationPositionText(tab, block);
            // Same colour rule as the card itself, so the box reads as an
            // extension of the sticky note rather than a generic dialog.
            annotationEditorOverlay.BorderBrush =
                new SolidColorBrush(ResolveAnnotationColor(tab, block));
        }
        finally
        {
            annotationEditorSuppress = false;
        }
        PlaceAnnotationEditor(cardBounds);
        annotationEditorOverlay.IsVisible = true;
        Dispatcher.UIThread.Post(
            () =>
            {
                if (!annotationEditorOverlay.IsVisible) return;
                annotationEditorBox.Focus();
                annotationEditorBox.CaretIndex = annotationEditorBox.Text?.Length ?? 0;
            },
            DispatcherPriority.Input);
    }

    /// <summary>
    /// Parks the editor over its own card, clamped into the viewport: a card
    /// docked against an edge would otherwise push half the box off screen.
    /// </summary>
    private void PlaceAnnotationEditor(Rect cardBounds)
    {
        var margin = timeline.Margin;
        var maxX = Math.Max(4, timelineHost.Bounds.Width - annotationEditorOverlay.Width - 8);
        var maxY = Math.Max(4, timelineHost.Bounds.Height - AnnotationEditorEstimatedHeight - 8);
        annotationEditorOverlay.Margin = new Thickness(
            Math.Clamp(cardBounds.X + margin.Left, 4, maxX),
            Math.Clamp(cardBounds.Y + margin.Top, 4, maxY),
            0,
            0);
    }

    /// <summary>
    /// Writes while typing, so the sticky note follows the box and neither the
    /// card nor the 批注 tab can show stale text. The list is updated rather
    /// than rebuilt — its signature is structure only — so the caret stays put.
    /// </summary>
    private void PushAnnotationEditorText()
    {
        if (annotationEditorSuppress) return;
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.Id != annotationEditorTabId) return;
        if (!WindowsAnnotationCommand.SetText(tab, annotationEditorId, annotationEditorBox.Text)) return;
        MarkGroupCatalogDirty(tab);
        PushGroupVisuals();
        UpdateAnnotationRows(tab);
    }

    private void CloseAnnotationEditor()
    {
        if (!annotationEditorOverlay.IsVisible) return;
        var tab = viewModel.ActiveTab;
        var annotation = annotationEditorId;
        var text = annotationEditorBox.Text;
        // Hiding the box raises LostFocus, which lands back here; the visibility
        // flag is the guard, so the second call is a no-op.
        annotationEditorOverlay.IsVisible = false;
        // Switching charts while the box was open would otherwise write this
        // text into a same-numbered block on the chart that is now in front.
        if (tab == null || tab.Id != annotationEditorTabId) return;
        if (!WindowsAnnotationCommand.SetText(tab, annotation, text)) return;
        MarkGroupCatalogDirty(tab);
        RefreshAnnotationPanel();
        // Hand the keyboard back to the chart, so the next shortcut lands on the
        // timeline instead of a box that is no longer on screen.
        timeline.Focus();
    }

    /// <summary>
    /// The swatch popup is one shared instance re-targeted at whichever group
    /// row opened it: twelve palette entries plus a hex box, so a group can take
    /// a built-in colour or any exact one.
    /// </summary>
    private void BuildGroupColorPopup()
    {
        groupColorSwatches.Orientation = Orientation.Horizontal;
        groupColorSwatches.Children.Clear();
        foreach (var hex in WindowsGroupVisuals.PaletteHex)
        {
            var swatch = hex;
            var button = new Button
            {
                Width = 34,
                Height = 26,
                Padding = new Thickness(0),
                Margin = new Thickness(2),
                Background = new SolidColorBrush(Color.Parse(swatch)),
                BorderBrush = StrokeBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4)
            };
            AutomationProperties.SetName(button, AvaloniaLocalizationCatalog.Format("分组颜色 {0}", swatch));
            ToolTip.SetTip(button, swatch);
            button.Click += (_, _) => ApplyGroupColor(groupColorTargetGroup, swatch);
            groupColorSwatches.Children.Add(button);
        }

        groupColorHexBox.PlaceholderText = "#RRGGBB";
        groupColorHexBox.FontSize = 12;
        groupColorHexBox.Width = 108;
        groupColorHexBox.KeyDown += (_, eventArgs) =>
        {
            if (eventArgs.Key != Key.Enter) return;
            ApplyGroupColorHexFromPopup();
            eventArgs.Handled = true;
        };
        var applyHex = PrimaryButton("应用色值", (_, _) => ApplyGroupColorHexFromPopup());
        var clearHex = PrimaryButton("用回默认", (_, _) => ApplyGroupColor(groupColorTargetGroup, string.Empty));
        ApplyWpfToolButtonStyle(applyHex);
        ApplyWpfToolButtonStyle(clearHex);

        var hexRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 6 };
        hexRow.Children.Add(groupColorHexBox);
        hexRow.Children.Add(applyHex);
        hexRow.Children.Add(clearHex);

        groupColorPopupTitleText.Foreground = Brushes.White;
        groupColorPopupTitleText.FontSize = 12;
        groupColorPopupTitleText.FontWeight = FontWeight.SemiBold;
        groupColorPopupSurface.Background = PanelBrush;
        groupColorPopupSurface.BorderBrush = StrokeBrush;
        groupColorPopupSurface.BorderThickness = new Thickness(1);
        groupColorPopupSurface.CornerRadius = new CornerRadius(6);
        groupColorPopupSurface.Padding = new Thickness(10);
        groupColorPopupSurface.Child = new StackPanel
        {
            Spacing = 8,
            Children =
            {
                groupColorPopupTitleText,
                groupColorSwatches,
                hexRow
            }
        };
        groupColorPopup.Placement = PlacementMode.Bottom;
        groupColorPopup.IsLightDismissEnabled = true;
        groupColorPopup.TakesFocusFromNativeControl = true;
        groupColorPopup.WindowManagerAddShadowHint = true;
        groupColorPopup.Child = groupColorPopupSurface;
    }


    private static void ConfigureGroupButton(
        Button button,
        string content,
        string automationName,
        Action action)
    {
        button.Content = content;
        button.Click += (_, _) => action();
        ApplyPrimaryButtonStyle(button);
        button.Padding = new Thickness(7, 6);
        AutomationProperties.SetName(button, automationName);
    }

    private Control BuildAudioTransport()
    {
        audioPlayPauseButton.Content = "▶ 播放";
        audioPlayPauseButton.Click += async (_, _) => await ToggleAudioPlaybackAsync();
        ApplyPrimaryButtonStyle(audioPlayPauseButton);
        AutomationProperties.SetAutomationId(audioPlayPauseButton, "Audio.PlayPause");

        audioStopButton.Content = "■ 停止";
        audioStopButton.Click += async (_, _) => await StopAudioAsync();
        ApplyPrimaryButtonStyle(audioStopButton);
        AutomationProperties.SetAutomationId(audioStopButton, "Audio.Stop");

        audioRefreshDeviceButton.Content = SupportsDesktopWindowSizing
            ? "刷新输出设备"
            : "重建音频输出";
        audioRefreshDeviceButton.Click += async (_, _) =>
            await RefreshEditorAudioDeviceAsync();
        ApplyPrimaryButtonStyle(audioRefreshDeviceButton);
        AutomationProperties.SetAutomationId(audioRefreshDeviceButton, "Audio.RefreshDevice");

        audioPositionSlider.Minimum = 0;
        audioPositionSlider.Maximum = 1;
        audioPositionSlider.Value = 0;
        ConstrainInspectorSlider(audioPositionSlider);
        AutomationProperties.SetAutomationId(audioPositionSlider, "Audio.Position");
        audioPositionSlider.AddHandler(
            InputElement.PointerPressedEvent,
            (_, _) => audioPositionPointerDown = true,
            RoutingStrategies.Tunnel);
        audioPositionSlider.AddHandler(
            InputElement.PointerReleasedEvent,
            async (_, _) =>
            {
                audioPositionPointerDown = false;
                await SeekAudioFromSliderAsync();
            },
            RoutingStrategies.Tunnel);
        audioPositionSlider.PointerCaptureLost += async (_, _) =>
        {
            if (!audioPositionPointerDown) return;
            audioPositionPointerDown = false;
            await SeekAudioFromSliderAsync();
        };
        audioPositionSlider.ValueChanged += async (_, _) =>
        {
            if (!suppressAudioControls && !audioPositionPointerDown && audioPositionSlider.IsFocused)
                await SeekAudioFromSliderAsync();
        };

        audioVolumeSlider.Minimum = 0;
        audioVolumeSlider.Maximum = 100;
        audioVolumeSlider.Value = 80;
        ConstrainInspectorSlider(audioVolumeSlider);
        AutomationProperties.SetAutomationId(audioVolumeSlider, "Audio.Volume");
        audioVolumeSlider.ValueChanged += async (_, eventArgs) =>
        {
            if (suppressAudioControls) return;
            audioVolumeText.Text = $"{eventArgs.NewValue:0}%";
            var volume = Math.Clamp(eventArgs.NewValue / 100, 0, 1);
            await audioTransport.SetVolumeAsync((float)volume);
            editorViewSettings = editorViewSettings.WithMusicVolume(volume);
            MarkEditorViewSettingsDirty();
        };

        audioRateSlider.Minimum = .2;
        audioRateSlider.Maximum = 1;
        audioRateSlider.Value = 1;
        audioRateSlider.SmallChange = .05;
        audioRateSlider.LargeChange = .1;
        ConstrainInspectorSlider(audioRateSlider);
        AutomationProperties.SetAutomationId(audioRateSlider, "Audio.Rate");
        audioRateSlider.ValueChanged += async (_, eventArgs) =>
        {
            if (suppressAudioControls) return;
            var rate = Math.Round(eventArgs.NewValue, 2);
            audioRateText.Text = $"{rate:0.00}x";
            await SetEditorPlaybackRateAsync(rate);
        };

        audioPreservePitchBox.Content = "变速不变调";
        audioPreservePitchBox.Foreground = Brushes.White;
        AutomationProperties.SetAutomationId(audioPreservePitchBox, "Audio.PreservePitch");
        audioPreservePitchBox.IsCheckedChanged += async (_, _) =>
        {
            if (!suppressAudioControls)
                await SetEditorPreservePitchAsync(audioPreservePitchBox.IsChecked == true);
        };

        waveformBackgroundBox.Content = "背景波形";
        waveformBackgroundBox.Foreground = Brushes.White;
        waveformBackgroundBox.IsChecked = evidenceEnableBackgroundWaveform;
        ToolTip.SetTip(
            waveformBackgroundBox,
            "WPF 默认是展开的侧栏波形；背景模式默认关闭，勾选后铺在可玩轨道背景");
        waveformBackgroundBox.IsCheckedChanged += (_, _) =>
        {
            if (!suppressAudioPanelControls)
                SetAudioPanelBackgroundMode(
                    WindowsAudioPanelKind.Waveform,
                    waveformBackgroundBox.IsChecked == true);
        };
        spectrogramBackgroundBox.Content = "背景频谱";
        spectrogramBackgroundBox.Foreground = Brushes.White;
        spectrogramBackgroundBox.IsChecked = evidenceEnableBackgroundSpectrogram;
        ToolTip.SetTip(
            spectrogramBackgroundBox,
            "WPF 默认折叠频谱；勾选后在可玩轨道背景显示 L/M/H 频谱");
        spectrogramBackgroundBox.IsCheckedChanged += (_, _) =>
        {
            if (!suppressAudioPanelControls)
                SetAudioPanelBackgroundMode(
                    WindowsAudioPanelKind.Spectrogram,
                    spectrogramBackgroundBox.IsChecked == true);
        };
        audioVisualizationStatusText.Text = "没有打开的谱面";
        audioVisualizationStatusText.Foreground = MutedBrush;
        audioVisualizationStatusText.FontSize = 11;
        audioVisualizationStatusText.TextWrapping = TextWrapping.Wrap;
        var visualizationToggles = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 12,
            Children = { waveformBackgroundBox, spectrogramBackgroundBox }
        };

        audioTimeText.Text = "00:00.000 / 00:00.000";
        audioTimeText.Foreground = Brushes.White;
        audioTimeText.FontFamily = new FontFamily("Cascadia Mono, Consolas");
        audioTimeText.FontSize = 11;
        AutomationProperties.SetAutomationId(audioTimeText, "Audio.Time");
        audioRateText.Text = "1.00x";
        audioRateText.Foreground = MutedBrush;
        AutomationProperties.SetAutomationId(audioRateText, "Audio.RateText");
        audioVolumeText.Text = "80%";
        audioVolumeText.Foreground = MutedBrush;
        AutomationProperties.SetAutomationId(audioVolumeText, "Audio.VolumeText");
        audioStatusText.Text = "没有打开的谱面";
        audioStatusText.Foreground = MutedBrush;
        audioStatusText.FontSize = 11;
        audioStatusText.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(audioStatusText, "Audio.RuntimeStatus");

        var transportButtons = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,*,Auto"),
            ColumnSpacing = 6,
            Children = { audioPlayPauseButton, audioStopButton, audioRefreshDeviceButton }
        };
        Grid.SetColumn(audioStopButton, 1);
        Grid.SetColumn(audioRefreshDeviceButton, 2);

        var rateRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("Auto,*,46"),
            ColumnSpacing = 8,
            Children =
            {
                new TextBlock
                {
                    Text = "倍速",
                    Foreground = MutedBrush,
                    VerticalAlignment = VerticalAlignment.Center
                },
                audioRateSlider,
                audioRateText
            }
        };
        Grid.SetColumn(audioRateSlider, 1);
        Grid.SetColumn(audioRateText, 2);
        audioRateText.VerticalAlignment = VerticalAlignment.Center;

        audioVolumeText.Margin = new Thickness(0, 5, 0, 10);

        audioPreservePitchBox.Margin = new Thickness(2, 10, 0, 2);
        ToolTip.SetTip(
            audioPreservePitchBox,
            "开启后只改变播放速度，不改变音高；切换时保持当前播放位置");
        return new StackPanel
        {
            Spacing = 7,
            Children =
            {
                TimingField("音乐音量", audioVolumeSlider),
                audioVolumeText,
                BuildKeySoundPanel(),
                audioPreservePitchBox,
                new TextBlock
                {
                    Text = "开启会使用时间伸缩处理；关闭则随倍速改变音高，性能开销更低。",
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(22, 3, 0, 2)
                }
            }
        };
    }

    private Control BuildKeySoundPanel()
    {
        keySoundEnabledBox.Content = "播放时启用 Key 音";
        keySoundEnabledBox.Foreground = Brushes.White;
        keySoundEnabledBox.IsCheckedChanged += (_, _) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundEnabledBox.IsChecked == true,
                keySoundSettings.Volume,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundEnabledBox, "KeySound.Enabled");

        keySoundPresetBox.ItemsSource = new KeySoundPresetChoice[]
        {
            new("Snare", KeySoundPreset.Snare),
            new("Tambourine", KeySoundPreset.BrightTick),
            new("Hand Drum", KeySoundPreset.HandDrum),
            new("Clap", KeySoundPreset.HandDrum2),
            new("Kick", KeySoundPreset.DeepPulse),
            new("自定义", KeySoundPreset.Custom)
        };
        keySoundPresetBox.SelectionChanged += (_, _) =>
        {
            if (suppressKeySoundControls ||
                keySoundPresetBox.SelectedItem is not KeySoundPresetChoice choice) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                choice.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundPresetBox, "KeySound.Preset");

        keySoundCustomFileButton.Content = "选择文件";
        keySoundCustomFileButton.Click += async (_, _) => await SelectKeySoundFileAsync();
        ApplyPrimaryButtonStyle(keySoundCustomFileButton);
        AutomationProperties.SetAutomationId(keySoundCustomFileButton, "KeySound.CustomFile");

        var presetRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions(
                $"*,{WindowsInspectorParityPolicy.SettingsKeySoundActionWidth}"),
            ColumnSpacing = 6,
            Children = { keySoundPresetBox, keySoundCustomFileButton }
        };
        Grid.SetColumn(keySoundCustomFileButton, 1);

        keySoundCustomFileText.Text = "未选择自定义音频";
        keySoundCustomFileText.Foreground = MutedBrush;
        keySoundCustomFileText.FontSize = 10;
        keySoundCustomFileText.TextTrimming = TextTrimming.CharacterEllipsis;
        AutomationProperties.SetAutomationId(keySoundCustomFileText, "KeySound.CustomFilePath");

        keySoundVolumeSlider.Minimum = 0;
        keySoundVolumeSlider.Maximum = 100;
        keySoundVolumeSlider.Value = WindowsKeySoundSettings.DefaultVolume * 100;
        ConstrainInspectorSlider(keySoundVolumeSlider);
        keySoundVolumeSlider.ValueChanged += (_, eventArgs) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                eventArgs.NewValue / 100d,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundVolumeSlider, "KeySound.Volume");
        keySoundVolumeText.Foreground = MutedBrush;

        var volumeRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("Auto,*,42"),
            ColumnSpacing = 8,
            Children =
            {
                new TextBlock
                {
                    Text = "Key 音音量",
                    Foreground = MutedBrush,
                    VerticalAlignment = VerticalAlignment.Center
                },
                keySoundVolumeSlider,
                keySoundVolumeText
            }
        };
        Grid.SetColumn(keySoundVolumeSlider, 1);
        Grid.SetColumn(keySoundVolumeText, 2);
        keySoundVolumeText.VerticalAlignment = VerticalAlignment.Center;

        keySoundLongNoteEndBox.Content = "LN 尾部也播放 Key 音";
        keySoundLongNoteEndBox.Foreground = Brushes.White;
        keySoundLongNoteEndBox.IsCheckedChanged += (_, _) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundLongNoteEndBox.IsChecked == true,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundLongNoteEndBox, "KeySound.LongNoteEnd");

        ConfigureKeySoundOffsetSlider(keySoundGlobalOffsetSlider, "KeySound.GlobalOffset");
        keySoundGlobalOffsetSlider.ValueChanged += (_, eventArgs) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                (int)Math.Round(eventArgs.NewValue),
                keySoundSettings.PerChartOffsets));
        };
        keySoundGlobalOffsetText.Foreground = MutedBrush;
        keySoundGlobalOffsetText.FontSize = 10;

        ConfigureKeySoundOffsetSlider(keySoundChartOffsetSlider, "KeySound.ChartOffset");
        keySoundChartOffsetSlider.ValueChanged += (_, eventArgs) =>
        {
            if (suppressKeySoundControls || keySoundActiveTab == null) return;
            ApplyKeySoundSettings(keySoundSettings.SetChartOffset(
                keySoundActiveTab.SourcePath,
                eventArgs.NewValue));
        };
        keySoundChartOffsetText.Foreground = MutedBrush;
        keySoundChartOffsetText.FontSize = 10;
        keySoundChartOffsetText.TextWrapping = TextWrapping.Wrap;

        keySoundRuntimeStatusText.Foreground = MutedBrush;
        keySoundRuntimeStatusText.FontSize = 10;
        keySoundRuntimeStatusText.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(keySoundRuntimeStatusText, "KeySound.RuntimeStatus");

        var keySoundHeader = new TextBlock
        {
            Text = "Key 音",
            Foreground = Brushes.White,
            FontSize = WindowsInspectorParityPolicy.SettingsSectionTitleFontSize,
            FontWeight = FontWeight.SemiBold,
            Margin = new Thickness(0, 14, 0, 2)
        };
        // Border is purely visual in Avalonia and does not create a Windows UIA
        // peer. Put the panel anchor on its visible heading so GUI acceptance can
        // locate and scroll the real panel without inventing a hidden test control.
        AutomationProperties.SetAutomationId(keySoundHeader, "KeySound.Panel");

        keySoundPanel.Background = Brushes.Transparent;
        keySoundPanel.BorderThickness = new Thickness(0);
        keySoundPanel.Padding = new Thickness(0);
        keySoundPanel.Margin = new Thickness(0);
        keySoundPanel.Child = new StackPanel
        {
            Spacing = 6,
            Children =
            {
                keySoundHeader,
                keySoundEnabledBox,
                new TextBlock
                {
                    Text = "Note 自带 sound 时优先播放真实采音；否则使用下面的全局音色。",
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap
                },
                presetRow,
                keySoundCustomFileText,
                volumeRow,
                keySoundLongNoteEndBox,
                TimingField("Key 音全局同步补偿", keySoundGlobalOffsetSlider),
                keySoundGlobalOffsetText,
                TimingField("当前谱面额外补偿", keySoundChartOffsetSlider),
                keySoundChartOffsetText,
                new TextBlock
                {
                    Text = "负数让 Key 音提前，正数让 Key 音延后；当前谱面的值会单独记忆。",
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 2, 0, 8)
                },
                new TextBlock
                {
                    Text = AvaloniaLocalizationCatalog.Format("程序会实时读取当前音频输出队列并自动补偿；上面两项只用于特殊驱动或素材的微调。"),
                    Foreground = new SolidColorBrush(Color.Parse("#789DA0")),
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 0, 0, 8)
                },
                keySoundRuntimeStatusText
            }
        };
        return keySoundPanel;
    }

    private static void ConfigureKeySoundOffsetSlider(Slider slider, string automationId)
    {
        slider.Minimum = WindowsKeySoundSettings.MinimumOffsetMilliseconds;
        slider.Maximum = WindowsKeySoundSettings.MaximumOffsetMilliseconds;
        slider.SmallChange = 1;
        slider.LargeChange = 10;
        ConstrainInspectorSlider(slider);
        AutomationProperties.SetAutomationId(slider, automationId);
    }

    /// <summary>
    /// Opens the SV template picker. The dialog writes through the session on
    /// its own; this window only refreshes the timing list after each apply, so
    /// the dialog does not need to know about the editor around it.
    /// </summary>
    private Control BuildTimingEditor()
    {
        timingBeatBox.Text = "0:0/1";
        timingBeatBox.PlaceholderText = "1:0/1 或十进制";
        timingBpmBox.Text = "120";
        timingBpmBox.PlaceholderText = "留空表示无 BPM";
        timingDelayBox.Text = "0";
        timingValueBox.Text = "1.0";
        timingCustomFieldBox.PlaceholderText = "custom.field";
        timingEffectBox.ItemsSource =
            WindowsInspectorParityPolicy.Wpf110TimingEffectOptions;
        timingEffectBox.SelectedIndex = 0;

        ConfigureInspectorInput(timingBeatBox, "Inspector.Timing.Beat", "Timing Beat");
        ConfigureInspectorInput(timingDelayBox, "Inspector.Timing.Delay", "Timing Delay");
        ConfigureInspectorInput(timingBpmBox, "Inspector.Timing.Bpm", "Timing BPM");
        ConfigureInspectorInput(timingValueBox, "Inspector.Timing.Value", "Timing Effect Value");
        ConfigureInspectorInput(
            timingCustomFieldBox,
            "Inspector.Timing.CustomField",
            "Timing Custom Field");
        ConfigureInspectorComboBox(
            timingEffectBox,
            "Inspector.Timing.Effect",
            "Timing Effect");

        var customFieldPanel = InspectorField("自定义字段名", timingCustomFieldBox);
        customFieldPanel.Margin = new Thickness(0, 8, 0, 0);
        customFieldPanel.IsVisible = false;
        timingEffectBox.SelectionChanged += (_, _) =>
        {
            customFieldPanel.IsVisible =
                timingEffectBox.SelectedItem is WindowsTimingEffectOption
                {
                    Value: "Custom"
                };
            if (customFieldPanel.IsVisible &&
                string.IsNullOrWhiteSpace(timingCustomFieldBox.Text))
                timingCustomFieldBox.Text =
                    timingEffectMemory.Current.CustomFieldName;
            MarkTimingEditorDirty();
        };
        foreach (var textBox in new[]
                 {
                     timingBeatBox,
                     timingBpmBox,
                     timingDelayBox,
                     timingValueBox,
                     timingCustomFieldBox
                 })
            textBox.TextChanged += (_, _) => MarkTimingEditorDirty();
        timingPermissionText.Foreground = new SolidColorBrush(Color.Parse("#C28B79"));
        timingPermissionText.FontSize = 10;
        timingPermissionText.TextWrapping = TextWrapping.Wrap;
        timingPermissionText.Margin = new Thickness(0, 0, 0, 5);
        timingPermissionText.IsVisible = false;
        AutomationProperties.SetAutomationId(
            timingPermissionText,
            "Inspector.Timing.Permission");

        timingList.Height = double.NaN;
        timingList.MinHeight = 80;
        timingList.HorizontalAlignment = HorizontalAlignment.Stretch;
        timingList.VerticalAlignment = VerticalAlignment.Stretch;
        timingList.Margin = new Thickness(
            0,
            WindowsInspectorParityPolicy.TimingListTopMargin,
            0,
            0);
        timingList.Background = Brushes.Transparent;
        timingList.BorderThickness = new Thickness(0);
        timingList.SelectionMode = SelectionMode.Multiple;
        timingList.ItemTemplate = new FuncDataTemplate<TimingListItem>(
            (item, _) => item == null ? new Border() : BuildTimingListRow(item),
            supportsRecycling: false);
        ConfigureTimingListStyles();
        AutomationProperties.SetAutomationId(timingList, "Inspector.Timing.List");
        AutomationProperties.SetName(timingList, "Timing 列表");
        timingList.SelectionChanged += TimingList_SelectionChanged;
        timingList.AddHandler(
            InputElement.PointerPressedEvent,
            TimingList_PointerPressed,
            RoutingStrategies.Tunnel);
        timingList.AddHandler(
            InputElement.KeyDownEvent,
            TimingList_KeyDown,
            RoutingStrategies.Tunnel);
        timingList.DoubleTapped += (_, _) => JumpToSelectedTiming();

        timingAddButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[0],
            "Inspector.Timing.Add",
            InspectorButtonTone.Primary,
            (_, _) => AddTimingFromFields());
        timingApplyButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[1],
            "Inspector.Timing.Apply",
            InspectorButtonTone.Tool,
            (_, _) => ApplyTimingFromFields());
        timingDeleteButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[2],
            "Inspector.Timing.Delete",
            InspectorButtonTone.Tool,
            (_, _) => DeleteSelectedTiming());
        timingCopyButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[3],
            "Inspector.Timing.CopyEffect",
            InspectorButtonTone.Tool,
            (_, _) => CopyTimingSelection());
        timingPasteButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[4],
            "Inspector.Timing.PasteAtRedLine",
            InspectorButtonTone.Assign,
            (_, _) => PasteTimingSelection());
        ApplyWpf110InspectorTabOrder(
            "Timing",
            [
                timingBeatBox,
                timingDelayBox,
                timingBpmBox,
                timingEffectBox,
                timingValueBox,
                timingCustomFieldBox,
                timingList,
                timingAddButton,
                timingApplyButton,
                timingDeleteButton,
                timingCopyButton,
                timingPasteButton
            ],
            WindowsInspectorParityPolicy.ResolveTimingTabIndex);

        var header = new StackPanel
        {
            Children =
            {
                new TextBlock
                {
                    Text = "Timing 表",
                    Foreground = Brushes.White,
                    FontSize = WindowsInspectorParityPolicy.TimingTitleFontSize,
                    FontWeight = FontWeight.SemiBold
                },
                new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 3),
                    Children =
                    {
                        new Border
                        {
                            Background = Brushes.Transparent,
                            BorderBrush = new SolidColorBrush(Color.Parse("#485054")),
                            BorderThickness = new Thickness(1),
                            CornerRadius = new CornerRadius(3),
                            Padding = new Thickness(7, 3),
                            Child = new TextBlock
                            {
                                Text = "MALODY",
                                Foreground = new SolidColorBrush(Color.Parse("#A7B1B4")),
                                FontSize = 9
                            }
                        },
                        new TextBlock
                        {
                            Text = "Beat · Delay · BPM · Effect",
                            Foreground = MutedBrush,
                            FontSize = 11,
                            Margin = new Thickness(8, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        }
                    }
                },
                timingPermissionText
            }
        };

        var beatDelayBpm = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto"),
            ColumnDefinitions = new ColumnDefinitions("*,10,*")
        };
        var beatField = InspectorField("Beat（新增时自动取红线）", timingBeatBox);
        var delayField = InspectorField("Delay（ms）", timingDelayBox);
        var bpmField = InspectorField("BPM（可留空）", timingBpmBox);
        Grid.SetColumn(delayField, 2);
        Grid.SetRow(bpmField, 1);
        beatDelayBpm.Children.Add(beatField);
        beatDelayBpm.Children.Add(delayField);
        beatDelayBpm.Children.Add(bpmField);

        var effectAndList = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,*")
        };
        var effectFields = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,10,*")
        };
        var effectField = InspectorField("Effect", timingEffectBox);
        var valueField = InspectorField("Value", timingValueBox);
        Grid.SetColumn(valueField, 2);
        effectFields.Children.Add(effectField);
        effectFields.Children.Add(valueField);
        effectAndList.Children.Add(effectFields);
        Grid.SetRow(customFieldPanel, 1);
        effectAndList.Children.Add(customFieldPanel);
        Grid.SetRow(timingList, 2);
        effectAndList.Children.Add(timingList);

        var primaryActions = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,*,*")
        };
        Grid.SetColumn(timingApplyButton, 1);
        Grid.SetColumn(timingDeleteButton, 2);
        primaryActions.Children.Add(timingAddButton);
        primaryActions.Children.Add(timingApplyButton);
        primaryActions.Children.Add(timingDeleteButton);
        var clipboardActions = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,*"),
            Margin = new Thickness(
                0,
                WindowsInspectorParityPolicy.TimingClipboardActionsTopMargin,
                0,
                0)
        };
        Grid.SetColumn(timingPasteButton, 1);
        clipboardActions.Children.Add(timingCopyButton);
        clipboardActions.Children.Add(timingPasteButton);
        var actions = new StackPanel
        {
            Margin = new Thickness(
                0,
                WindowsInspectorParityPolicy.TimingActionsTopMargin,
                0,
                0),
            Children = { primaryActions, clipboardActions }
        };

        var root = new Grid
        {
            Margin = WindowsInspectorParityPolicy.TimingContentMargin,
            RowDefinitions = new RowDefinitions("Auto,Auto,*,Auto")
        };
        root.Children.Add(header);
        Grid.SetRow(beatDelayBpm, 1);
        root.Children.Add(beatDelayBpm);
        Grid.SetRow(effectAndList, 2);
        root.Children.Add(effectAndList);
        Grid.SetRow(actions, 3);
        root.Children.Add(actions);
        AutomationProperties.SetAutomationId(root, "Inspector.Timing.Root");
        return BuildTimingShell(root);
    }

    // Timing 父标签下的一条子标签条：Timing 表 / SV 模板。
    // 这两页是固定页，不是可增删的预设集合，所以没有 ＋ / 重命名 / 删除
    // （那是分组预设、批注预设自己的功能）。
    private int timingSubTabIndex;
    private SvTemplatePanel? svTemplatePanel;

    private Control BuildTimingShell(Control tablePane)
    {
        var svPane = new SvTemplatePanel(
            () => viewModel.ActiveTab?.Session,
            timeline.CurrentBeat,
            displayScaleSettings.FontScale,
            _ =>
            {
                RefreshTimingList((Guid?)null, force: true);
                UpdateSelectionUi();
            });
        svPane.IsVisible = false;
        AutomationProperties.SetAutomationId(svPane, "Inspector.Timing.SvPane");
        svTemplatePanel = svPane;

        var tableTab = BuildTimingSubTab("Timing 表", "Inspector.Timing.SubTab.Table");
        var svTab = BuildTimingSubTab("SV 模板（未完成）", "Inspector.Timing.SubTab.Sv");

        void Apply()
        {
            var showSv = timingSubTabIndex == 1;
            tablePane.IsVisible = !showSv;
            svPane.IsVisible = showSv;
            SetTimingSubTabSelected(tableTab, !showSv);
            SetTimingSubTabSelected(svTab, showSv);
            // 切到 SV 面板时把起拍跟到红线：刚点过谱面时通常就想在那一拍套模板。
            if (showSv) svPane.SyncStartBeat(timeline.CurrentBeat);
        }

        tableTab.Button.Click += (_, _) => { timingSubTabIndex = 0; Apply(); };
        svTab.Button.Click += (_, _) => { timingSubTabIndex = 1; Apply(); };

        var strip = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("Auto,Auto,*"),
            Background = new SolidColorBrush(Color.Parse("#1B2124"))
        };
        strip.Children.Add(tableTab.Host);
        Grid.SetColumn(svTab.Host, 1);
        strip.Children.Add(svTab.Host);

        var shell = new Grid { RowDefinitions = new RowDefinitions("Auto,*") };
        shell.Children.Add(strip);
        Grid.SetRow(tablePane, 1);
        shell.Children.Add(tablePane);
        Grid.SetRow(svPane, 1);
        shell.Children.Add(svPane);
        AutomationProperties.SetAutomationId(shell, "Inspector.Timing.Shell");

        Apply();
        return shell;
    }

    private (Border Host, Button Button) BuildTimingSubTab(string label, string automationId)
    {
        var button = new Button
        {
            Content = label,
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(0),
            CornerRadius = new CornerRadius(0),
            Padding = new Thickness(12, 5),
            MinHeight = 26,
            FontSize = 11.5,
            Focusable = false
        };
        AutomationProperties.SetAutomationId(button, automationId);
        AutomationProperties.SetName(button, label);
        var host = new Border
        {
            BorderThickness = new Thickness(0, 0, 0, 2),
            BorderBrush = Brushes.Transparent,
            Child = button
        };
        return (host, button);
    }

    private static void SetTimingSubTabSelected((Border Host, Button Button) tab, bool selected)
    {
        tab.Host.BorderBrush = selected
            ? new SolidColorBrush(Color.Parse("#7FA4A7"))
            : Brushes.Transparent;
        tab.Button.Background = selected
            ? new SolidColorBrush(Color.Parse("#22272A"))
            : Brushes.Transparent;
        tab.Button.Foreground = selected
            ? Brushes.White
            : new SolidColorBrush(Color.Parse("#929A9F"));
    }

    private enum InspectorButtonTone
    {
        Tool,
        Primary,
        Assign
    }

    private static StackPanel InspectorField(string label, Control control) => new()
    {
        Children =
        {
            new TextBlock
            {
                Text = label,
                Foreground = MutedBrush,
                FontSize = 11,
                Margin = new Thickness(0, 10, 0, 5)
            },
            control
        }
    };

    private static void ConfigureInspectorInput(
        TextBox textBox,
        string automationId,
        string automationName)
    {
        var normalBorder = new SolidColorBrush(Color.Parse("#383E43"));
        textBox.Background = new SolidColorBrush(Color.Parse("#15181A"));
        textBox.Foreground = new SolidColorBrush(Color.Parse("#E3E6E8"));
        textBox.CaretBrush = new SolidColorBrush(Color.Parse("#B9C7C8"));
        textBox.BorderBrush = normalBorder;
        textBox.BorderThickness = new Thickness(1);
        textBox.CornerRadius = new CornerRadius(3);
        textBox.Padding = new Thickness(8, 6);
        // Keep inspector fields measurable in the Android tablet content host.
        // The native TabControl is bypassed there, so styles applied to the
        // outer host do not always reach the templated input itself.
        textBox.MinHeight = 34;
        textBox.VerticalContentAlignment = VerticalAlignment.Center;
        textBox.SelectionBrush = new SolidColorBrush(Color.Parse("#526E71"));
        textBox.AcceptsReturn = false;
        textBox.MaxLines = 1;
        textBox.GotFocus += (_, _) =>
            textBox.BorderBrush = new SolidColorBrush(Color.Parse("#718F92"));
        textBox.LostFocus += (_, _) => textBox.BorderBrush = normalBorder;
        AutomationProperties.SetAutomationId(textBox, automationId);
        AutomationProperties.SetName(textBox, automationName);
    }

