    private static Button InspectorActionButton(
        string text,
        string automationId,
        InspectorButtonTone tone,
        EventHandler<RoutedEventArgs> handler)
    {
        var button = new Button
        {
            Content = text,
            Foreground = tone == InspectorButtonTone.Assign
                ? new SolidColorBrush(Color.Parse("#FFF4E3"))
                : Brushes.White,
            Background = tone switch
            {
                InspectorButtonTone.Primary => new SolidColorBrush(Color.Parse("#38676C")),
                InspectorButtonTone.Assign => new SolidColorBrush(Color.Parse("#76572F")),
                _ => new SolidColorBrush(Color.Parse("#1A1D20"))
            },
            BorderBrush = tone switch
            {
                InspectorButtonTone.Primary => new SolidColorBrush(Color.Parse("#4A777B")),
                InspectorButtonTone.Assign => new SolidColorBrush(Color.Parse("#9B7542")),
                _ => new SolidColorBrush(Color.Parse("#34393D"))
            },
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Padding = new Thickness(9, 6),
            Margin = new Thickness(3, 0),
            MinHeight = WindowsInspectorParityPolicy.TimingActionMinimumHeight,
            HorizontalAlignment = HorizontalAlignment.Stretch,
            FontWeight = tone == InspectorButtonTone.Tool
                ? FontWeight.Normal
                : FontWeight.SemiBold,
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center
        };
        if (tone == InspectorButtonTone.Primary)
            button.Classes.Add("accent");
        button.Click += handler;
        AutomationProperties.SetAutomationId(button, automationId);
        AutomationProperties.SetName(button, text);
        return button;
    }

    private void ConfigureTimingListStyles()
    {
        var itemTheme = new ControlTheme(typeof(ListBoxItem));
        itemTheme.Setters.Add(new Setter(
            TemplatedControl.TemplateProperty,
            new FuncControlTemplate<ListBoxItem>((_, _) =>
            {
                var presenter = new ContentPresenter
                {
                    HorizontalContentAlignment = HorizontalAlignment.Stretch,
                    VerticalContentAlignment = VerticalAlignment.Center
                };
                presenter.Bind(
                    ContentPresenter.ContentProperty,
                    new TemplateBinding(ContentControl.ContentProperty));
                presenter.Bind(
                    ContentPresenter.ContentTemplateProperty,
                    new TemplateBinding(ContentControl.ContentTemplateProperty));
                presenter.Bind(
                    ContentPresenter.PaddingProperty,
                    new TemplateBinding(ContentControl.PaddingProperty));
                var border = new Border { Child = presenter };
                border.Bind(
                    Border.BackgroundProperty,
                    new TemplateBinding(TemplatedControl.BackgroundProperty));
                border.Bind(
                    Border.BorderBrushProperty,
                    new TemplateBinding(TemplatedControl.BorderBrushProperty));
                border.Bind(
                    Border.BorderThicknessProperty,
                    new TemplateBinding(TemplatedControl.BorderThicknessProperty));
                border.Bind(
                    Border.CornerRadiusProperty,
                    new TemplateBinding(TemplatedControl.CornerRadiusProperty));
                return border;
            })));
        timingList.ItemContainerTheme = itemTheme;

        var baseStyle = new Style(selector => selector.OfType<ListBoxItem>());
        baseStyle.Setters.Add(new Setter(TemplatedControl.BackgroundProperty, Brushes.Transparent));
        baseStyle.Setters.Add(new Setter(
            TemplatedControl.BorderBrushProperty,
            new SolidColorBrush(Color.Parse("#34393D"))));
        baseStyle.Setters.Add(new Setter(TemplatedControl.BorderThicknessProperty, new Thickness(1)));
        baseStyle.Setters.Add(new Setter(TemplatedControl.CornerRadiusProperty, new CornerRadius(3)));
        baseStyle.Setters.Add(new Setter(ContentControl.PaddingProperty, new Thickness(10, 8)));
        baseStyle.Setters.Add(new Setter(Layoutable.MarginProperty, new Thickness(0, 0, 0, 6)));
        baseStyle.Setters.Add(new Setter(
            ContentControl.HorizontalContentAlignmentProperty,
            HorizontalAlignment.Stretch));
        timingList.Styles.Add(baseStyle);

        var hoverStyle = new Style(selector =>
            selector.OfType<ListBoxItem>().Class(":pointerover"));
        hoverStyle.Setters.Add(new Setter(
            TemplatedControl.BackgroundProperty,
            new SolidColorBrush(Color.Parse("#222629"))));
        timingList.Styles.Add(hoverStyle);

        var selectedStyle = new Style(selector =>
            selector.OfType<ListBoxItem>().Class(":selected"));
        selectedStyle.Setters.Add(new Setter(
            TemplatedControl.BackgroundProperty,
            new SolidColorBrush(Color.Parse("#293235"))));
        selectedStyle.Setters.Add(new Setter(
            TemplatedControl.BorderBrushProperty,
            new SolidColorBrush(Color.Parse("#698B8E"))));
        timingList.Styles.Add(selectedStyle);
    }

    private static Control BuildTimingListRow(TimingListItem item)
    {
        var row = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("92,*,82")
        };
        var beat = new TextBlock
        {
            Text = item.Beat,
            Foreground = new SolidColorBrush(Color.Parse("#E0E3E4")),
            FontWeight = FontWeight.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        };
        AutomationProperties.SetAutomationId(
            beat,
            $"Inspector.Timing.Row.{item.Id:D}");
        AutomationProperties.SetHelpText(
            beat,
            $"TimingId={item.Id:D}; Beat={item.Beat}");
        var main = new TextBlock
        {
            Text = item.Main,
            Foreground = new SolidColorBrush(Color.Parse("#A3AAAE")),
            TextTrimming = TextTrimming.CharacterEllipsis,
            VerticalAlignment = VerticalAlignment.Center
        };
        var effect = new TextBlock
        {
            Text = item.Effect,
            Foreground = new SolidColorBrush(Color.Parse("#D09A56")),
            HorizontalAlignment = HorizontalAlignment.Right,
            TextTrimming = TextTrimming.CharacterEllipsis,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(main, 1);
        Grid.SetColumn(effect, 2);
        row.Children.Add(beat);
        row.Children.Add(main);
        row.Children.Add(effect);
        AutomationProperties.SetName(
            row,
            $"{item.Beat} · {item.Main} · {item.Effect}");
        return row;
    }

