    /// <summary>
    /// Hosts an inspector label or value that would otherwise report its full
    /// content width. A grid star column takes that width as a floor, so one
    /// long chart title, file name or field caption used to push the row's
    /// action button outside the fixed-width inspector panel. The host reports
    /// no width of its own and lays the child out into whatever the panel
    /// finally grants it.
    /// </summary>
    private sealed class InspectorFlexibleField : Decorator
    {
        protected override Size MeasureOverride(Size availableSize)
        {
            if (Child is not { } child) return default;
            child.Measure(availableSize);
            return new Size(0, child.DesiredSize.Height);
        }

        protected override Size ArrangeOverride(Size finalSize)
        {
            Child?.Arrange(new Rect(finalSize));
            return finalSize;
        }
    }

    private async void Window_Opened(object? sender, EventArgs eventArgs)
    {
        if (initialized) return;
        initialized = true;
        if (OperatingSystem.IsWindows() &&
            editorViewSettings.FullscreenMode == WindowsFullscreenMode.Borderless &&
            WindowState != WindowState.FullScreen)
        {
            windowStateBeforeFullscreen = WindowState;
            WindowState = WindowState.FullScreen;
            ConfigureFullscreenTitleBar();
        }
        // GUI evidence normally stays account-silent so a local capture can never
        // restore or mutate the user's production session. Stateful two-client
        // collaboration evidence is allowed only against the explicitly resolved
        // HTTP loopback endpoint used by the isolated Windows harness.
        var allowEvidenceLoopbackAccountRestore = evidenceChartMode &&
                                                  onlineAccountHost?.Endpoint.IsLoopback == true &&
                                                  onlineAccountHost.Endpoint.Scheme == Uri.UriSchemeHttp;
        if ((!evidenceChartMode &&
             !evidenceFocusLibraryVirtualization &&
             !evidenceFocusLibraryLauncher) ||
            allowEvidenceLoopbackAccountRestore)
            _ = RestoreStartupOnlineAccountAsync(
                showStartupChoice: !evidenceChartMode);
        if (!evidenceFocusLibraryVirtualization && !evidenceFocusLibraryLauncher)
        {
            roomInvitationTimer.Start();
            followNotificationTimer.Start();
            ReconcileFollowNotificationSession();
        }
        var displayScaleBeforeInitialization = displayScaleSettings;
        displayScaleSettings = displayScaleController.InitializeForScreen(
            OperatingSystem.IsWindows() ? Screens?.Primary : null);
        if (!displayScaleBeforeInitialization.DisplayScaleInitialized ||
            Math.Abs(displayScaleBeforeInitialization.UiScale - displayScaleSettings.UiScale) > 1e-12 ||
            Math.Abs(displayScaleBeforeInitialization.FontScale - displayScaleSettings.FontScale) > 1e-12)
        {
            displayScaleSettingsDirty = true;
            ScheduleDisplayScaleSettingsSave();
        }
        RefreshDisplayScaleSettingsUi();
        QueueDisplayScaleMaterializedContentScan();
        localizationController.ScheduleApply();
        var deferInitialLibraryScan =
            !evidenceChartMode &&
            !evidenceFocusLibraryVirtualization &&
            !evidenceFocusLibraryLauncher &&
            string.IsNullOrWhiteSpace(evidenceOutputPath);
        var libraryInitializationStopwatch = Stopwatch.StartNew();
        await viewModel.InitializeAsync(
            restorePreviousSession: startupChartPaths.Count == 0,
            scanLibrary: !deferInitialLibraryScan);
        ShowWorkspaceRecoveryWarningsIfNeeded();
        ShowWorkspaceRootFallbackNoticeIfNeeded();
        if (!deferInitialLibraryScan) ShowLibraryScanErrorIfNeeded();
        await RestoreRetainedOnlineRoomTabsAsync();
        libraryInitializationStopwatch.Stop();
        evidenceLibraryInitializationMilliseconds =
            libraryInitializationStopwatch.Elapsed.TotalMilliseconds;
        foreach (var path in startupChartPaths)
        {
            if (evidenceChartMode &&
                !evidenceShowOsuImportDialog &&
                Path.GetExtension(path).Equals(".osu", StringComparison.OrdinalIgnoreCase))
            {
                try
                {
                    await viewModel.OpenAsync(
                        path,
                        OsuNoteTimingImportMode.CalibrateCommonSubdivisions);
                    ShowEditorSurface();
                }
                catch (Exception exception) { viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("打开谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message))); }
            }
            else
            {
                await OpenChartOrArchiveAsync(path);
            }
        }
        startupInitializationCompleted = true;
        _ = DrainSingleInstanceRequestsAsync();
        PrepareSyntheticEvidenceWorkload();
        PrepareChartValidationEvidenceWorkload();
        UpdateUi();
        FocusLibraryDeletionEvidence();
        FocusKeySoundEvidencePanel();
        FocusAudioTransportEvidencePanel();
        FocusDisplayScaleEvidencePanel();
        FocusSettingsCacheEvidencePanel();
        audioUiTimer.Start();
        ConfigureEditorFrameRateRuntime(resetCounters: true);
        ConfigureAutoBackupTimer();
        // Registered here rather than in the constructor: opening a chart needs a
        // built editor, and a file handed over by the operating system can arrive
        // during launch. Anything that arrived before this point was queued and
        // is replayed now. See PlatformIncomingFiles.
        PlatformIncomingFiles.SetHandler(OpenChartOrArchiveAsync);
#if LUMACHART_SHARED
        AttachMobileLifecycle();
#endif
        if (deferInitialLibraryScan)
            Dispatcher.UIThread.Post(
                StartDeferredLibraryScan,
                DispatcherPriority.Background);
        if (!string.IsNullOrWhiteSpace(evidenceOutputPath))
        {
            if (evidenceFocusLibraryVirtualization)
                Dispatcher.UIThread.Post(
                    StartLibraryVirtualizationEvidenceProbe,
                    DispatcherPriority.Background);
            else
                Dispatcher.UIThread.Post(StartEvidenceProbe, DispatcherPriority.Background);
        }
    }

    private void ShowWorkspaceRecoveryWarningsIfNeeded()
    {
        var request = WindowsWorkspaceRecoveryNoticePolicy.Create(
            viewModel.RecoveryWarnings);
        if (request != null)
            WindowsNativeMessageBox.Show(this, request);
    }

    /// <summary>
    /// The saved library root was unreachable at startup (unplugged drive,
    /// offline NAS) and this session runs on a fallback root. Say so once:
    /// otherwise the library silently looks empty or different. The saved
    /// setting is untouched, so the next launch returns to it by itself.
    /// </summary>
    private void ShowWorkspaceRootFallbackNoticeIfNeeded()
    {
        if (viewModel.WorkspaceRootFallback is not { } fallback) return;
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("原谱库目录暂时不可用，本次改用：{0}", fallback.FallbackRoot));
        WindowsNativeMessageBox.Show(
            this,
            new WindowsNativeMessageBoxRequest(
                AvaloniaLocalizationCatalog.Format("原谱库目录暂时无法访问：\n{0}\n\n原因：{1}\n\n本次改用：\n{2}\n\n设置没有被修改；原目录恢复可用后，下次启动会自动回到原目录。", fallback.RequestedRoot, fallback.Reason, fallback.FallbackRoot),
                "谱库目录暂时不可用",
                WindowsNativeMessageBoxIcon.Warning));
    }

    private void StartDeferredLibraryScan()
    {
        if (windowClosePreflightInProgress ||
            windowClosePreflightComplete ||
            !startupLibraryScanTask.IsCompleted)
            return;
        startupLibraryScanTask = RunDeferredLibraryScanAsync();
    }

    private async Task RunDeferredLibraryScanAsync()
    {
        try
        {
            await viewModel.RefreshLibraryAsync();
            if (!windowClosePreflightInProgress &&
                !windowClosePreflightComplete)
                ShowLibraryScanErrorIfNeeded();
        }
        catch (Exception exception)
        {
            if (!windowClosePreflightComplete)
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("曲库扫描失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

