    private async Task SelectKeySoundFileAsync()
    {
        // The chosen path is written into the persisted Key-sound settings and
        // reopened in later sessions, so a staged copy has to be durable.
        var path = await PickLocalFileAsync(
            new FilePickerOpenOptions
            {
                Title = "选择自定义 Key 音",
                AllowMultiple = false,
                FileTypeFilter =
                [
                    new FilePickerFileType("音频文件")
                        { Patterns = ["*.wav", "*.ogg", "*.mp3"], MimeTypes = ["audio/*"] }
                ]
            },
            PickedFileRetention.Durable);
        if (string.IsNullOrWhiteSpace(path)) return;
        try
        {
            path = Path.GetFullPath(path);
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                KeySoundPreset.Custom,
                path,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        }
        catch (Exception exception)
        {
            keySoundRuntimeStatusText.Text = AvaloniaLocalizationCatalog.Format("选择 Key 音失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            keySoundRuntimeStatusText.Foreground = Brushes.IndianRed;
        }
    }

    private static string FormatSignedMilliseconds(double value) =>
        value > .5 ? $"+{value:0} ms" : $"{value:0} ms";

    private void Timeline_CurrentBeatChanged(object? sender, double beat)
    {
        if (settingProgrammaticPlaybackBeat) return;
        UpdatePlaybackPositionUi(beat);
        UpdateInspector();

        var tab = viewModel.ActiveTab;
        if (tab == null || !IsCurrentKeySoundTab(tab)) return;
        var milliseconds = Math.Max(
            0,
            GetAudioTimingMap(tab).BeatToMilliseconds(BeatPosition.FromDouble(beat)));
        QueueEditorSeek(
            tab,
            milliseconds,
            resumeAfterSeek: DateTimeOffset.UtcNow > editorSeekResumeSuppressedUntilUtc);
    }

    private void Timeline_ManualNavigationRequested(
        object? sender,
        TimelineManualNavigationEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        editorSeekResumeSuppressedUntilUtc = DateTimeOffset.UtcNow.AddMilliseconds(650);
        if (editorSeekPending)
        {
            editorSeekResumeRequested = false;
            EnsurePendingEditorSeekTransportPaused();
            UpdateQuickPlayPresentation();
        }

        var version = ++editorManualNavigationPauseVersion;
        Dispatcher.UIThread.Post(() =>
        {
            if (version != editorManualNavigationPauseVersion) return;
            if (!editorManualNavigationPauseTask.IsCompleted) return;
            editorManualNavigationPauseTask = PauseEditorPlaybackForManualNavigationAsync();
        }, DispatcherPriority.Input);
    }

    private async Task PauseEditorPlaybackForManualNavigationAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || !IsCurrentKeySoundTab(tab)) return;
        if (editorSeekPending && ReferenceEquals(editorSeekTab, tab))
        {
            editorSeekResumeRequested = false;
            EnsurePendingEditorSeekTransportPaused();
            UpdateQuickPlayPresentation();
            return;
        }

        var snapshot = audioTransport.PlaybackSnapshot;
        if (audioTransport.ActiveTabId == tab.Id && snapshot?.IsPlaying == true)
        {
            keySoundRuntime.InvalidatePlayback();
            await audioTransport.TogglePlayPauseAsync();
        }
        else if (keySoundRuntime.Snapshot.IsSilentPlaying)
        {
            keySoundRuntime.PauseSilent();
        }
    }

    private void UpdatePlaybackPositionUi(double beat)
    {
        viewModel.UpdateCurrentBeat(beat);
        editorOverview.SetCurrentBeat(beat);
        difficultyOverview.SetCurrentBeat(beat);
        UpdateAudioPanelViewports();
    }

