    private void Timeline_TimingSelectionChanged(object? sender, EventArgs eventArgs)
    {
        if (!suppressTimingSelection)
        {
            var ids = timeline.SelectedTimingIds.ToHashSet();
            SyncTimingListSelection(ids, timeline.PrimarySelectedTimingId);
            if (timeline.PrimarySelectedTimingId.HasValue &&
                timingList.Items.OfType<TimingListItem>().FirstOrDefault(item =>
                    item.Id == timeline.PrimarySelectedTimingId.Value) is { } primary)
                timingList.ScrollIntoView(primary);
        }
        UpdateSelectionUi();
