    private void Timeline_TimingDeleteRequested(
        object? sender,
        TimingDeleteRequestedEventArgs eventArgs) =>
        DeleteTimingBatch(eventArgs.TimingIds);

    private void TimingList_PointerPressed(object? sender, PointerPressedEventArgs eventArgs)
    {
        CaptureTimingListSelectionModifiers(eventArgs.KeyModifiers);
        if (!eventArgs.GetCurrentPoint(timingList).Properties.IsRightButtonPressed) return;

        var current = eventArgs.Source as Control;
        while (current != null && current != timingList && current is not ListBoxItem)
            current = current.Parent as Control;
        if (current is not ListBoxItem item) return;
        if (!item.IsSelected)
        {
            timingList.SelectedItems?.Clear();
            item.IsSelected = true;
        }
        DeleteSelectedTiming();
        eventArgs.Handled = true;
    }

    private void TimingList_KeyDown(object? sender, KeyEventArgs eventArgs)
    {
        CaptureTimingListSelectionModifiers(eventArgs.KeyModifiers);
        var command = WindowsInspectorParityPolicy.ResolveTimingListShortcut(
            eventArgs.Key,
            eventArgs.PhysicalKey,
            eventArgs.KeySymbol,
            eventArgs.KeyModifiers,
            eventArgs.Key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed
                ? WindowsShortcutPhysicalKeyState.TryResolvePressedKey()
                : null);
        switch (command)
        {
            case WindowsTimingListShortcutCommand.Delete:
                DeleteSelectedTiming();
                eventArgs.Handled = true;
                break;
            case WindowsTimingListShortcutCommand.CopyEffect:
                CopyTimingSelection();
                eventArgs.Handled = true;
                break;
            case WindowsTimingListShortcutCommand.PasteEffect:
                PasteTimingSelection();
                eventArgs.Handled = true;
                break;
        }
    }

    private void CaptureTimingListSelectionModifiers(KeyModifiers modifiers)
    {
        timingListSelectionModifiers = modifiers;
        var version = ++timingListInputVersion;
        Dispatcher.UIThread.Post(() =>
        {
            if (version == timingListInputVersion)
                timingListSelectionModifiers = KeyModifiers.None;
        });
    }

    private void TimingList_SelectionChanged(object? sender, SelectionChangedEventArgs eventArgs)
    {
        if (suppressTimingSelection) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (!WindowsAvaloniaEditorInputPolicy.PreserveNotesForTimingListSelection(
                timingListSelectionModifiers))
            tab.Session.Selection.Clear();

        var ids = SelectedTimingListIds();
        var primary = timingList.SelectedItem as TimingListItem;
        var previous = suppressTimingSelection;
        suppressTimingSelection = true;
        try
        {
            timeline.SetSelectedTimings(ids, primary?.Id);
        }
        finally
        {
            suppressTimingSelection = previous;
        }
        if (primary != null) PopulateTimingFields(primary.Id);
        UpdateSelectionUi();
    }

    private void UpdateUi()
    {
        if (!WindowsInspectorParityPolicy.AllowWindowUiMutation(
                windowCloseTeardownStarted,
                windowClosePreflightComplete))
            return;
        var activeTabId = viewModel.ActiveTab?.Id;
        if (audioAnalysisCancellation != null && audioAnalysisTabId != activeTabId)
            audioAnalysisCancellation.Cancel();
        if (imageImportCancellation != null && imageImportTabId != activeTabId)
            imageImportCancellation.Cancel();
        if (titleRomanizationCancellation != null && titleRomanizationTabId != activeTabId)
            titleRomanizationCancellation.Cancel();
        if (artistRomanizationCancellation != null && artistRomanizationTabId != activeTabId)
            artistRomanizationCancellation.Cancel();
        workspaceText.Text = AvaloniaLocalizationCatalog.Format("工作目录  {0}", viewModel.WorkspaceRoot);
        AutomationProperties.SetName(workspaceText, workspaceText.Text);
        statusText.Text = viewModel.Status;
        libraryStatusText.Text = viewModel.Status;
        var activeTitleTab = viewModel.ActiveTab;
        if (activeTitleTab == null) libraryVisible = true;
        if (evidenceFocusLibraryDeletion || evidenceFocusLibraryVirtualization)
            libraryVisible = true;
        var surface = WindowsLibrarySurfacePolicy.Resolve(
            libraryVisible,
            activeTitleTab != null,
            activeTitleTab?.Session.Document.Metadata.Title,
            activeTitleTab?.Session.IsDirty == true);
        libraryVisible = surface.LibraryVisible;
        titleSaveStateText.IsVisible = surface.SaveStateVisible;
        titleSaveStateText.Text = activeTitleTab?.Session.IsDirty == true
            ? "· 未保存"
            : "· 已保存";
        titleSaveStateText.Foreground = activeTitleTab?.Session.IsDirty == true
            ? new SolidColorBrush(Color.Parse("#D6A35C"))
            : new SolidColorBrush(Color.Parse("#7FAE93"));
        // Translated here rather than left to the localization pass: this runs on
        // every UI refresh, so an asynchronous pass would keep racing it and the
        // title bar would flip back to the source language.
        Title = localizationController.Translate(surface.WindowTitle);
#if LUMACHART_SHARED
        RefreshTabletLibraryCards();
#else
        libraryList.ItemsSource = viewModel.LibraryFolders;
#endif
        var libraryContent = WindowsLibraryContentPolicy.Resolve(
            viewModel.LibraryEntries.Count,
            viewModel.LibraryFolders.Count,
            viewModel.LibrarySearchQuery,
            viewModel.IsScanning);
#if LUMACHART_SHARED
        tabletLibraryScroll.IsVisible = libraryContent.ShowLibraryList;
#else
        libraryList.IsVisible = libraryContent.ShowLibraryList;
#endif
        emptyLibraryPanel.IsVisible = libraryContent.ShowEmptyPanel;
        emptyLibraryActions.IsVisible = libraryContent.ShowLauncherActions;
        emptyLibraryTitleText.Text = libraryContent.EmptyTitle;
        emptyLibrarySubtitleText.Text = libraryContent.EmptySubtitle;
        libraryTitle.Text = "曲库";
        libraryCountText.Text = viewModel.IsScanning
            ? "扫描中"
            : AvaloniaLocalizationCatalog.Format("{0:N0} 个文件夹  ·  {1:N0} 张谱面", viewModel.LibraryFolders.Count, viewModel.LibraryFolders.Sum(folder => folder.VisibleCharts.Count));
        UpdateLibrarySelectionUi();
        RebuildTabs();
        if (viewModel.ActiveTab != null)
        {
            editorView.IsVisible = surface.EditorVisible;
            libraryView.IsVisible = surface.LibraryVisible;
            audioTransport.Activate(viewModel.ActiveTab);
            var audioPath = WindowsAudioTransportViewModel.ResolveDocumentAudioPath(viewModel.ActiveTab);
            RequestMissingAudioRecovery(viewModel.ActiveTab, audioPath);
            audioVisualization.Activate(
                viewModel.ActiveTab.Id,
                audioPath,
                viewModel.ActiveTab.Session.Document.Metadata.AudioFile);
            var activeTab = viewModel.ActiveTab;
            WindowsGroupManagerCommand.RemoveHiddenSelection(activeTab);
            EnsureGroupCatalogLoaded(activeTab);
            // Deliberately no "invalidate the group panel" line here. This runs
            // on every state change, and a status line is a state change: the
            // forced rebuild it used to trigger tore down the group rows and the
            // drawer tabs on the way to a refresh that had nothing new to show.
            // Anything that really changes the panel — a chart switch, a new
            // group, a drawer opening — is already named in the panel signature
            // that RefreshGroupPanel compares, so the rebuild arrives on its own.
            timeline.Session = activeTab.Session;
            editorOverview.Session = activeTab.Session;
            editorOverview.SetIssues(timeline.ChartIssues);
            editorOverview.SetNavigationMarkers(activeTab.NavigationMarkers);
            editorOverview.SetCurrentBeat(activeTab.CurrentBeat);
            RefreshNavigationMarkerUi();
            miniNoteCountText.Text = activeTab.Session.Document.Notes.Count.ToString(
                "N0",
                CultureInfo.InvariantCulture);
            persistedProGridColumns = Math.Max(
                persistedProGridColumns,
                activeTab.Session.Document.KeyCount);
            timeline.SetProGridColumnCount(persistedProGridColumns);
            timeline.PlacementGroup = activeTab.ActivePlacementGroup;
            if (quickGroupLabel != null)
                quickGroupLabel.Text = AvaloniaLocalizationCatalog.Format("分组 {0}", activeTab.ActivePlacementGroup);
            timeline.SetHiddenGroups(activeTab.HiddenGroups);
            RefreshTimelineOnlineCreators();
            SetProgrammaticPlaybackBeat(activeTab.CurrentBeat);
            activeTab.Session.SnapDivision = editorViewSettings.SnapDivision;
            divisionPicker.SelectedItem = activeTab.Session.SnapDivision;
            SyncSettingsSnapBox(activeTab.Session.SnapDivision);
            RefreshQuickValuesPaletteValues();
            _ = GetAudioTimingMap(activeTab);
            EnsureKeySoundActiveTab(activeTab, audioPath);
            RefreshTimingList();
        }
        else
        {
            editorView.IsVisible = false;
            libraryView.IsVisible = true;
            audioTransport.Activate(null);
            CancelMissingAudioRecovery();
            audioVisualization.Activate(null, null);
            timeline.Session = null;
            editorOverview.Session = null;
            editorOverview.SetIssues([]);
            editorOverview.SetNavigationMarkers([]);
            editorOverview.SetExternalEndBeat(0);
            RefreshNavigationMarkerUi();
            miniNoteCountText.Text = "0";
            timeline.PlacementGroup = 0;
            if (quickGroupLabel != null) quickGroupLabel.Text = "分组 0";
            timeline.SetHiddenGroups([]);
            RefreshTimelineOnlineCreators();
            timingList.ItemsSource = Array.Empty<TimingListItem>();
            timingListTabId = null;
            timingListChangeSerial = -1;
            SyncTimingListSelection([]);
            audioTimingMapCache.Clear();
            EnsureKeySoundActiveTab(null, null);
        }
        // The library-deletion evidence run intentionally keeps a real survivor
        // tab open while exercising a different folder. Session-selection
        // changes during the render probe can raise another workspace update;
        // keep the explicitly requested library view visible across those events.
        // WPF keeps command, permission and save feedback visible while the
        // editor is active. The WPF library uses its own footer row, so keeping
        // the shared editor footer visible there added a duplicate 30-DIP strip.
        statusBar.IsVisible = surface.EditorStatusVisible;
        RefreshDifficultyUi();
        UpdateInspector();
        UpdateChartBackground(viewModel.ActiveTab);
        UpdateEditorAvailability();
        UpdateAudioUi();
        UpdateAudioVisualizationUi();
        RefreshProEditorControls();
        RefreshSubdivisionCheckControls();
        RefreshRoomCollaborationPanelVisibility();
        QueueDisplayScaleMaterializedContentScan();
        QueueFactoryFloatingLayout();
    }

    private void RequestMissingAudioRecovery(DesktopChartTab tab, string? resolvedAudioPath)
    {
        var reference = tab.Session.Document.Metadata.AudioFile;
        if (!string.IsNullOrWhiteSpace(resolvedAudioPath) || string.IsNullOrWhiteSpace(reference))
        {
            CancelMissingAudioRecovery();
            return;
        }

        var key = string.Concat(
            tab.Id.ToString("N"),
            "\0",
            tab.WorkingPath,
            "\0",
            tab.SourcePath,
            "\0",
            reference);
        if (string.Equals(missingAudioRecoveryKey, key, StringComparison.Ordinal)) return;

        missingAudioRecoveryCancellation?.Cancel();
        var cancellation = new CancellationTokenSource();
        missingAudioRecoveryCancellation = cancellation;
        missingAudioRecoveryKey = key;
        activeMissingAudioRecoveryTask = RecoverMissingAudioAsync(
            tab,
            reference,
            key,
            cancellation);
    }

    private async Task RecoverMissingAudioAsync(
        DesktopChartTab tab,
        string reference,
        string recoveryKey,
        CancellationTokenSource cancellation)
    {
        try
        {
            var roots = AvaloniaAppPaths.EnumerateCompatibilityWorkspaceRoots();
            var candidate = await Task.Run(
                () => ChartAssetImportService.FindRelatedAsset(
                    tab.WorkingPath,
                    tab.SourcePath,
                    reference,
                    roots,
                    cancellation.Token),
                cancellation.Token);
            if (candidate == null) return;

            var imported = await Task.Run(
                () => ChartAssetImportService.ImportAudio(
                    tab.WorkingPath,
                    candidate,
                    tab.SourcePath,
                    preferredFileName: reference),
                cancellation.Token);
            cancellation.Token.ThrowIfCancellationRequested();
            if (viewModel.ActiveTab?.Id != tab.Id ||
                !string.Equals(missingAudioRecoveryKey, recoveryKey, StringComparison.Ordinal))
                return;

            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已从曲库自动恢复音频：{0}", imported.FileName));
            UpdateUi();
        }
        catch (OperationCanceledException)
        {
        }
        catch (Exception exception) when (
            exception is ArgumentException or IOException or NotSupportedException or UnauthorizedAccessException)
        {
            if (viewModel.ActiveTab?.Id == tab.Id &&
                string.Equals(missingAudioRecoveryKey, recoveryKey, StringComparison.Ordinal))
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("自动恢复音频失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            if (ReferenceEquals(missingAudioRecoveryCancellation, cancellation))
                missingAudioRecoveryCancellation = null;
            cancellation.Dispose();
        }
    }

    private void CancelMissingAudioRecovery()
    {
        missingAudioRecoveryCancellation?.Cancel();
        missingAudioRecoveryKey = null;
    }

    private void UpdateInspector()
    {
        var tab = viewModel.ActiveTab;
        RefreshMetadataEditor(tab);
        UpdateNoteInspector(tab);
        RefreshGroupPanel();
        RefreshAnnotationPanel();
        if (tab == null)
        {
            inspectorText.Text = "没有打开的谱面";
            return;
        }
        var document = tab.Session.Document;
        var selected = document.Notes.Where(note =>
            tab.Session.Selection.Contains(note.Id) &&
            !tab.HiddenGroups.Contains(note.Group)).ToArray();
        var selectedTimingCount = timeline.SelectedTimingIds.Count(id =>
            document.Timing.Any(timing => timing.Id == id));
        var selectedText = selected.Length == 0
            ? "未选择 Note"
            : string.Join("\n", selected.Take(4).Select(note =>
                (note.IsDraft
                    ? $"Draft D:{note.DraftColumn} · {note.Beat}"
                    : $"Lane {note.Lane + 1} · {note.Beat}") +
                (note.EndBeat.HasValue ? $" → {note.EndBeat}" : string.Empty)));
        inspectorText.Text =
            AvaloniaLocalizationCatalog.Format("{0}\n{1} · {2}K\nNote {3:N0} · LN {4:N0}\nTiming {5:N0}\n红线 {6:F3}\n分度 {7}\n选择 {8:N0} Note · {9:N0} Timing\n权限：只读 {10} · Note {11} · Timing {12} · 元数据 {13}\n房主锁：{14:N0} Note · {15:N0} 连续区域\n未保存：{16}\n\n{17}", tab.DisplayTitle, tab.FormatBadge, document.KeyCount, document.Notes.Count, document.Notes.Count(note => note.IsHold), document.Timing.Count, timeline.CurrentBeat, TimelineSubdivisionCheckPalette.FormatDivisionLabel(tab.Session.SnapDivision), selected.Length, selectedTimingCount, (tab.Session.IsReadOnly ? AvaloniaLocalizationCatalog.Text("是") : AvaloniaLocalizationCatalog.Text("否")), (tab.Session.CanEditNotes ? AvaloniaLocalizationCatalog.Text("可编辑") : AvaloniaLocalizationCatalog.Text("禁用")), (tab.Session.CanEditTiming ? AvaloniaLocalizationCatalog.Text("可编辑") : AvaloniaLocalizationCatalog.Text("禁用")), (tab.Session.CanEditMetadata ? AvaloniaLocalizationCatalog.Text("可编辑") : AvaloniaLocalizationCatalog.Text("禁用")), tab.Session.OwnerProtectedNotes.Count, tab.Session.OwnerProtectedRegions.Count, (tab.Session.IsDirty ? AvaloniaLocalizationCatalog.Text("是") : AvaloniaLocalizationCatalog.Text("否")), selectedText);
    }

    private void MetadataEditorControlChanged(object? sender, EventArgs eventArgs)
    {
        if (!suppressMetadataEditorControls) metadataEditorDirty = true;
    }

    private async void MetadataKeyCountSelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        if (suppressMetadataEditorControls ||
            metadataKeyCountChangeInProgress ||
            metadataKeyCountBox.SelectedItem is not WindowsMetadataKeyCountOption option ||
            viewModel.ActiveTab is not { } tab ||
            option.Value == tab.Session.Document.KeyCount)
            return;

        metadataEditorDirty = true;
        metadataKeyCountChangeInProgress = true;
        try
        {
            // The count shown in the confirmation is a snapshot; room sync can
            // add Notes on the removed lanes while the dialog is open. Recount
            // after each confirmation and ask again if more would be deleted
            // than the user agreed to.
            var confirmedRemoved = 0;
            while (true)
            {
                var removed = tab.Session.Document.Notes.Count(
                    note => !note.IsDraft && note.Lane >= option.Value);
                if (removed <= confirmedRemoved) break;
                var confirmed = await ShowSettingsConfirmationAsync(
                    "更改轨道数",
                    AvaloniaLocalizationCatalog.Format("切换为 {0}K 会删除最右侧的 {1} 个 Note，继续吗？", option.Value, removed),
                    "继续",
                    dangerous: true);
                if (!confirmed ||
                    viewModel.ActiveTab?.Id != tab.Id)
                {
                    RestoreMetadataKeyCountSelection(tab);
                    return;
                }
                confirmedRemoved = removed;
            }

            if (!ApplyMetadataEditor())
                RestoreMetadataKeyCountSelection(tab);
        }
        catch (Exception exception)
        {
            // async void handler: keep the editor alive and the old key count.
            Debug.WriteLine($"Changing the key count failed: {exception}");
            if (!windowCloseTeardownStarted)
            {
                RestoreMetadataKeyCountSelection(tab);
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
        }
        finally
        {
            metadataKeyCountChangeInProgress = false;
        }
    }

    private void RestoreMetadataKeyCountSelection(DesktopChartTab tab)
    {
        var previous = suppressMetadataEditorControls;
        suppressMetadataEditorControls = true;
        try
        {
            metadataKeyCountBox.SelectedItem =
                WindowsInspectorParityPolicy.Wpf110MetadataKeyCountOptions
                    .FirstOrDefault(option =>
                        option.Value == tab.Session.Document.KeyCount);
        }
        finally
        {
            suppressMetadataEditorControls = previous;
        }
        metadataEditorDirty = !ChartMetadataEditingService.DraftEquals(
            CaptureMetadataEditorDraft(tab),
            ChartMetadataEditingService.Capture(tab.Session.Document));
    }

    private Task RomanizeMetadataAsync(bool title)
    {
        if (title ? titleRomanizationInProgress : artistRomanizationInProgress)
            return title ? activeTitleRomanizationTask : activeArtistRomanizationTask;
        var operation = RomanizeMetadataCoreAsync(title);
        if (title) activeTitleRomanizationTask = operation;
        else activeArtistRomanizationTask = operation;
        return operation;
    }

    private async Task RomanizeMetadataCoreAsync(bool title)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            metadataStatusText.Text = tab.Session.IsReadOnly
                ? "观察者不能修改谱面信息。"
                : "转罗马音需要谱面信息权限。";
            metadataStatusText.Foreground = Brushes.OrangeRed;
            return;
        }
        var source = title ? metadataTitleOriginalBox : metadataArtistOriginalBox;
        var destination = title ? metadataTitleBox : metadataArtistBox;
        var button = title ? metadataRomanizeTitleButton : metadataRomanizeArtistButton;
        var sourceSnapshot = source.Text ?? string.Empty;
        var cancellation = new CancellationTokenSource();
        if (title)
        {
            titleRomanizationCancellation?.Cancel();
            titleRomanizationCancellation?.Dispose();
            titleRomanizationCancellation = cancellation;
            titleRomanizationTabId = tab.Id;
            titleRomanizationInProgress = true;
        }
        else
        {
            artistRomanizationCancellation?.Cancel();
            artistRomanizationCancellation?.Dispose();
            artistRomanizationCancellation = cancellation;
            artistRomanizationTabId = tab.Id;
            artistRomanizationInProgress = true;
        }

        button.Content = "分析读音…";
        UpdateEditorAvailability();
        try
        {
            var romanized = await WindowsJapaneseRomanizer.RomanizeAsync(
                sourceSnapshot,
                cancellation.Token);
            cancellation.Token.ThrowIfCancellationRequested();
            if (viewModel.ActiveTab?.Id != tab.Id ||
                !string.Equals(source.Text ?? string.Empty, sourceSnapshot, StringComparison.Ordinal))
                throw new OperationCanceledException("读音分析期间谱面或原文已变化。", cancellation.Token);

            destination.Text = romanized;
            metadataEditorDirty = true;
            metadataStatusText.Text = string.IsNullOrWhiteSpace(romanized)
                ? "原文为空，已清空对应的 ASCII 栏。"
                : AvaloniaLocalizationCatalog.Format("已生成罗马音：{0}", romanized);
            metadataStatusText.Foreground = MutedBrush;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        catch (OperationCanceledException)
        {
            metadataStatusText.Text = "读音分析已取消，未覆盖当前输入。";
            metadataStatusText.Foreground = MutedBrush;
        }
        catch (Exception exception)
        {
            // The status line only has room for the message, and a BCL message
            // arrives as a bare resource key where UseSystemResourceKeys is on.
            // The stack is what says which library call failed, so it goes to the
            // Avalonia log sink — which the iOS host forwards into the launch log
            // and Windows leaves unattached.
            Logger.TryGet(LogEventLevel.Warning, LogArea.Control)?.Log(
                this,
                "Japanese romanization failed: {Error}",
                exception);
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("无法分析这段日文的读音：{0}；可以直接在英文栏手动填写罗马音。", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        finally
        {
            if (title)
            {
                if (ReferenceEquals(titleRomanizationCancellation, cancellation))
                {
                    titleRomanizationCancellation = null;
                    titleRomanizationTabId = null;
                }
                titleRomanizationInProgress = false;
                metadataRomanizeTitleButton.Content = "转罗马音";
            }
            else
            {
                if (ReferenceEquals(artistRomanizationCancellation, cancellation))
                {
                    artistRomanizationCancellation = null;
                    artistRomanizationTabId = null;
                }
                artistRomanizationInProgress = false;
                metadataRomanizeArtistButton.Content = "转罗马音";
            }
            cancellation.Dispose();
            UpdateEditorAvailability();
        }
    }

    private void RefreshMetadataEditor(DesktopChartTab? tab, bool force = false)
    {
        RefreshMetadataStats(tab);
        if (tab == null)
        {
            metadataEditorTabId = null;
            metadataEditorChangeSerial = -1;
            metadataEditorDirty = false;
            metadataEditorBaseline = null;
            metadataStatusText.Text = "没有打开的谱面。";
            return;
        }
        var tabChanged = metadataEditorTabId != tab.Id;
        if (!force && !tabChanged && metadataEditorChangeSerial == tab.Session.ChangeSerial) return;

        var authoritative = ChartMetadataEditingService.Capture(tab.Session.Document);
        var rebased = !force &&
                      !tabChanged &&
                      metadataEditorDirty &&
                      metadataEditorBaseline != null
            ? ChartMetadataEditingService.RebaseDraftWithDiagnostics(
                CaptureMetadataEditorDraft(tab),
                metadataEditorBaseline,
                authoritative)
            : null;
        var draft = rebased?.Draft ?? authoritative;
        PopulateMetadataEditorDraft(tab, draft);
        metadataEditorTabId = tab.Id;
        metadataEditorChangeSerial = tab.Session.ChangeSerial;
        metadataEditorBaseline = authoritative;
        metadataEditorDirty = rebased?.HasLocalChanges == true;
        metadataStatusText.Foreground = MutedBrush;
        if (rebased is { UpdatedAuthoritativeFieldCount: > 0, HasLocalChanges: true })
        {
            metadataStatusText.Text =
                "远端谱面信息已同步；未应用的本地输入已保留";
            return;
        }
        metadataStatusText.Text = tab.Session.IsReadOnly
            ? "观察者只读：谱面信息不可修改。"
            : !tab.Session.CanEditMetadata
                ? "没有谱面信息权限；请向房主索要。"
                : "Metadata、KeyCount 与 Offset 以一个撤销步骤原子应用。";
    }

    private void RefreshMetadataStats(DesktopChartTab? tab)
    {
        var stats = tab == null
            ? new WindowsMetadataStats(0, 0, 0)
            : WindowsInspectorParityPolicy.MeasureMetadataStats(
                tab.Session.Document);
        metadataStatsNotesText.Text =
            stats.Notes.ToString(CultureInfo.InvariantCulture);
        metadataStatsHoldsText.Text =
            stats.Holds.ToString(CultureInfo.InvariantCulture);
        metadataStatsTimingText.Text =
            stats.Timing.ToString(CultureInfo.InvariantCulture);
    }

    private ChartMetadataDraft CaptureMetadataEditorDraft(DesktopChartTab tab) =>
        new(
            metadataTitleBox.Text ?? string.Empty,
            metadataTitleOriginalBox.Text ?? string.Empty,
            metadataArtistBox.Text ?? string.Empty,
            metadataArtistOriginalBox.Text ?? string.Empty,
            metadataCreatorBox.Text ?? string.Empty,
            metadataVersionBox.Text ?? string.Empty,
            metadataPreviewTimeBox.Text ?? string.Empty,
            metadataBpmBox.Text ?? string.Empty,
            metadataOffsetBox.Text ?? string.Empty,
            metadataKeyCountBox.SelectedItem is WindowsMetadataKeyCountOption keyCount
                ? keyCount.Value
                : tab.Session.Document.KeyCount,
            metadataOverallDifficultyBox.Text ?? string.Empty,
            metadataHpDrainRateBox.Text ?? string.Empty,
            metadataCoverFileBox.Text ?? string.Empty,
            metadataBackgroundFileBox.Text ?? string.Empty);

    private void PopulateMetadataEditorDraft(
        DesktopChartTab tab,
        ChartMetadataDraft draft)
    {
        var previous = suppressMetadataEditorControls;
        suppressMetadataEditorControls = true;
        try
        {
            metadataTitleBox.Text = draft.Title;
            metadataTitleOriginalBox.Text = draft.TitleOriginal;
            metadataArtistBox.Text = draft.Artist;
            metadataArtistOriginalBox.Text = draft.ArtistOriginal;
            metadataCreatorBox.Text = draft.Creator;
            metadataVersionBox.Text = draft.Version;
            metadataPreviewTimeBox.Text = draft.PreviewTime;
            metadataBpmBox.Text = draft.Bpm;
            metadataOffsetBox.Text = draft.Offset;
            metadataKeyCountBox.SelectedItem =
                WindowsInspectorParityPolicy.Wpf110MetadataKeyCountOptions
                    .FirstOrDefault(option => option.Value == draft.KeyCount);
            metadataOverallDifficultyBox.Text = draft.OverallDifficulty;
            metadataHpDrainRateBox.Text = draft.HpDrainRate;
            metadataAudioFileBox.Text = tab.Session.Document.Metadata.AudioFile;
            metadataCoverFileBox.Text = draft.CoverFile;
            metadataBackgroundFileBox.Text = draft.BackgroundFile;
        }
        finally
        {
            suppressMetadataEditorControls = previous;
        }
    }

    private bool ApplyMetadataEditor(bool enforceCommunityRules = false)
    {
        lastMetadataApplyError = null;
        var tab = viewModel.ActiveTab;
        if (tab == null) return false;
        var draft = CaptureMetadataEditorDraft(tab);
        ChartMetadataEdit? edit;
        string error;
        var parsed = enforceCommunityRules
            ? ChartMetadataEditingService.TryParseDraft(
                draft,
                out edit,
                out error)
            : ChartMetadataEditingService.TryParseDraftForLocalPreservation(
                draft,
                tab.Session.Document,
                out edit,
                out error);
        if (!parsed || edit == null)
        {
            lastMetadataApplyError = error;
            metadataStatusText.Text = error;
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", error));
            return false;
        }

        try
        {
            var result = ChartMetadataEditingService.Apply(
                tab.Session,
                edit,
                enforceCommunityRules);
            metadataStatusText.Text = result.Message;
            metadataStatusText.Foreground = result.Status == ChartMetadataApplyStatus.Denied
                ? Brushes.OrangeRed
                : MutedBrush;
            viewModel.SetStatus(result.Message);
            if (result.Status == ChartMetadataApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.MetadataApplyDenied(
                    result.PermissionCategory) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (result.Status == ChartMetadataApplyStatus.Denied) return false;
            if (result.Status != ChartMetadataApplyStatus.Applied)
            {
                metadataEditorDirty = false;
                metadataEditorBaseline =
                    ChartMetadataEditingService.Capture(tab.Session.Document);
                return true;
            }
            metadataEditorDirty = false;
            RefreshMetadataEditor(tab, force: true);
            RequestChartBackground(tab, tab.Session.Document.Metadata.BackgroundFile);
            metadataStatusText.Text = result.Message;
            return true;
        }
        catch (Exception exception) when (exception is InvalidOperationException or ArgumentException)
        {
            lastMetadataApplyError = exception.Message;
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
            return false;
        }
    }

    private bool TryApplyPendingMetadataEditor(
        DesktopChartTab tab,
        bool enforceCommunityRules)
    {
        if (metadataEditorTabId != tab.Id || !metadataEditorDirty) return true;
        if (!ReferenceEquals(viewModel.ActiveTab, tab)) return false;
        return ApplyMetadataEditor(enforceCommunityRules);
    }

    private void SetMetadataPreviewToCurrentPosition()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        try
        {
            var snapshot = audioTransport.PlaybackSnapshot;
            var playingCurrentAudio = snapshot?.IsPlaying == true && audioTransport.ActiveTabId == tab.Id;
            var previewTime = ChartMetadataEditingService.ResolvePreviewTime(
                playingCurrentAudio,
                snapshot?.Position.TotalMilliseconds ?? 0,
                tab.Session.Document.Timing,
                BeatPosition.FromDouble(timeline.CurrentBeat));
            var result = ChartMetadataEditingService.SetPreviewTime(tab.Session, previewTime);
            if (result.Status != ChartMetadataApplyStatus.Denied)
            {
                var authoritative = ChartMetadataEditingService.Capture(tab.Session.Document);
                var current = CaptureMetadataEditorDraft(tab) with
                {
                    PreviewTime = previewTime.ToString(CultureInfo.InvariantCulture)
                };
                var rebased = ChartMetadataEditingService.RebaseDraftWithDiagnostics(
                    current,
                    metadataEditorBaseline ?? authoritative,
                    authoritative);
                PopulateMetadataEditorDraft(tab, rebased.Draft);
                metadataEditorBaseline = authoritative;
                metadataEditorDirty = rebased.HasLocalChanges;
            }
            metadataEditorTabId = tab.Id;
            metadataEditorChangeSerial = tab.Session.ChangeSerial;
            metadataStatusText.Text = result.Message;
            metadataStatusText.Foreground = result.Status == ChartMetadataApplyStatus.Denied
                ? Brushes.OrangeRed
                : MutedBrush;
            viewModel.SetStatus(result.Message);
            if (result.Status == ChartMetadataApplyStatus.Denied)
                ShowRoomPermissionNotice(
                    WindowsRoomPermissionNoticePolicy.PreviewTimeDenied(
                        tab.Session.IsReadOnly));
        }
        catch (Exception exception)
        {
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("无法读取当前播放位置：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
        }
    }

    private Task ImportCurrentChartAudioAsync()
    {
        if (!activeAudioImportTask.IsCompleted) return activeAudioImportTask;
        var operation = ImportCurrentChartAudioCoreAsync();
        activeAudioImportTask = operation;
        return operation;
    }

    /// <summary>
    /// Single-flight import of a known audio path (file drop). Registers the
    /// operation as the active import so the close preflight waits for it and
    /// a second import cannot cancel this one mid-copy.
    /// </summary>
    private Task ImportChartAudioPathAsync(DesktopChartTab tab, string sourcePath)
    {
        if (!activeAudioImportTask.IsCompleted)
        {
            viewModel.SetStatus("音频导入进行中，请稍后再试。");
            return activeAudioImportTask;
        }
        var operation = ImportChartAudioPathCoreAsync(tab, sourcePath);
        activeAudioImportTask = operation;
        return operation;
    }

    private Task ImportCurrentChartImageAsync(bool background)
    {
        if (imageImportInProgress) return activeImageImportTask;
        var operation = ImportCurrentChartImageCoreAsync(background);
        activeImageImportTask = operation;
        return operation;
    }

    private async Task ImportCurrentChartImageCoreAsync(bool background)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            metadataStatusText.Text = tab.Session.IsReadOnly
                ? "观察者不能修改谱面图片。"
                : "选择谱面图片需要谱面信息权限。";
            metadataStatusText.Foreground = Brushes.OrangeRed;
            return;
        }

        imageImportCancellation?.Cancel();
        imageImportCancellation?.Dispose();
        var cancellation = new CancellationTokenSource();
        imageImportCancellation = cancellation;
        imageImportTabId = tab.Id;
        imageImportInProgress = true;
        UpdateEditorAvailability();
        ChartAssetImportResult? imported = null;
        try
        {
            var sourcePath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择图片",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("图片文件")
                        {
                            Patterns = ["*.png", "*.jpg", "*.jpeg", "*.webp", "*.bmp"],
                            MimeTypes = ["image/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient,
                cancellation.Token);
            if (string.IsNullOrWhiteSpace(sourcePath)) return;

            imported = await Task.Run(
                () => ChartAssetImportService.ImportImage(
                    tab.WorkingPath,
                    Path.GetFullPath(sourcePath),
                    tab.SourcePath),
                cancellation.Token);
            cancellation.Token.ThrowIfCancellationRequested();
            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new OperationCanceledException("导入期间已切换谱面。", cancellation.Token);

            if (background)
            {
                metadataBackgroundFileBox.Text = imported.FileName;
                RequestChartBackground(tab, imported.FileName);
            }
            else
            {
                metadataCoverFileBox.Text = imported.FileName;
            }
            metadataEditorTabId = tab.Id;
            metadataEditorChangeSerial = tab.Session.ChangeSerial;
            metadataEditorDirty = true;
            metadataStatusText.Text =
                AvaloniaLocalizationCatalog.Format("{0}已导入：{1}；点击“应用谱面信息与 Offset”后写入谱面。", (background ? AvaloniaLocalizationCatalog.Text("背景图片") : AvaloniaLocalizationCatalog.Text("歌曲封面")), imported.FileName);
            metadataStatusText.Foreground = MutedBrush;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        catch (OperationCanceledException)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            metadataStatusText.Text = "图片导入已取消，未修改当前谱面。";
            metadataStatusText.Foreground = MutedBrush;
        }
        catch (Exception exception)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("无法导入图片：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法复制图片到谱面目录",
                    exception));
        }
        finally
        {
            if (ReferenceEquals(imageImportCancellation, cancellation))
            {
                imageImportCancellation = null;
                imageImportTabId = null;
            }
            cancellation.Dispose();
            imageImportInProgress = false;
            UpdateEditorAvailability();
        }
    }

    private void UpdateChartBackground(DesktopChartTab? tab)
    {
        var reference = tab == null
            ? null
            : metadataEditorDirty && metadataEditorTabId == tab.Id
                ? metadataBackgroundFileBox.Text
                : tab.Session.Document.Metadata.BackgroundFile;
        RequestChartBackground(tab, reference);
    }

    /// <summary>
    /// Forgets which background is currently loaded, so the next
    /// <see cref="UpdateChartBackground"/> reloads it instead of deciding that
    /// the right one is already there.
    ///
    /// Needed after test play. On a tablet the playtest surface is a modal
    /// overlay, which means the editor's whole visual tree is detached from the
    /// host and re-attached on the way back — unlike Windows, where playtest is a
    /// separate window and the editor is never taken down. Coming back, the
    /// chart background was gone on both mobile clients while the notes and grid
    /// drew normally, and none of the three places that clear the bitmap had
    /// run: the field still held it, the opacity was untouched, and
    /// RequestChartBackground's "same tab, same path" guard then decided there
    /// was nothing to do. The bitmap survives the trip as an object without
    /// surviving it as something drawable.
    ///
    /// The mechanism behind that is not identified — this restores the image
    /// rather than explaining it. It is cheap (one decode after a playtest
    /// session) and it reports itself: the reload writes either
    /// "背景预览已加载" or "背景图片无法解码" to the status line, so a
    /// recurrence says which half is at fault.
    /// </summary>
    private void InvalidateChartBackgroundCache()
    {
        backgroundImageTabId = null;
        backgroundImagePath = null;
    }

    private void RequestChartBackground(DesktopChartTab? tab, string? reference)
    {
        var path = tab == null
            ? null
            : ChartAssetImportService.ResolveAssetPath(tab.WorkingPath, tab.SourcePath, reference);
        if (backgroundImageTabId == tab?.Id &&
            string.Equals(backgroundImagePath, path, StringComparison.OrdinalIgnoreCase))
            return;

        backgroundImageLoadCancellation?.Cancel();
        backgroundImageLoadCancellation = null;
        var generation = ++backgroundImageLoadGeneration;
        backgroundImageTabId = tab?.Id;
        backgroundImagePath = path;
        timeline.SetChartBackgroundImage(null);
        if (tab == null || path == null) return;

        var cancellation = new CancellationTokenSource();
        var cancellationToken = cancellation.Token;
        backgroundImageLoadCancellation = cancellation;
        _ = LoadChartBackgroundAsync(path, tab.Id, generation, cancellation, cancellationToken);
    }

    private async Task LoadChartBackgroundAsync(
        string path,
        Guid tabId,
        long generation,
        CancellationTokenSource cancellation,
        CancellationToken cancellationToken)
    {
        Bitmap? bitmap = null;
        try
        {
            bitmap = await Task.Run(() =>
            {
                cancellationToken.ThrowIfCancellationRequested();
                using var stream = new FileStream(
                    path,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.ReadWrite,
                    64 * 1024,
                    FileOptions.SequentialScan);
                var decoded = Bitmap.DecodeToWidth(
                    stream,
                    2560,
                    BitmapInterpolationMode.HighQuality);
                cancellationToken.ThrowIfCancellationRequested();
                return decoded;
            }, cancellationToken);
            if (generation != backgroundImageLoadGeneration ||
                cancellationToken.IsCancellationRequested ||
                viewModel.ActiveTab?.Id != tabId ||
                !string.Equals(backgroundImagePath, path, StringComparison.OrdinalIgnoreCase))
            {
                bitmap.Dispose();
                return;
            }
            timeline.SetChartBackgroundImage(bitmap);
            bitmap = null;
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("背景预览已加载：{0}。", Path.GetFileName(path));
            metadataStatusText.Foreground = MutedBrush;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        catch (OperationCanceledException)
        {
            bitmap?.Dispose();
        }
        catch
        {
            bitmap?.Dispose();
            if (generation == backgroundImageLoadGeneration && viewModel.ActiveTab?.Id == tabId)
            {
                timeline.SetChartBackgroundImage(null);
                metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("背景图片无法解码：{0}。", Path.GetFileName(path));
                metadataStatusText.Foreground = Brushes.OrangeRed;
                viewModel.SetStatus(metadataStatusText.Text);
            }
        }
        finally
        {
            if (ReferenceEquals(backgroundImageLoadCancellation, cancellation))
                backgroundImageLoadCancellation = null;
            cancellation.Dispose();
        }
    }

    private async Task ImportCurrentChartAudioCoreAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            SetMetadataAudioStatus(
                tab.Session.IsReadOnly
                    ? "观察者不能修改谱面音频。"
                    : "选择谱面音频需要谱面信息权限。",
                error: true);
            return;
        }

        string? sourcePath;
        try
        {
            sourcePath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择音乐",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("音频文件")
                        {
                            Patterns = ["*.mp3", "*.ogg", "*.wav", "*.flac", "*.m4a", "*.aac"],
                            MimeTypes = ["audio/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient);
        }
        catch (Exception exception)
        {
            // The import itself reports its failures; the picker had no boundary.
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
            return;
        }
        if (string.IsNullOrWhiteSpace(sourcePath)) return;
        _ = await ImportChartAudioPathCoreAsync(tab, Path.GetFullPath(sourcePath));
    }

    private async Task<WindowsChartAudioImportStatus> ImportChartAudioPathCoreAsync(
        DesktopChartTab tab,
        string sourcePath)
    {
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            SetMetadataAudioStatus(
                tab.Session.IsReadOnly
                    ? "观察者不能修改谱面音频。"
                    : "选择谱面音频需要谱面信息权限。",
                error: true);
            return WindowsChartAudioImportStatus.Denied;
        }

        var mode = AudioImportMode.KeepOriginal;
        if (!Path.GetExtension(sourcePath).Equals(".ogg", StringComparison.OrdinalIgnoreCase))
        {
            mode = await new AudioImportModeDialog(
                    Path.GetFileName(sourcePath),
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<AudioImportMode>(this);
            if (mode == AudioImportMode.Cancel)
                return WindowsChartAudioImportStatus.Canceled;
        }

        audioImportCancellation?.Cancel();
        audioImportCancellation?.Dispose();
        var cancellation = new CancellationTokenSource();
        audioImportCancellation = cancellation;
        audioImportInProgress = true;
        UpdateEditorAvailability();
        if (evidenceAudioPermissionRevokeDelayMilliseconds > 0)
        {
            DispatcherTimer.RunOnce(
                () =>
                {
                    if (viewModel.ActiveTab?.Id != tab.Id) return;
                    tab.Session.CanEditMetadata = false;
                    UpdateEditorAvailability();
                },
                TimeSpan.FromMilliseconds(
                    evidenceAudioPermissionRevokeDelayMilliseconds));
        }
        try
        {
            if (audioAnalysisInProgress)
            {
                audioAnalysisCancellation?.Cancel();
                try { await activeAudioAnalysisTask; }
                catch (OperationCanceledException) { }
            }

            IProgress<double>? progress = null;
            if (mode == AudioImportMode.ConvertToOgg)
            {
                progress = new Progress<double>(value =>
                    SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("正在转换 OGG… {0:P0}", value)));
                SetMetadataAudioStatus("正在转换 OGG…");
            }
            else
                SetMetadataAudioStatus("正在复制音频到谱面编辑目录…");

            var result = await chartAudioImportWorkflow.RunAsync(
                tab.Session,
                tab.WorkingPath,
                tab.SourcePath,
                sourcePath,
                mode == AudioImportMode.ConvertToOgg,
                () => viewModel.ActiveTab?.Id == tab.Id,
                progress,
                cancellation.Token,
                TimeSpan.FromMilliseconds(
                    evidenceAudioPreCommitDelayMilliseconds));
            if (result.Status == WindowsChartAudioImportStatus.Canceled)
            {
                SetMetadataAudioStatus("音频导入已取消，未修改当前谱面。", error: true);
                return WindowsChartAudioImportStatus.Canceled;
            }
            if (result.Status == WindowsChartAudioImportStatus.Failed)
            {
                SetMetadataAudioStatus(
                    AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", result.Error?.Message ?? AvaloniaLocalizationCatalog.Text("未知错误")),
                    error: true);
                return WindowsChartAudioImportStatus.Failed;
            }
            if (result.Status == WindowsChartAudioImportStatus.Denied)
            {
                SetMetadataAudioStatus(
                    result.MetadataApply?.Message ?? "当前权限不允许修改谱面音频。",
                    error: true);
                return WindowsChartAudioImportStatus.Denied;
            }

            var imported = result.Asset
                           ?? throw new InvalidOperationException("音频导入没有返回资源。");
            var apply = result.MetadataApply
                        ?? throw new InvalidOperationException("音频导入没有返回谱面修改结果。");
            metadataAudioFileBox.Text = imported.FileName;
            metadataEditorTabId = tab.Id;
            metadataEditorChangeSerial = tab.Session.ChangeSerial;
            SetMetadataAudioStatus(
                mode == AudioImportMode.ConvertToOgg
                    ? AvaloniaLocalizationCatalog.Format("音频已转换并导入：{0}", imported.FileName)
                    : AvaloniaLocalizationCatalog.Format("音频已导入：{0}", imported.FileName));
            viewModel.SetStatus(apply.Message);
            UpdateUi();
            await StartSingleTempoAnalysisAsync();
            return WindowsChartAudioImportStatus.Imported;
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
            return WindowsChartAudioImportStatus.Failed;
        }
        finally
        {
            // Only the import that still owns the token may clear the shared
            // state; a newer import that replaced it is still running.
            if (ReferenceEquals(audioImportCancellation, cancellation))
            {
                audioImportCancellation = null;
                audioImportInProgress = false;
                UpdateEditorAvailability();
            }
            cancellation.Dispose();
        }
    }

    private Task StartSingleTempoAnalysisAsync()
    {
        if (audioAnalysisInProgress)
        {
            if (activeTempoAnalysisKind == TempoAnalysisKind.Single)
                RequestTempoAnalysisCancellation();
            return activeAudioAnalysisTask;
        }
        var operation = RunSingleTempoAnalysisAsync();
        activeAudioAnalysisTask = operation;
        return operation;
    }

    private async Task RunSingleTempoAnalysisAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryBeginTempoAnalysis(
                tab,
                TempoAnalysisKind.Single,
                out var audioPath,
                out var cancellation))
            return;
        metadataAnalyzeSingleTempoButton.Content = "取消 BPM 分析";
        SetMetadataAudioStatus("正在读取波形并分析节拍，最长分析前 4 分钟；可点击按钮取消。");
        try
        {
            var result = await WindowsBeatAnalyzer.AnalyzeAsync(audioPath, cancellation.Token);
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("分析期间已切换谱面，本次结果已取消且不会写入当前谱面。", error: true);
                return;
            }

            SetMetadataAudioStatus(
                AvaloniaLocalizationCatalog.Format("BPM {0:0.###} · Offset {1:0.###} ms · 稳定度 {2:P0} · 置信度 {3:P0}", result.Bpm, result.OffsetMilliseconds, 1 - result.Instability, result.Confidence));
            var serialAtPreview = tab!.Session.ChangeSerial;
            var confirmed = await new SingleTempoResultDialog(
                    result,
                    tab.Session.CanEditMetadata,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<bool>(this);
            if (!confirmed) return;
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("确认前已切换谱面，检测结果未写入。", error: true);
                return;
            }

            var applied = TempoDetectionEditingService.ApplySingle(tab.Session, result, serialAtPreview);
            SetMetadataAudioStatus(
                applied.Message,
                applied.Status is TempoDetectionApplyStatus.Denied or TempoDetectionApplyStatus.Stale);
            viewModel.SetStatus(applied.Message);
            if (applied.Status == TempoDetectionApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.TempoAnalysisApplyDenied(
                    applied.PermissionCategory,
                    variableTempo: false) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (applied.Status != TempoDetectionApplyStatus.Applied) return;
            UpdateTempoEditorFields(tab, result.Bpm, result.OffsetMilliseconds, applied.MetadataBpmUpdated);
        }
        catch (OperationCanceledException)
        {
            SetMetadataAudioStatus("BPM 分析已取消，未写入谱面。", error: true);
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("BPM 检测失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
        finally
        {
            metadataAnalyzeSingleTempoButton.Content = "检测 BPM 与 Offset";
            CompleteTempoAnalysis(cancellation);
        }
    }

    private Task StartVariableTempoAnalysisAsync()
    {
        if (audioAnalysisInProgress)
        {
            if (activeTempoAnalysisKind == TempoAnalysisKind.Variable)
                RequestTempoAnalysisCancellation();
            return activeAudioAnalysisTask;
        }
        var operation = RunVariableTempoAnalysisAsync();
        activeAudioAnalysisTask = operation;
        return operation;
    }

    private Task StartManualTempoMeasurementAsync()
    {
        if (audioAnalysisInProgress) return activeAudioAnalysisTask;
        var operation = RunManualTempoMeasurementAsync();
        activeAudioAnalysisTask = operation;
        return operation;
    }

    private async Task RunManualTempoMeasurementAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryBeginTempoAnalysis(
                tab,
                TempoAnalysisKind.Manual,
                out _,
                out var cancellation))
            return;

        metadataAnalyzeManualTempoButton.Content = "正在手动测量…";
        SetMetadataAudioStatus("手动测量会播放当前歌曲；请在弹窗内设置按键并跟随整拍连续打拍。");
        var originalRate = audioTransport.PlaybackRate;
        var wasPlaying = audioTransport.PlaybackSnapshot?.IsPlaying == true &&
                         audioTransport.ActiveTabId == tab!.Id;
        try
        {
            if (!await audioTransport.EnsureAudioReadyAsync(tab!))
                throw new InvalidOperationException(audioTransport.Status);
            if (!IsCurrentAudioAnalysisContext(tab))
                throw new OperationCanceledException();

            await audioTransport.SetPlaybackRateAsync(1);
            if (audioTransport.LastError != null)
                throw new InvalidOperationException(
                    audioTransport.LastError.Message,
                    audioTransport.LastError);

            var serialAtPreview = tab!.Session.ChangeSerial;
            var result = await new ManualTempoMeasurementDialog(
                    ToggleAudioPlaybackAsync,
                    () => audioTransport.ActiveTabId == tab.Id &&
                          audioTransport.PlaybackSnapshot?.IsPlaying == true,
                    () => audioTransport.ActiveTabId == tab.Id
                        ? audioTransport.PlaybackSnapshot?.Position.TotalMilliseconds
                        : null,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<BeatAnalysisResult?>(this);
            if (result is not { } measured) return;
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("确认前已切换谱面，手动测量结果未写入。", error: true);
                return;
            }

            var applied = TempoDetectionEditingService.ApplySingle(
                tab.Session,
                measured,
                serialAtPreview);
            SetMetadataAudioStatus(
                applied.Message,
                applied.Status is TempoDetectionApplyStatus.Denied or TempoDetectionApplyStatus.Stale);
            viewModel.SetStatus(applied.Message);
            if (applied.Status == TempoDetectionApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.TempoAnalysisApplyDenied(
                    applied.PermissionCategory,
                    variableTempo: false) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (applied.Status == TempoDetectionApplyStatus.Applied)
                UpdateTempoEditorFields(
                    tab,
                    measured.Bpm,
                    measured.OffsetMilliseconds,
                    applied.MetadataBpmUpdated);
        }
        catch (OperationCanceledException)
        {
            SetMetadataAudioStatus("手动测量已取消，未写入谱面。", error: true);
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("手动测量失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
        finally
        {
            if (audioTransport.ActiveTabId == tab!.Id)
            {
                var isPlaying = audioTransport.PlaybackSnapshot?.IsPlaying == true;
                if (isPlaying != wasPlaying)
                    await audioTransport.TogglePlayPauseAsync();
                await audioTransport.SetPlaybackRateAsync(originalRate);
            }
            metadataAnalyzeManualTempoButton.Content = "手动测量 BPM 与 Offset";
            CompleteTempoAnalysis(cancellation);
        }
    }

    private async Task RunVariableTempoAnalysisAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryBeginTempoAnalysis(
                tab,
                TempoAnalysisKind.Variable,
                out var audioPath,
                out var cancellation))
            return;
        metadataAnalyzeVariableTempoButton.Content = "取消多 BPM 分析";
        SetMetadataAudioStatus("正在分窗估计局部节拍并合并稳定变速点，最长分析前 4 分钟；可点击按钮取消。");
        try
        {
            var result = await WindowsBeatAnalyzer.AnalyzeTimelineAsync(audioPath, cancellation.Token);
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("分析期间已切换谱面，本次结果已取消且不会写入当前谱面。", error: true);
                return;
            }

            var plan = TempoDetectionEditingService.CreateTimelinePlan(tab!.Session.Document, result.Timeline);
            var minimumConfidence = result.Timeline.Segments.Min(segment => segment.Confidence);
            SetMetadataAudioStatus(
                AvaloniaLocalizationCatalog.Format("预测到 {0} 个 BPM 段 · 首段 Offset {1:0.###} ms · 最低置信度 {2:P0}", plan.Candidates.Count, result.Timeline.InitialOffsetMilliseconds, minimumConfidence));
            var serialAtPreview = tab.Session.ChangeSerial;
            var choice = await new VariableTempoResultDialog(
                    result,
                    plan,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<VariableTempoDialogChoice>(this);
            if (choice == VariableTempoDialogChoice.Cancel) return;
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("确认前已切换谱面，预测结果未写入。", error: true);
                return;
            }

            var compensate = choice == VariableTempoDialogChoice.ApplyWithScrollCompensation;
            if (compensate &&
                (!TryParseMetadataNumber(metadataBpmBox.Text, out var displayedBpm) ||
                 !displayedBpm.Equals(plan.ReferenceBpm)))
            {
                SetMetadataAudioStatus(
                    AvaloniaLocalizationCatalog.Format("谱面 BPM 输入框中有尚未应用的内容。流速补正只使用已保存的基准 BPM {0:R}；请先应用谱面信息后重新预测。", plan.ReferenceBpm),
                    error: true);
                return;
            }

            var applied = TempoDetectionEditingService.ApplyTimeline(
                tab.Session,
                plan,
                result.Timeline.InitialOffsetMilliseconds,
                compensate,
                serialAtPreview);
            SetMetadataAudioStatus(
                applied.Message,
                applied.Status is TempoDetectionApplyStatus.Denied or TempoDetectionApplyStatus.Stale);
            viewModel.SetStatus(applied.Message);
            if (applied.Status == TempoDetectionApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.TempoAnalysisApplyDenied(
                    applied.PermissionCategory,
                    variableTempo: true) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (applied.Status != TempoDetectionApplyStatus.Applied) return;
            UpdateTempoEditorFields(
                tab,
                plan.ReferenceBpm,
                result.Timeline.InitialOffsetMilliseconds,
                updateBpm: false);
        }
        catch (OperationCanceledException)
        {
            SetMetadataAudioStatus("多 BPM 分析已取消，未写入谱面。", error: true);
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("多 BPM 预测失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
        finally
        {
            metadataAnalyzeVariableTempoButton.Content = "预测多个 BPM";
            CompleteTempoAnalysis(cancellation);
        }
    }

    private bool TryBeginTempoAnalysis(
        DesktopChartTab? tab,
        TempoAnalysisKind kind,
        out string audioPath,
        out CancellationTokenSource cancellation)
    {
        audioPath = string.Empty;
        cancellation = new CancellationTokenSource();
        if (tab == null)
        {
            cancellation.Dispose();
            return false;
        }
        if (tab.Session.IsReadOnly || !tab.Session.CanEditTiming)
        {
            cancellation.Dispose();
            SetMetadataAudioStatus(
                tab.Session.IsReadOnly
                    ? "观察者不能写入 BPM 或 Delay。"
                    : "BPM 与 Offset 属于 Timing，需要 Effect 权限。",
                error: true);
            ShowRoomPermissionNotice(
                WindowsRoomPermissionNoticePolicy.TempoAnalysisStartDenied());
            return false;
        }
        audioPath = WindowsAudioTransportViewModel.ResolveDocumentAudioPath(tab) ?? string.Empty;
        if (audioPath.Length == 0)
        {
            cancellation.Dispose();
            SetMetadataAudioStatus("请先选择一个存在的音频文件。", error: true);
            return false;
        }

        audioAnalysisCancellation?.Cancel();
        cancellation = new CancellationTokenSource();
        audioAnalysisCancellation = cancellation;
        audioAnalysisTabId = tab.Id;
        activeTempoAnalysisKind = kind;
        audioAnalysisInProgress = true;
        UpdateEditorAvailability();
        return true;
    }

    private void RequestTempoAnalysisCancellation()
    {
        if (!audioAnalysisInProgress || audioAnalysisCancellation == null) return;
        SetMetadataAudioStatus("正在取消 BPM 分析…");
        audioAnalysisCancellation.Cancel();
    }

    private void CompleteTempoAnalysis(CancellationTokenSource cancellation)
    {
        if (ReferenceEquals(audioAnalysisCancellation, cancellation))
        {
            audioAnalysisCancellation = null;
            audioAnalysisTabId = null;
        }
        cancellation.Dispose();
        audioAnalysisInProgress = false;
        activeTempoAnalysisKind = TempoAnalysisKind.None;
        UpdateEditorAvailability();
    }

    private bool IsCurrentAudioAnalysisContext(DesktopChartTab? tab) =>
        tab != null && viewModel.ActiveTab?.Id == tab.Id && audioAnalysisTabId == tab.Id;

    private void UpdateTempoEditorFields(
        DesktopChartTab tab,
        double bpm,
        double offset,
        bool updateBpm)
    {
        var previous = suppressMetadataEditorControls;
        suppressMetadataEditorControls = true;
        try
        {
            metadataOffsetBox.Text = offset.ToString("0.###", CultureInfo.InvariantCulture);
            if (updateBpm) metadataBpmBox.Text = bpm.ToString("R", CultureInfo.InvariantCulture);
        }
        finally
        {
            suppressMetadataEditorControls = previous;
        }
        metadataEditorTabId = tab.Id;
        metadataEditorChangeSerial = tab.Session.ChangeSerial;
    }

    private void SetMetadataAudioStatus(string message, bool error = false)
    {
        metadataAudioAnalysisText.Text = message;
        metadataAudioAnalysisText.Foreground = error ? Brushes.IndianRed : MutedBrush;
        viewModel.SetStatus(message);
    }

    private static bool TryParseMetadataNumber(string? text, out double value)
    {
        var parsed = double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out value) ||
                     double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out value);
        return parsed && double.IsFinite(value);
    }

    private static void TryDeleteImportedAsset(string path)
    {
        try { if (File.Exists(path)) File.Delete(path); }
        catch { }
    }

    private void UpdateNoteInspector(DesktopChartTab? tab)
    {
        if (tab == null)
        {
            noteSelectionHint.Text = "选择一个 Note 进行编辑";
            ClearNotePropertyFields();
            return;
        }

        var state = WindowsNotePropertyCommand.ReadInspectorState(
            tab.Session,
            tab.HiddenGroups);
        noteSelectionHint.Text = state.Hint;
        if (state.SelectedCount == 0)
        {
            ClearNotePropertyFields();
            return;
        }
        if (state.Fields is not { } fields)
        {
            noteInspectorNoteId = null;
            noteInspectorFields = null;
            return;
        }

        // UpdateUi runs on every status change and, in a room, on each presence
        // poll. Only rewrite a box when the selected note changed or that
        // field's stored value changed since the last fill; otherwise the box
        // holds the user's unapplied input, which must not be reverted.
        var previous = noteInspectorNoteId == state.NoteId
            ? noteInspectorFields
            : null;
        RefillNoteField(noteBeatBox, fields.Beat, previous?.Beat);
        RefillNoteField(noteEndBeatBox, fields.EndBeat, previous?.EndBeat);
        RefillNoteField(noteLaneBox, fields.Lane, previous?.Lane);
        RefillNoteField(noteVolumeBox, fields.Volume, previous?.Volume);
        RefillNoteField(noteSoundBox, fields.Sound, previous?.Sound);
        RefillNoteField(noteGroupBox, fields.Group, previous?.Group);
        noteInspectorNoteId = state.NoteId;
        noteInspectorFields = fields;
    }

    private static void RefillNoteField(
        TextBox box,
        string value,
        string? previouslyFilledValue)
    {
        if (previouslyFilledValue == null ||
            !string.Equals(value, previouslyFilledValue, StringComparison.Ordinal))
            box.Text = value;
    }

    /// <summary>
    /// Forces the next note-inspector refresh to rewrite every field, e.g.
    /// after an explicit Apply so the boxes show the canonical stored values.
    /// </summary>
    private void ResetNoteInspectorFill()
    {
        noteInspectorNoteId = null;
        noteInspectorFields = null;
    }

    private void ClearNotePropertyFields()
    {
        ResetNoteInspectorFill();
        noteBeatBox.Text = string.Empty;
        noteEndBeatBox.Text = string.Empty;
        noteLaneBox.Text = string.Empty;
        noteVolumeBox.Text = string.Empty;
        noteSoundBox.Text = string.Empty;
        noteGroupBox.Text = string.Empty;
    }

    private void RefreshGroupPanel()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            if (groupRows.Count > 0 ||
                groupListPanel.Children.Count > 0 ||
                groupPresetTabStrip.Children.Count > 0)
            {
                groupListPanel.Children.Clear();
                groupPresetTabStrip.Children.Clear();
                groupRows.Clear();
            }
            groupPanelSignature = string.Empty;
            DiscardPresetRename();
            currentPlacementGroupText.Text = "未分组（0）";
            currentPlacementGroupText.Foreground = MutedBrush;
            groupManagerHint.Text = "选择 Note 后可批量设置分组";
            PushGroupVisuals();
            return;
        }

        // A chart switch retires the rename box without committing: the name in
        // it belongs to a drawer on the chart it was opened from, and the new
        // chart's preset 1 is a different drawer that merely shares the number.
        // This runs before the rebuild below, which would otherwise commit the
        // text into the chart that is only now becoming the active one.
        if (groupPresetRenameHost != 0 && tab.Id != groupPresetRenameTabId)
            DiscardPresetRename();

        var snapshot = WindowsGroupManagerCommand.ReadSnapshot(tab);
        SyncKeySoundHiddenGroups(tab);
        timeline.PlacementGroup = snapshot.ActivePlacementGroup;
        timeline.SetHiddenGroups(tab.HiddenGroups);
        currentPlacementGroupText.Text = snapshot.ActivePlacementGroup == 0
            ? "未分组（0）"
            : AvaloniaLocalizationCatalog.Format(
                "Group {0} · {1}",
                snapshot.ActivePlacementGroup,
                tab.GroupCatalog.NameOf(snapshot.ActivePlacementGroup));
        currentPlacementGroupText.Foreground = snapshot.ActivePlacementGroup == 0
            ? MutedBrush
            : ResolveGroupBrush(tab, snapshot.ActivePlacementGroup, string.Empty);
        groupManagerHint.Text = snapshot.VisibleEditableSelectionCount == 0
            ? "选择 Note 后可批量设置分组"
            : AvaloniaLocalizationCatalog.Format(
                "已选择 {0} 个可见 Note，可批量分配",
                snapshot.VisibleEditableSelectionCount);

        // Rows own editable boxes now. Rebuilding them on every inspector tick
        // would take the caret away mid-word, so the shape of the list decides
        // whether to rebuild at all; the rest is updated in place.
        //
        // The signature is taken over the rows the panel will actually list, not
        // over every group in the catalog: which scheme is on screen decides the
        // rows, and a signature blind to that would call a scheme switch "no
        // change" and leave the previous scheme's groups on screen.
        var rows = GroupPanelRows(tab, snapshot);
        var signature = BuildGroupPanelSignature(tab, rows);
        if (!string.Equals(signature, groupPanelSignature, StringComparison.Ordinal))
        {
            // Recorded only when the rebuild actually ran. A rebuild refused by
            // the re-entrancy guard has to leave the old signature in place, or
            // the panel would believe it is showing a shape it never rendered
            // and would silently stop refreshing.
            if (RebuildGroupPanel(tab, snapshot)) groupPanelSignature = signature;
        }
        else
        {
            UpdateGroupRows(tab, snapshot);
        }
        PushGroupVisuals();
    }

    /// <summary>
    /// The panel shape, not its contents: which groups are listed, how they
    /// nest, what the schemes are called and which one is open. A change here
    /// means the tabs and the rows behind them have to be rebuilt; anything else
    /// is written into the existing controls, so typing is never interrupted.
    ///
    /// <paramref name="rows"/> is the list the panel will render, and the open
    /// scheme is already folded into it by <see cref="GroupPanelRows"/>. The
    /// rename box deliberately does *not* belong here: it is swapped into the
    /// live tab in place, so nothing about it needs the strip rebuilt — and a
    /// rebuild is exactly what would tear it off the screen mid-word.
    /// </summary>
    private string BuildGroupPanelSignature(
        DesktopChartTab tab,
        IReadOnlyList<WindowsGroupManagerRow> rows)
    {
        var parts = new List<string>(rows.Count + tab.GroupCatalog.Presets.Count + 2)
        {
            tab.Id.ToString("N"),
            string.Concat(
                "A",
                (tab.ActiveGroupPreset ?? 0).ToString(CultureInfo.InvariantCulture))
        };
        foreach (var preset in tab.GroupCatalog.Presets)
        {
            parts.Add(string.Concat(
                "P",
                preset.Id.ToString(CultureInfo.InvariantCulture),
                ":",
                preset.Name));
        }
        foreach (var row in rows)
        {
            parts.Add(string.Concat(
                row.Group.ToString(CultureInfo.InvariantCulture),
                ":",
                (row.ParentId ?? -1).ToString(CultureInfo.InvariantCulture),
                ":",
                row.Depth.ToString(CultureInfo.InvariantCulture)));
        }
        return string.Join("|", parts);
    }

    /// <summary>
    /// The rows the group list shows: 未分组, the groups the scheme on screen
    /// owns, and any group a visible note actually carries.
    ///
    /// Listing every group that exists is what made switching schemes look like
    /// it changed nothing: a group made while 「按音轨」 was open would still be
    /// sitting in the panel after switching to 「按手感」, which had never used it.
    /// The roster is part of the reading, so the panel follows it.
    ///
    /// Two things are deliberately never filtered out. 未分组 is the target that
    /// takes notes out of a group. And a group that notes are currently carrying
    /// is shown even if no roster names it — a row that is invisible while its
    /// notes are on screen is how a mapper loses track of their own chart.
    ///
    /// Draft notes count as carriers. A ProEditor scratch note has a group of its
    /// own, and on a chart whose reading is written on that track it is the only
    /// thing a group holds: skip it and Ctrl+Z after a 解散 restores the notes but
    /// leaves the row filtered out, which reads as "the group is gone and only
    /// its notes are left behind".
    /// </summary>
    private static List<WindowsGroupManagerRow> GroupPanelRows(
        DesktopChartTab tab,
        WindowsGroupManagerSnapshot snapshot)
    {
        if (tab.GroupCatalog.VisibleGroupIds() is not { } owned) return [.. snapshot.Rows];
        var onNotes = tab.Session.Document.Notes
            .Where(note => note.Group != 0)
            .Select(note => note.Group)
            .ToHashSet();
        return
        [
            .. snapshot.Rows.Where(row =>
                row.Group == 0 || owned.Contains(row.Group) || onNotes.Contains(row.Group))
        ];
    }

    /// <summary>
    /// Lays out the preset tabs and the rows the open scheme lists underneath
    /// them. The name, colour and nesting boxes all edit the per-chart catalog,
    /// so they persist with the chart and never open an undo entry — the
    /// document itself is untouched by any of them.
    ///
    /// The nesting column only exists while 显示子分组 is on. A tree is a real
    /// feature but a rare want, and a flat list of groups is what a mapper
    /// almost always wants, so the parent picker and the ＋子 button cost
    /// nothing until they are asked for.
    ///
    /// Re-entrancy is refused on purpose. The strip holds controls that can take
    /// focus, and taking one off screen raises focus events; a rebuild raised
    /// from one of those would clear the strip from inside the loop that is
    /// currently filling it and leave two copies of every tab behind. The state
    /// such a nested call would render is the state this call is already
    /// rendering, so there is nothing to catch up on — but the caller is told,
    /// so it can leave the panel signature unrecorded and try again later.
    /// </summary>
    private bool RebuildGroupPanel(DesktopChartTab tab, WindowsGroupManagerSnapshot snapshot)
    {
        if (rebuildingGroupPanel) return false;
        rebuildingGroupPanel = true;
        try
        {
            RebuildGroupPanelCore(tab, snapshot);
        }
        finally
        {
            rebuildingGroupPanel = false;
        }
        return true;
    }

    private void RebuildGroupPanelCore(DesktopChartTab tab, WindowsGroupManagerSnapshot snapshot)
    {
        // A box may still be up on a tab that is about to go; its text is
        // committed straight to the catalog, without a refresh, because a
        // refresh from here would run inside the rebuild that asked for it.
        FlushPresetRename();
        groupPresetTabStrip.Children.Clear();
        groupPresetTabButtons.Clear();
        groupPresetTabCounts.Clear();
        groupListPanel.Children.Clear();
        groupRows.Clear();
        groupColorPopup.IsOpen = false;

        var showSubGroups = groupDisplaySettings.ShowSubGroups;
        var dynamicTabIndex = WindowsInspectorParityPolicy.GroupDynamicFocusStartIndex;
        var openScheme = tab.ActiveGroupPreset;
        // There is no 全部 tab: with no scheme selected — before the first one
        // exists, or after the selected one is deleted — the rows below are
        // every group, which is the honest reading of a grouping no scheme owns.
        // 删除 has no target while no scheme is on screen, and it is dimmed as
        // well as disabled because a skin that paints its own colours leaves a
        // disabled button looking exactly like a live one. 重命名 stays live: it
        // answers by opening a scheme rather than by refusing, so no press can
        // do nothing.
        groupDeletePresetButton.IsEnabled = openScheme is not null;
        groupDeletePresetButton.Opacity = openScheme is not null ? 1 : 0.45;

        foreach (var preset in tab.GroupCatalog.Presets)
        {
            groupPresetTabStrip.Children.Add(BuildPresetTab(
                tab,
                preset.Id,
                preset.Id == openScheme
                    ? CountGroupedNotes(tab)
                    : preset.Assignments.Count,
                ref dynamicTabIndex));
        }

        var panelRows = GroupPanelRows(tab, snapshot);
        // 未分组 is always listed, so "nothing in the panel" really means "nothing
        // but 未分组" — which is what a scheme owning no group yet looks like. It
        // has to say so, because a lone 未分组 row reads as groups having been
        // lost rather than as a scheme that is simply still empty.
        if (panelRows.All(row => row.Group == 0))
        {
            groupListPanel.Children.Add(new TextBlock
            {
                Text = tab.ActiveGroupPreset is null
                    ? "还没有分组：点「新建并使用」建立第一个分组，再把选中的 Note 分配进去。"
                    : "这个分组预设里还没有分组：点「新建并使用」或某行的「使用」，" +
                      "分组会归进这个预设，别的预设不会跟着变。",
                Foreground = MutedBrush,
                FontSize = 10,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(2, 4, 0, 2)
            });
        }

        foreach (var row in panelRows)
        {
            var group = row.Group;
            var color = ResolveGroupBrush(tab, group, row.ColorText);

            var visible = new CheckBox
            {
                Content = "显示",
                IsChecked = row.IsVisible,
                Foreground = color,
                FontSize = 11,
                VerticalAlignment = VerticalAlignment.Center,
                Padding = new Thickness(0),
                Margin = new Thickness(0, 0, 4, 0)
            };
            AutomationProperties.SetName(visible, AvaloniaLocalizationCatalog.Format("Group {0} 显示", group));
            AutomationProperties.SetAutomationId(visible, $"Inspector.Group.Row.{group}.Visible");
            KeyboardNavigation.SetTabIndex(visible, dynamicTabIndex++);
            visible.IsCheckedChanged += (_, _) =>
            {
                var controls = FindGroupRow(group);
                if (controls is { SuppressEvents: false })
                    SetGroupVisibility(group, visible.IsChecked == true);
            };

            var name = new TextBox
            {
                Text = row.Name,
                PlaceholderText = "分组名称",
                IsEnabled = group != 0,
                FontSize = 12,
                Padding = new Thickness(6, 3)
            };
            AutomationProperties.SetName(name, AvaloniaLocalizationCatalog.Format("Group {0} 名称", group));
            AutomationProperties.SetAutomationId(name, $"Inspector.Group.Row.{group}.Name");
            KeyboardNavigation.SetTabIndex(name, dynamicTabIndex++);
            name.LostFocus += (_, _) => CommitGroupName(group, name.Text);
            name.KeyDown += (_, eventArgs) =>
            {
                if (eventArgs.Key != Key.Enter) return;
                CommitGroupName(group, name.Text);
                eventArgs.Handled = true;
            };

            var swatch = new Border
            {
                Width = 18,
                Height = 14,
                CornerRadius = new CornerRadius(3),
                Background = color
            };
            var colorButton = new Button
            {
                Content = swatch,
                Width = 32,
                Height = 26,
                Padding = new Thickness(0),
                Margin = new Thickness(4, 0, 0, 0),
                IsEnabled = group != 0
            };
            ApplyWpfToolButtonStyle(colorButton);
            AutomationProperties.SetName(colorButton, AvaloniaLocalizationCatalog.Format("Group {0} 颜色", group));
            AutomationProperties.SetAutomationId(colorButton, $"Inspector.Group.Row.{group}.Color");
            ToolTip.SetTip(colorButton, "分组颜色：点击自定义");
            KeyboardNavigation.SetTabIndex(colorButton, dynamicTabIndex++);
            colorButton.Click += (_, _) => OpenGroupColorPopup(group, colorButton);

            ComboBox? parentCombo = null;
            var parentIds = new List<int?> { null };
            if (showSubGroups)
            {
                var parentLabels = new List<string> { "层级：顶层" };
                if (group != 0)
                {
                    var forbidden = tab.GroupCatalog.Descendants(group);
                    foreach (var candidate in tab.GroupCatalog.FlattenedOrder())
                    {
                        if (candidate == group || forbidden.Contains(candidate)) continue;
                        parentLabels.Add(string.Concat(
                            new string(' ', Math.Min(6, tab.GroupCatalog.DepthOf(candidate)) * 2),
                            tab.GroupCatalog.NameOf(candidate)));
                        parentIds.Add(candidate);
                    }
                }
                parentCombo = new ComboBox
                {
                    ItemsSource = parentLabels,
                    SelectedIndex = Math.Max(0, parentIds.FindIndex(id => id == row.ParentId)),
                    IsEnabled = group != 0,
                    FontSize = 11,
                    HorizontalAlignment = HorizontalAlignment.Stretch
                };
                AutomationProperties.SetName(
                    parentCombo,
                    AvaloniaLocalizationCatalog.Format("Group {0} 父分组", group));
                AutomationProperties.SetAutomationId(
                    parentCombo,
                    $"Inspector.Group.Row.{group}.Parent");
                ToolTip.SetTip(parentCombo, "分组的分组：把这一组挂到另一组下面");
                KeyboardNavigation.SetTabIndex(parentCombo, dynamicTabIndex++);
                parentCombo.SelectionChanged += (_, _) =>
                {
                    var controls = FindGroupRow(group);
                    if (controls is not { SuppressEvents: false }) return;
                    var index = parentCombo.SelectedIndex;
                    if (index >= 0 && index < parentIds.Count)
                        CommitGroupParent(group, parentIds[index]);
                };
            }

            var use = PrimaryButton(row.IsCurrent ? "当前" : "使用", (_, _) =>
            {
                WindowsGroupManagerCommand.SetPlacementGroup(tab, group);
                groupIdBox.Text = group.ToString(CultureInfo.InvariantCulture);
                viewModel.SetStatus(group == 0
                    ? "新放置的 Note 将不分组"
                    : AvaloniaLocalizationCatalog.Format("新放置的 Note 将进入 Group {0}", group) +
                      GroupFiledIntoPresetSuffix(tab, group));
                RefreshGroupPanel();
            });
            ApplyWpfToolButtonStyle(use);
            use.Padding = new Thickness(7, 5);
            use.Margin = new Thickness(3, 0, 0, 0);
            use.IsEnabled = !row.IsCurrent;
            AutomationProperties.SetName(use, AvaloniaLocalizationCatalog.Format("Group {0} 使用", group));
            AutomationProperties.SetAutomationId(use, $"Inspector.Group.Row.{group}.Use");
            KeyboardNavigation.SetTabIndex(use, dynamicTabIndex++);

            Button? child = null;
            if (showSubGroups)
            {
                child = PrimaryButton("＋子", (_, _) => CreateChildGroup(group));
                ApplyWpfToolButtonStyle(child);
                child.Padding = new Thickness(7, 5);
                child.Margin = new Thickness(3, 0, 0, 0);
                child.IsEnabled = group != 0 && !tab.Session.IsReadOnly;
                AutomationProperties.SetName(
                    child,
                    AvaloniaLocalizationCatalog.Format("Group {0} 新建子分组", group));
                AutomationProperties.SetAutomationId(child, $"Inspector.Group.Row.{group}.Child");
                ToolTip.SetTip(child, "新建一个挂在这一组下面的子分组");
                KeyboardNavigation.SetTabIndex(child, dynamicTabIndex++);
            }

            var dissolve = PrimaryButton("解散", (_, _) => DissolveGroup(group));
            ApplyWpfToolButtonStyle(dissolve);
            dissolve.Padding = new Thickness(7, 5);
            dissolve.Margin = new Thickness(3, 0, 0, 0);
            dissolve.IsEnabled = group != 0 && row.IsVisible &&
                                 !tab.Session.IsReadOnly && tab.Session.CanEditNotes;
            AutomationProperties.SetName(dissolve, AvaloniaLocalizationCatalog.Format("Group {0} 解散", group));
            AutomationProperties.SetAutomationId(dissolve, $"Inspector.Group.Row.{group}.Dissolve");
            KeyboardNavigation.SetTabIndex(dissolve, dynamicTabIndex++);

            var stats = new TextBlock
            {
                Text = BuildGroupStatsText(row),
                Foreground = MutedBrush,
                FontSize = 10,
                TextTrimming = TextTrimming.CharacterEllipsis
            };

            var headerLine = new Grid { ColumnDefinitions = new ColumnDefinitions("Auto,*,Auto") };
            headerLine.Children.Add(visible);
            Grid.SetColumn(name, 1);
            headerLine.Children.Add(name);
            Grid.SetColumn(colorButton, 2);
            headerLine.Children.Add(colorButton);

            var actionsLine = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions(
                    showSubGroups ? "*,Auto,Auto" : "Auto,Auto")
            };
            var column = 0;
            if (parentCombo != null)
            {
                Grid.SetColumn(parentCombo, column++);
                actionsLine.Children.Add(parentCombo);
            }
            Grid.SetColumn(use, column++);
            actionsLine.Children.Add(use);
            if (child != null)
            {
                Grid.SetColumn(child, column++);
                actionsLine.Children.Add(child);
            }
            Grid.SetColumn(dissolve, column);
            actionsLine.Children.Add(dissolve);

            var stack = new StackPanel { Spacing = 4 };
            stack.Children.Add(headerLine);
            stack.Children.Add(actionsLine);
            stack.Children.Add(stats);

            var container = new Border
            {
                Background = row.IsCurrent ? PanelBrush : Brushes.Transparent,
                BorderBrush = row.IsCurrent ? AccentBrush : StrokeBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Padding = new Thickness(7, 6),
                Child = stack
            };
            if (showSubGroups && row.Depth > 0)
                container.Margin = new Thickness(Math.Min(18, row.Depth * 10), 0, 0, 0);
            AutomationProperties.SetAutomationId(container, $"Inspector.Group.Row.{group}");

            groupListPanel.Children.Add(container);
            groupRows.Add(new GroupRowControls(
                group,
                visible,
                name,
                colorButton,
                parentCombo,
                parentIds,
                use,
                child,
                dissolve,
                stats,
                container));
        }
    }

    /// <summary>
    /// One scheme's tab. Clicking it re-groups the chart by that scheme — and
    /// brings its own group roster onto the panel with it — while right-clicking
    /// puts a box where the label was, the way a browser tab renames. There is no
    /// 全部 tab: a chart starts with no scheme selected and deleting the selected
    /// one goes back to that, and in both states the panel lists every group,
    /// because a grouping no scheme owns is every group's equal.
    ///
    /// The colours are the WPF 1.1.0 TabItem theme's own, so the preset row and
    /// the inspector's tab row above it read as one control: muted label,
    /// #22272A plate and a 2-DIP #7FA4A7 underline on the active tab.
    /// </summary>
    private Control BuildPresetTab(
        DesktopChartTab tab,
        int preset,
        int noteCount,
        ref int dynamicTabIndex)
    {
        var isActive = tab.ActiveGroupPreset == preset;
        var button = new Button
        {
            Content = PresetTabLabel(tab, preset, noteCount, isActive),
            Padding = new Thickness(11, 6),
            MinHeight = 32,
            HorizontalAlignment = HorizontalAlignment.Left,
            VerticalAlignment = VerticalAlignment.Bottom,
            CornerRadius = new CornerRadius(0),
            BorderThickness = new Thickness(0, 0, 0, 2)
        };
        ApplyPresetTabAppearance(button, isActive);
        button.Click += (_, _) => UseGroupPreset(preset);
        button.PointerEntered += (_, _) =>
        {
            if (tab.ActiveGroupPreset != preset) ApplyPresetTabAppearance(button, false, hovered: true);
        };
        button.PointerExited += (_, _) =>
        {
            if (tab.ActiveGroupPreset != preset) ApplyPresetTabAppearance(button, false);
        };
        AutomationProperties.SetName(
            button,
            AvaloniaLocalizationCatalog.Format(
                "分组预设「{0}」标签{1}",
                tab.GroupCatalog.PresetNameOf(preset),
                isActive ? "（当前）" : string.Empty));
        AutomationProperties.SetAutomationId(
            button,
            $"Inspector.Group.Preset.{preset}.Tab");
        ToolTip.SetTip(
            button,
            AvaloniaLocalizationCatalog.Format(
                "切到「{0}」：整张谱会按这个预设重新分组。右键这个标签可以改名",
                tab.GroupCatalog.PresetNameOf(preset)));
        KeyboardNavigation.SetTabIndex(button, dynamicTabIndex++);
        groupPresetTabButtons[preset] = button;
        groupPresetTabCounts[preset] = noteCount;

        // A Button consumes the press itself, so the right-click has to be
        // caught on the way down (the tunnel route) or it never arrives. The
        // swap itself is safe here: it replaces the button's content and
        // leaves the button in place, so nothing is pulled out from under
        // the event that asked for it.
        button.AddHandler(
            InputElement.PointerPressedEvent,
            (_, eventArgs) =>
            {
                if (!eventArgs.GetCurrentPoint(button).Properties.IsRightButtonPressed) return;
                eventArgs.Handled = true;
                BeginPresetRename(preset);
            },
            RoutingStrategies.Tunnel);

        if (preset == groupPresetScrollTarget)
        {
            // 新建预设 appends its tab to a strip that can grow past the panel,
            // so without this the button would look like it did nothing at all.
            groupPresetScrollTarget = 0;
            Dispatcher.UIThread.Post(
                () => button.BringIntoView(),
                DispatcherPriority.Loaded);
        }

        return button;
    }

    /// <summary>The caption on a scheme tab: its name plus how many notes it groups.</summary>
    private static TextBlock PresetTabLabel(
        DesktopChartTab tab,
        int preset,
        int noteCount,
        bool isActive)
    {
        var label = tab.GroupCatalog.PresetNameOf(preset);
        return new TextBlock
        {
            Text = noteCount == 0
                ? label
                : AvaloniaLocalizationCatalog.Format("{0} ({1})", label, noteCount),
            Foreground = isActive ? Brushes.White : MutedBrush,
            FontSize = 12,
            VerticalAlignment = VerticalAlignment.Center
        };
    }

    /// <summary>Paints a drawer tab in the skin's tab colours.</summary>
    private static void ApplyPresetTabAppearance(Button button, bool isActive, bool hovered = false)
    {
        button.Background = isActive
            ? RaisedBrush
            : hovered
                ? PresetTabHoverBrush
                : Brushes.Transparent;
        button.BorderBrush = isActive ? AccentBrush : Brushes.Transparent;
        if (button.Content is TextBlock label)
            label.Foreground = isActive
                ? Brushes.White
                : hovered
                    ? PresetTabHoverForeground
                    : MutedBrush;
    }

    /// <summary>
    /// The box that takes a tab's place while its drawer is renamed. It is built
    /// here and swapped into the live tab by BeginPresetRename — never rendered
    /// by rebuilding the strip — because a rebuild detaches the box, and the
    /// commit that detaching raises would then rebuild the strip from inside the
    /// rebuild that is still running.
    /// </summary>
    private TextBox BuildPresetRenameBox(DesktopChartTab tab, int preset)
    {
        var box = new TextBox
        {
            Text = tab.GroupCatalog.FindPreset(preset)?.Name ?? string.Empty,
            PlaceholderText = ChartGroupCatalog.DefaultPresetName(preset),
            FontSize = 12,
            Padding = new Thickness(6, 2),
            MinWidth = 96,
            VerticalAlignment = VerticalAlignment.Center
        };
        AutomationProperties.SetName(
            box,
            AvaloniaLocalizationCatalog.Format("预设 {0} 名称", preset));
        AutomationProperties.SetAutomationId(box, $"Inspector.Group.Preset.{preset}.Name");
        box.LostFocus += (_, _) =>
        {
            // Only the tab that actually hosts a box commits. ClosePresetRenameBox
            // clears the host before it takes the box off screen, so the focus
            // loss caused by putting it away ourselves lands here as a no-op.
            if (groupPresetRenameHost != preset) return;
            // Checked one message later rather than here: focus can blink away
            // for a frame while the panel lays out, and a box that closed itself
            // the instant it opened would read as a rename button that does
            // nothing. The re-focus posted by BeginPresetRename runs at a higher
            // priority, so a box that is focused again never reaches this check.
            Dispatcher.UIThread.Post(
                () =>
                {
                    if (groupPresetRenameHost != preset) return;
                    if (ReferenceEquals(groupPresetRenameBox, box) && box.IsFocused) return;
                    CommitPresetName(preset, box.Text);
                },
                DispatcherPriority.Background);
        };
        box.KeyDown += (_, eventArgs) =>
        {
            if (eventArgs.Key == Key.Enter)
            {
                CommitPresetName(preset, box.Text);
                eventArgs.Handled = true;
            }
            else if (eventArgs.Key == Key.Escape)
            {
                CancelPresetRename();
                eventArgs.Handled = true;
            }
        };
        return box;
    }

    private void UpdateGroupRows(DesktopChartTab tab, WindowsGroupManagerSnapshot snapshot)
    {
        foreach (var row in snapshot.Rows)
        {
            var controls = FindGroupRow(row.Group);
            // A row with no controls is simply not in the scheme on screen — the
            // panel only builds that scheme's roster — so it is skipped, not a
            // sign that the set changed under us.
            if (controls == null) continue;
            var color = ResolveGroupBrush(tab, row.Group, row.ColorText);
            controls.SuppressEvents = true;
            try
            {
                if (controls.Visible.IsChecked != row.IsVisible)
                    controls.Visible.IsChecked = row.IsVisible;
                controls.Visible.Foreground = color;
                if (!controls.Name.IsFocused && controls.Name.Text != row.Name)
                    controls.Name.Text = row.Name;
                if (controls.Color.Content is Border swatch) swatch.Background = color;
                controls.Stats.Text = BuildGroupStatsText(row);
                var label = row.IsCurrent ? "当前" : "使用";
                if (!string.Equals(controls.Use.Content as string, label, StringComparison.Ordinal))
                    controls.Use.Content = label;
                controls.Use.IsEnabled = !row.IsCurrent;
                controls.Dissolve.IsEnabled = row.Group != 0 && row.IsVisible &&
                                              !tab.Session.IsReadOnly && tab.Session.CanEditNotes;
                controls.Container.Background = row.IsCurrent ? PanelBrush : Brushes.Transparent;
                controls.Container.BorderBrush = row.IsCurrent ? AccentBrush : StrokeBrush;
                // The parent selector is null while the sub-group column is
                // hidden, which is the default.
                if (controls.Parent is { } parent)
                {
                    var parentIndex = IndexOf(controls.ParentIds, row.ParentId);
                    if (parentIndex >= 0 && parent.SelectedIndex != parentIndex)
                        parent.SelectedIndex = parentIndex;
                }
            }
            finally
            {
                controls.SuppressEvents = false;
            }
        }
    }

    private static int IndexOf(IReadOnlyList<int?> ids, int? value)
    {
        for (var slot = 0; slot < ids.Count; slot++)
            if (ids[slot] == value)
                return slot;
        return -1;
    }

    private AnnotationRowControls? FindAnnotationRow(int annotation)
    {
        foreach (var controls in annotationRows)
            if (controls.Annotation == annotation)
                return controls;
        return null;
    }

    private GroupRowControls? FindGroupRow(int group)
    {
        foreach (var row in groupRows)
            if (row.Group == group)
                return row;
        return null;
    }

    private static string BuildGroupStatsText(WindowsGroupManagerRow row) => string.Concat(
        row.NoteCount.ToString("N0", CultureInfo.InvariantCulture),
        " Notes · ",
        row.DominantSound ?? "未指定 Key 音");

    /// <summary>
    /// How many notes the scheme on screen actually groups. Read from the chart
    /// rather than from the preset, because the active scheme keeps its table in
    /// the document and only hands it back when the mapper switches away.
    /// </summary>
    private static int CountGroupedNotes(DesktopChartTab tab) =>
        tab.Session.Document.Notes.Count(note => !note.IsDraft && note.Group != 0);

    /// <summary>
    /// "…, and it joined 预设「X」", or nothing when no scheme is on screen (where
    /// every group is listed anyway). A group that quietly becomes part of one
    /// reading and not the others is the whole point of a scheme owning its own
    /// roster, so the status line says which reading it joined instead of leaving
    /// the next scheme switch to look like it lost something.
    /// </summary>
    private static string GroupFiledIntoPresetSuffix(DesktopChartTab tab, int group)
    {
        if (group == 0) return string.Empty;
        if (tab.ActiveGroupPreset is not { } preset) return string.Empty;
        if (tab.GroupCatalog.GroupIdsOf(preset).Contains(group) is false) return string.Empty;
        return AvaloniaLocalizationCatalog.Format(
            "；它归入当前分组预设「{0}」",
            tab.GroupCatalog.PresetNameOf(preset));
    }

    private static IBrush ResolveGroupBrush(
        DesktopChartTab tab,
        int group,
        string colorText)
    {
        if (group == 0) return new SolidColorBrush(Color.Parse("#FF70787C"));
        var text = string.IsNullOrWhiteSpace(colorText) ? tab.GroupCatalog.ColorOf(group) : colorText;
        if (ChartGroupCatalog.IsValidColorText(text) && Color.TryParse(text.Trim(), out var parsed))
            return new SolidColorBrush(parsed);
        return TimelineSurface.GetGroupBrush(group);
    }

    private void CommitGroupName(int group, string? text)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || group == 0) return;
        if (!WindowsGroupManagerCommand.RenameGroup(tab, group, text)) return;
        MarkGroupCatalogDirty(tab);
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "Group {0} 已重命名为「{1}」",
            group,
            tab.GroupCatalog.NameOf(group)));
        RefreshGroupPanel();
    }

    private void CreateGroupPreset()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var preset = WindowsGroupManagerCommand.CreatePresetAndUse(tab);
        MarkGroupCatalogDirty(tab);
        groupPresetScrollTarget = preset;
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "已新建预设「{0}」：分组和分组列表都是当前预设的副本，改它不影响别的预设",
            tab.GroupCatalog.PresetNameOf(preset)));
        RefreshGroupPanel();
    }

    /// <summary>
    /// Right-clicking a tab and this button do the same thing: put that drawer's
    /// name into a box where the label was. Pressing the button while its own
    /// drawer is already being renamed cancels, so one control both enters and
    /// leaves the mode.
    ///
    /// Every press ends in either a box or a sentence, never in nothing. With no
    /// scheme on screen this provides one — the chart's own while it still has an
    /// empty table to adopt, otherwise a fresh 预设 N that is a copy of the
    /// current grouping — because a mapper who presses 重命名 has come to name
    /// their schemes and has nothing to gain from being told there is nothing to
    /// name. 删除 puts it back.
    /// </summary>
    private void TogglePresetRenameMode()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            viewModel.SetStatus("先打开一张谱面，再来改它预设的名字");
            return;
        }

        var opened = false;
        if (tab.ActiveGroupPreset is not { } preset)
        {
            // Adopting only lands while a scheme still has an empty table, so the
            // fallback is a fresh scheme copied from the grouping on screen —
            // either way the press ends on a scheme that can be named.
            if (WindowsGroupManagerCommand.AdoptPresetForLoadedChart(tab) &&
                tab.ActiveGroupPreset is { } adopted)
                preset = adopted;
            else
                preset = WindowsGroupManagerCommand.CreatePresetAndUse(tab);
            MarkGroupCatalogDirty(tab);
            groupPanelSignature = string.Empty;
            RefreshGroupPanel();
            opened = true;
        }

        if (groupPresetRenameHost == preset)
        {
            CancelPresetRename();
            return;
        }

        // The strip is rebuilt from a signature, so the tab for the drawer just
        // chosen can still be one refresh away. Rebuilding here — in front of
        // the open rather than inside it — is what keeps "the rename button did
        // nothing" off the table, because the tab the box replaces is found by
        // then.
        if (!groupPresetTabButtons.ContainsKey(preset))
        {
            groupPanelSignature = string.Empty;
            RefreshGroupPanel();
        }

        BeginPresetRename(preset);
        if (opened)
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "「{0}」就是当前的分组预设；改完按 Enter，Esc 取消",
                tab.GroupCatalog.PresetNameOf(preset)));
    }

    /// <summary>
    /// Puts a box where the drawer's label is. Nothing is rebuilt: the strip is
    /// left exactly as it is and only one tab's content changes, which is what
    /// keeps the caret and the button both alive — a rebuild here would take the
    /// box off screen the moment it appeared.
    /// </summary>
    private void BeginPresetRename(int preset)
    {
        if (preset == 0) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (groupPresetRenameHost == preset) return;
        // Only one box exists at a time; opening a second puts the first back
        // without committing anything.
        ClosePresetRenameBox();
        if (!groupPresetTabButtons.TryGetValue(preset, out var host))
        {
            // Reachable only if the strip is showing a drawer its own bookkeeping
            // does not know about. Saying so beats a press that appears to do
            // nothing at all; the next press rebuilds and lands. The panel is not
            // invalidated here: a rebuild raised by this very refresh would take
            // the box off screen as soon as it was put on.
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "「{0}」这个预设不在面板上，再点一次重命名",
                tab.GroupCatalog.PresetNameOf(preset)));
            return;
        }

        var box = BuildPresetRenameBox(tab, preset);
        groupPresetRenameHost = preset;
        groupPresetRenameBox = box;
        groupPresetRenameTabId = tab.Id;
        host.Content = box;
        AutomationProperties.SetName(
            host,
            AvaloniaLocalizationCatalog.Format("预设「{0}」正在改名", tab.GroupCatalog.PresetNameOf(preset)));
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "重命名「{0}」：改完按 Enter，Esc 取消",
            tab.GroupCatalog.PresetNameOf(preset)));
        // The box is brand new, so it has not been laid out yet; focus it from
        // the dispatcher, which also keeps this off the pointer route that may
        // have asked for it. A box that cannot take focus on the first try is
        // retried a couple of messages later, because one that is up but
        // keyboard-deaf reads as the rename having failed.
        void FocusBox(int attempt)
        {
            if (!ReferenceEquals(groupPresetRenameBox, box)) return;
            box.Focus();
            box.SelectAll();
            if (box.IsFocused || attempt >= 3) return;
            Dispatcher.UIThread.Post(
                () => FocusBox(attempt + 1),
                DispatcherPriority.Background);
        }

        Dispatcher.UIThread.Post(() => FocusBox(0), DispatcherPriority.Input);
        // Paired with the "flushed" line in FlushPresetRename: together they say
        // whether a rename that looked like nothing opened no box, or opened one
        // that something took away.
        WindowsDiagnosticLog.Current?.WriteLifecycle("preset-rename-opened");
    }

    private void CancelPresetRename()
    {
        if (groupPresetRenameHost == 0) return;
        ClosePresetRenameBox();
    }

    /// <summary>
    /// Takes the box off its tab and puts the label back. The rename state is
    /// cleared before the box is detached, because detaching a focused control
    /// raises LostFocus and that handler commits: it has to see that the box
    /// being taken away is not a user finishing an edit.
    /// </summary>
    private void ClosePresetRenameBox()
    {
        var host = groupPresetRenameHost;
        var box = groupPresetRenameBox;
        groupPresetRenameHost = 0;
        groupPresetRenameBox = null;
        groupPresetRenameTabId = Guid.Empty;
        if (host == 0 || box == null) return;
        if (!groupPresetTabButtons.TryGetValue(host, out var button)) return;
        if (!ReferenceEquals(button.Content, box)) return;
        var tab = viewModel.ActiveTab;
        var count = groupPresetTabCounts.TryGetValue(host, out var stored) ? stored : 0;
        var isActive = tab?.ActiveGroupPreset == host;
        button.Content = tab == null
            ? null
            : PresetTabLabel(tab, host, count, isActive);
        ApplyPresetTabAppearance(button, isActive);
        AutomationProperties.SetName(
            button,
            tab == null
                ? "预设标签"
                : AvaloniaLocalizationCatalog.Format(
                    "预设「{0}」标签{1}",
                    tab.GroupCatalog.PresetNameOf(host),
                    isActive ? "（当前）" : string.Empty));
    }

    /// <summary>Throws the box away without committing what was typed.</summary>
    private void DiscardPresetRename()
    {
        var host = groupPresetRenameHost;
        var box = groupPresetRenameBox;
        groupPresetRenameHost = 0;
        groupPresetRenameBox = null;
        groupPresetRenameTabId = Guid.Empty;
        if (box == null || host == 0) return;
        if (!groupPresetTabButtons.TryGetValue(host, out var button)) return;
        if (!ReferenceEquals(button.Content, box)) return;
        // Every caller rebuilds the strip right after, so the tab can go blank on
        // the way out; what matters is that the box leaves the tab before the
        // focus it holds is lost, or that loss would commit the abandoned text.
        button.Content = null;
    }

    /// <summary>
    /// Commits a pending rename because the strip is being rebuilt underneath
    /// it. It writes to the catalog and stops there: refreshing from inside the
    /// rebuild that called this would re-enter it.
    /// </summary>
    private void FlushPresetRename()
    {
        var preset = groupPresetRenameHost;
        var box = groupPresetRenameBox;
        if (preset == 0 || box == null)
        {
            DiscardPresetRename();
            return;
        }
        var text = box.Text;
        // The one occurrence worth a log line: a box that was open when the panel
        // rebuilt underneath it. On screen it is indistinguishable from a box
        // that never appeared, and the difference decides where the fault is.
        WindowsDiagnosticLog.Current?.WriteLifecycle("preset-rename-flushed-by-rebuild");
        ClosePresetRenameBox();
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (WindowsGroupManagerCommand.RenamePreset(tab, preset, text))
            MarkGroupCatalogDirty(tab);
    }

    /// <summary>
    /// Removes the active preset. The groups inside it survive — only the drawer
    /// goes — so deleting a preset can never cost a mapper their grouping.
    /// </summary>
    private void DeleteActiveGroupPreset()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.ActiveGroupPreset is not { } preset)
        {
            viewModel.SetStatus("先点一个分组预设的标签，再删除它");
            return;
        }
        DeleteGroupPreset(preset);
    }

    private void DeleteGroupPreset(int preset)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var name = tab.GroupCatalog.PresetNameOf(preset);
        // A box on the scheme being deleted has nowhere to live afterwards, and
        // its text would be written to a scheme that no longer exists.
        if (groupPresetRenameHost == preset) DiscardPresetRename();
        if (!WindowsGroupManagerCommand.RemovePreset(tab, preset)) return;
        MarkGroupCatalogDirty(tab);
        groupPanelSignature = string.Empty;
        viewModel.SetStatus(tab.ActiveGroupPreset is null
            ? AvaloniaLocalizationCatalog.Format(
                "已删除预设「{0}」；谱面当前的分组不变，分组列表回到显示全部分组",
                name)
            : AvaloniaLocalizationCatalog.Format(
                "已删除预设「{0}」；谱面当前的分组不变",
                name));
        RefreshGroupPanel();
    }

    private void CommitPresetName(int preset, string? text)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var renamed = WindowsGroupManagerCommand.RenamePreset(tab, preset, text);
        if (renamed) MarkGroupCatalogDirty(tab);
        // Closed last, so the label it puts back carries the name that was just
        // written — and it clears the host before detaching the box, which is
        // what stops the LostFocus that follows from committing again.
        if (groupPresetRenameHost == preset) ClosePresetRenameBox();
        // Said out loud even when the text did not change: a rename that quietly
        // keeps the old name looks exactly like a rename that never opened.
        viewModel.SetStatus(renamed
            ? AvaloniaLocalizationCatalog.Format(
                "预设已重命名为「{0}」",
                tab.GroupCatalog.PresetNameOf(preset))
            : AvaloniaLocalizationCatalog.Format(
                "「{0}」的名字没有变",
                tab.GroupCatalog.PresetNameOf(preset)));
    }

    /// <summary>
    /// Switches grouping schemes. This is the one preset action that touches the
    /// chart: the scheme on screen hands its assignments back and the next one
    /// writes its own, so the notes are re-grouped in one undoable step.
    /// </summary>
    private void UseGroupPreset(int preset)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.ActiveGroupPreset == preset) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditNotes)
        {
            // Switching re-groups the chart, so on a chart that cannot be
            // edited there is nothing this press could honestly do.
            viewModel.SetStatus("当前谱面为只读，切换预设需要能改动 Note 分组");
            return;
        }
        var regrouped = WindowsGroupManagerCommand.SetActivePreset(tab, preset);
        MarkGroupCatalogDirty(tab);
        viewModel.SetStatus(regrouped
            ? AvaloniaLocalizationCatalog.Format(
                "已切到预设「{0}」：整张谱按它重新分组，分组列表也换成它的分组（Ctrl+Z 可以撤销）",
                tab.GroupCatalog.PresetNameOf(preset))
            : AvaloniaLocalizationCatalog.Format(
                "已切到预设「{0}」：这张谱的分组本来就与它一致，分组列表已换成它的分组",
                tab.GroupCatalog.PresetNameOf(preset)));
        RefreshGroupPanel();
    }

    // ---- 批注预设 -----------------------------------------------------------
    // The annotation-side twin of the preset commands above, but deliberately
    // the other way round: a group preset *is* the grouping and re-groups the
    // chart when it is selected, while an annotation preset only decides which
    // blocks are drawn. These read and write tab.ActiveAnnotationPreset and the
    // annotation catalog's own preset list, and never look at the group ones.

    /// <summary>Files a block into a drawer, or takes it out when the id is null.</summary>
    private void CommitAnnotationPreset(int annotation, int? presetId)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (!WindowsAnnotationCommand.AssignAnnotationToPreset(tab, annotation, presetId)) return;
        MarkGroupCatalogDirty(tab);
        // Moving a block into another preset takes its row off screen while that
        // preset is the one on screen; saying so is the difference between "it
        // moved" and "it went missing".
        var leftTheDrawer = presetId != tab.ActiveAnnotationPreset;
        viewModel.SetStatus(presetId is { } preset
            ? AvaloniaLocalizationCatalog.Format(
                leftTheDrawer
                    ? "批注 {0} 已归入「{1}」，它跟着离开了当前显示的预设"
                    : "批注 {0} 已放进「{1}」",
                annotation,
                tab.AnnotationCatalog.PresetNameOf(preset))
            : AvaloniaLocalizationCatalog.Format(
                leftTheDrawer
                    ? "批注 {0} 已移出预设，回到「全部」里"
                    : "批注 {0} 已移出预设",
                annotation));
        RefreshAnnotationPanel();
    }

    private void CreateAnnotationPreset()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var preset = WindowsAnnotationCommand.CreatePresetAndUse(tab);
        MarkGroupCatalogDirty(tab);
        annotationPresetScrollTarget = preset;
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "已新建批注预设「{0}」并切了过去：只显示这个预设里的批注",
            tab.AnnotationCatalog.PresetNameOf(preset)));
        RefreshAnnotationPanel();
    }

    /// <summary>
    /// Right-clicking a tab and this button do the same thing: put that drawer's
    /// name into a box where the label was. Mirror of the group version — every
    /// press ends in either a box or a sentence, never in nothing.
    /// </summary>
    private void ToggleAnnotationPresetRenameMode()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            viewModel.SetStatus("先打开一张谱面，再来改它批注预设的名字");
            return;
        }

        var opened = false;
        if (tab.ActiveAnnotationPreset is not { } preset)
        {
            var existing = tab.AnnotationCatalog.Presets.Count > 0;
            preset = existing
                ? tab.AnnotationCatalog.Presets[0].Id
                : WindowsAnnotationCommand.CreatePresetAndUse(tab);
            WindowsAnnotationCommand.SetActivePreset(tab, preset);
            if (!existing) MarkGroupCatalogDirty(tab);
            annotationPanelSignature = string.Empty;
            RefreshAnnotationPanel();
            opened = true;
        }

        if (annotationPresetRenameHost == preset)
        {
            CancelAnnotationPresetRename();
            return;
        }

        // The strip is rebuilt from a signature, so the tab for the drawer just
        // chosen can still be one refresh away; rebuilding in front of the open
        // rather than inside it keeps "the rename button did nothing" off the
        // table, because the tab the box replaces is found by then.
        if (!annotationPresetTabButtons.ContainsKey(preset))
        {
            annotationPanelSignature = string.Empty;
            RefreshAnnotationPanel();
        }

        BeginAnnotationPresetRename(preset);
        if (opened)
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "「{0}」就是当前的批注预设；改完按 Enter，Esc 取消",
                tab.AnnotationCatalog.PresetNameOf(preset)));
    }

    /// <summary>
    /// Puts a box where the drawer's label is. Nothing is rebuilt: the strip is
    /// left exactly as it is and only one tab's content changes, which is what
    /// keeps the caret and the button both alive.
    /// </summary>
    private void BeginAnnotationPresetRename(int preset)
    {
        if (preset == 0) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (annotationPresetRenameHost == preset) return;
        CloseAnnotationPresetRenameBox();
        if (!annotationPresetTabButtons.TryGetValue(preset, out var host))
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "「{0}」这个批注预设不在面板上，再点一次重命名",
                tab.AnnotationCatalog.PresetNameOf(preset)));
            return;
        }

        var box = BuildAnnotationPresetRenameBox(tab, preset);
        annotationPresetRenameHost = preset;
        annotationPresetRenameBox = box;
        annotationPresetRenameTabId = tab.Id;
        host.Content = box;
        AutomationProperties.SetName(
            host,
            AvaloniaLocalizationCatalog.Format(
                "批注预设「{0}」正在改名",
                tab.AnnotationCatalog.PresetNameOf(preset)));
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "重命名批注预设「{0}」：改完按 Enter，Esc 取消",
            tab.AnnotationCatalog.PresetNameOf(preset)));

        void FocusBox(int attempt)
        {
            if (!ReferenceEquals(annotationPresetRenameBox, box)) return;
            box.Focus();
            box.SelectAll();
            if (box.IsFocused || attempt >= 3) return;
            Dispatcher.UIThread.Post(
                () => FocusBox(attempt + 1),
                DispatcherPriority.Background);
        }

        Dispatcher.UIThread.Post(() => FocusBox(0), DispatcherPriority.Input);
    }

    private TextBox BuildAnnotationPresetRenameBox(DesktopChartTab tab, int preset)
    {
        var box = new TextBox
        {
            Text = tab.AnnotationCatalog.FindPreset(preset)?.Name ?? string.Empty,
            PlaceholderText = ChartAnnotationCatalog.DefaultPresetName(preset),
            FontSize = 12,
            Padding = new Thickness(6, 2),
            MinWidth = 96,
            VerticalAlignment = VerticalAlignment.Center
        };
        AutomationProperties.SetName(
            box,
            AvaloniaLocalizationCatalog.Format("批注预设 {0} 名称", preset));
        AutomationProperties.SetAutomationId(
            box,
            $"Inspector.Annotation.Preset.{preset}.Name");
        box.LostFocus += (_, _) =>
        {
            // Only the tab that actually hosts a box commits, and the check runs
            // one message later: a box that closed itself the instant it opened
            // would read as a rename button that does nothing.
            if (annotationPresetRenameHost != preset) return;
            Dispatcher.UIThread.Post(
                () =>
                {
                    if (annotationPresetRenameHost != preset) return;
                    if (ReferenceEquals(annotationPresetRenameBox, box) && box.IsFocused) return;
                    CommitAnnotationPresetName(preset, box.Text);
                },
                DispatcherPriority.Background);
        };
        box.KeyDown += (_, eventArgs) =>
        {
            if (eventArgs.Key == Key.Enter)
            {
                CommitAnnotationPresetName(preset, box.Text);
                eventArgs.Handled = true;
            }
            else if (eventArgs.Key == Key.Escape)
            {
                CancelAnnotationPresetRename();
                eventArgs.Handled = true;
            }
        };
        return box;
    }

    private void CancelAnnotationPresetRename()
    {
        if (annotationPresetRenameHost == 0) return;
        CloseAnnotationPresetRenameBox();
    }

    /// <summary>
    /// Takes the box off its tab and puts the label back. The rename state is
    /// cleared before the box is detached, because detaching a focused control
    /// raises LostFocus and that handler commits.
    /// </summary>
    private void CloseAnnotationPresetRenameBox()
    {
        var host = annotationPresetRenameHost;
        var box = annotationPresetRenameBox;
        annotationPresetRenameHost = 0;
        annotationPresetRenameBox = null;
        annotationPresetRenameTabId = Guid.Empty;
        if (host == 0 || box == null) return;
        if (!annotationPresetTabButtons.TryGetValue(host, out var button)) return;
        if (!ReferenceEquals(button.Content, box)) return;
        var tab = viewModel.ActiveTab;
        var count = annotationPresetTabCounts.TryGetValue(host, out var stored) ? stored : 0;
        var isActive = tab?.ActiveAnnotationPreset == host;
        button.Content = tab == null
            ? null
            : AnnotationPresetTabLabel(tab, host, count, isActive);
        ApplyPresetTabAppearance(button, isActive);
        AutomationProperties.SetName(
            button,
            tab == null
                ? "批注预设标签"
                : AvaloniaLocalizationCatalog.Format(
                    "批注预设「{0}」标签{1}",
                    tab.AnnotationCatalog.PresetNameOf(host),
                    isActive ? "（当前）" : string.Empty));
    }

    /// <summary>Throws the box away without committing what was typed.</summary>
    private void DiscardAnnotationPresetRename()
    {
        var host = annotationPresetRenameHost;
        var box = annotationPresetRenameBox;
        annotationPresetRenameHost = 0;
        annotationPresetRenameBox = null;
        annotationPresetRenameTabId = Guid.Empty;
        if (box == null || host == 0) return;
        if (!annotationPresetTabButtons.TryGetValue(host, out var button)) return;
        if (!ReferenceEquals(button.Content, box)) return;
        // Every caller rebuilds the strip right after, so the tab can go blank on
        // the way out; what matters is that the box leaves before the focus it
        // holds is lost, or that loss would commit the abandoned text.
        button.Content = null;
    }

    /// <summary>
    /// Commits a pending rename because the strip is being rebuilt underneath it.
    /// It writes to the catalog and stops there: refreshing from inside the
    /// rebuild that called this would re-enter it.
    /// </summary>
    private void FlushAnnotationPresetRename()
    {
        var preset = annotationPresetRenameHost;
        var box = annotationPresetRenameBox;
        if (preset == 0 || box == null)
        {
            DiscardAnnotationPresetRename();
            return;
        }
        var text = box.Text;
        WindowsDiagnosticLog.Current?.WriteLifecycle(
            "annotation-preset-rename-flushed-by-rebuild");
        CloseAnnotationPresetRenameBox();
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (WindowsAnnotationCommand.RenamePreset(tab, preset, text))
            MarkGroupCatalogDirty(tab);
    }

    /// <summary>
    /// Removes the open drawer. The blocks inside it survive — only the drawer
    /// goes — so deleting a preset can never cost a mapper their annotations.
    /// </summary>
    private void DeleteActiveAnnotationPreset()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.ActiveAnnotationPreset is not { } preset)
        {
            viewModel.SetStatus("先点一个批注预设的标签，再删除它");
            return;
        }
        DeleteAnnotationPreset(preset);
    }

    private void DeleteAnnotationPreset(int preset)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var name = tab.AnnotationCatalog.PresetNameOf(preset);
        // A box on the drawer being deleted has nowhere to live afterwards, and
        // its text would be written to a drawer that no longer exists.
        if (annotationPresetRenameHost == preset) DiscardAnnotationPresetRename();
        if (!WindowsAnnotationCommand.RemovePreset(tab, preset)) return;
        MarkGroupCatalogDirty(tab);
        annotationPanelSignature = string.Empty;
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "已删除批注预设「{0}」；批注本身还在，回「全部」就能看到",
            name));
        RefreshAnnotationPanel();
    }

    private void CommitAnnotationPresetName(int preset, string? text)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var renamed = WindowsAnnotationCommand.RenamePreset(tab, preset, text);
        if (renamed) MarkGroupCatalogDirty(tab);
        // Closed last, so the label it puts back carries the name that was just
        // written — and it clears the host before detaching the box, which is
        // what stops the LostFocus that follows from committing again.
        if (annotationPresetRenameHost == preset) CloseAnnotationPresetRenameBox();
        viewModel.SetStatus(renamed
            ? AvaloniaLocalizationCatalog.Format(
                "批注预设已重命名为「{0}」",
                tab.AnnotationCatalog.PresetNameOf(preset))
            : AvaloniaLocalizationCatalog.Format(
                "「{0}」的名字没有变",
                tab.AnnotationCatalog.PresetNameOf(preset)));
    }

    private void UseAnnotationPreset(int? preset)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || tab.ActiveAnnotationPreset == preset) return;
        WindowsAnnotationCommand.SetActivePreset(tab, preset);
        // Which preset is on screen is persisted with the chart, so the same
        // reading is back the next time it is opened.
        MarkGroupCatalogDirty(tab);
        viewModel.SetStatus(preset is { } id
            ? AvaloniaLocalizationCatalog.Format(
                "当前批注预设「{0}」：只显示这个预设里的批注",
                tab.AnnotationCatalog.PresetNameOf(id))
            : "当前是「全部」：所有批注都显示，包括还没归入任何预设的");
        RefreshAnnotationPanel();
    }

    // ---- 编辑器存档 ---------------------------------------------------------
    // Export / import of the editor-side metadata. The per-chart catalog is keyed
    // by the chart's absolute path, so renaming the folder (or moving the chart,
    // or moving to another machine) takes the group names, the drawers and the
    // annotations with it; this is the way they come back.

    /// <summary>
    /// Writes the chart's editor metadata — group names / colours / drawers, the
    /// grouping on every note, the annotation blocks and their drawers, and the
    /// ProEditor scratch track — to a file the mapper picks. Read-only: it never
    /// touches the chart or the catalog.
    /// </summary>
    private async void ExportEditorArchive()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            viewModel.SetStatus("先打开一张谱面，再导出它的编辑器存档");
            return;
        }

        var archive = WindowsChartMetadataArchiveCodec.Capture(tab);
        var text = WindowsChartMetadataArchiveCodec.Serialize(archive);
        var suggestedName = WindowsChartMetadataArchiveCodec.SuggestedFileName(tab);
        var fileType = new FilePickerFileType("LumaChart 编辑器存档")
        {
            Patterns = ["*.json"]
        };
        try
        {
            string? writtenTo;
            if (PlatformFileExportServices.Current is { } exportPlatform)
            {
                await using var destination =
                    await exportPlatform.PickExportDestinationAsync(suggestedName, "json");
                if (destination == null) return;
                await File.WriteAllTextAsync(destination.StagingPath, text);
                await destination.CommitAsync();
                writtenTo = destination.DisplayName;
            }
            else
            {
                IStorageFolder? startLocation = null;
                var sourceDirectory = Path.GetDirectoryName(tab.SourcePath);
                if (!string.IsNullOrWhiteSpace(sourceDirectory) &&
                    Directory.Exists(sourceDirectory))
                    startLocation = await StorageProvider.TryGetFolderFromPathAsync(sourceDirectory);
                var picked = await StorageProvider.SaveFilePickerAsync(new FilePickerSaveOptions
                {
                    Title = "导出编辑器存档",
                    SuggestedFileName = suggestedName,
                    SuggestedStartLocation = startLocation,
                    DefaultExtension = "json",
                    FileTypeChoices = [fileType],
                    SuggestedFileType = fileType,
                    ShowOverwritePrompt = true
                });
                writtenTo = picked?.TryGetLocalPath();
                if (string.IsNullOrWhiteSpace(writtenTo)) return;
                await File.WriteAllTextAsync(writtenTo, text);
            }

            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "已导出编辑器存档：{0}",
                writtenTo));
            WindowsNativeMessageBox.Show(
                this,
                new WindowsNativeMessageBoxRequest(
                    AvaloniaLocalizationCatalog.Format(
                        "已导出编辑器存档。\n\n{0}\n\n" +
                        "分组 {1} 个 · 分组预设 {2} 个 · Note 的分组 {3} 条 · " +
                        "批注 {4} 块 · 批注预设 {5} 个 · ProEditor Note {6} 个",
                        writtenTo,
                        archive.Groups.Count,
                        archive.GroupPresets.Count,
                        archive.GroupAssignments.Count,
                        archive.Annotations.Count,
                        archive.AnnotationPresets.Count,
                        archive.Drafts.Count),
                    "导出编辑器存档",
                    WindowsNativeMessageBoxIcon.Information));
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "导出编辑器存档失败：{0}",
                AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                new WindowsNativeMessageBoxRequest(
                    AvaloniaLocalizationCatalog.Format(
                        "无法写出存档文件：\n{0}",
                        AvaloniaLocalizationCatalog.Text(exception.Message)),
                    "导出编辑器存档",
                    WindowsNativeMessageBoxIcon.Error));
        }
    }

    /// <summary>
    /// Reads an archive the mapper picks and merges it into the open chart.
    /// Merging — never replacing — is deliberate: the catalog is not undoable, so
    /// an import that cleared the chart first could throw away hours of grouping
    /// in one keystroke. The only step that overwrites the chart is the ProEditor
    /// track, and that one goes through the document, so Ctrl+Z brings it back.
    /// </summary>
    private async void ImportEditorArchive()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            viewModel.SetStatus("先打开一张谱面，再导入编辑器存档");
            return;
        }

        try
        {
            var fileType = new FilePickerFileType("LumaChart 编辑器存档")
            {
                Patterns = ["*.json"]
            };
            var picked = await StorageProvider.OpenFilePickerAsync(new FilePickerOpenOptions
            {
                Title = "导入编辑器存档",
                AllowMultiple = false,
                FileTypeFilter = [fileType]
            });
            var path = picked.Count > 0 ? picked[0].TryGetLocalPath() : null;
            if (string.IsNullOrWhiteSpace(path)) return;

            var parsed = WindowsChartMetadataArchiveCodec.Read(
                await File.ReadAllTextAsync(path));
            if (!parsed.Ok || parsed.Archive is not { } archive)
            {
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                    "导入编辑器存档失败：{0}",
                    parsed.Error));
                WindowsNativeMessageBox.Show(
                    this,
                    new WindowsNativeMessageBoxRequest(
                        parsed.Error.Length > 0 ? parsed.Error : "存档文件无法解析。",
                        "导入编辑器存档",
                        WindowsNativeMessageBoxIcon.Error));
                return;
            }

            var readOnly = !tab.Session.CanEditNotes || tab.Session.IsReadOnly;
            var confirmed = WindowsNativeMessageBox.Show(
                this,
                new WindowsNativeMessageBoxRequest(
                    AvaloniaLocalizationCatalog.Format(
                        "存档来自「{0}」。\n\n" +
                        "分组 {1} 个 · 分组预设 {2} 个 · Note 的分组 {3} 条 · " +
                        "批注 {4} 块 · 批注预设 {5} 个 · ProEditor Note {6} 个\n\n" +
                        "导入是合并：同号的分组 / 批注会被存档里的内容覆盖，其余保持不变，" +
                        "已有的分组和批注不会被删掉。ProEditor 轨道会被存档里的内容替换（可撤销）。{7}",
                        string.IsNullOrWhiteSpace(archive.ChartTitle)
                            ? Path.GetFileName(archive.SourcePath)
                            : archive.ChartTitle,
                        archive.Groups.Count,
                        archive.GroupPresets.Count,
                        archive.GroupAssignments.Count,
                        archive.Annotations.Count,
                        archive.AnnotationPresets.Count,
                        archive.Drafts.Count,
                        readOnly
                            ? "\n\n⚠ 当前谱面是只读 / 无编辑权限，Note 的分组与 ProEditor 轨道不会被导入。"
                            : string.Empty),
                    "导入编辑器存档",
                    WindowsNativeMessageBoxIcon.Question,
                    WindowsNativeMessageBoxButtons.YesNo));
            if (confirmed != WindowsNativeMessageBox.YesResult)
            {
                viewModel.SetStatus("已取消导入编辑器存档");
                return;
            }

            var result = WindowsChartMetadataArchiveCodec.Apply(tab, archive);
            MarkGroupCatalogDirty(tab);
            PersistPendingGroupCatalogs(force: true);
            groupPanelSignature = string.Empty;
            annotationPanelSignature = string.Empty;
            RefreshGroupPanel();
            RefreshAnnotationPanel();
            UpdateNoteInspector(tab);
            UpdateSelectionUi();
            PushGroupVisuals();

            var summary = AvaloniaLocalizationCatalog.Format(
                "已导入编辑器存档：写入分组 {0} 个 · 分组预设 {1} 个 · 批注 {2} 块 · " +
                "批注预设 {3} 个 · ProEditor Note {4} 个{5}",
                result.Groups,
                result.GroupPresets,
                result.Annotations,
                result.AnnotationPresets,
                result.Drafts,
                result.DocumentChanged ? "；谱面已改动，可撤销" : string.Empty);
            viewModel.SetStatus(summary);
            WindowsNativeMessageBox.Show(
                this,
                new WindowsNativeMessageBoxRequest(
                    result.DocumentEditsAllowed
                        ? summary
                        : summary + "\n\n（Note 的分组与 ProEditor 轨道因谱面只读而未导入。）",
                    "导入编辑器存档",
                    WindowsNativeMessageBoxIcon.Information));
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "导入编辑器存档失败：{0}",
                AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                new WindowsNativeMessageBoxRequest(
                    AvaloniaLocalizationCatalog.Format(
                        "无法读入存档文件：\n{0}",
                        AvaloniaLocalizationCatalog.Text(exception.Message)),
                    "导入编辑器存档",
                    WindowsNativeMessageBoxIcon.Error));
        }
    }

    private void CommitGroupParent(int group, int? parentId)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || group == 0) return;
        try
        {
            if (!WindowsGroupManagerCommand.SetGroupParent(tab, group, parentId)) return;
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Text(exception.Message));
            RefreshGroupPanel();
            return;
        }
        MarkGroupCatalogDirty(tab);
        viewModel.SetStatus(parentId is { } parent
            ? AvaloniaLocalizationCatalog.Format(
                "Group {0} 已挂到 Group {1} 下面",
                group,
                parent)
            : AvaloniaLocalizationCatalog.Format("Group {0} 已提升为顶层分组", group));
        RefreshGroupPanel();
    }

    private void OpenGroupColorPopup(int group, Control target)
    {
