        groupColorPopupTitleText.Text = tab == null
            ? AvaloniaLocalizationCatalog.Format("Group {0} 颜色", group)
            : AvaloniaLocalizationCatalog.Format(
                "Group {0} · {1}",
                group,
                tab.GroupCatalog.NameOf(group));
        groupColorHexBox.Text = tab?.GroupCatalog.ColorOf(group) ?? string.Empty;
        groupColorPopup.PlacementTarget = target;
        groupColorPopup.IsOpen = true;
    }

    private void ApplyGroupColorHexFromPopup()
    {
