    /// <summary>
    /// Opens a 批注 block over the current selection and puts the caret in its
    /// text box.
    ///
    /// The block does not touch the chart: it stores which notes it points at,
    /// and the sticky note on the timeline takes its colour from those notes'
    /// group (the stock white when they were never grouped). Notes that were
    /// already grouped keep that grouping — an annotation is a second reading
    /// axis, not a re-tagging.
    /// </summary>
    private void CreateAnnotationFromSelection()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var id = WindowsAnnotationCommand.AddFromSelection(tab);
        if (id == 0)
        {
            viewModel.SetStatus("先在时间轴上选中要批注的 Note，再按「把选中 Note 做成批注」");
            return;
        }
        var annotation = tab.AnnotationCatalog.Find(id);
        MarkGroupCatalogDirty(tab);
        annotationPanelSignature = string.Empty;
        RefreshAnnotationPanel();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
            "已新建批注 {0}，指向 {1} 个 Note；在右侧「批注」页写文字",
            id,
            annotation?.Notes.Count ?? 0));
        // The block is created empty on purpose: one keystroke to mark the spot
        // while looking at the chart, then type where the text is readable.
        var row = annotationRows.FirstOrDefault(candidate => candidate.Annotation == id);
        row?.Text.Focus();
    }

    private void ApplyGroupDisplaySettingsFromUi()
    {
        if (suppressGroupDisplayEvents) return;
        var mode = groupColorModeBox.SelectedIndex switch
        {
            0 => WindowsGroupColorMode.Off,
            2 => WindowsGroupColorMode.Root,
            _ => WindowsGroupColorMode.Leaf
        };
        groupDisplaySettings = new WindowsGroupDisplaySettings
        {
            ColorMode = mode,
            ShowGroupNumbers = groupShowNumbersCheck.IsChecked == true,
            ShowAnnotations = groupShowAnnotationsCheck.IsChecked == true,
            AnnotationsDockRight = groupAnnotationDockRightCheck.IsChecked == true,
            ShowSubGroups = groupShowSubGroupsCheck.IsChecked == true
        }.Normalize();
        groupDisplaySettingsDirty = true;
        groupDisplaySettingsSaveTimer?.Start();
        pushedGroupVisualsRevision = 0;
        PushGroupVisuals();
        // Turning the tree on or off changes which columns a row owns, so the
        // row signature has to be invalidated rather than updated in place.
        groupPanelSignature = string.Empty;
        RefreshGroupPanel();
    }

    private void ApplyGroupDisplaySettingsToUi()
    {
        suppressGroupDisplayEvents = true;
        try
        {
            groupColorModeBox.SelectedIndex = groupDisplaySettings.ColorMode switch
            {
                WindowsGroupColorMode.Off => 0,
                WindowsGroupColorMode.Root => 2,
                _ => 1
            };
            groupShowNumbersCheck.IsChecked = groupDisplaySettings.ShowGroupNumbers;
            groupShowAnnotationsCheck.IsChecked = groupDisplaySettings.ShowAnnotations;
            groupAnnotationDockRightCheck.IsChecked = groupDisplaySettings.AnnotationsDockRight;
            groupShowSubGroupsCheck.IsChecked = groupDisplaySettings.ShowSubGroups;
        }
        finally
        {
            suppressGroupDisplayEvents = false;
        }
    }

    private void PushGroupVisuals()
    {
        var tab = viewModel.ActiveTab;
        var catalog = tab?.GroupCatalog ?? new ChartGroupCatalog();
        var annotations = tab?.AnnotationCatalog ?? new ChartAnnotationCatalog();
        var current = timeline.GroupVisuals;
        if (ReferenceEquals(current.Catalog, catalog) &&
            ReferenceEquals(current.Annotations, annotations) &&
            current.ColorMode == groupDisplaySettings.ColorMode &&
            current.ShowGroupNumbers == groupDisplaySettings.ShowGroupNumbers &&
            current.ShowAnnotations == groupDisplaySettings.ShowAnnotations &&
            current.AnnotationsDockRight == groupDisplaySettings.AnnotationsDockRight &&
            pushedGroupVisualsRevision == groupVisualsRevision)
            return;
        pushedGroupVisualsRevision = groupVisualsRevision;
        timeline.GroupVisuals = new WindowsGroupVisuals
        {
            Catalog = catalog,
            Annotations = annotations,
            // The annotation preset is a display choice, and the timeline is the
            // display: a card the preset filters out has to leave the chart, not
            // just the list beside it.
            VisibleAnnotationIds = annotations.VisibleAnnotationIds(),
            ColorMode = groupDisplaySettings.ColorMode,
            ShowGroupNumbers = groupDisplaySettings.ShowGroupNumbers,
            ShowAnnotations = groupDisplaySettings.ShowAnnotations,
            AnnotationsDockRight = groupDisplaySettings.AnnotationsDockRight
        };
    }

    /// <summary>
    /// Hydrates a tab's group catalog from local storage the first time the tab
    /// becomes active, and seeds a definition for every group its notes already
    /// use, so an imported chart opens with named and coloured groups.
    /// </summary>
    private void EnsureGroupCatalogLoaded(DesktopChartTab tab)
    {
        if (!groupCatalogLoadedTabs.Add(tab.Id)) return;
        var stored = WindowsGroupCatalogStore.Load(tab.SourcePath);
        foreach (var definition in stored.Groups)
            tab.GroupCatalog.Ensure(definition.Id).CopyFrom(definition);
        foreach (var preset in stored.Presets)
            tab.GroupCatalog.EnsurePreset(preset.Id).CopyFrom(preset);
        var storedAnnotations = WindowsGroupCatalogStore.LoadAnnotations(tab.SourcePath);
        foreach (var annotation in storedAnnotations.Annotations)
            tab.AnnotationCatalog.Ensure(annotation.Id).CopyFrom(annotation);
        foreach (var preset in storedAnnotations.Presets)
            tab.AnnotationCatalog.EnsurePreset(preset.Id).CopyFrom(preset);
        WindowsGroupManagerCommand.EnsureDefinitionsFor(tab);
        // The chart file only remembers the scheme that was last on screen, so
        // the active preset has to be re-seeded from those notes rather than
        // trusted from disk: a scheme whose table is stale would re-group the
        // chart to an older reading the moment the mapper switched away.
        WindowsGroupManagerCommand.AdoptPresetForLoadedChart(tab);
        WindowsGroupManagerCommand.CaptureActivePreset(tab);
        MigrateLegacyGroupAnnotations(tab);
        groupVisualsRevision++;
    }

    /// <summary>
    /// Rescues the per-group text a schema-1 catalog stored, which has no field
    /// left to live in. The group itself is the anchor: a block starts out
    /// covering exactly the Notes still carrying that group id, which is what
    /// the text was written about. Writing the catalog back at the current
    /// version retires the old shape, and because only a schema-1 file is read,
    /// the blocks are never minted twice.
    /// </summary>
    private void MigrateLegacyGroupAnnotations(DesktopChartTab tab)
    {
        var legacy = WindowsGroupCatalogStore.LoadLegacyGroupAnnotations(tab.SourcePath);
        if (legacy.Count == 0) return;
        foreach (var (groupId, text) in legacy)
        {
            var keys = tab.Session.Document.Notes
                .Where(note => !note.IsDraft && note.Group == groupId)
                .Select(WindowsAnnotationCommand.NoteKeyFor)
                .Distinct()
                .ToList();
            var annotation = tab.AnnotationCatalog.Ensure(tab.AnnotationCatalog.NextId());
            annotation.Text = text;
            annotation.Notes = keys;
            if (keys.Count > 0) annotation.AnchorBeat = keys.Min(key => key.Beat);
        }
        tab.AnnotationCatalog.Normalize();
        groupVisualsRevision++;
        MarkGroupCatalogDirty(tab);
    }

    private void MarkGroupCatalogDirty(DesktopChartTab tab)
    {
        if (!groupCatalogDirtyTabs.Contains(tab.Id)) groupCatalogDirtyTabs.Add(tab.Id);
        groupVisualsRevision++;
        groupCatalogSaveTimer?.Start();
    }

    /// <summary>
    /// Both catalogs live in one per-chart entry, so one flush writes both.
    /// The annotation list is written even when only groups changed (and the
    /// other way round), because the merge inside the store keeps whichever
    /// half was not passed in.
    /// </summary>
    private void PersistPendingGroupCatalogs(bool force = false)
    {
        if (groupCatalogDirtyTabs.Count == 0)
        {
            if (force) groupCatalogSaveTimer?.Stop();
            return;
        }
        foreach (var id in groupCatalogDirtyTabs.ToArray())
        {
            var tab = viewModel.Tabs.FirstOrDefault(candidate => candidate.Id == id);
            if (tab == null)
            {
                groupCatalogDirtyTabs.Remove(id);
                continue;
            }
            WindowsGroupCatalogStore.Save(tab.SourcePath, tab.GroupCatalog);
            WindowsGroupCatalogStore.SaveAnnotations(tab.SourcePath, tab.AnnotationCatalog);
            groupCatalogDirtyTabs.Remove(id);
        }
        if (force) groupCatalogSaveTimer?.Stop();
    }

    private void PersistPendingGroupDisplaySettings(bool force = false)
    {
        if (!groupDisplaySettingsDirty)
        {
            if (force) groupDisplaySettingsSaveTimer?.Stop();
            return;
        }
        WindowsGroupDisplaySettingsStore.Save(groupDisplaySettings);
        groupDisplaySettingsDirty = false;
        if (force) groupDisplaySettingsSaveTimer?.Stop();
    }
