    /// <summary>
    /// The "加入 / 移出当前使用分组" shortcut. One key does both directions: if
    /// every selected note is already in the active group the press means "take
    /// them out", otherwise it means "put them in". Splitting that over two
    /// shortcuts would only make the mapper remember which one they are on.
    /// </summary>
    private void ToggleSelectionGroupMembership()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.ActivePlacementGroup == 0)
        {
            viewModel.SetStatus("当前分组是「未分组」。先选一个分组，再加入/移出才有意义");
            return;
        }
        try
        {
            var target = tab.ActivePlacementGroup;
            var result = WindowsGroupManagerCommand.ToggleMembership(tab);
            viewModel.SetStatus(result.CandidateCount == 0
                ? "请先选择一个或多个可见、未锁定的 Note"
                : result.Applied
                    ? AvaloniaLocalizationCatalog.Format(
                        "已把 {0} 个 Note 移出 Group {1}",
                        result.ChangedCount,
                        target)
                    : AvaloniaLocalizationCatalog.Format(
                        "已将 {0} 个 Note 加入 Group {1}（单次撤销）",
                        result.ChangedCount,
                        target));
            UpdateSelectionUi();
            RefreshGroupPanel();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "加入 / 移出分组失败：{0}",
                AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

