    private void DissolveGroup(int group) => _ = DissolveGroupAsync(group);

    /// <summary>
    /// 解散 asks first, because the button sits in a row that also carries 使用
    /// and ＋子 and its two halves land in different places: the notes in the
    /// document, the group itself in the editor's own catalog.
    ///
    /// The prompt names the group, says how many notes it takes out of it, and
    /// says that Ctrl+Z brings both back — the count comes from the same rule the
    /// command applies, and the name from the definition the dissolve retires
    /// rather than deletes, so the message is still right on the way out.
    /// </summary>
    private async Task DissolveGroupAsync(int group)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        try
        {
            var name = tab.GroupCatalog.NameOf(group);
            var notes = WindowsGroupManagerCommand.DissolvableNoteCount(tab, group);
            var message = notes > 0
                ? AvaloniaLocalizationCatalog.Format(
                    "「{0}」里的 {1} 个 Note 会变回「未分组」，这个分组会从当前读数里移除。\n\n" +
                    "按 Ctrl+Z 可以一起撤销，分组名也会回来。",
                    name,
                    notes)
                : AvaloniaLocalizationCatalog.Format(
                    "「{0}」里没有可解散的 Note，这个分组会从当前读数里移除。\n\n" +
                    "按 Ctrl+Z 可以撤销，分组名也会回来。",
                    name);
            var confirmed = await new SettingsActionDialog(
                    "解散分组",
                    message,
                    "解散",
                    showCancel: true,
                    dangerous: false,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<bool>(this);
            if (!confirmed) return;

            var result = WindowsGroupManagerCommand.Dissolve(tab, group);
            viewModel.SetStatus(result.Applied
                ? AvaloniaLocalizationCatalog.Format(
                    "已解散「{0}」的 {1} 个 Note（Ctrl+Z 可撤销）", name, result.ChangedCount)
                : AvaloniaLocalizationCatalog.Format(
                    "「{0}」已从当前读数里移除（Ctrl+Z 可撤销）", name));
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("解散 Group 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private bool TryReadGroupId(out int group)
    {
