        catch (FormatException exception)
        {
            group = 0;
            viewModel.SetStatus(exception.Message);
            return false;
        }
    }

    private void UpdateSelectionUi()
    {
        timeline.PruneNonInteractiveNoteSelection();
        UpdateInspector();
        UpdateEditorAvailability();
        // The curve and gap panels report counts for the current selection, so
        // they have to follow it. Skipped while the palette is closed.
        if (extensionPalette.IsVisible)
        {
            RefreshToolboxCurvePreview();
            RefreshToolboxFillPreview();
        }
        timeline.InvalidateVisual();
    }

    private void OpenExistingNoteSounds()
    {
        var tab = viewModel.ActiveTab;
        if (!TryGetEditableSelectedNote(tab, out _)) return;
        var workingRoot = Path.GetDirectoryName(Path.GetFullPath(tab!.WorkingPath));
        if (string.IsNullOrWhiteSpace(workingRoot)) return;
        var onlineRoomChart = IsBoundOnlineRoomChart(tab);
        var sourceRoot = onlineRoomChart || string.IsNullOrWhiteSpace(tab.SourcePath)
            ? null
            : Path.GetDirectoryName(Path.GetFullPath(tab.SourcePath));
        var candidates = CoalesceNoteSoundCandidates(
                ChartAssetImportService.EnumerateNoteSoundCandidates([workingRoot, sourceRoot]),
                workingRoot)
            .Where(candidate => !onlineRoomChart || IsListedFrozenRoomNoteSound(tab, candidate.FullPath))
            .ToArray();

        noteSoundPickerItems.Children.Clear();
        noteSoundPickerFocusableButtons.Clear();
        noteSoundPickerFocusableButtons.Add(noteSoundPickerClearButton);
        noteSoundPickerCountText.Text = AvaloniaLocalizationCatalog.Format("{0} 个", candidates.Length);
        noteSoundPickerEmptyText.Text = onlineRoomChart
            ? "房间资源中没有可用的 Key 音。"
            : "谱面目录中没有可用的音频文件。";
        noteSoundPickerEmptyText.IsVisible = candidates.Length == 0;
        noteSoundPickerScrollViewer.IsVisible = candidates.Length > 0;

        if (candidates.Length == 0)
            noteSoundPickerLastNavigation = "opened-empty";
        else
        {
            var repeatedNames = candidates
                .GroupBy(candidate => candidate.FileName, StringComparer.OrdinalIgnoreCase)
                .Where(group => group.Count() > 1)
                .Select(group => group.Key)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            foreach (var candidate in candidates)
            {
                var displayName = repeatedNames.Contains(candidate.FileName)
                    ? $"{candidate.FileName}  —  {Path.GetFileName(Path.GetDirectoryName(candidate.FullPath))}"
                    : candidate.FileName;
                var item = new Button();
                ConfigureNoteSoundPickerItemButton(
                    item,
                    "♪",
                    displayName,
                    WindowsNoteSoundPickerParityPolicy.SoundGlyph);
                ToolTip.SetTip(item, candidate.FullPath);
                AutomationProperties.SetName(item, displayName);
                AutomationProperties.SetAutomationId(
                    item,
                    $"Inspector.Note.SoundPicker.Item.{noteSoundPickerFocusableButtons.Count - 1}");
                KeyboardNavigation.SetTabIndex(
                    item,
                    noteSoundPickerFocusableButtons.Count);
                var sourcePath = candidate.FullPath;
                item.Click += async (_, _) =>
                {
                    noteSoundExistingPopup.IsOpen = false;
                    await AssignSelectedNoteSoundAsync(tab, sourcePath, import: false);
                };
                noteSoundPickerItems.Children.Add(item);
                noteSoundPickerFocusableButtons.Add(item);
            }
        }

        noteSoundPickerEscapeRestoredFocus = false;
        noteSoundPickerLastRawKey = "none";
        noteSoundPickerLastResolvedKey = "none";
        noteSoundPickerLastInputRoute = "none";
        noteSoundExistingPopup.IsOpen = true;
    }

    private static void ConfigureNoteSoundPickerItemButton(
        Button button,
        string glyph,
        string label,
        string glyphColor)
    {
        button.Foreground = new SolidColorBrush(
            Color.Parse(WindowsNoteSoundPickerParityPolicy.Item));
        button.Background = Brushes.Transparent;
        button.BorderBrush = Brushes.Transparent;
        button.BorderThickness = new Thickness(1);
        button.Padding = new Thickness(
            WindowsNoteSoundPickerParityPolicy.ItemHorizontalPadding,
            WindowsNoteSoundPickerParityPolicy.ItemVerticalPadding);
        button.Margin = new Thickness(0, 1);
        button.HorizontalContentAlignment = HorizontalAlignment.Stretch;
        button.CornerRadius = new CornerRadius(3);
        button.Cursor = new Cursor(StandardCursorType.Hand);

        var text = new TextBlock
        {
            Text = label,
            Foreground = button.Foreground,
            TextTrimming = TextTrimming.CharacterEllipsis,
            VerticalAlignment = VerticalAlignment.Center
        };
        var row = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("22,*"),
            Children =
            {
                new TextBlock
                {
                    Text = glyph,
                    Foreground = new SolidColorBrush(Color.Parse(glyphColor)),
                    FontSize = glyph == "×" ? 15 : 12,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                },
                text
            }
        };
        Grid.SetColumn(text, 1);
        button.Content = row;

        button.PointerEntered += (_, _) =>
        {
            button.Background = new SolidColorBrush(Color.Parse("#263034"));
            button.BorderBrush = new SolidColorBrush(Color.Parse("#4B6267"));
            button.Foreground = Brushes.White;
            text.Foreground = Brushes.White;
        };
        button.PointerExited += (_, _) =>
        {
            button.Background = Brushes.Transparent;
            button.BorderBrush = button.IsFocused
                ? new SolidColorBrush(Color.Parse("#71999C"))
                : Brushes.Transparent;
            button.Foreground = new SolidColorBrush(
                Color.Parse(WindowsNoteSoundPickerParityPolicy.Item));
            text.Foreground = button.Foreground;
        };
        button.GotFocus += (_, _) =>
            button.BorderBrush = new SolidColorBrush(Color.Parse("#71999C"));
        button.LostFocus += (_, _) =>
        {
            if (!button.IsPointerOver) button.BorderBrush = Brushes.Transparent;
        };
    }

    private void NoteSoundPicker_Opened()
    {
        var settings = displayScaleController.CurrentSettings.Normalize();
        var plan = AvaloniaPopupScaleController.Resolve(
            WindowsNoteSoundPickerParityPolicy.ItemFontSize,
            settings);
        if (TopLevel.GetTopLevel(noteSoundPickerSurface) is PopupRoot popupRoot)
            popupRoot.Transform = new ScaleTransform(plan.UiScale, plan.UiScale);

        noteSoundPickerTitleText.FontSize =
            WindowsNoteSoundPickerParityPolicy.HeaderFontSize * plan.FontScale;
        noteSoundPickerSubtitleText.FontSize =
            WindowsNoteSoundPickerParityPolicy.SubtitleFontSize * plan.FontScale;
        noteSoundPickerCountText.FontSize =
            WindowsNoteSoundPickerParityPolicy.CountFontSize * plan.FontScale;
        noteSoundPickerEmptyText.FontSize =
            WindowsNoteSoundPickerParityPolicy.ItemFontSize * plan.FontScale;
        foreach (var button in noteSoundPickerFocusableButtons)
            button.FontSize =
                WindowsNoteSoundPickerParityPolicy.ItemFontSize * plan.FontScale;

        noteSoundPickerScrollViewer.ScrollToHome();
        noteSoundPickerLastNavigation = "opened-clear";
        UpdateNoteSoundPickerAutomation();
        Dispatcher.UIThread.Post(
            () =>
            {
                noteSoundPickerClearButton.Focus();
                UpdateNoteSoundPickerAutomation();
            },
            DispatcherPriority.Input);
    }

    private void NoteSoundPicker_KeyDown(object? sender, KeyEventArgs eventArgs)
    {
        var key = WindowsEditorShortcutGesture.ResolveReportedKey(
            eventArgs.Key,
            eventArgs.PhysicalKey,
            eventArgs.KeySymbol,
            eventArgs.Key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed
                ? WindowsShortcutPhysicalKeyState.TryResolvePressedKey()
                : null);
        noteSoundPickerLastRawKey = eventArgs.Key.ToString();
        noteSoundPickerLastResolvedKey = key.ToString();
        noteSoundPickerLastInputRoute = sender?.GetType().Name ?? "null";
        var focused = FocusManager?.GetFocusedElement() as Button;
        var focusedIndex = focused == null
            ? -1
            : noteSoundPickerFocusableButtons.IndexOf(focused);
        var navigation = WindowsNoteSoundPickerParityPolicy.ResolveNavigation(
            key,
            eventArgs.KeyModifiers,
            focusedIndex,
            noteSoundPickerFocusableButtons.Count);
        if (navigation.Action == WindowsNoteSoundPickerNavigationAction.None)
        {
            UpdateNoteSoundPickerAutomation();
            return;
        }

        eventArgs.Handled = true;
        if (navigation.Action == WindowsNoteSoundPickerNavigationAction.Focus)
        {
            var target = noteSoundPickerFocusableButtons[navigation.TargetIndex];
            target.Focus();
            target.BringIntoView();
            noteSoundPickerLastNavigation =
                $"{key}:{focusedIndex}->{navigation.TargetIndex}";
            UpdateNoteSoundPickerAutomation();
            return;
        }

        noteSoundPickerLastNavigation = "Escape:close-restore";
        noteSoundExistingPopup.IsOpen = false;
        Dispatcher.UIThread.Post(
            () =>
            {
                noteSoundExistingButton.Focus();
                noteSoundPickerEscapeRestoredFocus =
                    ReferenceEquals(FocusManager?.GetFocusedElement(), noteSoundExistingButton);
                UpdateNoteSoundPickerAutomation();
            },
            DispatcherPriority.Input);
    }

    private void UpdateNoteSoundPickerAutomation()
    {
        var focused = FocusManager?.GetFocusedElement() as Button;
        var focusedIndex = focused == null
            ? -1
            : noteSoundPickerFocusableButtons.IndexOf(focused);
        AutomationProperties.SetHelpText(
            noteSoundPickerSurface,
            $"Open={noteSoundExistingPopup.IsOpen}; " +
            $"FocusableCount={noteSoundPickerFocusableButtons.Count}; " +
            $"FocusedIndex={focusedIndex}; " +
            $"LastNavigation={noteSoundPickerLastNavigation}; " +
            $"LastRawKey={noteSoundPickerLastRawKey}; " +
            $"LastResolvedKey={noteSoundPickerLastResolvedKey}; " +
            $"LastInputRoute={noteSoundPickerLastInputRoute}; " +
            $"EscapeRestoredFocus={noteSoundPickerEscapeRestoredFocus}; " +
            $"Width={WindowsNoteSoundPickerParityPolicy.Width:R}; " +
            $"MaxHeight={WindowsNoteSoundPickerParityPolicy.MaxHeight:R}; " +
            $"ScrollMaxHeight={WindowsNoteSoundPickerParityPolicy.ScrollMaxHeight:R}");
        AutomationProperties.SetHelpText(
            noteSoundExistingButton,
            $"PickerOpen={noteSoundExistingPopup.IsOpen}; " +
            $"FocusableCount={noteSoundPickerFocusableButtons.Count}; " +
            $"CandidateCount={Math.Max(0, noteSoundPickerFocusableButtons.Count - 1)}; " +
            $"FocusedIndex={focusedIndex}; " +
            $"EscapeRestoredFocus={noteSoundPickerEscapeRestoredFocus}; " +
            $"LastNavigation={noteSoundPickerLastNavigation}; " +
            $"LastRawKey={noteSoundPickerLastRawKey}; " +
            $"LastResolvedKey={noteSoundPickerLastResolvedKey}; " +
            $"LastInputRoute={noteSoundPickerLastInputRoute}; " +
            $"Width={WindowsNoteSoundPickerParityPolicy.Width:R}; " +
            $"MaxHeight={WindowsNoteSoundPickerParityPolicy.MaxHeight:R}; " +
            $"ScrollMaxHeight={WindowsNoteSoundPickerParityPolicy.ScrollMaxHeight:R}; " +
            $"VerticalOffset={WindowsNoteSoundPickerParityPolicy.VerticalOffset:R}");
    }

    private async Task ImportSelectedNoteSoundAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryGetEditableSelectedNote(tab, out _)) return;
        if (IsBoundOnlineRoomChart(tab!))
        {
            await ShowSettingsMessageAsync(
                "联机中不能新增本地 Key 音",
                ChartWorkspaceSafetyPolicy.OnlineNoteSoundImportBlockedMessage);
            return;
        }

        string? sourcePath;
        try
        {
            sourcePath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择 Note Key 音",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("音频文件")
                        {
                            Patterns = ["*.wav", "*.ogg", "*.mp3", "*.flac", "*.m4a", "*.aac"],
                            MimeTypes = ["audio/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient);
        }
        catch (Exception exception)
        {
            // Button handler boundary for the picker; the assignment below
            // reports its own failures.
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("设置 Note Key 音失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            return;
        }
        if (string.IsNullOrWhiteSpace(sourcePath)) return;
        await AssignSelectedNoteSoundAsync(tab!, Path.GetFullPath(sourcePath), import: true);
    }

    private async Task AssignSelectedNoteSoundAsync(
        DesktopChartTab tab,
        string? sourcePath,
        bool import)
    {
        ChartAssetImportResult? imported = null;
        try
        {
            var sound = sourcePath;
            if (import && !string.IsNullOrWhiteSpace(sourcePath))
            {
                imported = await Task.Run(() => ChartAssetImportService.ImportNoteSound(
                    tab.WorkingPath,
                    sourcePath,
                    tab.SourcePath));
                sound = imported.FileName;
            }
            else if (!string.IsNullOrWhiteSpace(sound))
            {
                sound = Path.GetFileName(sound);
            }

            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new OperationCanceledException("选择 Key 音期间已切换谱面。");
            var soundPolicy = await CreateNoteSoundAssignmentPolicyAsync(tab, sound);
            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new OperationCanceledException("校验 Key 音期间已切换谱面。");
            var result = WindowsNotePropertyCommand.AssignSound(
                tab.Session,
                sound,
                soundPolicy,
                tab.HiddenGroups);
            noteSoundBox.Text = result.Sound ?? string.Empty;
            viewModel.SetStatus(result.Sound == null
                ? "已清除当前 Note 的 Key 音引用；音频文件本身未删除"
                : import
                    ? AvaloniaLocalizationCatalog.Format("Key 音已复制为 {0}；保存谱面时写回曲库目录", result.Sound)
                    : IsBoundOnlineRoomChart(tab)
                        ? AvaloniaLocalizationCatalog.Format("已使用房间冻结资源 {0}；不会产生资源上传请求", result.Sound)
                        : AvaloniaLocalizationCatalog.Format("已使用谱面资源 {0}", result.Sound));
            UpdateSelectionUi();
        }
        catch (OperationCanceledException exception)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            viewModel.SetStatus(exception.Message);
        }
        catch (Exception exception) when (
            exception is InvalidOperationException or ArgumentException or IOException or
            UnauthorizedAccessException or NotSupportedException)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("设置 Note Key 音失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private bool TryGetEditableSelectedNote(DesktopChartTab? tab, out ChartNote? note)
    {
        note = null;
        if (tab == null) return false;
        var selected = tab.Session.Document.Notes
            .Where(candidate => tab.Session.Selection.Contains(candidate.Id) &&
                                !tab.HiddenGroups.Contains(candidate.Group))
            .ToArray();
        if (selected.Length != 1)
        {
            viewModel.SetStatus("请先只选择一个 Note。");
            return false;
        }
        if (tab.Session.IsReadOnly || !tab.Session.CanEditNotes ||
            (!tab.Session.AllowOwnerProtectedEdits && tab.Session.IsOwnerProtected(selected[0])))
        {
            viewModel.SetStatus("当前 Note 没有可用的编辑权限。");
            return false;
        }
        note = selected[0];
        return true;
    }

    private bool IsBoundOnlineRoomChart(DesktopChartTab tab) =>
        roomChartSyncRoomId != null && ReferenceEquals(roomChartSyncTab, tab);

    private bool IsListedFrozenRoomNoteSound(DesktopChartTab tab, string fullPath)
    {
        return IsBoundOnlineRoomChart(tab) &&
               ChartAssetImportService.IsSupportedNoteSoundFile(fullPath) &&
               roomChartFrozenResources?.ContainsListedFile(fullPath) == true;
    }

    private async Task<WindowsNoteSoundAssignmentPolicy> CreateNoteSoundAssignmentPolicyAsync(
        DesktopChartTab tab,
        string? sound)
    {
        if (!IsBoundOnlineRoomChart(tab))
            return new WindowsNoteSoundAssignmentPolicy(false, null);

        var requested = sound?.Trim();
        if (string.IsNullOrWhiteSpace(requested))
            return new WindowsNoteSoundAssignmentPolicy(true, _ => false);
        var safeName = Path.GetFileName(requested);
        if (string.IsNullOrWhiteSpace(safeName) ||
            !string.Equals(requested, safeName, StringComparison.Ordinal))
            return new WindowsNoteSoundAssignmentPolicy(true, _ => false);

        string fullPath;
        try
        {
            var root = Path.GetDirectoryName(Path.GetFullPath(tab.WorkingPath));
            if (string.IsNullOrWhiteSpace(root))
                return new WindowsNoteSoundAssignmentPolicy(true, _ => false);
            fullPath = Path.GetFullPath(Path.Combine(root, safeName));
        }
        catch (Exception exception) when (
            exception is ArgumentException or IOException or NotSupportedException)
        {
            return new WindowsNoteSoundAssignmentPolicy(true, _ => false);
        }

        var registry = roomChartFrozenResources;
        var verified = registry != null &&
                       await registry.VerifyAsync(fullPath).ConfigureAwait(true);
        return new WindowsNoteSoundAssignmentPolicy(
            true,
            candidate => verified && ReferenceEquals(roomChartFrozenResources, registry) &&
                         IsBoundOnlineRoomChart(tab) && PathsEqual(candidate, fullPath));
    }

    private static IReadOnlyList<ChartNoteSoundCandidate> CoalesceNoteSoundCandidates(
        IReadOnlyList<ChartNoteSoundCandidate> candidates,
        string workingRoot)
    {
        var result = new List<ChartNoteSoundCandidate>();
        foreach (var group in candidates.GroupBy(
                     candidate => candidate.FileName,
                     StringComparer.OrdinalIgnoreCase))
        {
            var working = group.FirstOrDefault(candidate => string.Equals(
                Path.GetDirectoryName(candidate.FullPath)?.TrimEnd(Path.DirectorySeparatorChar),
                workingRoot.TrimEnd(Path.DirectorySeparatorChar),
                StringComparison.OrdinalIgnoreCase));
            if (working == null)
            {
                result.AddRange(group);
                continue;
            }
            result.Add(working);
            result.AddRange(group.Where(candidate =>
                !ReferenceEquals(candidate, working) &&
                !NoteSoundCandidateFilesEqual(candidate.FullPath, working.FullPath)));
        }
        return result
            .OrderBy(candidate => candidate.FileName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(candidate => candidate.FullPath, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static bool NoteSoundCandidateFilesEqual(string left, string right)
    {
        try
        {
            var leftInfo = new FileInfo(left);
            var rightInfo = new FileInfo(right);
            if (leftInfo.Length != rightInfo.Length) return false;
            using var leftStream = File.OpenRead(left);
            using var rightStream = File.OpenRead(right);
            return System.Security.Cryptography.SHA256.HashData(leftStream).AsSpan()
                .SequenceEqual(System.Security.Cryptography.SHA256.HashData(rightStream));
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
        {
            return false;
        }
    }

    private async Task ApplyNotePropertiesAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var session = tab.Session;
        try
        {
            var sound = noteSoundBox.Text ?? string.Empty;
            var soundPolicy = await CreateNoteSoundAssignmentPolicyAsync(tab, sound);
            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new InvalidOperationException("校验 Key 音期间已切换谱面。");
            var result = WindowsNotePropertyCommand.Apply(
                session,
                new WindowsNotePropertyFields(
                    noteBeatBox.Text ?? string.Empty,
                    noteEndBeatBox.Text ?? string.Empty,
                    noteLaneBox.Text ?? string.Empty,
                    noteVolumeBox.Text ?? string.Empty,
                    sound,
                    noteGroupBox.Text ?? string.Empty),
                soundPolicy,
                hiddenGroups: tab.HiddenGroups);
            var lane = result.IsDraft
                ? $"D:{result.Column}"
                : result.Column.ToString(CultureInfo.InvariantCulture);
            // Explicit apply: show the canonical applied values in every box.
            ResetNoteInspectorFill();
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已应用 Note 属性 · Beat {0} · 轨道 {1}{2}", WindowsBeatDisplayFormat.Format(result.Beat), lane, (result.EndBeat.HasValue ? $" · End {WindowsBeatDisplayFormat.Format(result.EndBeat)}" : " · Tap")));
            UpdateSelectionUi();
        }
        catch (Exception exception)
        {
            // Button handler: beyond the command's own validation errors, the
            // edit and the room sound-policy lookup can fault on odd input.
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("应用 Note 属性失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private HashSet<Guid> SelectedTimingListIds() =>
        timingList.SelectedItems?.OfType<TimingListItem>().Select(item => item.Id).ToHashSet() ?? [];

    private void SyncTimingListSelection(
        IReadOnlyCollection<Guid> timingIds,
        Guid? primaryId = null)
    {
        var ids = timingIds.ToHashSet();
        var items = timingList.Items.OfType<TimingListItem>().ToArray();
        var primary = primaryId.HasValue
            ? items.FirstOrDefault(item => item.Id == primaryId.Value)
            : items.FirstOrDefault(item => ids.Contains(item.Id));
        var previous = suppressTimingSelection;
        suppressTimingSelection = true;
        try
        {
            timingList.SelectedItems?.Clear();
            timingList.SelectedItem = primary;
            if (timingList.SelectedItems != null)
            {
                foreach (var item in items.Where(item => ids.Contains(item.Id)))
                    if (!timingList.SelectedItems.Contains(item))
                        timingList.SelectedItems.Add(item);
            }
        }
        finally
        {
            suppressTimingSelection = previous;
        }

        if (primary != null) PopulateTimingFields(primary.Id);
    }

    private void UpdateEditorAvailability()
    {
        var session = viewModel.ActiveTab?.Session;
        var canEditNotes = session != null && !session.IsReadOnly && session.CanEditNotes;
        var canEditTiming = session != null && !session.IsReadOnly && session.CanEditTiming;
        var canEditMetadata = session != null && !session.IsReadOnly && session.CanEditMetadata;
        if (quickMirrorButton != null) quickMirrorButton.IsEnabled = canEditNotes;
        if (quickEffectButton != null) quickEffectButton.IsEnabled = canEditTiming;
        if (!WindowsAvaloniaEditorInputPolicy.CanUseTimelineTool(session, timeline.Tool))
            timeline.Tool = TimelineTool.Select;

        UpdateTimelineToolButtons();
        foreach (var control in new Control[]
                 {
                     metadataTitleBox,
                     metadataTitleOriginalBox,
                     metadataRomanizeTitleButton,
                     metadataArtistBox,
                     metadataArtistOriginalBox,
                     metadataRomanizeArtistButton,
                     metadataCreatorBox,
                     metadataVersionBox,
                     metadataBpmBox,
                     metadataKeyCountBox,
                     metadataPreviewTimeBox,
                      metadataOverallDifficultyBox,
                      metadataHpDrainRateBox,
                      metadataPreviewHereButton,
                      metadataAudioSelectButton,
                      metadataCoverSelectButton,
                      metadataBackgroundSelectButton
                  })
            control.IsEnabled = canEditMetadata;
        metadataAudioFileBox.IsEnabled = session != null;
        metadataCoverFileBox.IsEnabled = session != null;
        metadataBackgroundFileBox.IsEnabled = session != null;
        metadataAudioSelectButton.IsEnabled =
            canEditMetadata && !audioImportInProgress && !imageImportInProgress;
        metadataCoverSelectButton.IsEnabled =
            canEditMetadata && !audioImportInProgress && !imageImportInProgress;
        metadataBackgroundSelectButton.IsEnabled =
            canEditMetadata && !audioImportInProgress && !imageImportInProgress;
        metadataRomanizeTitleButton.IsEnabled = canEditMetadata && !titleRomanizationInProgress;
        metadataRomanizeArtistButton.IsEnabled = canEditMetadata && !artistRomanizationInProgress;
        metadataOffsetBox.IsEnabled = canEditTiming;
        metadataAnalyzeSingleTempoButton.IsEnabled =
            canEditTiming &&
            !audioImportInProgress &&
            (!audioAnalysisInProgress || activeTempoAnalysisKind == TempoAnalysisKind.Single);
        metadataAnalyzeVariableTempoButton.IsEnabled =
            canEditTiming &&
            !audioImportInProgress &&
            (!audioAnalysisInProgress || activeTempoAnalysisKind == TempoAnalysisKind.Variable);
        metadataAnalyzeManualTempoButton.IsEnabled =
            canEditTiming &&
            !audioImportInProgress &&
            (!audioAnalysisInProgress || activeTempoAnalysisKind == TempoAnalysisKind.Manual);
        metadataApplyButton.IsEnabled = (canEditMetadata || canEditTiming) &&
                                        !audioAnalysisInProgress &&
                                        !audioImportInProgress &&
                                        !imageImportInProgress &&
                                        !titleRomanizationInProgress &&
                                        !artistRomanizationInProgress;
        foreach (var control in new Control[]
                 {
                     timingBeatBox,
                     timingBpmBox,
                     timingDelayBox,
                     timingEffectBox,
                     timingValueBox,
                     timingCustomFieldBox
                 })
            control.IsEnabled = canEditTiming;
        timingPermissionText.Text = session == null
            ? string.Empty
            : session.IsReadOnly
                ? "当前谱面为只读状态，不能编辑 Timing / Effect。"
                : !session.CanEditTiming
                    ? "当前没有编辑 Timing / Effect 的权限。"
                    : string.Empty;
        timingPermissionText.IsVisible = !string.IsNullOrEmpty(timingPermissionText.Text);

        var selectedTimingIds = timeline.SelectedTimingIds.ToHashSet();
        var selectedNoteCount = session?.Selection.Count ?? 0;
        var selectedEffectCount = session?.Document.Timing.Count(timing =>
            selectedTimingIds.Contains(timing.Id) && timing.Effect.HasValue) ?? 0;
        var needsNotePermission = selectedNoteCount > 0;
        var needsTimingPermission = selectedEffectCount > 0;
        var canMutateMixedSelection = session != null && !session.IsReadOnly &&
                                      (!needsNotePermission || session.CanEditNotes) &&
                                      (!needsTimingPermission || session.CanEditTiming);
        var canPaste = session != null && !session.IsReadOnly && viewModel.HasMixedSelectionClipboard &&
                       (viewModel.MixedClipboardNoteCount == 0 || session.CanEditNotes) &&
                       (viewModel.MixedClipboardEffectCount == 0 || session.CanEditTiming);
        SetQuickShortcutEnabled("Undo", session != null && !session.IsReadOnly);
        SetQuickShortcutEnabled("Redo", session != null && !session.IsReadOnly);
        SetQuickShortcutEnabled(
            "Cut",
            canMutateMixedSelection && (selectedNoteCount > 0 || selectedEffectCount > 0));
        SetQuickShortcutEnabled(
            "Copy",
            session != null && (selectedNoteCount > 0 || selectedEffectCount > 0));
        SetQuickShortcutEnabled("Paste", canPaste);
        SetQuickShortcutEnabled("SelectAll", session != null);

        if (mixedCopyButton != null)
            mixedCopyButton.IsEnabled = session != null && (selectedNoteCount > 0 || selectedEffectCount > 0);
        if (mixedPasteButton != null) mixedPasteButton.IsEnabled = canPaste;
        if (mixedDeleteButton != null)
            mixedDeleteButton.IsEnabled = canMutateMixedSelection &&
                                          (selectedNoteCount > 0 || selectedEffectCount > 0);
        if (extensionMenuButton != null) extensionMenuButton.IsEnabled = session != null;
        UpdateToolboxAvailability();
        foreach (var control in new Control[]
                 {
                     noteBeatBox,
                     noteEndBeatBox,
                     noteLaneBox,
                     noteVolumeBox,
                     noteSoundBox,
                     noteSoundExistingButton,
                     noteSoundSelectButton,
                     noteGroupBox,
                     noteApplyButton,
                     noteDeleteButton
                 })
            control.IsEnabled = canEditNotes;
        groupIdBox.IsEnabled = session != null;
        groupCreateAndUseButton.IsEnabled = canEditNotes;
        groupSetCurrentButton.IsEnabled = session != null;
        groupAssignButton.IsEnabled = canEditNotes;
        groupShowAllButton.IsEnabled = session != null;
        groupHideNonzeroButton.IsEnabled = session != null;
        groupClearSelectedButton.IsEnabled = canEditNotes;
        if (timingAddButton != null) timingAddButton.IsEnabled = canEditTiming;
        if (timingApplyButton != null)
            timingApplyButton.IsEnabled = canEditTiming && timingList.SelectedItem != null;
        if (timingDeleteButton != null)
            timingDeleteButton.IsEnabled = canEditTiming && selectedTimingIds.Count > 0;
        if (timingCopyButton != null)
            timingCopyButton.IsEnabled = session != null;
        if (timingPasteButton != null)
            timingPasteButton.IsEnabled = canEditTiming && viewModel.MixedClipboardEffectCount > 0;
        RefreshOwnerLockUi();
    }

    private void RefreshOwnerLockUi()
    {
        if (ownerLockButton == null || quickOwnerLockButton == null) return;
        var tab = viewModel.ActiveTab;
        var session = tab?.Session;
        var inOnlineEditor = tab != null &&
                             ReferenceEquals(tab, roomChartSyncTab) &&
                             roomChartSyncCoordinator != null &&
                             roomChartSyncRoomId != null;
        ownerLockButton.IsVisible = inOnlineEditor;
        quickOwnerLockButton.IsVisible = inOnlineEditor;
        if (!inOnlineEditor || session == null)
        {
            ownerLockButton.IsEnabled = false;
            ownerLockButton.Content = "锁定选区";
            quickOwnerLockButton.IsEnabled = false;
            if (quickOwnerLockLabel != null) quickOwnerLockLabel.Text = "锁定选区";
            AutomationProperties.SetName(quickOwnerLockButton, "锁定选区");
            return;
        }

        var ranges = SelectedOwnerLockRanges(
            tab ?? throw new InvalidOperationException("The online editor tab is unavailable."));
        var selectionIsLocked = OwnerLockSelectionPlanner.IsFullyCovered(
            ranges,
            session.OwnerProtectedRegions.Select(region =>
                new OwnerLockSelectionRange(region.StartBeat, region.EndBeat)));
        ownerLockButton.IsEnabled = session.AllowOwnerProtectedEdits && ranges.Count > 0;
        quickOwnerLockButton.IsEnabled = ownerLockButton.IsEnabled;
        var label = !session.AllowOwnerProtectedEdits
            ? "仅房主可锁定"
            : selectionIsLocked
                ? "解除选区"
                : "锁定选区";
        ownerLockButton.Content = label;
        if (quickOwnerLockLabel != null) quickOwnerLockLabel.Text = label;
        AutomationProperties.SetName(quickOwnerLockButton, label);
    }

    private async Task ToggleOwnerLockSelectionAsync()
    {
        var account = onlineAccountHost?.Session;
        var tab = roomChartSyncTab;
        var roomId = roomChartSyncRoomId;
        if (account == null || tab == null || roomId == null ||
            !ReferenceEquals(viewModel.ActiveTab, tab) ||
            !tab.Session.AllowOwnerProtectedEdits)
            return;
        var ranges = SelectedOwnerLockRanges(tab);
        if (ranges.Count == 0) return;

        if (ownerLockButton != null) ownerLockButton.IsEnabled = false;
        if (quickOwnerLockButton != null) quickOwnerLockButton.IsEnabled = false;
        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(30));
            var result = await account.ToggleRoomChartLockSelectionAsync(
                roomId.Value,
                ranges.Select(range => new OnlineChartLockRange(
                    new OnlineSyncBeat(
                        range.StartBeat.Bar,
                        range.StartBeat.Numerator,
                        range.StartBeat.Denominator),
                    new OnlineSyncBeat(
                        range.EndBeat.Bar,
                        range.EndBeat.Numerator,
                        range.EndBeat.Denominator)))
                    .ToArray(),
                timeout.Token);
            if (roomChartSyncRoomId != roomId || !ReferenceEquals(roomChartSyncTab, tab)) return;

            applyingRemoteChartSync = true;
            try
            {
                tab.Session.ReplaceOwnerProtectedRegions(
                    OnlineChartSyncCodec.ToOwnerRegions(result.Locks));
            }
            finally
            {
                applyingRemoteChartSync = false;
            }
            viewModel.SetStatus(result.IsUnlock
                ? "房主已解除当前连续选区；选区外两侧的锁定保持不变"
                : "已锁定当前选区；单对象保持精确行 / LN 区间，多选保持一个连续区间");
            timeline.InvalidateVisual();
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException or InvalidOperationException)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("选区锁同步失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            RefreshOwnerLockUi();
        }
    }

    private IReadOnlyList<OwnerLockSelectionRange> SelectedOwnerLockRanges(DesktopChartTab tab)
    {
        var session = tab.Session;
        var selectedTimingIds = timeline.SelectedTimingIds.ToHashSet();
        var notes = session.Document.Notes
            .Where(note => session.Selection.Contains(note.Id) && !tab.HiddenGroups.Contains(note.Group))
            .ToArray();
        var timing = session.Document.Timing
            .Where(item => selectedTimingIds.Contains(item.Id))
            .ToArray();
        if (notes.Length == 0 && timing.Length == 0) return [];

        var ranges = notes.Select(note => new OwnerLockSelectionRange(
                note.Beat,
                note.EndBeat is { } end && end.CompareTo(note.Beat) > 0
                    ? end
                    : OwnerLockSelectionPlanner.BuildPointRange(
                        note.Beat,
                        session.SnapDivision).EndBeat))
            .Concat(timing.Select(item => new OwnerLockSelectionRange(
                item.Beat,
                OwnerLockSelectionPlanner.BuildPointRange(
                    item.Beat,
                    session.SnapDivision).EndBeat)));
        return OwnerLockSelectionPlanner.BuildSelectedObjectRanges(ranges);
    }

    private void CopyMixedSelection()
    {
        if (viewModel.ActiveTab == null) return;
        try
        {
            _ = viewModel.CopyMixedSelection(timeline.SelectedTimingIds);
            UpdateEditorAvailability();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("复制失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    /// <summary>
    /// Quick range copy. The first press marks the playhead, the second copies
    /// every note between the two marks, so a range can be taken without
    /// dragging a selection across the timeline first.
    /// </summary>
    private void CopyRangeByPlayhead()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var beat = BeatPosition.FromDouble(timeline.CurrentBeat);
        if (rangeCopyAnchor is not { } anchor || !ReferenceEquals(anchor.Tab, tab))
        {
            rangeCopyAnchor = (tab, beat);
            viewModel.SetStatus("正在选中复制区间");
            return;
        }

        if (Math.Abs(anchor.Beat.Value - beat.Value) < 1e-9)
        {
            // Holding the copy shortcut repeats the keystroke. Staying silent
            // keeps the "正在选中复制区间" prompt from flickering on every
            // repeat, and the mark is still waiting for a real second point.
            return;
        }

        try
        {
            var clipboard = viewModel.CopyRange(anchor.Beat, beat);
            rangeCopyAnchor = null;
            UpdateEditorAvailability();
            viewModel.SetStatus(
                clipboard.IsEmpty
                    ? "复制区间成功，但这段里没有 Note"
                    : AvaloniaLocalizationCatalog.Format(
                        "复制区间成功：{0:N0} 个 Note、{1:N0} 个 Effect",
                        clipboard.NoteCount,
                        clipboard.EffectCount));
        }
        catch (InvalidOperationException exception)
        {
            rangeCopyAnchor = null;
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("复制失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void CancelRangeCopySelection()
    {
        rangeCopyAnchor = null;
    }

    private void CutMixedSelection()
    {
        if (viewModel.ActiveTab == null) return;
        try
        {
            var clipboard = viewModel.CopyMixedSelection(timeline.SelectedTimingIds);
            if (clipboard.IsEmpty) return;
            var result = viewModel.DeleteMixedSelection(timeline.SelectedTimingIds);
            if (!result.Applied) return;
            timeline.SetSelectedTiming(null);
            RefreshTimingList([], force: true);
            UpdateSelectionUi();
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已剪切 {0:N0} 个 Note、{1:N0} 个 Effect", clipboard.NoteCount, clipboard.EffectCount));
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("剪切失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void SelectAllVisibleObjects()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        tab.Session.Selection.Clear();
        tab.Session.Selection.UnionWith(tab.Session.Document.Notes
            .Where(note => !tab.HiddenGroups.Contains(note.Group) &&
                           (timeline.ProEditorEnabled || !note.IsDraft))
            .Select(note => note.Id));
        var timingIds = tab.Session.Document.Timing
            .Where(timing => timing.Effect.HasValue)
            .Select(timing => timing.Id)
            .ToArray();
        timeline.SetSelectedTimings(timingIds);
        SyncTimingListSelection(timingIds);
        viewModel.SetStatus(
            AvaloniaLocalizationCatalog.Format("已全选 {0:N0} 个可见 Note、{1:N0} 个 Effect", tab.Session.Selection.Count, timingIds.Length));
        UpdateSelectionUi();
    }

    private void ExecuteHistoryCommand(bool redo)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            viewModel.SetStatus(redo ? "没有可重做操作" : "没有可撤销操作");
            return;
        }

        var outcome = WindowsEditorHistoryCommand.Execute(
            tab.Session,
            IsBoundOnlineRoomChart(tab),
            redo);
        viewModel.SetStatus(outcome.Status);
    }

    private void MirrorVisibleSelection()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        // Match WPF: a mixed source selection mirrors only visible, unlocked
        // Notes. Destination-lock validation remains atomic in the shared
        // service; one locked source must not cancel unrelated unlocked Notes.
        var ids = WindowsGroupManagerCommand.VisibleEditableSelectionIds(tab);
        if (ids.Count == 0)
        {
            viewModel.SetStatus("请先选择一个或多个可见 Note");
            return;
        }
        try
        {
            var changed = NoteMirrorEditingService.MirrorSelection(tab.Session, ids);
            viewModel.SetStatus(changed > 0
                ? AvaloniaLocalizationCatalog.Format("已水平镜像 {0} 个可见 Note（单次撤销）", changed)
                : "选中的 Note 位于镜像轴上，无需移动");
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(exception.Message);
            timeline.InvalidateVisual();
        }
    }

    /// <summary>
    /// 内外对调：1 轨↔2 轨、3 轨↔4 轨。逐 Note 换列，不做成对检查（和镜像同样
    /// 只按选区走），所以只选一半时可能和未选中的 Note 叠在同一轨上。
    /// </summary>
    private void SwapOuterInnerSelection()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var ids = WindowsGroupManagerCommand.VisibleEditableSelectionIds(tab);
        if (ids.Count == 0)
        {
            viewModel.SetStatus("请先选择一个或多个可见 Note");
            return;
        }
        try
        {
            var changed = NoteLaneSwapEditingService.SwapOuterInner(tab.Session, ids);
            viewModel.SetStatus(changed > 0
                ? AvaloniaLocalizationCatalog.Format("已内外对调 {0} 个可见 Note（单次撤销）", changed)
                : "选区里没有正式轨道的 Note 可对调");
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(exception.Message);
            timeline.InvalidateVisual();
        }
    }

    private void RandomizeVisibleSelection(bool perBeat)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var ids = WindowsGroupManagerCommand.VisibleEditableSelectionIds(tab);
        if (ids.Count == 0)
        {
            viewModel.SetStatus("请先选择一个或多个可见 Note");
            return;
        }
        try
        {
            var mode = perBeat
                ? NoteLaneRandomizationMode.PerBeatPermutation
                : NoteLaneRandomizationMode.FixedPermutation;
            var result = NoteLaneRandomizationService.RandomizeSelection(
                tab.Session,
                ids,
                mode);
            viewModel.SetStatus(result.ChangedCount > 0
                ? perBeat
                    ? AvaloniaLocalizationCatalog.Format("已完全随机 {0} 个 Note（{1} 排分别打乱 · 单次撤销）", result.ChangedCount, result.RowCount)
                    : AvaloniaLocalizationCatalog.Format("已随机排列 {0} 个 Note（固定轨道映射 · 单次撤销）", result.ChangedCount)
                : result.CollisionBlocked
                    ? "没有找到不与未选中 Note / LN 重叠的安全排列，谱面未修改"
                : result.SelectedCount == 0
                    ? "选区中没有可随机的正式轨道 Note"
                    : "当前轨道数无法产生不同的随机排列");
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(exception.Message);
            timeline.InvalidateVisual();
        }
    }

    private void BeginQuickEffectEdit()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditTiming)
        {
            viewModel.SetStatus("当前没有编辑 Timing / Effect 的权限");
            return;
        }
        if (!inspectorPanel.IsVisible)
        {
            inspectorPanel.IsVisible = true;
            editorWorkbench.ColumnDefinitions[4].Width = new GridLength(350);
            inspectorToggleButton.Content = "−";
            ToolTip.SetTip(inspectorToggleButton, "收起右侧面板");
        }
        editorInspectorTabs.SelectedItem = timingInspectorTab;
        timeline.SetSelectedTiming(null);
        SyncTimingListSelection([]);
        var rememberedEffect = timingEffectMemory.Current;
        timingBeatBox.Text = BeatPosition.FromDouble(timeline.CurrentBeat)
            .Snap(tab.Session.SnapDivision)
            .ToString();
        timingBpmBox.Text = string.Empty;
        timingDelayBox.Text = "0";
        // The box is bound to option records, so select the matching record;
        // assigning the enum name string never matched and left the previous
        // selection (often "None") in place.
        var rememberedEffectValue = rememberedEffect.Effect.ToString();
        timingEffectBox.SelectedItem =
            WindowsInspectorParityPolicy.Wpf110TimingEffectOptions.FirstOrDefault(
                option => option.Value.Equals(
                    rememberedEffectValue,
                    StringComparison.Ordinal)) ??
            timingEffectBox.SelectedItem;
        timingValueBox.Text = rememberedEffect.ValueText;
        timingCustomFieldBox.Text = rememberedEffect.CustomFieldName;
        timingValueBox.Focus();
        timingValueBox.SelectAll();
        viewModel.SetStatus(
            AvaloniaLocalizationCatalog.Format("添加 {0} Effect · Beat {1} · 继承值 {2}", EffectNumberText.CanonicalName(
                rememberedEffect.Effect,
                rememberedEffect.CustomFieldName), timingBeatBox.Text, rememberedEffect.ValueText));
    }

    private void SetTimelineToolFromShortcut(TimelineTool tool)
    {
        if (!WindowsAvaloniaEditorInputPolicy.CanUseTimelineTool(viewModel.ActiveTab?.Session, tool))
        {
            viewModel.SetStatus("当前权限不能使用该编辑工具");
            return;
        }
        timeline.Tool = tool;
        UpdateTimelineToolButtons();
        timeline.Focus();
    }

    private void NudgeSelectionOrRedLine(int direction)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var ids = WindowsGroupManagerCommand.VisibleEditableSelectionIds(
            tab.Session,
            tab.HiddenGroups);
        if (ids.Count == 0)
        {
            timeline.SetCurrentBeat(Math.Max(
                0,
                timeline.CurrentBeat + direction / (double)Math.Clamp(tab.Session.SnapDivision, 1, 1920)));
            return;
        }

        try
        {
            var moved = BasicChartEditingService.NudgeSelection(tab.Session, direction, ids);
            viewModel.SetStatus(moved > 0
                ? AvaloniaLocalizationCatalog.Format("已按当前 {0} 分度{1}移动 {2} 个 Note", TimelineSubdivisionCheckPalette.FormatDivisionLabel(tab.Session.SnapDivision), (direction > 0 ? AvaloniaLocalizationCatalog.Text("向前") : AvaloniaLocalizationCatalog.Text("向后")), moved)
                : "Note 已到达谱面起点，不能继续向后移动");
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(exception.Message);
            timeline.InvalidateVisual();
        }
    }

    private async Task ConvertLongNotesToTapsAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var session = tab.Session;
        if (session.IsReadOnly)
        {
            viewModel.SetStatus("当前谱面为只读状态，不能转换 Note 类型");
            return;
        }
        if (!session.CanEditNotes)
        {
            viewModel.SetStatus("当前没有编辑 Note 的权限");
            return;
        }
        var count = WindowsNoteTypeTransformCommand.CountSelectedLongNotes(
            session,
            tab.HiddenGroups);
        if (count == 0)
        {
            viewModel.SetStatus("当前选区中没有可转换的面");
            return;
        }

        var mode = await new NoteTypeTransformDialog(
                count,
                session.SnapDivision,
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale)
            .ShowDialog<LongNoteToTapMode?>(this);
        if (!mode.HasValue) return;

        try
        {
            var result = WindowsNoteTypeTransformCommand.ConvertLongNotesToTaps(
                session,
                mode.Value,
                tab.HiddenGroups);
            ApplyNoteTransformSelection();
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已转换 {0} 个面，新增 {1} 个米{2}", result.ConvertedCount, result.CreatedCount, (result.SkippedCount > 0
                                    ? AvaloniaLocalizationCatalog.Format(AvaloniaLocalizationCatalog.Text("，跳过 {0} 个重叠位置"), result.SkippedCount)
                                    : string.Empty)));
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("面转米失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    /// <summary>
    /// Turns each selected long note into a single-lane stream whose gaps follow
    /// a curve. The long note's own head and tail are the range, so the mapping
    /// never has to guess boundaries.
    /// </summary>
    /// <summary>
    /// Runs the curve with whatever the toolbox panel currently shows. The
    /// shape used to come from a dialog per run; it is a setting now, so the
    /// parameters stay visible next to the button that consumes them.
    /// </summary>
    private void GenerateCurveDensity()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var session = tab.Session;
        if (session.IsReadOnly)
        {
            viewModel.SetStatus("当前谱面为只读状态，不能生成曲线密度");
            return;
        }
        if (!session.CanEditNotes)
        {
            viewModel.SetStatus("当前没有编辑 Note 的权限");
            return;
        }
        var count = WindowsCurveDensityCommand.CountSelectedLongNotes(session, tab.HiddenGroups);
        if (count == 0)
        {
            viewModel.SetStatus("先选中一根面：它的面头到面尾就是要生成的区间");
            return;
        }

        try
        {
            var result = WindowsCurveDensityCommand.FillCurveDensity(
                session,
                CurrentCurveDensityOptions(),
                tab.HiddenGroups);
            ApplyNoteTransformSelection();
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "已生成曲线密度：{0} 根面转换为 {1} 个米{2}",
                result.ConvertedCount,
                result.CreatedCount,
                result.SkippedCount > 0
                    ? AvaloniaLocalizationCatalog.Format("，跳过 {0} 个重叠位置", result.SkippedCount)
                    : string.Empty));
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "曲线密度失败：{0}",
                AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void FillNoteGaps()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var session = tab.Session;
        if (session.IsReadOnly)
        {
            viewModel.SetStatus("当前谱面为只读状态，不能填充音符");
            return;
        }
        if (!session.CanEditNotes)
        {
            viewModel.SetStatus("当前没有编辑 Note 的权限");
            return;
        }
        var taps = WindowsNoteGapFillCommand.CountSelectedTaps(session, tab.HiddenGroups);
        if (taps < 2)
        {
            viewModel.SetStatus("先选中同一轨道上前后两颗米");
            return;
        }

        try
        {
            // Plan first: "no pair at all" and "the pair is too short" are
            // different mistakes and deserve different messages.
            var plan = WindowsNoteGapFillCommand.Plan(
                session,
                toolboxGapFillCount,
                tab.HiddenGroups);
            if (plan.Pairs == 0)
            {
                viewModel.SetStatus(plan.TooShort > 0
                    ? AvaloniaLocalizationCatalog.Format(
                        "这两颗米之间放不下 {0} 个：每段会小于 1/1440",
                        toolboxGapFillCount)
                    : "选中的米不在同一轨道上：填充需要同一轨道上前后两颗米");
                return;
            }

            var result = WindowsNoteGapFillCommand.FillGaps(
                session,
                toolboxGapFillCount,
                tab.HiddenGroups);
            ApplyNoteTransformSelection();
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "已填充 {0} 个米（{1} 段，每段 {2} 个）{3}{4}",
                result.CreatedCount,
                result.ConvertedCount,
                toolboxGapFillCount,
                result.SkippedCount > 0
                    ? AvaloniaLocalizationCatalog.Format(
                        "，跳过 {0} 个重叠位置",
                        result.SkippedCount)
                    : string.Empty,
                plan.TooShort > 0
                    ? AvaloniaLocalizationCatalog.Format(
                        "，{0} 段放不下跳过",
                        plan.TooShort)
                    : string.Empty));
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format(
                "填充失败：{0}",
                AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

