    /// <summary>
    /// The pair variant of the tap-to-hold conversion: the player marks both ends,
    /// so the hold covers exactly the range they pointed at instead of running to
    /// whatever the column holds next.
    /// </summary>
    private void ConvertTapPairsToLongNotes()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var session = tab.Session;
        if (session.IsReadOnly)
        {
            viewModel.SetStatus("当前谱面为只读状态，不能转换 Note 类型");
            return;
        }
        if (!session.CanEditNotes)
        {
            viewModel.SetStatus("当前没有编辑 Note 的权限");
            return;
        }
        if (WindowsNoteTypeTransformCommand.CountSelectedTaps(session, tab.HiddenGroups) < 2)
        {
            viewModel.SetStatus("先选中同一轨道上前后两颗米");
            return;
        }

        try
        {
            var result = WindowsNoteTypeTransformCommand.ConvertTapPairsToLongNotes(
