                : AvaloniaLocalizationCatalog.Format(
                    "已把 {0} 对米连成面{1}",
                    result.ConvertedCount,
                    result.SkippedCount > 0
                        ? AvaloniaLocalizationCatalog.Format("，{0} 颗米没配对", result.SkippedCount)
                        : string.Empty));
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("米转面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void ApplyNoteTransformSelection()
