    private void CopyTimingSelection()
    {
        if (viewModel.ActiveTab == null) return;
        try
        {
            var selectedIds = SelectedTimingListIds();
            if (selectedIds.Count == 0 && timingList.SelectedItem is TimingListItem selected)
                selectedIds.Add(selected.Id);
            if (selectedIds.Count == 0)
                selectedIds.UnionWith(timeline.SelectedTimingIds);
            _ = viewModel.CopyTimingSelection(selectedIds);
            UpdateEditorAvailability();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("复制 Effect 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void PasteMixedSelection()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
