    private static void ConfigureCommandToggleButton(ToggleButton button, string text)
    {
        button.Content = text;
        button.Padding = new Thickness(9, 7);
        button.Margin = new Thickness(1, 0);
        button.Background = Brushes.Transparent;
        button.Foreground = new SolidColorBrush(Color.Parse("#D0D4D6"));
        button.BorderBrush = Brushes.Transparent;
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(3);
    }

    private static Button CommandButton(
        string text,
        EventHandler<RoutedEventArgs> handler,
        bool horizontal = false)
    {
        var button = new Button
        {
            Content = text,
            Height = horizontal ? 35 : double.NaN,
            Padding = new Thickness(9, 7),
            Margin = new Thickness(1, 0),
            HorizontalContentAlignment = horizontal
                ? HorizontalAlignment.Left
                : HorizontalAlignment.Center,
            Background = Brushes.Transparent,
            Foreground = new SolidColorBrush(Color.Parse("#D0D4D6")),
            BorderBrush = Brushes.Transparent,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3)
        };
        button.Click += handler;
        return button;
    }

    private static void ApplyPrimaryButtonStyle(Button button)
    {
        button.Padding = new Thickness(8, 6);
        button.Background = RaisedBrush;
        button.Foreground = Brushes.White;
        button.BorderBrush = StrokeBrush;
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(4);
    }

    private static void ApplyWpfToolButtonStyle(Button button)
    {
        button.Padding = new Thickness(9, 6);
        button.Margin = new Thickness(2, 0);
        button.Background = new SolidColorBrush(Color.Parse("#1A1D20"));
        button.Foreground = new SolidColorBrush(Color.Parse("#D0D4D6"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#34393D"));
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(3);
        button.HorizontalAlignment = HorizontalAlignment.Stretch;
        button.HorizontalContentAlignment = HorizontalAlignment.Center;
        button.VerticalContentAlignment = VerticalAlignment.Center;
    }

    private static void ApplyWpfPrimaryButtonStyle(Button button)
    {
        ApplyWpfToolButtonStyle(button);
        button.Classes.Add("accent");
        button.Background = new SolidColorBrush(Color.Parse("#38676C"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#4A777B"));
        button.Foreground = Brushes.White;
        button.FontWeight = FontWeight.SemiBold;
    }

    private static void ApplyWpfAssignButtonStyle(Button button)
    {
        ApplyWpfToolButtonStyle(button);
        button.Background = new SolidColorBrush(Color.Parse("#76572F"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#9B7542"));
        button.Foreground = new SolidColorBrush(Color.Parse("#FFF4E3"));
        button.FontWeight = FontWeight.SemiBold;
    }

    private static void ApplyDangerButtonStyle(Button button)
    {
        button.Padding = new Thickness(12, 7);
        button.Background = new SolidColorBrush(Color.Parse("#2B1E21"));
        button.Foreground = new SolidColorBrush(Color.Parse("#FF969B"));
        button.BorderBrush = new SolidColorBrush(Color.Parse("#6A3439"));
        button.BorderThickness = new Thickness(1);
        button.CornerRadius = new CornerRadius(4);
    }

    private sealed record TimingListItem(Guid Id, string Beat, string Main, string Effect);

    private static string? ParseArgument(string[] args, string name)
    {
        for (var index = 0; index < args.Length - 1; index++)
            if (string.Equals(args[index], name, StringComparison.OrdinalIgnoreCase))
                return args[index + 1];
        return null;
    }

    private static int ParsePositiveIntArgument(string[] args, string name)
    {
        var text = ParseArgument(args, name);
        return int.TryParse(text, out var value) && value is > 0 and <= 1_000_000 ? value : 0;
    }

    private static bool IsSupportedOpenPath(string path)
        => WindowsSingleInstancePolicy.IsSupportedOpenPath(path);

    private sealed record LibrarySortChoice(string Label, DesktopLibrarySort Sort)
    {
        public override string ToString() => Label;
    }

    private sealed record LibraryRealizedContainerSnapshot(
        IReadOnlyList<ListBoxItem> ListBoxItems,
        IReadOnlyList<LibraryFolderCard> Cards);

    private sealed record KeySoundPresetChoice(string Label, KeySoundPreset Preset)
    {
        public override string ToString() => Label;
    }

    private sealed record PreparedOnlineRoomUpload(
        Guid TabId,
        long ChangeSerial,
        WindowsOnlineRoomUploadPackage Package);
}

public static class WindowsAvaloniaEditorInputPolicy
{
    public static bool CanUseTimelineTool(EditorSession? session, TimelineTool tool) => tool switch
    {
        TimelineTool.Select => true,
        TimelineTool.Erase => session != null && !session.IsReadOnly &&
                              (session.CanEditNotes || session.CanEditTiming),
        TimelineTool.Tap or TimelineTool.Hold =>
            session != null && !session.IsReadOnly && session.CanEditNotes,
        _ => false
    };

    public static bool PreserveNotesForTimingListSelection(KeyModifiers modifiers) =>
        modifiers.HasFlag(KeyModifiers.Shift);

    public static bool IsTextEditingShortcut(Key key, KeyModifiers modifiers) =>
        key is Key.Delete or Key.Back ||
        modifiers.HasFlag(KeyModifiers.Control) &&
        key is Key.C or Key.V or Key.X or Key.Z or Key.Y or Key.A;

    public static bool DeferToTextInputMethod(Key reportedKey, KeyModifiers modifiers)
    {
        if (reportedKey is Key.System or Key.ImeProcessed or Key.DeadCharProcessed)
            return true;
        return !modifiers.HasFlag(KeyModifiers.Control) &&
               !modifiers.HasFlag(KeyModifiers.Alt) &&
               !modifiers.HasFlag(KeyModifiers.Meta);
    }

    public static bool IsTextEditingControl(Control? control) =>
        FindTextEditingControl(control) != null;

    public static Control? FindTextEditingControl(Control? control)
    {
        for (var current = control; current != null; current = current.Parent as Control)
            if (current is TextBox or ComboBox) return current;
        return null;
    }
}

public readonly record struct WindowsOnlineRoomEditorAccess(
    bool IsReadOnly,
    bool CanEditMetadata,
    bool CanEditTiming,
    bool CanEditNotes);

public static class WindowsOnlineRoomPermissionPolicy
{
    public static WindowsOnlineRoomEditorAccess Resolve(
        bool isOwner,
        string? memberRole,
        bool canEditMetadata,
        bool canEditTiming,
        bool canEditNotes)
    {
        if (isOwner)
            return new WindowsOnlineRoomEditorAccess(false, true, true, true);
        if (memberRole?.Equals("viewer", StringComparison.OrdinalIgnoreCase) == true)
            return new WindowsOnlineRoomEditorAccess(true, false, false, false);
        return new WindowsOnlineRoomEditorAccess(
            false,
            canEditMetadata,
            canEditTiming,
            canEditNotes);
    }
}
